insert into public.catalog_ancestries (id,name_pt,name_en,description_pt,size,speed_feet,languages,traits,ruleset,source_book,source_page,system_id,data) values
('dnd35.frostburn.ancestry.frostburn-neanderthal','Neanderthal','Neanderthal','Ability adjustments: +2 Strength, +2 Constitution, –2 Dexterity, –2 Intelligence. Neanderthals are strong and hardy, but are hampered by slow intellects and reflexes. Medium: As Medium creatures, neanderthals have no special bonuses or penalties due to their size. Speed: Neanderthal base land speed is 30 feet. Primitive Weapon Mastery (Ex): Neanderthals have a +1 racial bonus on attack rolls made with the following weapons: bolas, club, dart, greatclub, goad, harpoon, iuak, javelin, longspear, quarterstaff, ritiik, shortbow, shortspear, sling, spear, sugliin, throwing axe, and tiger skull club. Skill bonus: +2 racial bonus on Listen, Spot, and Survival checks. Neanderthals have excellent senses and know how to get along in the wild with ease. Climate Tolerant (Ex): Neanderthals suffer little harm from environmental extremes of heat or cold. They do not have to make Fortitude saves in extreme environments between –20° and 140° F (severe cold to severe heat). This ability does not provide any protection from fire or cold damage. This ability counts as if a neanderthal had the Cold Endurance feat for purposes of fulfilling prerequisites for other feats or prestige classes. Human Blood: For all effects related to race, a neanderthal is considered a human. Neanderthals are just as vulnerable to special effects that affect humans as humans are, and they can use magic items that are only usable by humans. Illiteracy: Neanderthals do not automatically know how to read and write. A neanderthal must spend 2 skill points to gain the ability to read and write all languages he is able to speak. He does not automatically gain this skill when taking a nonbarbarian character class, with the exception of the wizard class. Languages: Automatic Languages: Common. Bonus Languages: Dwarven, Giant, and Orc. Favored Class: Barbarian. A multiclass neanderthal’s barbarian class does not count when determining whether he takes an experience point penalty for multiclassing.','Medium',30,ARRAY['Common']::text[],ARRAY[]::text[],'v35-frostburn','D&D 3.5 — Frostburn',36,'dnd35','{"id":"frostburn-neanderthal","name":"Neanderthal","sourceBook":"Frostburn","sourcePages":"36-38","abilityModifiers":{"str":2,"con":2,"dex":-2,"int":-2},"size":"Medium","baseLandSpeedFeet":30,"levelAdjustment":0,"favoredClass":"Barbarian","automaticLanguages":["Common"],"bonusLanguages":["Dwarven","Giant","Orc"],"classSkills":[],"traits":[{"name":"Ability adjustments","text":"+2 Strength, +2 Constitution, –2 Dexterity, –2 Intelligence. Neanderthals are strong and hardy, but are hampered by slow intellects and reflexes."},{"name":"Medium","text":"As Medium creatures, neanderthals have no special bonuses or penalties due to their size."},{"name":"Speed","text":"Neanderthal base land speed is 30 feet."},{"name":"Primitive Weapon Mastery (Ex)","text":"Neanderthals have a +1 racial bonus on attack rolls made with the following weapons: bolas, club, dart, greatclub, goad, harpoon, iuak, javelin, longspear, quarterstaff, ritiik, shortbow, shortspear, sling, spear, sugliin, throwing axe, and tiger skull club."},{"name":"Skill bonus","text":"+2 racial bonus on Listen, Spot, and Survival checks. Neanderthals have excellent senses and know how to get along in the wild with ease."},{"name":"Climate Tolerant (Ex)","text":"Neanderthals suffer little harm from environmental extremes of heat or cold. They do not have to make Fortitude saves in extreme environments between –20° and 140° F (severe cold to severe heat). This ability does not provide any protection from fire or cold damage. This ability counts as if a neanderthal had the Cold Endurance feat for purposes of fulfilling prerequisites for other feats or prestige classes."},{"name":"Human Blood","text":"For all effects related to race, a neanderthal is considered a human. Neanderthals are just as vulnerable to special effects that affect humans as humans are, and they can use magic items that are only usable by humans."},{"name":"Illiteracy","text":"Neanderthals do not automatically know how to read and write. A neanderthal must spend 2 skill points to gain the ability to read and write all languages he is able to speak. He does not automatically gain this skill when taking a nonbarbarian character class, with the exception of the wizard class."},{"name":"Languages","text":"Automatic Languages: Common. Bonus Languages: Dwarven, Giant, and Orc."},{"name":"Favored Class","text":"Barbarian. A multiclass neanderthal’s barbarian class does not count when determining whether he takes an experience point penalty for multiclassing."}],"age":{"adulthoodYears":14,"startingAge":{"barbarianRogueSorcerer":"+1d4","bardFighterPaladinRanger":"+1d6","clericDruidMonkWizard":"+3d6"},"middleAge":35,"old":50,"venerable":65,"maxAgeModifier":"+2d10 years"},"height":{"male":{"base":"6''6\"","modifier":"+2d8","weight":"200 lb.","weightModifier":"× (2d4) lb."},"female":{"base":"6''0\"","modifier":"+2d8","weight":"150 lb.","weightModifier":"× (2d4) lb."}}}'::jsonb),
('dnd35.frostburn.ancestry.frostburn-uldra','Uldra','Uldra','Ability adjustments: –2 Strength, +2 Constitution, +2 Wisdom. An uldra’s small size is more than compensated for by his vigor and faith in his convictions. Small: As a Small creature, an uldra gains a +1 size bonus to Armor Class, a +1 size bonus on attack rolls, and a +4 size bonus on Hide checks, but he uses smaller weapons than humans use, and his lifting and carrying limits are three-quarters of those of a Medium character. Speed: An uldra’s base land speed is 20 feet. Darkvision: Uldras can see in the dark up to 120 feet. Darkvision is black and white only, but it is otherwise like normal sight, and uldras can function just fine with no light at all. Low-Light Vision: An uldra can see twice as far as a human in starlight, moonlight, torchlight, and similar conditions of poor illumination. He retains the ability to distinguish color and detail under these conditions. Nature Scholar (Ex): The Knowledge (nature) skill is always a class skill for uldras, and they gain a +2 racial bonus on all Knowledge (nature) checks. Cold Resistance (Ex): Uldras are completely at home in freezing environments, and they suffer no harm from being in a cold environment. The uldra’s equipment is likewise protected. Against attacks that cause cold damage, an uldra possesses resistance to cold 5. Frosty Touch (Su): Uldras are supernaturally cold, and as a free action they can infuse their hands with cold energy. While their hands are frosty, their unarmed attacks do an additional 1 point of cold damage. Any melee weapon an uldra wields is infused with cold and does an additional 1 point of cold damage on a successful hit as long as the uldra continues to hold the weapon. This additional damage does not stack with a magic weapon’s ability to deal cold damage (if any). Spell-Like Abilities: 3/day—ray of frost; 1/day—speak with animals, touch of fatigue. These abilities are as the spells cast by a druid or wizard (save DC 10 + spell level) of a level equal to the uldra’s Hit Dice. The DCs are Wisdom-based. Fey Blood: Uldras are fey, and as such they are not subject to spells that specifically target humanoids, such as charm person or hold person. Likewise, effects that affect fey affect uldras as well. They possess no particular weakness against cold iron, although they find it uncomfortable to the touch, similar to the sensation of holding a rotting fish in your hand. Languages: Automatic Languages: Common and Sylvan. Bonus Languages: All. Uldras are gifted linguists, and the Speak Language skill is always a class skill for them. Favored Class: Druid. A multiclass uldra’s druid class does not count when determining whether he takes an experience point penalty for multiclassing. Level Adjustment: +1.','Small',20,ARRAY['Common','Sylvan']::text[],ARRAY[]::text[],'v35-frostburn','D&D 3.5 — Frostburn',38,'dnd35','{"id":"frostburn-uldra","name":"Uldra","sourceBook":"Frostburn","sourcePages":"38-40","abilityModifiers":{"str":-2,"con":2,"wis":2},"size":"Small","baseLandSpeedFeet":20,"levelAdjustment":1,"favoredClass":"Druid","automaticLanguages":["Common","Sylvan"],"bonusLanguages":null,"classSkills":["Knowledge (nature)","Speak Language"],"traits":[{"name":"Ability adjustments","text":"–2 Strength, +2 Constitution, +2 Wisdom. An uldra’s small size is more than compensated for by his vigor and faith in his convictions."},{"name":"Small","text":"As a Small creature, an uldra gains a +1 size bonus to Armor Class, a +1 size bonus on attack rolls, and a +4 size bonus on Hide checks, but he uses smaller weapons than humans use, and his lifting and carrying limits are three-quarters of those of a Medium character."},{"name":"Speed","text":"An uldra’s base land speed is 20 feet."},{"name":"Darkvision","text":"Uldras can see in the dark up to 120 feet. Darkvision is black and white only, but it is otherwise like normal sight, and uldras can function just fine with no light at all."},{"name":"Low-Light Vision","text":"An uldra can see twice as far as a human in starlight, moonlight, torchlight, and similar conditions of poor illumination. He retains the ability to distinguish color and detail under these conditions."},{"name":"Nature Scholar (Ex)","text":"The Knowledge (nature) skill is always a class skill for uldras, and they gain a +2 racial bonus on all Knowledge (nature) checks."},{"name":"Cold Resistance (Ex)","text":"Uldras are completely at home in freezing environments, and they suffer no harm from being in a cold environment. The uldra’s equipment is likewise protected. Against attacks that cause cold damage, an uldra possesses resistance to cold 5."},{"name":"Frosty Touch (Su)","text":"Uldras are supernaturally cold, and as a free action they can infuse their hands with cold energy. While their hands are frosty, their unarmed attacks do an additional 1 point of cold damage. Any melee weapon an uldra wields is infused with cold and does an additional 1 point of cold damage on a successful hit as long as the uldra continues to hold the weapon. This additional damage does not stack with a magic weapon’s ability to deal cold damage (if any)."},{"name":"Spell-Like Abilities","text":"3/day—ray of frost; 1/day—speak with animals, touch of fatigue. These abilities are as the spells cast by a druid or wizard (save DC 10 + spell level) of a level equal to the uldra’s Hit Dice. The DCs are Wisdom-based."},{"name":"Fey Blood","text":"Uldras are fey, and as such they are not subject to spells that specifically target humanoids, such as charm person or hold person. Likewise, effects that affect fey affect uldras as well. They possess no particular weakness against cold iron, although they find it uncomfortable to the touch, similar to the sensation of holding a rotting fish in your hand."},{"name":"Languages","text":"Automatic Languages: Common and Sylvan. Bonus Languages: All. Uldras are gifted linguists, and the Speak Language skill is always a class skill for them."},{"name":"Favored Class","text":"Druid. A multiclass uldra’s druid class does not count when determining whether he takes an experience point penalty for multiclassing."},{"name":"Level Adjustment","text":"+1."}],"age":{"adulthoodYears":100,"startingAge":{"barbarianRogueSorcerer":"+3d6","bardFighterPaladinRanger":"+5d6","clericDruidMonkWizard":"+8d6"},"middleAge":175,"old":263,"venerable":350,"maxAgeModifier":"+5d% years"},"height":{"male":{"base":"2''4\"","modifier":"+2d4","weight":"25 lb.","weightModifier":"× (1d4) lb."},"female":{"base":"2''2\"","modifier":"+2d4","weight":"20 lb.","weightModifier":"× (1d4) lb."}}}'::jsonb)
on conflict (id) do update set name_pt = excluded.name_pt, name_en = excluded.name_en, description_pt = excluded.description_pt, size = excluded.size, speed_feet = excluded.speed_feet, languages = excluded.languages, traits = excluded.traits, ruleset = excluded.ruleset, source_book = excluded.source_book, source_page = excluded.source_page, system_id = excluded.system_id, data = excluded.data, updated_at = now();

insert into public.catalog_classes (id,name_pt,name_en,description_pt,hp_per_level,key_attributes,traits,ruleset,source_book,source_page,system_id,data) values
('dnd35.frostburn.class.frostburn-cloud-anchorite','Cloud Anchorite','Cloud Anchorite','Alignment: Any nonchaotic. Base Fortitude Save: +5. Skills: Climb 9 ranks, Jump 9 ranks, Knowledge (religion) 9 ranks, Survival 4 ranks. Feats: Improved Unarmed Combat, Mountaineer. Special: The prospective student must live for a week on her own in a wilderness region, during which time she can travel no lower than 12,000 feet in altitude.',8,ARRAY[]::text[],ARRAY['prestige']::text[],'v35-frostburn','D&D 3.5 — Frostburn',52,'dnd35','{"id":"frostburn-cloud-anchorite","name":"Cloud Anchorite","hitDie":8,"requirements":["Alignment: Any nonchaotic.","Base Fortitude Save: +5.","Skills: Climb 9 ranks, Jump 9 ranks, Knowledge (religion) 9 ranks, Survival 4 ranks.","Feats: Improved Unarmed Combat, Mountaineer.","Special: The prospective student must live for a week on her own in a wilderness region, during which time she can travel no lower than 12,000 feet in altitude."],"classSkills":"The cloud anchorite class skills (and the key ability for each skill) are Balance (Dex), Climb (Str), Concentration (Con) Craft (Int), Escape Artist (Dex), Jump (Str), Knowledge (nature) (Int), Knowledge (religion) (Int), Listen (Wis), Spot (Wis), Survival (Wis), Tumble (Dex), and Use Rope (Dex). See Chapter 4 of the Player’s Handbook for skill descriptions.","skillPointsPerLevel":"4 + Int modifier","levels":[{"level":1,"bab":"+0","fort":"+2","ref":"+2","will":"+0","special":"Climb speed +10 ft., wisdom of the mountain"},{"level":2,"bab":"+1","fort":"+3","ref":"+3","will":"+0","special":"Slow breath"},{"level":3,"bab":"+2","fort":"+3","ref":"+3","will":"+1","special":"Climb speed +20 ft., bonus feat"},{"level":4,"bab":"+3","fort":"+4","ref":"+4","will":"+1","special":"Resistance to cold 5, fast movement +10 ft."},{"level":5,"bab":"+3","fort":"+4","ref":"+4","will":"+1","special":"Climb speed +30 ft., empty stride"},{"level":6,"bab":"+4","fort":"+5","ref":"+5","will":"+2","special":"Improved slow breath, acrobatic charge"},{"level":7,"bab":"+5","fort":"+5","ref":"+5","will":"+2","special":"Climb speed +40 ft., bonus feat"},{"level":8,"bab":"+6","fort":"+6","ref":"+6","will":"+2","special":"Resistance to cold 10, fast movement +20 ft."},{"level":9,"bab":"+6","fort":"+6","ref":"+6","will":"+3","special":"Climb speed +50 ft., walk on the clouds"},{"level":10,"bab":"+7","fort":"+7","ref":"+7","will":"+3","special":"Immortality of the mountain"}],"classFeaturesText":"Weapon and Armor Proficiency: Cloud anchorites gain no proficiency with any weapon, armor or shield.\n\n Monk Abilities: A cloud anchorite’s class levels stack with her monk levels for determining her unarmed damage and AC bonus.\n\n Climb Speed (Ex): At 1st level, a cloud anchorite gains a climb speed of 10 feet. She gains a +8 racial bonus on all Climb checks. A cloud anchorite must make a Climb check to climb any wall or slope with a DC of more than 0, but she can always choose to take 10, even if rushed or threatened while climbing. She cannot use the run action while climbing. She retains her Dexterity bonus to Armor Class (if any) while climbing, and opponents get no special bonus on their attacks against her while she is climbing. A cloud anchorite in armor (even light armor) or carrying a medium or heavy load loses this extra speed. As the cloud anchorite gains levels, her climb speed increases. At each odd-numbered level, she gains a +10-foot bonus to her current climb speed. If the cloud anchorite already possesses a climb speed (for example, if she possessed a racial climb speed before becoming a cloud anchorite), these bonuses stack with her current climb speed.\n\n Wisdom of the Mountain (Ex): A cloud anchorite adds her Wisdom modifier on Balance, Climb, and Jump checks made in mountain terrain. In addition, the cloud anchorite can always take 10 on a Balance, Climb, or Jump check, even if circumstances would normally prevent her from doing so.\n\n Slow Breath (Ex): At 2nd level, a cloud anchorite’s breathing slows to a fraction of what it used to be. She can hold her breath twice as long as normal, and gains a +2 bonus on all Fortitude saving throws against inhaled poisons, fatigue caused by high elevation, and altitude sickness. At 6th level, her bonus on these Fortitude saving throws increases to +6.\n\n Bonus Feat: At 3rd level and again at 7th level, a cloud anchorite gains a bonus feat. This feat must be selected from the following list, and she must qualify for any prerequisites the feat to be chosen might require: Acrobatic, Agile, Athletic, Cold Endurance, Endurance, Great Fortitude, Improved Cold Endurance, Self-Sufficient, Skill Focus (in any class skill), or Track.\n\n Resistance to Cold (Su): At 4th level, a cloud anchorite gains resistance to cold 5. This increases to resistance to cold 10 at 8th level.\n\n Fast Movement (Ex): At 4th level, a cloud anchorite gains a +10-foot enhancement bonus to her land speed. A cloud anchorite in armor (even light armor) or carrying a medium or heavy load loses this extra speed. At 8th level, this bonus increases to +20 feet.\n\n Empty Stride (Su): At 5th level, a cloud anchorite’s stride is nearly weightless. She gains a +4 bonus on all Balance checks. More impressively, she can walk on the surface of any material into which she would normally sink, such as powdery snow, thin ice, and even water. She may continue to walk on this surface as long as she makes a DC 15 Concentration check. Normally, the Concentration check for this activity is a standard action, so a cloud anchorite may make one move action per round while using her empty stride ability. If she makes a DC 30 Concentration check, she may concentrate on her Empty Stride ability as a move action instead, allowing her to use it and still take one standard action in a round. She does not trigger traps that use pressure plates while using empty stride, nor is her speed impacted by deep snow.\n\n Acrobatic Charge (Ex): At 6th level, a cloud anchorite gains the ability to charge in situations where others cannot. She may charge over difficult terrain that normally slows movement. This enables her to run down steep rock faces, leap down from an outcropping, or tumble over \n small boulders to get to the target of her charge. Depending on the circumstances, she may still need to make appropriate checks (Jump or Tumble checks in particular) to successfully move over the terrain.\n\n Walk on the Clouds (Su): At 9th level, a cloud anchorite can use her empty stride ability as a free action at all times. Additionally, once per day she may use air walk as a quickened spell-like ability. This effect manifests at a caster level equal to her cloud anchorite level.\n\n Immortality of the Mountain (Su): Upon reaching 10th level, a cloud anchorite has achieved the apotheosis she has sought. She no longer has a maximum age, and will never die of old age. Additionally, she no longer has to make saving throws to avoid altitude sickness or fatigue from thin air, and gains a +2 sacred bonus on all Wisdom checks and all saving throws while in mountain terrain."}'::jsonb),
('dnd35.frostburn.class.frostburn-cryokineticist','Cryokineticist','Cryokineticist','Alignment: Any lawful. Skills: Concentration 8 ranks, Craft (alchemy) 1 rank, Knowledge (psionics) 2 ranks. Powers: Able to manifest the energy emanation power.',8,ARRAY[]::text[],ARRAY['prestige']::text[],'v35-frostburn','D&D 3.5 — Frostburn',52,'dnd35','{"id":"frostburn-cryokineticist","name":"Cryokineticist","hitDie":8,"requirements":["Alignment: Any lawful.","Skills: Concentration 8 ranks, Craft (alchemy) 1 rank, Knowledge (psionics) 2 ranks.","Powers: Able to manifest the energy emanation power."],"classSkills":"The cryokineticist’s class skills (and the key ability for each skill) are Climb (Str), Concentration (Con), Craft (any) (Int), Intimidate (Cha), Jump (Str), Knowledge (psionics), and Psicraft (Int). See Chapter 4 of the Player’s Handbook or Chapter 3 of the Expanded Psionics Handbook for skill descriptions.","skillPointsPerLevel":"2 + Int modifier","levels":[{"level":1,"bab":"+0","fort":"+2","ref":"+2","will":"+0","special":"Glacial ray"},{"level":2,"bab":"+1","fort":"+3","ref":"+3","will":"+0","special":"Cold adaptation, frozen fist"},{"level":3,"bab":"+2","fort":"+3","ref":"+3","will":"+1","special":"Bolt of cold"},{"level":4,"bab":"+3","fort":"+4","ref":"+4","will":"+1","special":"Weapon afrost"},{"level":5,"bab":"+3","fort":"+4","ref":"+4","will":"+1","special":"Frostfell creature insight"},{"level":6,"bab":"+4","fort":"+5","ref":"+5","will":"+2","special":"Cold walk"},{"level":7,"bab":"+5","fort":"+5","ref":"+5","will":"+2","special":"Fear no cold"},{"level":8,"bab":"+6","fort":"+6","ref":"+6","will":"+2","special":"Greater weapon afrost"},{"level":9,"bab":"+6","fort":"+6","ref":"+6","will":"+3","special":"Wall of ice"},{"level":10,"bab":"+7","fort":"+7","ref":"+7","will":"+3","special":"Bone chill"}],"classFeaturesText":"Weapon and Armor Proficiency: Cryokineticists gain no proficiency with any weapons, armor, or shields.\n\n Glacial Ray (Ps): A cryokineticist can launch a frigid ray that freezes water and damages living creatures. The ray does 1d12 points of cold damage to any living creature on a successful ranged touch attack (up to 15 feet). The ray also freezes one pint of water per level of cryokineticist.\n\n Cold Adaptation (Ex): At 2nd level, the cryokineticist becomes resistant to cold, gaining a +4 bonus on all saving throws against cold and cold spells and spell-like abilities. In addition, the cryokineticist gains resistance to cold 10.\n\n Frozen Fist (Ps): At 2nd level, the cryokineticist can activate this psi-like ability as a move action. One of the cryokineticist’s clenched fists freezes into a solid block of ice that does him no harm, but causes his unarmed attacks to be treated as armed. A Medium cryokineticist deals 1d6 points of bludgeoning damage and 1d8 points of cold damage instead of any other special damage from the unarmed attack. The bludgeoning damage changes based on size, but the cold damage remains 1d8. This ability lasts a number of rounds equal to the cryokineticist’s class level.\n\n Bolt of Cold (Ps): Beginning at 3rd level, three times per day, the cryokineticist can launch a bolt of psionically manifested cold up to 60 feet at any target in line of sight as a standard action. This psi-like ability is treated as a ranged touch attack and deals 3d6 points of cold damage.\n\n Weapon Afrost (Ps): At 4th level, as a move action, the cryokineticist can cause a melee weapon he wields to become sheathed in a layer of intense cold, granting the weapon the frost special ability (+1d6 points of cold damage on a successful strike). If he lets go of the weapon, the frost dissipates immediately, otherwise it lasts for a number of rounds equal to his cryokineticist class level.\n\n Frostfell Creature Insight (Ex): At 5th level, the cryokineticist gains a +2 insight bonus on attack and damage rolls against all creatures with the cold subtype.\n\n Cold Walk (Ps): Starting at 6th level, the cryokineticist can walk on air that is 32° F or colder (cold, severe cold, extreme cold or unearthly cold temperatures). He moves at his normal speed in all directions, including vertically, but cannot move more than double his speed in a single round. A coldwalker leaves footprints of coldfire in the air that disperse in 2 rounds, but his tread does not deal damage. He must pay 1 power point per round traveled in this fashion.\n\n Fear No Cold (Ex): At 7th level, the cryokineticist is perfectly at home in cold temperatures. He now has a +8 bonus on all saving throws against cold and cold spells and spell-like abilities, and resistance to cold 20. Greater Weapon Afrost (Ps): At 8th level, the cryokineticist’s weapon afrost ability improves, dealing +2d6 points of cold damage on a successful strike. In addition, the cryokineticist can instead choose to apply this ability to his frozen fist (see above), which increases the cold damage of frozen fist from 1d8 to 2d8.\n\n Wall of Ice (Ps): At 9th level, the cryokineticist gains the ability to create walls of ice, as the spell wall of ice. It is a full-round action to use this psi-like ability, and the cryokineticist must expend his psionic focus. The cryokineticist manifests this as a psi-like ability but otherwise it is just as if a 9th-level sorcerer cast the spell wall of ice.\n\n Bone Chill (Ps): At 10th level, the cryokineticist gains the ability to create a massive burst of supernal cold around him, flash-freezing everything in the area. Once per day, the cryokineticist can use this psi-like ability to deal 9d6+21 points of cold damage in a 30-foot-radius burst emanating from himself (Fortitude save DC 15 + Cha modifier for half damage). Any creature failing its Fortitude saving throw against bone chill must succeed on a second Fortitude saving throw at the same DC or die due to the extreme shock of the intense cold."}'::jsonb),
('dnd35.frostburn.class.frostburn-disciple-of-thrym','Disciple of Thrym','Disciple of Thrym','Alignment: Any nongood. Skills: Intimidate 4 ranks, Survival 8 ranks. Base Attack Bonus: +4. Feat: Weapon Focus (greataxe). Special: Cold Endurance feat or cold subtype.',10,ARRAY[]::text[],ARRAY['prestige']::text[],'v35-frostburn','D&D 3.5 — Frostburn',52,'dnd35','{"id":"frostburn-disciple-of-thrym","name":"Disciple of Thrym","hitDie":10,"requirements":["Alignment: Any nongood.","Skills: Intimidate 4 ranks, Survival 8 ranks.","Base Attack Bonus: +4.","Feat: Weapon Focus (greataxe).","Special: Cold Endurance feat or cold subtype."],"classSkills":"The disciple of Thrym’s class skills (and the key ability for each skill) are Concentration (Con), Craft (Int), Diplomacy (Cha), Knowledge (the planes) (Int), Knowledge (religion) (Int), Profession (Wis), Sense Motive (Wis), Speak Language (none), Spellcraft (Int), and Survival (Wis). See Chapter 4 of the Player’s Handbook for skill descriptions.","skillPointsPerLevel":"2 + Int modifier","levels":[{"level":1,"bab":"+1","fort":"+0","ref":"+0","will":"+2","special":"Detect fire, protection of winter","spellsPerDay":[1,null,null,null,null]},{"level":2,"bab":"+2","fort":"+0","ref":"+0","will":"+3","special":"Resistance to fire 5","spellsPerDay":[2,null,null,null,null]},{"level":3,"bab":"+3","fort":"+1","ref":"+1","will":"+3","special":"Powerful grip","spellsPerDay":[2,1,null,null,null]},{"level":4,"bab":"+4","fort":"+1","ref":"+1","will":"+4","special":"Frost greataxe","spellsPerDay":[3,2,null,null,null]},{"level":5,"bab":"+5","fort":"+1","ref":"+1","will":"+4","special":"Agonizing strike 1/day","spellsPerDay":[3,2,1,null,null]},{"level":6,"bab":"+6","fort":"+2","ref":"+2","will":"+5","special":"Resistance to fire 10","spellsPerDay":[3,3,2,null,null]},{"level":7,"bab":"+7","fort":"+2","ref":"+2","will":"+5","special":"Dispel fire","spellsPerDay":[4,3,2,1,null]},{"level":8,"bab":"+8","fort":"+2","ref":"+2","will":"+6","special":"Icy greataxe","spellsPerDay":[4,3,3,2,null]},{"level":9,"bab":"+9","fort":"+3","ref":"+3","will":"+6","special":"Agonizing strike 2/day","spellsPerDay":[4,4,3,2,1]},{"level":10,"bab":"+10","fort":"+3","ref":"+3","will":"+7","special":"Immunity to Fire","spellsPerDay":[4,4,3,3,2]}],"classFeaturesText":"Weapon and Armor Proficiency: Disciples of Thrym are proficient with all simple and martial weapons, with all types of armor, and with shields.\n\n Spells per Day: A disciple of Thrym can cast a small number of divine spells. To cast a spell, the disciple must have a Wisdom score of at least 10 + the spell’s level. The disciple of Thrym’s spells are based on Wisdom, and saving throws against these spells have a DC of 10 + spell level + the disciple’s Wisdom modifier. A disciple of Thrym otherwise casts spells as a cleric does, although he cannot swap out prepared spells to spontaneously cast cure or inflict spells. The disciple’s spell list appears at the end of this prestige class description; when he prepares spells, he may select from any of the spells on this list.\n\n Detect Fire (Sp): At 1st level, the disciple of Thrym can detect fire at will as a cleric of a level equal to his class level.\n\n Protection of Winter (Su): At 1st level, the disciple of Thrym gains greater protection based on the local temperature. In cold areas (temperature at or below 40° F), he gains +1 sacred bonus on all saving throws and a +1 bonus to Armor Class. In areas of extreme cold (below –20° F), the sacred bonus is increased to +2 on all saves and AC. Resistance to Fire (Ex): At 2nd level, the disciple of Thrym gains resistance to fire 5. At 6th level, this increases to resistance to fire 10. Powerful Grip (Ex): At 3rd level, the disciple of Thrym gains a damage bonus equal to half his Strength bonus when he attacks with a greataxe. This means he adds 2 times his Strength bonus on his damage rolls instead of 1–1/2 times his Strength bonus when wielding the weapon in two hands. Frost Greataxe (Sp): At 4th level, as a move action, the disciple of Thrym can cause a greataxe he wields to become sheathed in a layer of intense cold, granting the axe the frost special ability (+1d6 points of cold damage on a successful strike). If he lets go of the axe, the frost dissipates immediately; other wise it lasts for a number of rounds equal to his class level.\n\n Agonizing Strike (Su): At 5th level, the disciple of Thrym gains the ability to focus all the anger and hatred in his frozen heart into a single blow once per day. He makes a normal melee attack; if he hits, he deals +1d6 points of cold damage for every two class levels (+2d6 at 5th, +3d6 at 6th, +4d6 at 8th, and +5d6 at 10th level). If the attack misses, the agonizing strike is still used up for the day. At 9th level, the disciple can perform this strike twice per day.\n\n Dispel Fire (Sp): At 7th level, the disciple of Thrym can dispel fire as a cleric of the same level a number of times per day equal to 1 + his Charisma modifier.\n\n Icy Greataxe (Sp): At 8th level, as a move action, the disciple of Thrym can cause a greataxe he wields to become sheathed in a layer of intense cold, granting the axe the icy burst special ability (+1d6 points of cold damage on a successful strike, plus an extra 2d10 points of cold damage on a successful critical). If he lets go of the axe, the frost dissipates immediately, otherwise it lasts for a number of rounds equal to his class level.\n\n Immunity to Fire (Ex): At 10th level, the disciple of Thrym gains immunity to fire, becoming prepared for the burning flames of Surtur that will destroy the multiverse. Disciple of Thrym Spell List Disciples of Thrym choose their spells from the following list: 1st Level: cause fear, corrupt weapon, detect fire*, divine favor, doom, ease of breath*, lesser frostburn*, magic weapon, obscuring mist, protection from good/law, lesser shivering touch*. 2nd Level: blood snow*, bull’s strength, chill metal, conjure ice object*, eagle’s splendor, fog cloud, frost weapon*, zone of glacial cold*. 3rd Level: binding snow*, ice shape*, lesser aura of cold*, meld into ice*, shivering touch*, sleet storm. 4th Level: boreal wind*, glacial globe of invulnerability*, frostburn*, hibernal healing*, summon giants*. 5th Level: dispel fire*, dispel good/law, entomb*, frostbite*, ice storm, stoneskin, wall of ice. *New spell described in Chapter 5."}'::jsonb),
('dnd35.frostburn.class.frostburn-frost-mage','Frost Mage','Frost Mage','Feats: Frozen Magic. Skills: Knowledge (arcana) 8 ranks. Spells: Able to cast 1st-level arcane spells. Special: The character must spend 24 hours unprotected in a blizzard.',4,ARRAY[]::text[],ARRAY['prestige']::text[],'v35-frostburn','D&D 3.5 — Frostburn',52,'dnd35','{"id":"frostburn-frost-mage","name":"Frost Mage","hitDie":4,"requirements":["Feats: Frozen Magic.","Skills: Knowledge (arcana) 8 ranks.","Spells: Able to cast 1st-level arcane spells.","Special: The character must spend 24 hours unprotected in a blizzard."],"classSkills":"The frost mage’s class skills (and the key ability for each skill) are Concentration (Con), Craft (alchemy) (Int), Knowledge (all skills, taken individually) (Int), Profession (Wis), Search (Int), and Spellcraft (Int). See Chapter 4 of the Player’s Handbook for skill descriptions.","skillPointsPerLevel":"2 + Int modifier","levels":[{"level":1,"bab":"+0","fort":"+0","ref":"+0","will":"+2","special":"Natural armor increase (+1)"},{"level":2,"bab":"+1","fort":"+0","ref":"+0","will":"+3","special":"Resistance to cold 10"},{"level":3,"bab":"+1","fort":"+1","ref":"+1","will":"+3","special":"Gain knowledge"},{"level":4,"bab":"+2","fort":"+1","ref":"+1","will":"+4","special":"Natural armor increase (+2), Piercing Cold"},{"level":5,"bab":"+2","fort":"+1","ref":"+1","will":"+4","special":"Gain knowledge"},{"level":6,"bab":"+3","fort":"+2","ref":"+2","will":"+5","special":""},{"level":7,"bab":"+3","fort":"+2","ref":"+2","will":"+5","special":"Natural armor increase (+3), Gain knowledge"},{"level":8,"bab":"+4","fort":"+2","ref":"+2","will":"+6","special":""},{"level":9,"bab":"+4","fort":"+3","ref":"+3","will":"+6","special":"Gain knowledge"},{"level":10,"bab":"+5","fort":"+3","ref":"+3","will":"+7","special":"Natural armor increase (+4), one with cold"}],"classFeaturesText":"Weapon and Armor Proficiency: Frost mages gain no proficiency with any weapons, armor, or shields. Spells per Day/Spells Known: At every level gained in the frost mage class, the character gains new spells per day (and spells known, if applicable) as if he had also gained a level in a spellcasting class he belonged to before adding the prestige class. He does not, however, gain any other benefit a character of that class would have gained (metamagic or item creation bonus feats, hit points beyond those he receives from the prestige class, and so on), except for an increased effective level of spellcasting. If a character has more than one spellcasting class before becoming a frost mage, he must decide to which class he adds the new level for purposes of determining spells per day and spells known.\n\n Natural Armor Increase (Ex): At 1st, 4th, 7th, and 10th level, a frost mage’s body becomes more like the ice he venerates. His skin turns whiter and colder to the touch as the permanent layer of frost grows deeper. This provides an increase to the character’s existing natural armor, as indicated on Table 3–5 (the numbers represent the total increase gained to that point) and he takes no damage from cold environments. In warm temperatures, the frost continually evaporates and replenishes itself, enshrouding the frost mage in a wispy vapor.\n\n Resistance to Cold (Ex): Starting at 2nd level, the frost mage’s icy skin grants him resistance to cold 10.\n\n Gain Knowledge (Ex): Beginning at 3rd level, the frost mage gains knowledge of the spell conjure ice beast I, if he does not already have it. Former wizards get to add this spell to their spellbooks for free, and former sorcerers and bards get to add this spell to their spells known, even if this takes them over their normal limit. For each two levels gained in the prestige class, he gains knowledge of the next higher level in the conjure ice beast spell progression (conjure ice beast II at 5th level, conjure ice beast III at 7th level, and conjure ice beast IV at 9th level). At 7th level, in addition to gaining conjure ice beast III, the frost mage gains animate snow as a spell known. At 9th level, in addition to gaining conjure ice beast IV, the frost mage gains frostfell as a spell known. This class feature does not change the level of the spell. A frost mage still must have a spell slot of the appropriate level to prepare or cast a spell acquired through the gain knowledge ability.\n\n Piercing Cold: At 4th level, the frost mage gains Piercing Cold as a bonus metamagic feat. In addition to the normal benefits of the feat, the frost mage bypasses all resistances and immunities to cold granted by spells and spell-like effects of magic items (for example, a ring of minor energy resistance [cold]).\n\n One with Cold (Ex): At 10th level, the frost mage’s body has become perfectly adapted to cold energy. He gains the cold subtype, granting him immunity to cold. His oneness with cold, however, makes him more susceptible to flame. Just like any other creature with the cold subtype, he gains vulnerability to fire, which means he takes half again as much (+50%) damage as normal from fire, regardless of whether or not a saving throw is allowed, or if the save is a success or a failure.","advancesExistingSpellcasting":true}'::jsonb),
('dnd35.frostburn.class.frostburn-frostrager','Frostrager','Frostrager','Base Attack Bonus: +6. Skills: Intimidate 4 ranks, Survival 4 ranks. Feats: Frozen Berserker, Improved Unarmed Strike, Power Attack. Special: Rage as a class ability. Special: The character must have been reduced to fewer than 0 hit points by cold damage (either from magical cold attacks or by taking enough damage from exposure to extreme cold environments). Whether or not this trauma is what allows the frostrage to take root in the character’s soul, or if the trauma merely unhinges the character’s mind enough that he decides to become a frostrager, is unknown.',12,ARRAY[]::text[],ARRAY['prestige']::text[],'v35-frostburn','D&D 3.5 — Frostburn',52,'dnd35','{"id":"frostburn-frostrager","name":"Frostrager","hitDie":12,"requirements":["Base Attack Bonus: +6.","Skills: Intimidate 4 ranks, Survival 4 ranks.","Feats: Frozen Berserker, Improved Unarmed Strike, Power Attack.","Special: Rage as a class ability.","Special: The character must have been reduced to fewer than 0 hit points by cold damage (either from magical cold attacks or by taking enough damage from exposure to extreme cold environments). Whether or not this trauma is what allows the frostrage to take root in the character’s soul, or if the trauma merely unhinges the character’s mind enough that he decides to become a frostrager, is unknown."],"classSkills":"The frostrager’s class skills (and the key ability for each skill) are Climb (Str), Intimidate (Cha), Jump (Str), Listen (Wis), Survival (Wis), and Swim (Str). See Chapter 4 of the Player’s Handbook for skill descriptions.","skillPointsPerLevel":"2 + Int modifier","levels":[{"level":1,"bab":"+1","fort":"+2","ref":"+0","will":"+0","special":"Frostrage, freezing blood"},{"level":2,"bab":"+2","fort":"+3","ref":"+0","will":"+0","special":"One-two punch"},{"level":3,"bab":"+3","fort":"+3","ref":"+1","will":"+1","special":"Absorb cold"},{"level":4,"bab":"+4","fort":"+4","ref":"+1","will":"+1","special":"Improved frostrage"},{"level":5,"bab":"+5","fort":"+4","ref":"+1","will":"+1","special":"Rend"}],"classFeaturesText":"Weapon and Armor Proficiency: Frostragers gain no proficiency with any weapon, armor, or shields.\n\n Frostrage (Su): While raging, the character grows larger and more massive, and his freezing sweat forms icicles as it streams out of his pores, coating his body in a glittering crust of ice. The frostrager’s actual size category does not change (nor does his space/reach), but he does gain a +4 natural armor bonus to Armor Class from the sheets of ice that form over his body. In addition, a frostrager’s unarmed attacks deal 1d6 points of damage plus 1d4 points of cold damage on a successful hit. If the frostrager is Small, his unarmed attack deals 1d4 points of damage, and if the frostrager is Large, his unarmed attack deals 1d8 points of damage.\n\n Freezing Blood (Su): At 1st level, a frostrager’s blood becomes freezing cold. His wounds instantly freeze over and stop bleeding; he is immune to attacks that cause wounding effects. If reduced to negative hit points, he automatically stabilizes. He still takes 1 point of damage if he takes any actions while at 0 or negative hit points, however.\n\n One-Two Punch (Ex): At 2nd level, while making an unarmed attack, the frostrager may make one extra attack in a round at his highest base attack bonus, but each attack made in that round (the extra one and the normal ones) take a –2 penalty.\n\n Absorb Cold (Su): At 3rd level, while raging, the frostrager not only gains immunity to cold, but it heals him. For every 2 points of cold damage that would have otherwise have been dealt by an attack, the frostrager heals 1 point of damage.\n\n Improved Frostrage (Su): At 4th level while raging, the frostrager’s natural armor bonus increases to +6. His unarmed attacks deal 1d8 points of damage plus 1d6 points of cold damage on a successful hit. If the frostrager is Small, his unarmed attack deals 1d6 points of damage, and if the frostrager is Large, his unarmed attack deals 2d6 points of damage.\n\n Rend (Ex): At 5th level, a frostrager gains the ability to rend a target. In any round that the frostrager hits the same foe with two or more unarmed attacks, he immediately deals an additional 2d8 points of damage (plus 1-1/2 times his Strength bonus), plus an additional 1d6 points of cold damage. If he is Small, his rend deals 2d6 points of damage; if he is Large, his rend deals 3d8 points of damage."}'::jsonb),
('dnd35.frostburn.class.frostburn-knight-of-the-iron-glacier','Knight of the Iron Glacier','Knight of the Iron Glacier','Alignment: Lawful good or lawful neutral. Skills: Handle Animal 5 ranks, Ride 9 ranks, Survival 2 ranks. Feats: Animal Affinity, Exotic Weapon Proficiency (bastard sword), Mounted Combat, Ride-By Attack. Special: Before a character is accepted into the Order of the Iron Glacier, she must first prove to the order that her intentions are noble and true. Typically, this means the character must undertake some form of task or quest in a region of the frostfell, such as defending a remote village from an attack by orcs or slaying a white dragon that has been menacing a region. Usually, high-ranking knights will send aspiring knights on a particular quest, but sometimes they waive this requirement for someone they have seen upholding Iron Glacier ideals even though she has not herself approached the order for membership.',10,ARRAY[]::text[],ARRAY['prestige']::text[],'v35-frostburn','D&D 3.5 — Frostburn',52,'dnd35','{"id":"frostburn-knight-of-the-iron-glacier","name":"Knight of the Iron Glacier","hitDie":10,"requirements":["Alignment: Lawful good or lawful neutral.","Skills: Handle Animal 5 ranks, Ride 9 ranks, Survival 2 ranks.","Feats: Animal Affinity, Exotic Weapon Proficiency (bastard sword), Mounted Combat, Ride-By Attack.","Special: Before a character is accepted into the Order of the Iron Glacier, she must first prove to the order that her intentions are noble and true. Typically, this means the character must undertake some form of task or quest in a region of the frostfell, such as defending a remote village from an attack by orcs or slaying a white dragon that has been menacing a region. Usually, high-ranking knights will send aspiring knights on a particular quest, but sometimes they waive this requirement for someone they have seen upholding Iron Glacier ideals even though she has not herself approached the order for membership."],"classSkills":"The Knight of the Iron Glacier class skills (and the key ability for each skill) are Craft (Wis), Diplomacy (Cha), Handle Animal (Cha), Heal (Wis), Knowledge (geography) (Int), Knowledge (history) (Int), Knowledge (local) (Int), Listen (Wis), Ride (Dex), Sense Motive (Wis), Spot (Wis), and Survival (Wis). See Chapter 4 of the Player’s Handbook for skill descriptions.","skillPointsPerLevel":"2 + Int modifier","levels":[{"level":1,"bab":"+1","fort":"+2","ref":"+0","will":"+2","special":"Warmount"},{"level":2,"bab":"+2","fort":"+3","ref":"+0","will":"+3","special":"Frostfell awareness +2"},{"level":3,"bab":"+3","fort":"+3","ref":"+1","will":"+3","special":""},{"level":4,"bab":"+4","fort":"+4","ref":"+1","will":"+4","special":"Rally the troops"},{"level":5,"bab":"+5","fort":"+4","ref":"+1","will":"+4","special":"Frostfell awareness +4"},{"level":6,"bab":"+6","fort":"+5","ref":"+2","will":"+5","special":""},{"level":7,"bab":"+7","fort":"+5","ref":"+2","will":"+5","special":"Oath of wrath"},{"level":8,"bab":"+8","fort":"+6","ref":"+2","will":"+6","special":"Frostfell awareness +6"},{"level":9,"bab":"+9","fort":"+6","ref":"+3","will":"+6","special":""},{"level":10,"bab":"+10","fort":"+7","ref":"+3","will":"+7","special":"Overwhelming odds"}],"classFeaturesText":"Weapon and Armor Proficiency: Knights of the Iron Glacier gain no proficiency with weapons, armor, or shields.\n\n Warmount: Upon becoming a Knight of the Iron Glacier, the character is awarded his own specially bred and trained mount, a war megaloceros. The character is expected to care for, feed, and protect his warmount; when a mission does not require the aid of the warmount, it can be stabled at no cost at any Iron Glacier stronghold.\n\n War Megaloceros: Large animal; HD 7d8+28; hp 59; Init +1; Spd 50 ft.; AC 14, touch 10, flat-footed 13; Base Atk +5; Grp +15; Atk or Full Atk +10 melee (1d8+9, gore); Space/Reach 10 ft./5 ft.; SA improved grab, stampede, toss; SQ combative mount, low-light vision, scent; AL N; SV Fort +10, Ref +8, Will +6; Str 23, Dex 12, Con 19, Int 2, Wis 13, Cha 8.\n\n Skills and Feats: Listen +9, Spot +9; Alertness, Lightning Reflexes, Run.\n\n Combative Mount (Ex): A rider on a war megaloceros gains a +2 circumstance bonus on all Ride checks. A war megaloceros is trained for war.\n\n Skills: A war megaloceros gains a +1 racial bonus on Listen and Spot checks. If the knight has enough paladin levels that he has a paladin’s special mount, the character has the option of dismissing his current special mount and replacing it with a war megaloceros special mount. In this case, the warmount functions identically to the paladin’s special mount except for the improved base statistics given above. The character’s paladin levels and Knight of the Iron Glacier levels stack for purposes of determining what sort of bonus Hit Dice, natural armor adjustments, Strength adjustments, base Intelligence, and special abilities the special mount gains.\n\n Frostfell Awareness (Ex): A Knight of the Iron Glacier trains extensively on how to notice signs of danger in the frostfell, and is quite adept at spotting ambushes and similar danger. Starting at 2nd level, as long as he is in the frostfell, he gains a +2 competence bonus on all Initiative, Listen, and Spot checks. This bonus increases to +4 at 5th level and to +6 at 8th level.\n\n Rally the Troops (Su): At 4th level, the Knight of the Iron Glacier’s ability to inspire allies has become so potent that his words take on a supernatural divine power. Once per day, the knight may speak to a number of listeners equal to his class level plus his Charisma modifier. \n He must speak for at least one minute, after which all listeners are filled with hope and bravery. For the next hour, these creatures gain a +2 morale bonus on attack rolls and Will saving throws, and have immunity to fear (magic or otherwise).\n\n Oath of Wrath (Su): Beginning at 7th level, as a free action, the Knight of the Iron Glacier may select a single opponent within 60 feet and swear an oath to defeat him. For the duration of the encounter, the knight gains a +2 morale bonus on melee attack rolls, weapon damage rolls, saving throws, and skill checks made against the challenged target. This effect ends immediately if the Knight of the Iron Glacier makes an attack or casts a spell targeted at any hostile creature other than the challenged target. Attacks of opportunity and spells cast on allies do not end the effect, nor do area spells such as fireball that catch other creatures in the area (as long as the challenged target is included in the area). The Knight of the Iron Glacier can use oath of wrath once per day. Overwhelming Odds (Ex): A 10th-level Knight of the Iron Glacier has expelled from his mind and soul the very notion of a hopeless battle; no matter how slight, there is always a chance for victory. Whenever the Knight of the Iron Glacier faces an enemy in combat that has 3 or more Hit Dice or levels than he does, the knight’s faith that he shall prevail grants him damage reduction 3/— and a +2 insight bonus to his Armor Class and all saving throws. These benefits apply only against attacks made against the knight from a creature whose levels or Hit Dice exceed the knight’s by 3 or more; if a creature with fewer Hit Dice or levels attacks the knight, he does not receive these benefits."}'::jsonb),
('dnd35.frostburn.class.frostburn-primeval','Primeval','Primeval','Alignment: Any nonlawful. Base Attack Bonus: +8. Skills: Handle Animal 5 ranks, Knowledge (nature) 5 ranks, Survival 5 ranks. Feats: Endurance, Self-Sufficient, Toughness.',10,ARRAY[]::text[],ARRAY['prestige']::text[],'v35-frostburn','D&D 3.5 — Frostburn',52,'dnd35','{"id":"frostburn-primeval","name":"Primeval","hitDie":10,"requirements":["Alignment: Any nonlawful.","Base Attack Bonus: +8.","Skills: Handle Animal 5 ranks, Knowledge (nature) 5 ranks, Survival 5 ranks.","Feats: Endurance, Self-Sufficient, Toughness."],"classSkills":"The primeval class skills (and the key ability for each skill) are Climb (Str), Concentration (Con), Handle Animal (Cha), Intimidate (Cha), Jump (Str), Knowledge (nature) (Int), Listen (Wis), Spot (Wis), Survival (Wis), and Swim (Str). See Chapter 4 of the Player’s Handbook for skill descriptions.","skillPointsPerLevel":"2 + Int modifier","levels":[{"level":1,"bab":"+1","fort":"+2","ref":"+0","will":"+0","special":"Primeval form 1/day, animal empathy"},{"level":2,"bab":"+2","fort":"+3","ref":"+0","will":"+0","special":"Regression 1, low-light vision"},{"level":3,"bab":"+3","fort":"+3","ref":"+1","will":"+1","special":"Feral power"},{"level":4,"bab":"+4","fort":"+4","ref":"+1","will":"+1","special":"Primeval form 2/day"},{"level":5,"bab":"+5","fort":"+4","ref":"+1","will":"+1","special":"Regression 2, scent"},{"level":6,"bab":"+6","fort":"+5","ref":"+2","will":"+2","special":"Feral power 2"},{"level":7,"bab":"+7","fort":"+5","ref":"+2","will":"+2","special":"Primeval form 3/day"},{"level":8,"bab":"+8","fort":"+6","ref":"+2","will":"+2","special":"Regression 3, fast movement"},{"level":9,"bab":"+9","fort":"+6","ref":"+3","will":"+3","special":"Feral power 3"},{"level":10,"bab":"+10","fort":"+7","ref":"+3","will":"+3","special":"Primeval form 4/day, primeval shapechanger"}],"classFeaturesText":"Weapon and Armor Proficiency: Primevals gain no proficiency with weapons, armor, or shields. (They are proficient with their natural weapons while in primeval form, though.)\n\n Primeval Form (Su): The primary ability of the primeval is the supernatural ability to assume an alternate form. This functions similarly to the druid’s wild shape ability, except the alternate form chosen must be selected when the character takes his first level of primeval and cannot be changed after that. Each time the character changes form with this ability, he assumes the same form. At 1st level, he may change shape into his primeval form once per day. He can use this ability one additional time each day at 4th level, 7th level, and again at 10th level. This ability functions like the polymorph spell, except as noted here. It lasts for 1 minute per primeval level, or until he changes back. Changing form (into either form) is a standard action and doesn’t provoke attacks of opportunity. The primeval does not assume the animal’s physical ability scores. Instead, he adds the animal’s ability score –10 (for even scores) or –11 (for odd scores) to his own ability scores. For example, a primeval with a Strength score of 16 who assumes the form of a dire lion (Strength 25) adds +14 to his normal Strength of 16 to determine his Strength score in his primeval form. Remember, items that enhance the character’s ability scores may be rendered inoperative by his change in form. The primeval loses his ability to speak while in primeval form because he is limited to the sounds that the form can make naturally. The primeval form chosen must be a prehistoric animal of some sort (dinosaur, dire animal, or other creature approved by the DM). The primeval form chosen must have no more than 8 HD and cannot be more than one size category larger than the primeval (so a Small character is limited to Medium animals or smaller, and a Medium character is limited to Large or smaller animals). The primeval form can be from any terrain familiar to the character. Appropriate primeval forms for a frostfell environment from the Monster Manual and this book include the dire lion, dire wolf, dire wolverine, and megaloceros. If the primeval has the wild shape ability from other class levels, he may use wild shape to assume his primeval form. He cannot use his primeval form ability to wild shape, however.\n\n Animal Empathy (Ex): In any form, the primeval can communicate with animals of his chosen primeval form (or related types). For example, a primeval whose primeval form is a dire wolf may communicate with wolves and dire wolves. He gains a +4 bonus on Charisma-based checks against animals of his chosen primeval form and related animals.\n\n Regression (Su): As a primeval gains levels, he begins to physically regress into a more primal, feral version of himself. At 2nd level, the primeval reduces his Intelligence and Charisma scores by 1 point (to a minimum of 3) and gains 1 point of Strength, Dexterity, Constitution, and Wisdom. At 5th level, he repeats his regression, losing an additional point of Intelligence and Charisma, and gaining an additional point to the rest of his ability scores. At 8th level, the primeval regresses again, losing a third point of Intelligence and Charisma but gaining a third point to the rest of his ability scores.\n\n Low-Light Vision (Ex): In any form, the primeval gains low-light vision at 2nd level. He can see twice as far as a human in starlight, moonlight, torchlight, and similar conditions of poor illumination. He retains the ability to distinguish color and detail under these conditions. If the primeval already has racial low-light vision, he can instead see four times as far as a human.\n\n Feral Power (Ex): As the primeval gains levels, his primeval form grows stronger and tougher, as shown below: Primeval Class Level Characteristic 3rd 6th 9th Strength +2 +4 +6 Dexterity +2 +2 +2 Constitution +2 +4 +4 Natural armor +2 +4 +8 These bonuses are not cumulative. For example, a 6th-level primeval whose primeval form is a dire lion has Str 29, Dex 17, Con 21, and a natural armor bonus of +8, instead of Str 25, Dex 15, Con 17, and natural armor +4.\n\n Scent (Ex): At 5th level, the primeval form gains the scent special quality in any form.\n\n Fast Movement (Ex): As he grows closer to his animal spirit, the primeval becomes quicker in his humanoid form. At 8th level, his base land speed improves by 10 feet. This benefit does not apply if the primeval is wearing heavy armor or carrying a heavy load. Primeval Shapechanger (Su): The primeval unites with his animal spirit at 10th level. His type changes to magical beast (shapechanger), which means that he is no longer subject to spells that affect humanoids. In addition, he gains damage reduction 10/ magic in any form. His natural attacks (but not weapon attacks) overcome damage reduction as if they were magic weapons."}'::jsonb),
('dnd35.frostburn.class.frostburn-rimefire-witch','Rimefire Witch','Rimefire Witch','Skills: Concentration 6 ranks, Knowledge (history) 6 ranks, Knowledge (religion) 9 ranks, Spellcraft 6 ranks. Feats: Iron Will, Mark of Hleid. Spells: Able to cast 1st-level divine spells. Patron Deity: Hleid. Special: Once a character meets all the requirements listed above, she soon has a vivid dream in which she receives a call from a rimefire eidolon. Once she wakes from the dream, she knows the most direct route to the rimefire eidolon’s iceberg, as if she had cast discern location to find it. This call does not force the character to answer, but until she travels to the iceberg and accepts the bond of the rimefire eidolon that dwells within, she cannot take any levels of rimefire witch. The journey to the iceberg should be played out as a minor quest, perhaps with some encounters with Iborighu cultists bent on preventing the rise of a new rimefire witch.',6,ARRAY[]::text[],ARRAY['prestige']::text[],'v35-frostburn','D&D 3.5 — Frostburn',52,'dnd35','{"id":"frostburn-rimefire-witch","name":"Rimefire Witch","hitDie":6,"requirements":["Skills: Concentration 6 ranks, Knowledge (history) 6 ranks, Knowledge (religion) 9 ranks, Spellcraft 6 ranks.","Feats: Iron Will, Mark of Hleid.","Spells: Able to cast 1st-level divine spells.","Patron Deity: Hleid.","Special: Once a character meets all the requirements listed above, she soon has a vivid dream in which she receives a call from a rimefire eidolon. Once she wakes from the dream, she knows the most direct route to the rimefire eidolon’s iceberg, as if she had cast discern location to find it. This call does not force the character to answer, but until she travels to the iceberg and accepts the bond of the rimefire eidolon that dwells within, she cannot take any levels of rimefire witch. The journey to the iceberg should be played out as a minor quest, perhaps with some encounters with Iborighu cultists bent on preventing the rise of a new rimefire witch."],"classSkills":"The rimefire witch’s class skills (and the key ability for each skill) are Climb (Str), Concentration (Con), Diplomacy (Cha), Gather Information (Cha), Heal (Wis), Jump (Str), Knowledge (arcana) (Int), Knowledge (history) (Int), Knowledge (religion) (Int), Sense Motive (Wis), Spellcraft (Int), and Swim (Str). See Chapter 4 of the Player’s Handbook for skill descriptions.","skillPointsPerLevel":"2 + Int modifier","levels":[{"level":1,"bab":"+0","fort":"+2","ref":"+0","will":"+2","special":"Rimefire bond, detect minion of Iborighu"},{"level":2,"bab":"+1","fort":"+3","ref":"+0","will":"+3","special":""},{"level":3,"bab":"+1","fort":"+3","ref":"+1","will":"+3","special":"Rimefire bolt (1d6)"},{"level":4,"bab":"+2","fort":"+4","ref":"+1","will":"+4","special":"Ice skate"},{"level":5,"bab":"+2","fort":"+4","ref":"+1","will":"+4","special":""},{"level":6,"bab":"+3","fort":"+5","ref":"+2","will":"+5","special":"Rimefire bolt (2d6)"},{"level":7,"bab":"+3","fort":"+5","ref":"+2","will":"+5","special":"Word of recall"},{"level":8,"bab":"+4","fort":"+6","ref":"+2","will":"+6","special":""},{"level":9,"bab":"+4","fort":"+6","ref":"+3","will":"+6","special":"Rimefire bolt (3d6)"},{"level":10,"bab":"+5","fort":"+7","ref":"+3","will":"+7","special":"Iceberg, rimefire apotheosis"}],"classFeaturesText":"Weapon and Armor Proficiency: Rimefire witches gain proficiency with the trident. The trident is the favored weapon of Hleid, and many rimefire witches choose to wield tridents as well. They gain no other proficiency with weapons, armor, or shields. Spells per Day/Spells Known: When a new rimefire witch level is gained, the character gains new spells per day (and spells known, if applicable) as if she had also gained a level in a spellcasting class she belonged to before adding the prestige class. She does not, however, gain any other benefit a character of that class would have gained (improved chance of controlling or rebuking undead, metamagic or item creation feats, and so on), except for an increased effective level of spellcasting. If a character had more than one spellcasting class before becoming a rimefire witch, she must decide to which class she adds the new level for purposes of determining spells per day and spells known.\n\n Rimefire Bond (Su): A rimefire witch becomes bonded on a deeply spiritual level with the rimefire eidolon that selected her as its guardian. Both the witch and the eidolon are constantly aware of the other’s location and condition, as if both were under the effects of a status spell. This is a permanent effect that cannot be dispelled or destroyed. The bond also shores up the mind and will to live of the witch and her eidolon; both gain a +2 morale bonus on all saving throws against mind-affecting and death effects while the other is alive. A rimefire bond is powerful enough that it even extends across planes. If a rimefire witch or her eidolon is killed, this bond is broken. A surviving rimefire witch loses all her supernatural and spell-like abilities granted by this class (but not her spellcasting ability) until she restores the slain eidolon to life and returns it to its iceberg. A surviving eidolon does not lose any of its abilities, and typically waits for a year before sending out a call for a new guardian. If the slain member of the bond is brought back to life within a year of death, the rimefire bond instantly reforges itself despite any physical distance between the two. If more than a year has passed, the rimefire witch does not regain her powers but within a week she is contacted in her dreams by a new rimefire eidolon; once she travels to its iceberg and accepts its bond of rimefire she immediately regains her lost powers.\n\n Detect Minion of Iborighu (Sp): A rimefire witch possesses the spell-like ability to detect minions of Iborighu at will. This spell-like ability functions like detect evil, except that it detects the presence or absence of devotion to Iborighu in a living creature’s aura and soul. Undetectable alignment can block this ability, as can certain magic items that have similar effects, such as the mantle of hidden faith.\n\n Rimefire Bolt (Su): At 3rd level, a rimefire witch’s bond with her eidolon becomes powerful enough that she can summon and direct a bolt of rimefire, as long as she is currently in the boundaries of a frostfell. Summoning and directing a rimefire bolt is a standard action. Rimefire bolts have a range of 30 feet and attack as ranged touch attacks, dealing damage equal to 1d6 + the witch’s Charisma modifier. Half this damage is cold damage and half is fire damage; for more information on rimefire, see page 17. At 6th level, a rimefire witch deals cold damage equal to 2d6 + her Charisma modifier with her rimefire bolt. At 9th level, a rimefire witch deals cold damage equal to 3d6 + her Charisma modifier with her rimefire bolt.\n\n Ice Skate (Sp): At 4th level, a rimefire witch gains the ability to use ice skate as a spell-like ability. She can use this ability a number of times each day equal to her Charisma modifier (minimum of once per day), at a caster level equal to her rimefire witch level.\n\n Word of Recall (Sp): At 7th level, a rimefire witch gains the ability to use word of recall as a spell-like ability. She can use this ability once per day, and it always recalls her to the chamber of her bonded rimefire eidolon.\n\n Iceberg (Sp): At 10th level, a rimefire witch gains the ability to use iceberg as a spell-like ability. She can use this ability once per day, at a caster level equal to her rimefire witch level.\n\n Rimefire Apotheosis (Su): Upon achieving 10th level, a rimefire witch undergoes a dramatic transformation as the bond with her eidolon physically changes her into a fey creature. Her type immediately changes to fey, and she can no longer be affected by effects that target her old type; she does become susceptible to attacks and effects that harm or aid fey. She gains low-light vision, damage reduction \n /cold iron, and a +2 racial bonus to her Charisma score as her skin and hair become light blue or white in color. Once she undergoes rimefire apotheosis, the death of her bonded eidolon does not cause the loss of her supernatural or spellcasting abilities.","advancesExistingSpellcasting":true}'::jsonb),
('dnd35.frostburn.class.frostburn-stormsinger','Stormsinger','Stormsinger','Skills: Concentration 8 ranks, Knowledge (arcana) 8 ranks, Knowledge (geography) 4 ranks, Knowledge (nature) 4 ranks, Perform (sing) 8 ranks, Spellcraft 4 ranks. Feats: Magical Aptitude, Storm Magic. Special: The stormsinger must have the bardic music class ability.',6,ARRAY[]::text[],ARRAY['prestige']::text[],'v35-frostburn','D&D 3.5 — Frostburn',52,'dnd35','{"id":"frostburn-stormsinger","name":"Stormsinger","hitDie":6,"requirements":["Skills: Concentration 8 ranks, Knowledge (arcana) 8 ranks, Knowledge (geography) 4 ranks, Knowledge (nature) 4 ranks, Perform (sing) 8 ranks, Spellcraft 4 ranks.","Feats: Magical Aptitude, Storm Magic.","Special: The stormsinger must have the bardic music class ability."],"classSkills":"The stormsinger’s class skills (and the key ability for each skill) are Climb (Str), Concentration (Con), Craft (Int), Diplomacy (Cha), Jump (Str), Knowledge (arcana) (Int), Knowledge (geography) (Int), Knowledge (nature) (Int), Listen (Wis), Perform (Cha), Profession (Wis), Spellcraft (Int), Spot (Wis), Survival (Wis), and Swim (Str). See Chapter 4 of the Player’s Handbook for skill descriptions.","skillPointsPerLevel":"4 + Int modifier","levels":[{"level":1,"bab":"+0","fort":"+0","ref":"+2","will":"+2","special":"Bardic music, stormsong (gust of wind)"},{"level":2,"bab":"+1","fort":"+0","ref":"+3","will":"+3","special":"Stormpower"},{"level":3,"bab":"+1","fort":"+1","ref":"+3","will":"+3","special":"Stormsong (thunderstrike)"},{"level":4,"bab":"+2","fort":"+1","ref":"+4","will":"+4","special":"Resistance to electricity 5"},{"level":5,"bab":"+2","fort":"+1","ref":"+4","will":"+4","special":"Stormsong (control winds)"},{"level":6,"bab":"+3","fort":"+2","ref":"+5","will":"+5","special":"Resistance to electricity 10"},{"level":7,"bab":"+3","fort":"+2","ref":"+5","will":"+5","special":"Stormsong (winter’s ballad)"},{"level":8,"bab":"+4","fort":"+2","ref":"+6","will":"+6","special":"Resistance to electricity 15"},{"level":9,"bab":"+4","fort":"+3","ref":"+6","will":"+6","special":"Stormsong (great thunderstrike)"},{"level":10,"bab":"+5","fort":"+3","ref":"+7","will":"+7","special":"Stormsong (storm of vengeance)"}],"classFeaturesText":"Weapon and Armor Proficiency: Stormsingers gain no proficiency with any weapon, armor, or shields. Spells per Day/Spells Known: At each stormsinger level, the character gains new spells per day (and spells known, if applicable) as if she had also gained a level in a spellcasting class she belonged to before adding the prestige class. She does not, however, gain any other benefit a character of that class would have gained (improved chance of controlling or rebuking undead, metamagic or item creation feats, and so on), except for an increased effective level of spellcasting. If a character had more than one spellcasting class before becoming a stormsinger, she must decide to which class she adds the new level for purposes of determining spells per day and spells known.\n\n Bardic Music: A stormsinger’s class level stacks with any levels of bard she has for purposes of determining the number of times per day she may use bardic music. Many of the stormsinger’s high-level abilities require her to use bardic music as well. When a stormsinger uses her bardic music ability to create a stormsong effect (see below), it counts as one (or more) uses of her bardic music for the day.\n\n Stormsong: The stormsinger can use her bardic music ability to create various storm-related effects in addition to the normal uses of bardic music. Additionally, the stormsinger can detect the approach of a natural storm 24 hours in advance of it reaching the character’s current location.\n\n Gust of Wind (Sp): A stormsinger of 1st level or higher with 9 or more ranks in Perform (sing) can use bardic music to generate a gust of wind, as the spell of the same name. Her caster level is equal to her ranks in Perform (sing), with a maximum caster level of 20th.\n\n Thunderstrike (Su): At 3rd level, a stormsinger with 11 or more ranks in Perform (sing) can use bardic music to unleash a deadly thunderbolt. The bolt can be targeted at any one creature within 60 feet, and the stormsinger must make a successful ranged touch attack to hit the target. If she hits, the stormsinger then makes a Perform (sing) check; the result indicates how much electricity damage the thunderbolt deals. A Reflex save (DC 10 + stormsinger’s class level + Cha modifier) halves the damage. If the creature fails its Reflex save, it must make a Fortitude save (same DC) or be deafened for a number of rounds equal to the damage dealt.\n\n Control Winds (Sp): At 5th level, a stormsinger with 13 or more ranks in Perform (sing) can use bardic music to cast control winds. This functions like the spell of the same name, except that the duration of the effect is concentration plus 3 rounds, and the save DC is 10 + the stormsinger’s class level + Charisma modifier. The stormsinger’s caster level is equal to her ranks in Perform (sing), with a maximum caster level of 20th.\n\n Winter’s Ballad (Su): At 7th level, a stormsinger with 15 or more ranks in Perform (sing) can use bardic music to cast control weather. This functions like the spell of the same name, except that the duration of the effect is concentration plus 1d6 hours. The stormsinger’s caster level is equal to her ranks in Perform (sing), with a maximum caster level of 20th.\n\n Great Thunderstrike (Su): At 9th level, a stormsinger with 17 or more ranks in Perform (sing) can use bardic music to unleash a terrible stroke of lightning, followed by a deafening clap of thunder. The great thunderstrike affects a line 60 feet long from the stormsinger. The stormsinger makes a Perform (sing) check; the result indicates how much electricity damage the great thunderstrike deals. A Reflex save (DC 10 + stormsinger’s class level + Cha modifier) halves the damage. If a creature fails its Reflex save, it must make a Fortitude save (same DC) or take an additional 2d6 points of sonic damage and be permanently deafened. The great thunderstrike is very strenuous, and uses up two of the stormsinger’s bardic music uses for the day.\n\n Storm of Vengeance (Sp): At 10th level, a stormsinger with 18 or more ranks in Perform (sing) can use bardic music to cause a storm of vengeance, as the spell of the same name (DC 10 + stormsinger’s class level + Cha modifier). Her caster level is equal to her ranks in Perform (sing), with a maximum caster level of 25th. This potent ability is quite exhausting to use; each time it is activated, the stormsinger uses four of her bardic music uses for the day.\n\n Stormpower (Ex): At 2nd level, a stormsinger gains a +2 bonus on Perform (sing) checks made to use her stormsong powers and adds a +2 bonus to her caster level with stormsong powers when the temperature is cold or colder (40° F or lower) or when she is in a storm. For information on storms, see Table 3–24: Wind Effects, page 95 of the Dungeon Master’s Guide.\n\n Resistance to Electricity (Ex): At 4th level, a stormsinger gains resistance to electricity 5. This increases to resistance to electricity 10 at 6th level, and resistance to electricity 15 at 8th level.","advancesExistingSpellcasting":true}'::jsonb),
('dnd35.frostburn.class.frostburn-winterhaunt-of-iborighu','Winterhaunt of Iborighu','Winterhaunt of Iborighu','Alignment: Chaotic neutral, chaotic evil, or neutral evil. Skills: Concentration 8 ranks, Knowledge (arcana) 5 ranks, Knowledge (religion) 8 ranks. Feats: Chosen of Iborighu, Craft Wondrous Item, Piercing Cold. Spells: Able to cast 1st-level divine spells. Patron Deity: Iborighu. Special: The character must successfully create an iceheart. This can be either a minor iceheart or a major iceheart; most prospective cultists opt to create a minor iceheart, naturally. The iceheart, once created, serves as the winterhaunt’s badge of office in the cult; if it is lost or destroyed, he must replace it with a new one within a week. Failure to do so results in the loss of all spellcasting and supernatural abilities granted by this prestige class. Regaining these abilities is possible only if the winterhaunt gains a new iceheart and then receives an atonement spell.',8,ARRAY[]::text[],ARRAY['prestige']::text[],'v35-frostburn','D&D 3.5 — Frostburn',52,'dnd35','{"id":"frostburn-winterhaunt-of-iborighu","name":"Winterhaunt of Iborighu","hitDie":8,"requirements":["Alignment: Chaotic neutral, chaotic evil, or neutral evil.","Skills: Concentration 8 ranks, Knowledge (arcana) 5 ranks, Knowledge (religion) 8 ranks.","Feats: Chosen of Iborighu, Craft Wondrous Item, Piercing Cold.","Spells: Able to cast 1st-level divine spells.","Patron Deity: Iborighu.","Special: The character must successfully create an iceheart. This can be either a minor iceheart or a major iceheart; most prospective cultists opt to create a minor iceheart, naturally. The iceheart, once created, serves as the winterhaunt’s badge of office in the cult; if it is lost or destroyed, he must replace it with a new one within a week. Failure to do so results in the loss of all spellcasting and supernatural abilities granted by this prestige class. Regaining these abilities is possible only if the winterhaunt gains a new iceheart and then receives an atonement spell."],"classSkills":"The winterhaunt of Iborighu’s class skills (and the key ability for each skill) are Concentration (Con), Craft (Int), Intimidate (Cha), Knowledge (arcana) (Int), Knowledge (religion) (Int), Profession (Wis), and Spellcraft (Int). See Chapter 4 of the Player’s Handbook for skill descriptions.","skillPointsPerLevel":"2 + Int modifier","levels":[{"level":1,"bab":"+0","fort":"+2","ref":"+0","will":"+2","special":"Cloak of winter’s chill"},{"level":2,"bab":"+1","fort":"+3","ref":"+0","will":"+3","special":"Resistance to cold 5"},{"level":3,"bab":"+1","fort":"+3","ref":"+1","will":"+3","special":"Frozen skin"},{"level":4,"bab":"+2","fort":"+4","ref":"+1","will":"+4","special":"Coldstrike +1d6"},{"level":5,"bab":"+2","fort":"+4","ref":"+1","will":"+4","special":"Resistance to cold 10"},{"level":6,"bab":"+3","fort":"+5","ref":"+2","will":"+5","special":"Constant Piercing Cold"},{"level":7,"bab":"+3","fort":"+5","ref":"+2","will":"+5","special":"Cold subtype"},{"level":8,"bab":"+4","fort":"+6","ref":"+2","will":"+6","special":"Coldstrike +2d6"},{"level":9,"bab":"+4","fort":"+6","ref":"+3","will":"+6","special":"Summon the entombed"},{"level":10,"bab":"+5","fort":"+7","ref":"+3","will":"+7","special":"Wintry apotheosis"}],"classFeaturesText":"Weapon and Armor Proficiency: Winterhaunts of Iborighu gain proficiency with all simple weapons, as well as proficiency with the scythe (the favored weapon of Iborighu). Winterhaunts are proficient with light armor, but not shields. Spells per Day/Spells Known: When a new winterhaunt level is gained, the character gains new spells per day (and spells known, if applicable) as if he had also gained a level in a spellcasting class she belonged to before adding the prestige class. He does not, however, gain any other benefit a character of that class would have gained (improved chance of controlling or rebuking undead, metamagic or item creation feats, and so on), except for an increased effective level of spellcasting. If a character had more than one spellcasting class before becoming a winterhaunt, he must decide to which class he adds the new level for purposes of determining spells per day and spells known.\n\n Cloak of Winter’s Chill (Su): As a free action, a winterhaunt can shroud himself in a sphere of cold a number of times per day equal to 3 + his Charisma modifier. This cloak of winter’s chill lasts for a number of rounds equal to the winterhaunt’s class level + his Charisma modifier. While cloaked in winter’s chill, the winterhaunt gleams with a frosty radiance that is both alluring and terrifying. He gains a +2 profane bonus on Will saving throws and all Charisma-based checks, including all Charisma-based skills and rebuke or command undead checks.\n\n Resistance to Cold (Ex): A winterhaunt gains resistance to cold 5 at 2nd level. This increases to resistance to cold 10 at 5th level. This resistance to cold granted to this ability stacks with a character’s natural cold resistance, if any.\n\n Frozen Skin (Su): At 3rd level, the winterhaunt’s skin becomes as hard (and cold) as frozen flesh, while retaining its flexibility. His skin appears to be coated with a fine layer of frost, and flecks of snow seem to float from his flesh at times. He gains a +2 natural armor bonus to his Armor Class, which increases to +4 while he is cloaked in his winter’s chill ability.\n\n Coldstrike (Su): Starting at 4th level, every time a winter haunt deals cold damage with a spell, spell-like ability, or supernatural ability (including an uldra’s icy touch or a white dragon’s breath weapon), he deals an additional 1d6 points of cold damage. Magic weapons that deal cold damage (such as frost weapons) do not trigger this additional cold damage, since the source of the cold damage is the weapon itself, not the winterhaunt. The winterhaunt’s coldstrike damage increases to +2d6 points of cold damage at 8th level. When his cloak of winter’s chill is active, he adds an additional 1d6 points of damage with his coldstrike ability (to a total of +2d6 at 4th level and +3d6 at 8th level).\n\n Constant Piercing Cold (Su): At 6th level, all spells with the cold descriptor cast by the winterhaunt are automatically enhanced by the Piercing Cold feat, with no change to the spell’s actual level.\n\n Cold Subtype (Ex): At 7th level, the winterhaunt gains the cold subtype. He gains immunity to cold, but also has a vulnerability to fire, which means he takes half again as much (+50%) damage as normal from fire, regardless of whether or not a saving throw is allowed, or if the save is a success or a failure.\n\n Summon the Entombed (Sp): At 9th level, a winterhaunt gains the spell-like ability to summon one of the entombed to do his bidding. Treat this as a summon monster IX spell, except that \n the winterhaunt can only summon entombed with it. The caster level of this ability is equal to the winterhaunt’s class level plus his Charisma modifier. The winterhaunt may use this spell-like ability once per day. For more information on entombed, see page 128.\n\n Wintry Apotheosis (Su): At 10th level, the winterhaunt undergoes a powerful and unholy transformation as his flesh and bones become consumed by the frozen wrath of Iborighu, only to be replaced by snowy flesh and icy bones. The winterhaunt has become a powerful supernatural servant of Iborighu. Once this apotheosis takes place, the winterhaunt’s type changes to elemental, and he gains the evil subtype. As a being composed of living, profane ice and snow, he is immune to poison, sleep effects, paralysis, and stunning. He is also not subject to extra damage from critical hits or flanking. The winter haunt cannot be raised, reincarnated or resurrected (though a limited wish, wish, miracle, or true resurrection spell can restore life). The winterhaunt also gains dark vision out to 60 feet. The winterhaunt’s natural weapons, as well as any weapons he wields, are treated as evil-aligned for the purpose of overcoming damage reduction.","advancesExistingSpellcasting":true}'::jsonb)
on conflict (id) do update set name_pt = excluded.name_pt, name_en = excluded.name_en, description_pt = excluded.description_pt, hp_per_level = excluded.hp_per_level, key_attributes = excluded.key_attributes, traits = excluded.traits, ruleset = excluded.ruleset, source_book = excluded.source_book, source_page = excluded.source_page, system_id = excluded.system_id, data = excluded.data, updated_at = now();

insert into public.catalog_feats (id,feat_type,level,name_pt,name_en,description_pt,prerequisites,traits,ruleset,source_book,source_page,system_id,data) values
('dnd35.frostburn.feat.frostburn-altitude-adaptation','General',1,'Altitude Adaptation','Altitude Adaptation','You gain a +4 bonus on all Fortitude saving throws to avoid the effects of altitude. Additionally, when you determine what effect the altitude has on you, you apply the effect for the next lower category of altitude than the category you are actually in. After you spend a week at a specific altitude, you become acclimated to that altitude and all lower altitudes, and no longer have to make Fortitude saving throws for each 6-hour period to avoid altitude sickness. If you travel to a lower altitude and remain there for a week, you lose your acclimation to the higher altitude and must reacclimatize, although you always retain the other benefits granted by this feat.','Base Fortitude save bonus +2',ARRAY[]::text[],'v35-frostburn','D&D 3.5 — Frostburn',45,'dnd35','{"id":"frostburn-altitude-adaptation","name":"Altitude Adaptation","type":"General","prerequisite":"Base Fortitude save bonus +2","summary":"Your body adapts quickly to changes in altitude, preventing you from suffering as much from altitude sickness.","benefit":"You gain a +4 bonus on all Fortitude saving throws to avoid the effects of altitude. Additionally, when you determine what effect the altitude has on you, you apply the effect for the next lower category of altitude than the category you are actually in. After you spend a week at a specific altitude, you become acclimated to that altitude and all lower altitudes, and no longer have to make Fortitude saving throws for each 6-hour period to avoid altitude sickness. If you travel to a lower altitude and remain there for a week, you lose your acclimation to the higher altitude and must reacclimatize, although you always retain the other benefits granted by this feat.","special":"This feat grants a +2 bonus on all Survival checks made in high altitude (above 5,000 feet) areas."}'::jsonb),
('dnd35.frostburn.feat.frostburn-arctic-priest','General',1,'Arctic Priest','Arctic Priest','You can channel stored spell energy into spells that aid in exploring and surviving in the frostfell, even if you did not prepare these spells ahead of time. You can “lose” any prepared spell that is not a domain spell in order to cast any of the spells that appear on the list below, as long as the spell to be cast is of an equal or lower level to the one you lose. Spells you can spontaneously cast when using this feat include: control weather, create food and water, endure elements, heroes’ feast, hibernate, protection from energy, and resist energy.','Access to Cold or Winter cleric domain',ARRAY[]::text[],'v35-frostburn','D&D 3.5 — Frostburn',45,'dnd35','{"id":"frostburn-arctic-priest","name":"Arctic Priest","type":"General","prerequisite":"Access to Cold or Winter cleric domain","summary":"You can swap out prepared spells to cast spells to aid in exploring and surviving in frostfell areas.","benefit":"You can channel stored spell energy into spells that aid in exploring and surviving in the frostfell, even if you did not prepare these spells ahead of time. You can “lose” any prepared spell that is not a domain spell in order to cast any of the spells that appear on the list below, as long as the spell to be cast is of an equal or lower level to the one you lose. Spells you can spontaneously cast when using this feat include: control weather, create food and water, endure elements, heroes’ feast, hibernate, protection from energy, and resist energy."}'::jsonb),
('dnd35.frostburn.feat.frostburn-beckon-the-frozen','General',1,'Beckon the Frozen','Beckon the Frozen','When you summon a creature or creatures using any summon spell, you can opt to summon a version of the creature from an extraplanar frostfell. If you do so, the summoned creature gains the cold subtype, and its natural attacks deal an additional 1d6 points of cold damage. Creatures with the fire subtype can never be enhanced with the cold subtype in this manner.','Augment Summoning, Spell Focus (conjuration)',ARRAY[]::text[],'v35-frostburn','D&D 3.5 — Frostburn',45,'dnd35','{"id":"frostburn-beckon-the-frozen","name":"Beckon the Frozen","type":"General","prerequisite":"Augment Summoning, Spell Focus (conjuration)","summary":"Creatures you summon are infused with cold energy and have the cold subtype.","benefit":"When you summon a creature or creatures using any summon spell, you can opt to summon a version of the creature from an extraplanar frostfell. If you do so, the summoned creature gains the cold subtype, and its natural attacks deal an additional 1d6 points of cold damage. Creatures with the fire subtype can never be enhanced with the cold subtype in this manner."}'::jsonb),
('dnd35.frostburn.feat.frostburn-chosen-of-iborighu','General',1,'Chosen of Iborighu','Chosen of Iborighu','Your left eye radiates faint evocation magic if it is viewed with a detect magic spell, and faint evil if viewed with a detect evil spell. Cleric is now a favored class for you; the cleric class does not count when determining whether you take an experi-ence point penalty for multiclassing. Once per day, you can cause one creature within 30 feet that meets your gaze to become overwhelmed with a wave of super-natural cold. The target can resist the effects of this attack with a successful Fortitude save (DC 10 + 1/2 your character level + your Charisma modifier), otherwise it causes cold damage equal to your Charisma modifier + 3 (minimum 1 point of damage) and causes the victim to become fatigued. If you use this attack against someone who is fatigued, they instead become exhausted. Using this supernatural ability is a standard action that does not provoke attacks of opportunity.','Patron deity must be Iborighu',ARRAY[]::text[],'v35-frostburn','D&D 3.5 — Frostburn',45,'dnd35','{"id":"frostburn-chosen-of-iborighu","name":"Chosen of Iborighu","type":"General","prerequisite":"Patron deity must be Iborighu","summary":"Your skin has a noticeable blue tint and your left eye is pale blue (your right eye is some other color); these features iden-tify you as an ally to the church of Iborighu and grant you supernatural qualities.","benefit":"Your left eye radiates faint evocation magic if it is viewed with a detect magic spell, and faint evil if viewed with a detect evil spell. Cleric is now a favored class for you; the cleric class does not count when determining whether you take an experi-ence point penalty for multiclassing. Once per day, you can cause one creature within 30 feet that meets your gaze to become overwhelmed with a wave of super-natural cold. The target can resist the effects of this attack with a successful Fortitude save (DC 10 + 1/2 your character level + your Charisma modifier), otherwise it causes cold damage equal to your Charisma modifier + 3 (minimum 1 point of damage) and causes the victim to become fatigued. If you use this attack against someone who is fatigued, they instead become exhausted. Using this supernatural ability is a standard action that does not provoke attacks of opportunity.","special":"If you ever lose favor with Iborighu, or change your patron deity to another deity, you lose all benefits of this feat but your unusual skin color and eye color remain. You do not gain a replacement feat. If you later return to Iborighu’s faithful and receive an atonement spell, you regain the benefits of the feat."}'::jsonb),
('dnd35.frostburn.feat.frostburn-cold-endurance','General',1,'Cold Endurance','Cold Endurance','You can exist comfortably in conditions between 0° F and 90° F without having to make Fortitude saves (as described in Cold Dangers, page 8). You also gain a +2 bonus on saving throws against cold effects. Cold Endurance doesn’t provide any level of resistance to cold damage.','Base Fortitude save bonus +2',ARRAY[]::text[],'v35-frostburn','D&D 3.5 — Frostburn',45,'dnd35','{"id":"frostburn-cold-endurance","name":"Cold Endurance","type":"General","prerequisite":"Base Fortitude save bonus +2","summary":"Either because of growing up in a frostfell or training your body and mind to ignore the biting effect of cold, you can exist with ease in low-temperature environments.","benefit":"You can exist comfortably in conditions between 0° F and 90° F without having to make Fortitude saves (as described in Cold Dangers, page 8). You also gain a +2 bonus on saving throws against cold effects. Cold Endurance doesn’t provide any level of resistance to cold damage."}'::jsonb),
('dnd35.frostburn.feat.frostburn-cold-focus','General',1,'Cold Focus','Cold Focus','Add +1 to the DC for all saving throws against spells you cast with the cold descriptor. This bonus stacks with similar bonuses, such as those granted by Spell Focus and Greater Spell Focus.',null,ARRAY[]::text[],'v35-frostburn','D&D 3.5 — Frostburn',45,'dnd35','{"id":"frostburn-cold-focus","name":"Cold Focus","type":"General","prerequisite":null,"summary":"Your cold spells are more potent than normal.","benefit":"Add +1 to the DC for all saving throws against spells you cast with the cold descriptor. This bonus stacks with similar bonuses, such as those granted by Spell Focus and Greater Spell Focus."}'::jsonb),
('dnd35.frostburn.feat.frostburn-cold-spell-specialization','General',1,'Cold Spell Specialization','Cold Spell Specialization','In cold areas (temperature at or below 40° F), you gain a +1 bonus per die to any dice rolled to determine damage caused by cold spells you cast. For example, if an 11th-level wizard with this feat casts a cone of cold in a cold area, the spell does 11d6+11 points of damage. In areas of extreme cold (below–20° F), the damage bonus increases to +2 per die.','Con 13, Snowcasting, Frozen Magic',ARRAY[]::text[],'v35-frostburn','D&D 3.5 — Frostburn',45,'dnd35','{"id":"frostburn-cold-spell-specialization","name":"Cold Spell Specialization","type":"General","prerequisite":"Con 13, Snowcasting, Frozen Magic","summary":"You do additional damage with cold spells.","benefit":"In cold areas (temperature at or below 40° F), you gain a +1 bonus per die to any dice rolled to determine damage caused by cold spells you cast. For example, if an 11th-level wizard with this feat casts a cone of cold in a cold area, the spell does 11d6+11 points of damage. In areas of extreme cold (below–20° F), the damage bonus increases to +2 per die."}'::jsonb),
('dnd35.frostburn.feat.frostburn-craft-skull-talisman','Item Creation',1,'Craft Skull Talisman','Craft Skull Talisman','You can create a skull talisman of any spell you know and that targets one or more creatures. Crafting a skull talisman takes one day. When you create a skull talisman, you set the caster level. The caster level must be sufficient to cast the spell in question and no higher than your own level. The base price of a skull talisman is its spell level × its caster level × 100 gp. To craft the talisman, you must spend 1/25 of this base price in XP and use up raw materials (mostly com-prised of the rare metallic inks needed to inscribe the runes of power on the skull) costing one-half this base price. When you create a skull talisman, you make any choices that you would normally make when casting the spell. Who-ever destroys the skull is the target of the spell. Any skull talisman that stores a spell with a costly mate-rial component or a XP cost also carries a commensurate cost. In addition to the costs derived from the base price, you must expend the material component or pay the XP when creating the skull talisman. The skull to be used to create a skull talisman must be from a creature of at least Small size. A Small creature’s skull can store a spell of up to 3rd level. A Medium creature’s skull can store a spell of up to 6th level. A Large creature’s skull can store a spell of up to 9th level. The art of crafting skull talismans was perfected by neanderthal druids, but any spellcaster can learn the art of making these devices. Many view the act of creating or using a skull talis-man as a distasteful activity, but neither in and of itself is it an evil act.','Caster level 6th',ARRAY[]::text[],'v35-frostburn','D&D 3.5 — Frostburn',45,'dnd35','{"id":"frostburn-craft-skull-talisman","name":"Craft Skull Talisman","type":"Item Creation","prerequisite":"Caster level 6th","summary":"You can create skull talismans, which carry spells within themselves (for more information on skull talismans, see page 112).","benefit":"You can create a skull talisman of any spell you know and that targets one or more creatures. Crafting a skull talisman takes one day. When you create a skull talisman, you set the caster level. The caster level must be sufficient to cast the spell in question and no higher than your own level. The base price of a skull talisman is its spell level × its caster level × 100 gp. To craft the talisman, you must spend 1/25 of this base price in XP and use up raw materials (mostly com-prised of the rare metallic inks needed to inscribe the runes of power on the skull) costing one-half this base price. When you create a skull talisman, you make any choices that you would normally make when casting the spell. Who-ever destroys the skull is the target of the spell. Any skull talisman that stores a spell with a costly mate-rial component or a XP cost also carries a commensurate cost. In addition to the costs derived from the base price, you must expend the material component or pay the XP when creating the skull talisman. The skull to be used to create a skull talisman must be from a creature of at least Small size. A Small creature’s skull can store a spell of up to 3rd level. A Medium creature’s skull can store a spell of up to 6th level. A Large creature’s skull can store a spell of up to 9th level. The art of crafting skull talismans was perfected by neanderthal druids, but any spellcaster can learn the art of making these devices. Many view the act of creating or using a skull talis-man as a distasteful activity, but neither in and of itself is it an evil act."}'::jsonb),
('dnd35.frostburn.feat.frostburn-faith-in-the-frost','General',1,'Faith in the Frost','Faith in the Frost','When you successfully turn or rebuke a crea-ture, it takes cold damage equal to your Charisma modifier as blasts of ice and cold energy tear through its body.','Ability to turn or rebuke creatures, access to Cold or Winter cleric domain',ARRAY[]::text[],'v35-frostburn','D&D 3.5 — Frostburn',45,'dnd35','{"id":"frostburn-faith-in-the-frost","name":"Faith in the Frost","type":"General","prerequisite":"Ability to turn or rebuke creatures, access to Cold or Winter cleric domain","summary":"You channel frozen energies from your deity when you turn or rebuke creatures.","benefit":"When you successfully turn or rebuke a crea-ture, it takes cold damage equal to your Charisma modifier as blasts of ice and cold energy tear through its body."}'::jsonb),
('dnd35.frostburn.feat.frostburn-frostfell-prodigy','General',1,'Frostfell Prodigy','Frostfell Prodigy','In cold areas (temperature at or below 40° F), the ability score used to determine how many bonus spells you may prepare or cast is treated as if it were 2 higher than its actual score. If you enter an area with a warmer tem-perature and remain in this area for longer than 1 minute, the bonus spells granted by this feat are lost until you can regain them. In areas of extreme cold (below –20° F), the ability score is treated as if it were 4 higher than its actual score for purposes of determining how many bonus spells you can prepare or cast.','Con 13, Snowcasting, Frozen Magic, Cold Focus',ARRAY[]::text[],'v35-frostburn','D&D 3.5 — Frostburn',45,'dnd35','{"id":"frostburn-frostfell-prodigy","name":"Frostfell Prodigy","type":"General","prerequisite":"Con 13, Snowcasting, Frozen Magic, Cold Focus","summary":"You gain additional bonus spells in cold regions.","benefit":"In cold areas (temperature at or below 40° F), the ability score used to determine how many bonus spells you may prepare or cast is treated as if it were 2 higher than its actual score. If you enter an area with a warmer tem-perature and remain in this area for longer than 1 minute, the bonus spells granted by this feat are lost until you can regain them. In areas of extreme cold (below –20° F), the ability score is treated as if it were 4 higher than its actual score for purposes of determining how many bonus spells you can prepare or cast."}'::jsonb),
('dnd35.frostburn.feat.frostburn-frozen-berserker','General',1,'Frozen Berserker','Frozen Berserker','As long as you are under the effects of a barbarian rage, you gain the cold subtype. You gain immunity to cold, but have vulnerability to fire, which means you take half again as much (+50%) damage as normal from fire, regard-less of whether a saving throw is allowed, or if the save is a success or failure.','Ability to rage',ARRAY[]::text[],'v35-frostburn','D&D 3.5 — Frostburn',45,'dnd35','{"id":"frostburn-frozen-berserker","name":"Frozen Berserker","type":"General","prerequisite":"Ability to rage","summary":"When you enter your barbarian rage, your body becomes infused with cold energy.","benefit":"As long as you are under the effects of a barbarian rage, you gain the cold subtype. You gain immunity to cold, but have vulnerability to fire, which means you take half again as much (+50%) damage as normal from fire, regard-less of whether a saving throw is allowed, or if the save is a success or failure."}'::jsonb),
('dnd35.frostburn.feat.frostburn-frozen-magic','General',1,'Frozen Magic','Frozen Magic','In cold areas (temperature at or below 40° F), spells with the cold descriptor cast by you manifest at caster level +1. In areas of extreme cold (below –20° F), cold spells cast by you manifest at caster level +2.','Con 13, Snowcasting',ARRAY[]::text[],'v35-frostburn','D&D 3.5 — Frostburn',45,'dnd35','{"id":"frostburn-frozen-magic","name":"Frozen Magic","type":"General","prerequisite":"Con 13, Snowcasting","summary":"Your cold spells are more powerful when you cast them in a cold region.","benefit":"In cold areas (temperature at or below 40° F), spells with the cold descriptor cast by you manifest at caster level +1. In areas of extreme cold (below –20° F), cold spells cast by you manifest at caster level +2."}'::jsonb),
('dnd35.frostburn.feat.frostburn-frozen-wild-shape','General',1,'Frozen Wild Shape','Frozen Wild Shape','You may use your wild shape ability to assume the form of any magical beast with the cold subtype. Your new form must still fall within the size limitations of your wild shape ability. As with the standard wild shape ability, you do not gain any of the extraordinary special qualities or any supernatural abilities possessed by the new form, with the exception of the cold subtype. This subtype grants you immunity to cold but vulnerability to fire, which means you take half again as much (+50%) damage as normal from fire while in a frozen wild shape, regardless of whether a saving throw is allowed, or if the save is a success or failure. Possible cold magical beasts from the Monster Manual include cryohydras (Huge wild shape required), frost worms (Huge wild shape required), and winter wolves. Possible cold magical beasts from Monster Manual II include frost salamanders. Possible cold magical beasts from this book include bran-tas (Large wild shape required), ice toads (Large wild shape required), urskans (Large wild shape required), and tlalusks (Huge wild shape required).','Base Fortitude save bonus +6, wild shape ability',ARRAY[]::text[],'v35-frostburn','D&D 3.5 — Frostburn',45,'dnd35','{"id":"frostburn-frozen-wild-shape","name":"Frozen Wild Shape","type":"General","prerequisite":"Base Fortitude save bonus +6, wild shape ability","summary":"You can assume the form of magical beasts with the cold subtype.","benefit":"You may use your wild shape ability to assume the form of any magical beast with the cold subtype. Your new form must still fall within the size limitations of your wild shape ability. As with the standard wild shape ability, you do not gain any of the extraordinary special qualities or any supernatural abilities possessed by the new form, with the exception of the cold subtype. This subtype grants you immunity to cold but vulnerability to fire, which means you take half again as much (+50%) damage as normal from fire while in a frozen wild shape, regardless of whether a saving throw is allowed, or if the save is a success or failure. Possible cold magical beasts from the Monster Manual include cryohydras (Huge wild shape required), frost worms (Huge wild shape required), and winter wolves. Possible cold magical beasts from Monster Manual II include frost salamanders. Possible cold magical beasts from this book include bran-tas (Large wild shape required), ice toads (Large wild shape required), urskans (Large wild shape required), and tlalusks (Huge wild shape required)."}'::jsonb),
('dnd35.frostburn.feat.frostburn-greater-cold-focus','General',1,'Greater Cold Focus','Greater Cold Focus','Add +1 to the DC for all saving throws against spells with the cold descriptor. This bonus stacks with simi-lar bonuses, such as those from Cold Focus, Spell Focus, and Greater Spell Focus.','Cold Focus',ARRAY[]::text[],'v35-frostburn','D&D 3.5 — Frostburn',45,'dnd35','{"id":"frostburn-greater-cold-focus","name":"Greater Cold Focus","type":"General","prerequisite":"Cold Focus","summary":"Your cold spells are now even more potent than before.","benefit":"Add +1 to the DC for all saving throws against spells with the cold descriptor. This bonus stacks with simi-lar bonuses, such as those from Cold Focus, Spell Focus, and Greater Spell Focus."}'::jsonb),
('dnd35.frostburn.feat.frostburn-icy-calling','General',1,'Icy Calling','Icy Calling','In cold areas (temperature at or below 40° F), creatures native to cold environments and creatures with the cold subtype summoned by you are more powerful and agile than normal. The summoned creatures gain a +4 enhancement bonus to Strength and Dexterity for the dura-tion of the spell that summoned them. In areas of extreme cold (below –20° F), any summoned creature affected by this feat has maximum hit points when summoned.','Con 13, Snowcasting',ARRAY[]::text[],'v35-frostburn','D&D 3.5 — Frostburn',45,'dnd35','{"id":"frostburn-icy-calling","name":"Icy Calling","type":"General","prerequisite":"Con 13, Snowcasting","summary":"Your summon spells work better in the frostfell if you summon native creatures.","benefit":"In cold areas (temperature at or below 40° F), creatures native to cold environments and creatures with the cold subtype summoned by you are more powerful and agile than normal. The summoned creatures gain a +4 enhancement bonus to Strength and Dexterity for the dura-tion of the spell that summoned them. In areas of extreme cold (below –20° F), any summoned creature affected by this feat has maximum hit points when summoned."}'::jsonb),
('dnd35.frostburn.feat.frostburn-ice-harmonics','General',1,'Ice Harmonics','Ice Harmonics','By expending one of your daily uses of bardic music, you can cause any unattended nonmagical ice object or portion of ice to explode violently. The target must be within 30 feet, and you must be able to sing in order to shatter the ice. Any creature located in the 5-foot square in which you target with this ability takes piercing damage equal to 2d6 + your Charisma modifier. Creatures made of ice that you specifically target with this effect take double damage.','Bardic music ability, Perform (sing) 6 ranks',ARRAY[]::text[],'v35-frostburn','D&D 3.5 — Frostburn',45,'dnd35','{"id":"frostburn-ice-harmonics","name":"Ice Harmonics","type":"General","prerequisite":"Bardic music ability, Perform (sing) 6 ranks","summary":"You can use your voice to shatter ice.","benefit":"By expending one of your daily uses of bardic music, you can cause any unattended nonmagical ice object or portion of ice to explode violently. The target must be within 30 feet, and you must be able to sing in order to shatter the ice. Any creature located in the 5-foot square in which you target with this ability takes piercing damage equal to 2d6 + your Charisma modifier. Creatures made of ice that you specifically target with this effect take double damage."}'::jsonb),
('dnd35.frostburn.feat.frostburn-improved-cold-endurance','General',1,'Improved Cold Endurance','Improved Cold Endurance','You gain resistance to cold 5. If you already have resistance to cold, it increases by 5 (maximum resistance to cold 15).','Base Fortitude save bonus +6, Cold Endurance',ARRAY[]::text[],'v35-frostburn','D&D 3.5 — Frostburn',45,'dnd35','{"id":"frostburn-improved-cold-endurance","name":"Improved Cold Endurance","type":"General","prerequisite":"Base Fortitude save bonus +6, Cold Endurance","summary":"Your training and natural hardiness have improved your natural resistance to cold temperatures.","benefit":"You gain resistance to cold 5. If you already have resistance to cold, it increases by 5 (maximum resistance to cold 15).","special":"You can gain this feat multiple times; its effects stack. You cannot have more than resistance to cold 15 as a result of taking this feat."}'::jsonb),
('dnd35.frostburn.feat.frostburn-improved-frosty-touch','General',1,'Improved Frosty Touch','Improved Frosty Touch','Your frosty touch ability now deals 2 points of cold damage.','Uldra',ARRAY[]::text[],'v35-frostburn','D&D 3.5 — Frostburn',45,'dnd35','{"id":"frostburn-improved-frosty-touch","name":"Improved Frosty Touch","type":"General","prerequisite":"Uldra","summary":"Your frosty touch causes more cold damage.","benefit":"Your frosty touch ability now deals 2 points of cold damage.","normal":"Your frosty touch ability deals 1 point of cold damage."}'::jsonb),
('dnd35.frostburn.feat.frostburn-mark-of-hleid','General',1,'Mark of Hleid','Mark of Hleid','The actual birthmark itself radiates faint abjura-tion magic if it is viewed with a detect magic spell, and faint good if viewed with a detect good spell. You are immune to the frost touch special attack of a rimefire eidolon. Additionally, you can handle rimefire ice barehanded without taking any cold damage. Cleric is now a favored class for you; the cleric class does not count when determining whether you take an experi-ence point penalty for multiclassing. You gain a +2 sacred bonus to your Armor Class against evil-aligned creatures with the cold subtype.','Your patron deity must be Hleid',ARRAY[]::text[],'v35-frostburn','D&D 3.5 — Frostburn',45,'dnd35','{"id":"frostburn-mark-of-hleid","name":"Mark of Hleid","type":"General","prerequisite":"Your patron deity must be Hleid","summary":"You bear a birthmark in the shape of the holy symbol of Hleid (a ragged white triangle with a vortex of blue flame in its center) somewhere on your body; this mark identifies you as an ally of the church of Hleid and grants you supernatural qualities.","benefit":"The actual birthmark itself radiates faint abjura-tion magic if it is viewed with a detect magic spell, and faint good if viewed with a detect good spell. You are immune to the frost touch special attack of a rimefire eidolon. Additionally, you can handle rimefire ice barehanded without taking any cold damage. Cleric is now a favored class for you; the cleric class does not count when determining whether you take an experi-ence point penalty for multiclassing. You gain a +2 sacred bonus to your Armor Class against evil-aligned creatures with the cold subtype.","special":"If you ever lose favor with Hleid, or change your patron deity to another deity, the mark of Hleid fades and you lose all benefits of this feat. You do not gain a replace-ment feat. If you later return to Hleid’s faithful and receive an atonement spell, the mark reappears and you regain the benefits of the feat."}'::jsonb),
('dnd35.frostburn.feat.frostburn-mountaineer','General',1,'Mountaineer','Mountaineer','You get a +2 bonus on all Climb and Survival checks.',null,ARRAY[]::text[],'v35-frostburn','D&D 3.5 — Frostburn',45,'dnd35','{"id":"frostburn-mountaineer","name":"Mountaineer","type":"General","prerequisite":null,"summary":"You are a particularly gifted explorer and mountain climber.","benefit":"You get a +2 bonus on all Climb and Survival checks."}'::jsonb),
('dnd35.frostburn.feat.frostburn-piercing-cold','Metamagic',1,'Piercing Cold','Piercing Cold','You can only apply this metamagic feat to spells with the cold descriptor. Piercing cold spells are so horribly cold that they are capable of damaging creatures normally unharmed by or resistant to cold. Piercing cold spells com-pletely ignore any resistance to cold a creature possesses, bypassing this resistance and dealing damage to the target as if it did not possess any resistance to cold at all. They are still entitled to whatever other defenses the attack allows (such as saving throws and spell resistance). Creatures normally immune to cold can be damaged by piercing cold spells as well. Piercing cold spells deal half damage to these creatures (or one-quarter on a successful saving throw). For example, Mialee casts a piercing cold cone of cold at a night hag, a creature normally immune to cold. She makes her level check to penetrate the night hag’s spell resistance, but the night hag makes her Reflex save against the spell. Mialee rolls the dice, and her cone of cold deals 42 points of cold damage; since the night hag made her save, the damage is halved to 21 points. This damage is then halved again (since the night hag is normally immune to cold), and 10 points of cold damage are actually dealt to the night hag, who is both shocked and enraged at this unexpected turn of events. Creatures with the cold subtype can tell that a piercing cold spell is colder than normal, but they remain undam-aged by the attack. Creatures with the fire subtype who are damaged by a piercing cold spell take double normal damage instead of the usual +50%. A piercing cold spell uses up a spell slot one level higher than the spell’s actual level.',null,ARRAY[]::text[],'v35-frostburn','D&D 3.5 — Frostburn',45,'dnd35','{"id":"frostburn-piercing-cold","name":"Piercing Cold","type":"Metamagic","prerequisite":null,"summary":"Your cold spells are so cold that they can damage creatures normally resistant or immune to cold.","benefit":"You can only apply this metamagic feat to spells with the cold descriptor. Piercing cold spells are so horribly cold that they are capable of damaging creatures normally unharmed by or resistant to cold. Piercing cold spells com-pletely ignore any resistance to cold a creature possesses, bypassing this resistance and dealing damage to the target as if it did not possess any resistance to cold at all. They are still entitled to whatever other defenses the attack allows (such as saving throws and spell resistance). Creatures normally immune to cold can be damaged by piercing cold spells as well. Piercing cold spells deal half damage to these creatures (or one-quarter on a successful saving throw). For example, Mialee casts a piercing cold cone of cold at a night hag, a creature normally immune to cold. She makes her level check to penetrate the night hag’s spell resistance, but the night hag makes her Reflex save against the spell. Mialee rolls the dice, and her cone of cold deals 42 points of cold damage; since the night hag made her save, the damage is halved to 21 points. This damage is then halved again (since the night hag is normally immune to cold), and 10 points of cold damage are actually dealt to the night hag, who is both shocked and enraged at this unexpected turn of events. Creatures with the cold subtype can tell that a piercing cold spell is colder than normal, but they remain undam-aged by the attack. Creatures with the fire subtype who are damaged by a piercing cold spell take double normal damage instead of the usual +50%. A piercing cold spell uses up a spell slot one level higher than the spell’s actual level."}'::jsonb),
('dnd35.frostburn.feat.frostburn-primeval-wild-shape','General',1,'Primeval Wild Shape','Primeval Wild Shape','When you assume a wild shape form, you can opt to cause the shape assumed to be a primeval form of the creature that existed in the ancient past during a vast ice age. Doing so grants the new form a +2 racial bonus to Strength, a +2 bonus to its natural armor, and resistance to cold 10. A primeval wild shape has a much shorter duration than normal, since the enhanced qualities of the new shape drain your supernatural energies much more quickly. A primeval wild shape has a duration of 1 round per druid level (or per level of the class that granted you the wild shape ability) instead of the normal 1 hour per druid level.','Wild shape ability',ARRAY[]::text[],'v35-frostburn','D&D 3.5 — Frostburn',45,'dnd35','{"id":"frostburn-primeval-wild-shape","name":"Primeval Wild Shape","type":"General","prerequisite":"Wild shape ability","summary":"Your wild shape forms are stronger than normal.","benefit":"When you assume a wild shape form, you can opt to cause the shape assumed to be a primeval form of the creature that existed in the ancient past during a vast ice age. Doing so grants the new form a +2 racial bonus to Strength, a +2 bonus to its natural armor, and resistance to cold 10. A primeval wild shape has a much shorter duration than normal, since the enhanced qualities of the new shape drain your supernatural energies much more quickly. A primeval wild shape has a duration of 1 round per druid level (or per level of the class that granted you the wild shape ability) instead of the normal 1 hour per druid level."}'::jsonb),
('dnd35.frostburn.feat.frostburn-primitive-caster','General',1,'Primitive Caster','Primitive Caster','This feat only functions when you cast a spell that does not already have a verbal, somatic, or material component. For each component you voluntarily add, you increase the effective caster level of the spell by +1. You can only add a component that’s not already present in the spell. For example, you can’t add a somatic component to a gaseous form spell, because it already has one. You could add a verbal component, however. The verbal component you add consists of animalistic shouts, screams, and growls. The DC of Listen checks to hear you cast a spell is –5 (before modifying for distance). The somatic component is also more complex, so you must have two hands free to add a somatic component with this feat. The extra material component you add with this feat must be a rare plant found in the frostfell, which requires a successful DC 15 Profession (herbalist) check to locate. This feat originally appeared in Races of Faerûn.',null,ARRAY[]::text[],'v35-frostburn','D&D 3.5 — Frostburn',45,'dnd35','{"id":"frostburn-primitive-caster","name":"Primitive Caster","type":"General","prerequisite":null,"summary":"You use screeches, wild gesticulations, and extra material components to give your spells additional power.","benefit":"This feat only functions when you cast a spell that does not already have a verbal, somatic, or material component. For each component you voluntarily add, you increase the effective caster level of the spell by +1. You can only add a component that’s not already present in the spell. For example, you can’t add a somatic component to a gaseous form spell, because it already has one. You could add a verbal component, however. The verbal component you add consists of animalistic shouts, screams, and growls. The DC of Listen checks to hear you cast a spell is –5 (before modifying for distance). The somatic component is also more complex, so you must have two hands free to add a somatic component with this feat. The extra material component you add with this feat must be a rare plant found in the frostfell, which requires a successful DC 15 Profession (herbalist) check to locate. This feat originally appeared in Races of Faerûn."}'::jsonb),
('dnd35.frostburn.feat.frostburn-sea-legs','General',1,'Sea Legs','Sea Legs','As long as you are on board a ship, you get a +2 bonus on all Balance and Tumble checks, and a +1 bonus on Initiative checks.',null,ARRAY[]::text[],'v35-frostburn','D&D 3.5 — Frostburn',45,'dnd35','{"id":"frostburn-sea-legs","name":"Sea Legs","type":"General","prerequisite":null,"summary":"You are accustomed to the rolling motion on board a ship, and can use this motion to your advantage.","benefit":"As long as you are on board a ship, you get a +2 bonus on all Balance and Tumble checks, and a +1 bonus on Initiative checks."}'::jsonb),
('dnd35.frostburn.feat.frostburn-smite-fiery-foe','General',1,'Smite Fiery Foe','Smite Fiery Foe','Once per day, you may attempt to smite a creature with the fire subtype with a normal melee attack. When you activate this ability, your attack becomes infused with cold energy. You add your Charisma modifier to your attack roll and deal 1 extra point of cold damage per character level. If you smite a creature that does not have the fire subtype, the blast of cold does not manifest and the smite attempt is used up for that day. Remember that creatures with the fire subtype take half again as much (+50%) damage as normal from cold, includ-ing the additional damage dealt by this ability. You may swap out any daily uses of a smite ability gained by a character class or cleric domain to smite fiery foes instead.','Smite ability',ARRAY[]::text[],'v35-frostburn','D&D 3.5 — Frostburn',45,'dnd35','{"id":"frostburn-smite-fiery-foe","name":"Smite Fiery Foe","type":"General","prerequisite":"Smite ability","summary":"You can smite creatures with the fire subtype.","benefit":"Once per day, you may attempt to smite a creature with the fire subtype with a normal melee attack. When you activate this ability, your attack becomes infused with cold energy. You add your Charisma modifier to your attack roll and deal 1 extra point of cold damage per character level. If you smite a creature that does not have the fire subtype, the blast of cold does not manifest and the smite attempt is used up for that day. Remember that creatures with the fire subtype take half again as much (+50%) damage as normal from cold, includ-ing the additional damage dealt by this ability. You may swap out any daily uses of a smite ability gained by a character class or cleric domain to smite fiery foes instead."}'::jsonb),
('dnd35.frostburn.feat.frostburn-snowcasting','General',1,'Snowcasting','Snowcasting','If you add a handful of snow or ice as an addi-tional material component to a spell when you cast it, the spell gains the cold descriptor. This does not actually change the nature of the spell you cast; a fireball cast with this feat still deals fire damage, but since it also carries the cold descriptor, it can be augmented by a number of feats listed in this chapter, such as Cold Focus and Frozen Magic. If you add a handful of snow or ice as an additional mate-rial component to a spell when you cast it and that spell already has the cold descriptor, you increase the effective level of the spell being cast by +1. Adding this additional material component requires you to spend a move action immediately before the spell is cast to gather fresh snow or ice from the surrounding environment. This snow or ice can be magically created by a conjuration spell, but no other ice manifested by a spell will do. You may take no other action between gathering the snow or ice and casting the spell.','Con 13',ARRAY[]::text[],'v35-frostburn','D&D 3.5 — Frostburn',45,'dnd35','{"id":"frostburn-snowcasting","name":"Snowcasting","type":"General","prerequisite":"Con 13","summary":"You add ice or snow to your spell’s components to make them more powerful.","benefit":"If you add a handful of snow or ice as an addi-tional material component to a spell when you cast it, the spell gains the cold descriptor. This does not actually change the nature of the spell you cast; a fireball cast with this feat still deals fire damage, but since it also carries the cold descriptor, it can be augmented by a number of feats listed in this chapter, such as Cold Focus and Frozen Magic. If you add a handful of snow or ice as an additional mate-rial component to a spell when you cast it and that spell already has the cold descriptor, you increase the effective level of the spell being cast by +1. Adding this additional material component requires you to spend a move action immediately before the spell is cast to gather fresh snow or ice from the surrounding environment. This snow or ice can be magically created by a conjuration spell, but no other ice manifested by a spell will do. You may take no other action between gathering the snow or ice and casting the spell."}'::jsonb),
('dnd35.frostburn.feat.frostburn-snowrunner','General',1,'Snowrunner','Snowrunner','You can move through loose snow at full speed, as if you were moving across open terrain. You are also skilled at moving across open ice, and gain a +5 competence bonus on Balance checks to avoid slipping when you move across icy surfaces.','Woodland stride ability',ARRAY[]::text[],'v35-frostburn','D&D 3.5 — Frostburn',45,'dnd35','{"id":"frostburn-snowrunner","name":"Snowrunner","type":"General","prerequisite":"Woodland stride ability","summary":"You are particularly adept at moving through snow and over ice.","benefit":"You can move through loose snow at full speed, as if you were moving across open terrain. You are also skilled at moving across open ice, and gain a +5 competence bonus on Balance checks to avoid slipping when you move across icy surfaces."}'::jsonb),
('dnd35.frostburn.feat.frostburn-snowflake-wardance','General',1,'Snowflake Wardance','Snowflake Wardance','By expending one of your daily uses of bardic music, you may perform a deadly style of combat known as the snowflake wardance. Activating a snowflake wardance is a free action, and once activated, you add your Charisma modifier to your attack rolls with any slashing melee weapon you wield in one hand. This bonus to hit stacks with any bonuses you get from a high Strength score (or Dexterity score, if you are using Weapon Finesse). You cannot use this feat if you are carrying a shield, wearing medium or heavy armor, or carrying a medium or heavy load. A snowflake wardance lasts for a number of rounds equal to your ranks in Perform (dance). Performing a snowflake wardance is physically tiresome—when the snowflake war-dance ends, you become fatigued for the next 10 minutes.','Bardic music ability, Perform (dance) 6 ranks',ARRAY[]::text[],'v35-frostburn','D&D 3.5 — Frostburn',45,'dnd35','{"id":"frostburn-snowflake-wardance","name":"Snowflake Wardance","type":"General","prerequisite":"Bardic music ability, Perform (dance) 6 ranks","summary":"You have mastered the snowflake wardance, a mystical style of fighting with slashing weapons that allows you to leap and almost seem to float haphazardly across the battlefield like a whirling, razor-edged snowflake.","benefit":"By expending one of your daily uses of bardic music, you may perform a deadly style of combat known as the snowflake wardance. Activating a snowflake wardance is a free action, and once activated, you add your Charisma modifier to your attack rolls with any slashing melee weapon you wield in one hand. This bonus to hit stacks with any bonuses you get from a high Strength score (or Dexterity score, if you are using Weapon Finesse). You cannot use this feat if you are carrying a shield, wearing medium or heavy armor, or carrying a medium or heavy load. A snowflake wardance lasts for a number of rounds equal to your ranks in Perform (dance). Performing a snowflake wardance is physically tiresome—when the snowflake war-dance ends, you become fatigued for the next 10 minutes."}'::jsonb),
('dnd35.frostburn.feat.frostburn-storm-magic','General',1,'Storm Magic','Storm Magic','All spells you cast while you are affected by a storm (either natural or magical) manifest at +1 caster level. For more information on storms, see page 94 of the Dungeon Master’s Guide.',null,ARRAY[]::text[],'v35-frostburn','D&D 3.5 — Frostburn',45,'dnd35','{"id":"frostburn-storm-magic","name":"Storm Magic","type":"General","prerequisite":null,"summary":"You gain a boost in spellcasting power during storms.","benefit":"All spells you cast while you are affected by a storm (either natural or magical) manifest at +1 caster level. For more information on storms, see page 94 of the Dungeon Master’s Guide."}'::jsonb),
('dnd35.frostburn.feat.frostburn-sugliin-mastery','General',1,'Sugliin Mastery','Sugliin Mastery','You can attack with a sugliin as if it were a normal weapon, either making a single attack as a standard action or a full attack as a full-round action.','Base attack bonus +5, Exotic Weapon Proficiency (sugliin)',ARRAY[]::text[],'v35-frostburn','D&D 3.5 — Frostburn',45,'dnd35','{"id":"frostburn-sugliin-mastery","name":"Sugliin Mastery","type":"General","prerequisite":"Base attack bonus +5, Exotic Weapon Proficiency (sugliin)","summary":"You are a master at fighting with the massive sugliin.","benefit":"You can attack with a sugliin as if it were a normal weapon, either making a single attack as a standard action or a full attack as a full-round action.","normal":"Making a single attack with a sugliin is always a full-round action."}'::jsonb),
('dnd35.frostburn.feat.frostburn-winters-champion','General',1,'Winter’s Champion','Winter’s Champion','When you gain this feat, you may add the 1st-, 2nd-, 3rd-, and 4th-level spells granted by the Cold and Winter domains as paladin spells of the same levels. You do not gain the ability to cast spells of these domains of 5th level or higher, nor do you gain the granted powers of the domains.','Paladin level 1st',ARRAY[]::text[],'v35-frostburn','D&D 3.5 — Frostburn',45,'dnd35','{"id":"frostburn-winters-champion","name":"Winter’s Champion","type":"General","prerequisite":"Paladin level 1st","summary":"Your paladin spell list is enhanced.","benefit":"When you gain this feat, you may add the 1st-, 2nd-, 3rd-, and 4th-level spells granted by the Cold and Winter domains as paladin spells of the same levels. You do not gain the ability to cast spells of these domains of 5th level or higher, nor do you gain the granted powers of the domains.","special":"If you have any levels of cleric, these additional domains are not available to your cleric levels, since they are technically paladin spells in this case."}'::jsonb),
('dnd35.frostburn.feat.frostburn-winters-mount','General',1,'Winter’s Mount','Winter’s Mount','Your special mount gains the cold subtype. It gains immunity to cold, but has vulnerability to fire, which means it takes half again as much (+50%) damage as normal from fire, regardless of whether a saving throw is allowed, or if the save is a success or failure. Your special mount is also hardier than a nonfrostfell version; it gains a +2 racial bonus to Constitution.','Special mount ability',ARRAY[]::text[],'v35-frostburn','D&D 3.5 — Frostburn',45,'dnd35','{"id":"frostburn-winters-mount","name":"Winter’s Mount","type":"General","prerequisite":"Special mount ability","summary":"Your special mount is native to the frostfell.","benefit":"Your special mount gains the cold subtype. It gains immunity to cold, but has vulnerability to fire, which means it takes half again as much (+50%) damage as normal from fire, regardless of whether a saving throw is allowed, or if the save is a success or failure. Your special mount is also hardier than a nonfrostfell version; it gains a +2 racial bonus to Constitution."}'::jsonb)
on conflict (id) do update set feat_type = excluded.feat_type, level = excluded.level, name_pt = excluded.name_pt, name_en = excluded.name_en, description_pt = excluded.description_pt, prerequisites = excluded.prerequisites, traits = excluded.traits, ruleset = excluded.ruleset, source_book = excluded.source_book, source_page = excluded.source_page, system_id = excluded.system_id, data = excluded.data, updated_at = now();

insert into public.catalog_weapons (id,name_pt,name_en,description_pt,weapon_category,damage_dice,damage_type,hands,price_gp,traits,ruleset,source_book,source_page,system_id,data) values
('dnd35.frostburn.weapon.frostburn-ice-axe','Ice axe','Ice axe','More tool than weapon, the ice axe has a sharp metal head that is perpendicular to the shaft and has a spiked handle. It grants a +1 circumstance bonus on Climb checks in mountainous and/or icy terrain, even if you do not possess the Exotic Weapon Proficiency (ice axe) feat. If you do possess this feat, the bonus increases to a +4 circumstance bonus. An ice axe may be used as a martial weapon, but takes a –2 penalty on attack rolls in this case.','exotic','1d6','Piercing or slashing','1',10,ARRAY['One-Handed']::text[],'v35-frostburn','D&D 3.5 — Frostburn',76,'dnd35','{"id":"frostburn-ice-axe","name":"Ice axe","group":"One-Handed","cost":"10 gp","damageSmall":"1d4","damageMedium":"1d6","critical":"×4","rangeIncrement":"—","rangeIncrementSpecialNote":false,"weight":"5 lb.","type":"Piercing or slashing","description":"More tool than weapon, the ice axe has a sharp metal head that is perpendicular to the shaft and has a spiked handle. It grants a +1 circumstance bonus on Climb checks in mountainous and/or icy terrain, even if you do not possess the Exotic Weapon Proficiency (ice axe) feat. If you do possess this feat, the bonus increases to a +4 circumstance bonus. An ice axe may be used as a martial weapon, but takes a –2 penalty on attack rolls in this case."}'::jsonb),
('dnd35.frostburn.weapon.frostburn-iuak','Iuak','Iuak','An iuak is a heavily weighted machete-shaped blade, usually made of bone or stone. While it makes an excellent weapon, its primary purpose is to cut through and destroy ice and other hard materials. If used against an object, an iuak ignores the first 3 points of hardness possessed by the object.','exotic','1d6','Slashing','1',12,ARRAY['One-Handed']::text[],'v35-frostburn','D&D 3.5 — Frostburn',76,'dnd35','{"id":"frostburn-iuak","name":"Iuak","group":"One-Handed","cost":"12 gp","damageSmall":"1d4","damageMedium":"1d6","critical":"19–20/×2","rangeIncrement":"—","rangeIncrementSpecialNote":false,"weight":"4 lb.","type":"Slashing","description":"An iuak is a heavily weighted machete-shaped blade, usually made of bone or stone. While it makes an excellent weapon, its primary purpose is to cut through and destroy ice and other hard materials. If used against an object, an iuak ignores the first 3 points of hardness possessed by the object."}'::jsonb),
('dnd35.frostburn.weapon.frostburn-tigerskull-club','Tigerskull club','Tigerskull club','The smilodon’s skull is remarkably sturdy; it would have to be, to absorb the impacts of its terrible bite. Many primitive tribes have capitalized on this fact of nature and use smilodon skulls to fashion tigerskull clubs. A tigerskull club consists of a smilodon’s skull (sans lower jaw) lashed to a short length of wood. The twin sabers of the skull’s upper jaw then function as a highly effective picklike weapon. Disarm and trip attacks made with a tigerskull club gain a +2 circumstance bonus. If you fail to trip your opponent, you may choose to drop your tigerskull club to avoid the retaliatory trip attack.','exotic','1d8','Bludgeoning and piercing','1',15,ARRAY['One-Handed']::text[],'v35-frostburn','D&D 3.5 — Frostburn',76,'dnd35','{"id":"frostburn-tigerskull-club","name":"Tigerskull club","group":"One-Handed","cost":"15 gp","damageSmall":"1d6","damageMedium":"1d8","critical":"×4","rangeIncrement":"—","rangeIncrementSpecialNote":false,"weight":"8 lb.","type":"Bludgeoning and piercing","description":"The smilodon’s skull is remarkably sturdy; it would have to be, to absorb the impacts of its terrible bite. Many primitive tribes have capitalized on this fact of nature and use smilodon skulls to fashion tigerskull clubs. A tigerskull club consists of a smilodon’s skull (sans lower jaw) lashed to a short length of wood. The twin sabers of the skull’s upper jaw then function as a highly effective picklike weapon. Disarm and trip attacks made with a tigerskull club gain a +2 circumstance bonus. If you fail to trip your opponent, you may choose to drop your tigerskull club to avoid the retaliatory trip attack."}'::jsonb),
('dnd35.frostburn.weapon.frostburn-goad','Goad','Goad','A goad is a long, thin wooden pole mounted with a heavy stone or metal weight and a large spike at one end. Primarily intended as a tool to direct the movement of large animals, a goad makes an excellent weapon in a pinch. When you attack with a goad, you must decide if you are attacking with the spike to deal piercing damage or the weight to deal bludgeoning damage. The flexibility of the goad’s shaft absorbs much of the force behind blows made with the bludgeoning head, and all bludgeoning damage dealt by a goad is nonlethal as a result. Piercing damage remains lethal. If you are proficient with its use, the goad grants a +2 circumstance bonus on all Handle Animal checks made against animals of Huge size or larger.','exotic','2d4','Bludgeoning or piercing','2',8,ARRAY['Two-Handed']::text[],'v35-frostburn','D&D 3.5 — Frostburn',76,'dnd35','{"id":"frostburn-goad","name":"Goad","group":"Two-Handed","cost":"8 gp","damageSmall":"1d6","damageMedium":"2d4","critical":"×2","rangeIncrement":"—","rangeIncrementSpecialNote":false,"weight":"10 lb.","type":"Bludgeoning or piercing","description":"A goad is a long, thin wooden pole mounted with a heavy stone or metal weight and a large spike at one end. Primarily intended as a tool to direct the movement of large animals, a goad makes an excellent weapon in a pinch. When you attack with a goad, you must decide if you are attacking with the spike to deal piercing damage or the weight to deal bludgeoning damage. The flexibility of the goad’s shaft absorbs much of the force behind blows made with the bludgeoning head, and all bludgeoning damage dealt by a goad is nonlethal as a result. Piercing damage remains lethal. If you are proficient with its use, the goad grants a +2 circumstance bonus on all Handle Animal checks made against animals of Huge size or larger."}'::jsonb),
('dnd35.frostburn.weapon.frostburn-ritiik','Ritiik','Ritiik','A ritiik is a spearlike weapon with an additional hooklike blade protruding from the base of the spear head. When you successfully hit a target with a ritiik, you can twist the weapon and hook this blade into the target’s flesh if the target fails a Reflex saving throw (DC 10 + the damage dealt). If you hook the target, you can immediately make a trip attack against the target. If you fail, you can let go of the ritiik to avoid the retaliatory trip attack. The damaged creature can pull the ritiik from its wound if it has two free hands and takes a full-round action to do so, but it deals damage to itself equal to the initial damage the ritiik dealt. A character who succeeds on a DC 15 Heal check can remove a ritiik without further damage.','exotic','1d8','Piercing','2',5,ARRAY['Two-Handed']::text[],'v35-frostburn','D&D 3.5 — Frostburn',76,'dnd35','{"id":"frostburn-ritiik","name":"Ritiik","group":"Two-Handed","cost":"5 gp","damageSmall":"1d6","damageMedium":"1d8","critical":"×3","rangeIncrement":"—","rangeIncrementSpecialNote":false,"weight":"6 lb.","type":"Piercing","description":"A ritiik is a spearlike weapon with an additional hooklike blade protruding from the base of the spear head. When you successfully hit a target with a ritiik, you can twist the weapon and hook this blade into the target’s flesh if the target fails a Reflex saving throw (DC 10 + the damage dealt). If you hook the target, you can immediately make a trip attack against the target. If you fail, you can let go of the ritiik to avoid the retaliatory trip attack. The damaged creature can pull the ritiik from its wound if it has two free hands and takes a full-round action to do so, but it deals damage to itself equal to the initial damage the ritiik dealt. A character who succeeds on a DC 15 Heal check can remove a ritiik without further damage."}'::jsonb),
('dnd35.frostburn.weapon.frostburn-sugliin','Sugliin','Sugliin','The infamous sugliin was created by primitive tribes more to strike terror into the hearts of their enemies rather than to be an effective weapon. This massive polearm consists of several sets of sharpened caribou and/or megaloceros antlers affixed to a long wooden shaft. You attack with the sugliin as if it were a massive axe or scythe, slashing and chopping at the targets with great arcs. This weapon is so unwieldy and heavy that making a single attack with it is a full-round action. Sugliins are favored weapons for low-level characters who want to deal huge amounts of damage and lack the skill to make additional attacks; higher-level characters only rarely use sugliins due to their awkwardness. The Sugliin Mastery feat (see page 50) allows a character to make attacks with this massive weapon normally. A sugliin has reach. You can strike opponents 10 feet away with it, but you can’t use it against an adjacent foe.','exotic','2d8','Piercing and slashing','2',35,ARRAY['Two-Handed']::text[],'v35-frostburn','D&D 3.5 — Frostburn',76,'dnd35','{"id":"frostburn-sugliin","name":"Sugliin","group":"Two-Handed","cost":"35 gp","damageSmall":"2d6","damageMedium":"2d8","critical":"×2","rangeIncrement":"—","rangeIncrementSpecialNote":false,"weight":"20 lb.","type":"Piercing and slashing","description":"The infamous sugliin was created by primitive tribes more to strike terror into the hearts of their enemies rather than to be an effective weapon. This massive polearm consists of several sets of sharpened caribou and/or megaloceros antlers affixed to a long wooden shaft. You attack with the sugliin as if it were a massive axe or scythe, slashing and chopping at the targets with great arcs. This weapon is so unwieldy and heavy that making a single attack with it is a full-round action. Sugliins are favored weapons for low-level characters who want to deal huge amounts of damage and lack the skill to make additional attacks; higher-level characters only rarely use sugliins due to their awkwardness. The Sugliin Mastery feat (see page 50) allows a character to make attacks with this massive weapon normally. A sugliin has reach. You can strike opponents 10 feet away with it, but you can’t use it against an adjacent foe."}'::jsonb),
('dnd35.frostburn.weapon.frostburn-bone-bow','Bone bow','Bone bow','This powerful and oversized bow is designed to fire exceptionally large arrows specially made for it. Made of the bones and sinews of huge animals such as woolly mammoths and dire rhinoceroses, these bows were designed by primitive cultures expressly for the hunting of huge creatures that require a lot of damage to take down. A bone bow functions as a composite longbow with regard to applying the user’s Strength bonus to damage done with arrows shot from it. The bow has a long, thick spike protruding from both ends; this spike is used to brace against a solid object (either the ground or an overhanging protrusion or ceiling) to aid in pulling the bow’s string. A character may use a bone bow as a martial weapon, but doing so imparts a –4 penalty on attack rolls, and firing an arrow from the bow requires a fullround action. For purposes of feats such as Weapon Focus and Weapon Specialization, a bone bow is treated as if it were a longbow; thus if you have Weapon Focus (longbow), that feat applies to bone bows as well.','exotic','1d10','Piercing','1',250,ARRAY['Ranged']::text[],'v35-frostburn','D&D 3.5 — Frostburn',76,'dnd35','{"id":"frostburn-bone-bow","name":"Bone bow","group":"Ranged","cost":"250 gp","damageSmall":"1d8","damageMedium":"1d10","critical":"×3","rangeIncrement":"120 ft.","rangeIncrementSpecialNote":false,"weight":"4 lb.","type":"Piercing","description":"This powerful and oversized bow is designed to fire exceptionally large arrows specially made for it. Made of the bones and sinews of huge animals such as woolly mammoths and dire rhinoceroses, these bows were designed by primitive cultures expressly for the hunting of huge creatures that require a lot of damage to take down. A bone bow functions as a composite longbow with regard to applying the user’s Strength bonus to damage done with arrows shot from it. The bow has a long, thick spike protruding from both ends; this spike is used to brace against a solid object (either the ground or an overhanging protrusion or ceiling) to aid in pulling the bow’s string. A character may use a bone bow as a martial weapon, but doing so imparts a –4 penalty on attack rolls, and firing an arrow from the bow requires a fullround action. For purposes of feats such as Weapon Focus and Weapon Specialization, a bone bow is treated as if it were a longbow; thus if you have Weapon Focus (longbow), that feat applies to bone bows as well."}'::jsonb),
('dnd35.frostburn.weapon.frostburn-glot','Glot','Glot','The glot is a specially balanced sphere of metal designed to be thrown low to the ground. It then skips and bounces across the ground with little reduction in velocity to strike its target. If the ground between you and your target is solid, flat, and relatively free of obstructions, the glot’s range increment increases to 20 feet. If the ground is also icy, the glot skips even more readily over the frozen ground and its range increment increases to 30 feet. If you use a glot to attack an airborne target, its range increment is always 10 feet. You can make ranged trip attacks with a thrown glot.','exotic','1d4','Bludgeoning','1',1,ARRAY['Ranged']::text[],'v35-frostburn','D&D 3.5 — Frostburn',76,'dnd35','{"id":"frostburn-glot","name":"Glot","group":"Ranged","cost":"1 gp","damageSmall":"1d3","damageMedium":"1d4","critical":"18–20/×2","rangeIncrement":"10 ft.","rangeIncrementSpecialNote":true,"weight":"1 lb.","type":"Bludgeoning","description":"The glot is a specially balanced sphere of metal designed to be thrown low to the ground. It then skips and bounces across the ground with little reduction in velocity to strike its target. If the ground between you and your target is solid, flat, and relatively free of obstructions, the glot’s range increment increases to 20 feet. If the ground is also icy, the glot skips even more readily over the frozen ground and its range increment increases to 30 feet. If you use a glot to attack an airborne target, its range increment is always 10 feet. You can make ranged trip attacks with a thrown glot."}'::jsonb),
('dnd35.frostburn.weapon.frostburn-harpoon','Harpoon','Harpoon','The harpoon is a broad-bladed spear forged with barbs. The shaft of the harpoon has a trailing rope attached to control harpooned opponents. Though designed for hunting whales and other large sea creatures, the harpoon can be used on dry land. If it deals damage, the harpoon lodges in an opponent who fails a Reflex saving throw (DC 10 + the damage dealt). A harpooned creature moves at only half speed and cannot charge or run. If you control the trailing rope by succeed-ing on an opposed Strength check while holding it, the harpooned creature can move only within the limits that the rope allows (the trailing rope is 30 feet long). If the harpooned creature attempts to cast a spell, it must succeed on a DC 15 Concentration check or lose the spell. The harpooned creature can pull the harpoon from its wound if it has two free hands and takes a full-round action to do so, but it deals damage to itself equal to the initial damage the harpoon dealt. A character who succeeds on a DC 15 Heal check can remove a harpoon without further damage.','exotic','1d10','Piercing','1',15,ARRAY['Ranged']::text[],'v35-frostburn','D&D 3.5 — Frostburn',76,'dnd35','{"id":"frostburn-harpoon","name":"Harpoon","group":"Ranged","cost":"15 gp","damageSmall":"1d8","damageMedium":"1d10","critical":"×2","rangeIncrement":"30 ft.","rangeIncrementSpecialNote":false,"weight":"10 lb.","type":"Piercing","description":"The harpoon is a broad-bladed spear forged with barbs. The shaft of the harpoon has a trailing rope attached to control harpooned opponents. Though designed for hunting whales and other large sea creatures, the harpoon can be used on dry land. If it deals damage, the harpoon lodges in an opponent who fails a Reflex saving throw (DC 10 + the damage dealt). A harpooned creature moves at only half speed and cannot charge or run. If you control the trailing rope by succeed-ing on an opposed Strength check while holding it, the harpooned creature can move only within the limits that the rope allows (the trailing rope is 30 feet long). If the harpooned creature attempts to cast a spell, it must succeed on a DC 15 Concentration check or lose the spell. The harpooned creature can pull the harpoon from its wound if it has two free hands and takes a full-round action to do so, but it deals damage to itself equal to the initial damage the harpoon dealt. A character who succeeds on a DC 15 Heal check can remove a harpoon without further damage."}'::jsonb),
('dnd35.frostburn.weapon.frostburn-icechucker','Icechucker','Icechucker','The icechucker appears to be a large crossbow at a casual glance, larger even than a heavy crossbow. Its launching mechanism is designed to fire large shards of ice (usually icicles) rather than regular crossbow bolts. You draw an icechucker back by pulling on a thick lever on the underside of the weapon. Loading an icechucker is a fullround action that provokes attacks of opportunity. If icicles aren’t handy to load into an icechucker, it can also be used to fire a javelin, dealing the same damage.','exotic','1d12','Piercing','1',150,ARRAY['Ranged']::text[],'v35-frostburn','D&D 3.5 — Frostburn',76,'dnd35','{"id":"frostburn-icechucker","name":"Icechucker","group":"Ranged","cost":"150 gp","damageSmall":"1d10","damageMedium":"1d12","critical":"×3","rangeIncrement":"30 ft.","rangeIncrementSpecialNote":false,"weight":"12 lb.","type":"Piercing","description":"The icechucker appears to be a large crossbow at a casual glance, larger even than a heavy crossbow. Its launching mechanism is designed to fire large shards of ice (usually icicles) rather than regular crossbow bolts. You draw an icechucker back by pulling on a thick lever on the underside of the weapon. Loading an icechucker is a fullround action that provokes attacks of opportunity. If icicles aren’t handy to load into an icechucker, it can also be used to fire a javelin, dealing the same damage."}'::jsonb),
('dnd35.frostburn.weapon.frostburn-razor-skipdisk','Razor skipdisk','Razor skipdisk','A razor skipdisk is a flat, circular disk of metal with a razor-sharp rim. One surface of the razor skipdisk is slightly convex and smooth, while the other is concave with a small knob protruding from the center. You attack with a razor skipdisk by gripping the knob and then hurling it so the convex surface skips and slides across the ground toward its target. If the ground between you and your target is solid, flat, and relatively free of obstructions, the razor skipdisk’s range increment increases to 20 feet. If the ground is also icy, the razor skipdisk skips even more readily over the frozen ground and its range increment increases to 30 feet. If you use a razor skipdisk to attack an airborne target, its range increment is always 10 feet.','exotic','1d6','Slashing','1',15,ARRAY['Ranged']::text[],'v35-frostburn','D&D 3.5 — Frostburn',76,'dnd35','{"id":"frostburn-razor-skipdisk","name":"Razor skipdisk","group":"Ranged","cost":"15 gp","damageSmall":"1d4","damageMedium":"1d6","critical":"18–20/×2","rangeIncrement":"10 ft.","rangeIncrementSpecialNote":true,"weight":"2 lb.","type":"Slashing","description":"A razor skipdisk is a flat, circular disk of metal with a razor-sharp rim. One surface of the razor skipdisk is slightly convex and smooth, while the other is concave with a small knob protruding from the center. You attack with a razor skipdisk by gripping the knob and then hurling it so the convex surface skips and slides across the ground toward its target. If the ground between you and your target is solid, flat, and relatively free of obstructions, the razor skipdisk’s range increment increases to 20 feet. If the ground is also icy, the razor skipdisk skips even more readily over the frozen ground and its range increment increases to 30 feet. If you use a razor skipdisk to attack an airborne target, its range increment is always 10 feet."}'::jsonb)
on conflict (id) do update set name_pt = excluded.name_pt, name_en = excluded.name_en, description_pt = excluded.description_pt, weapon_category = excluded.weapon_category, damage_dice = excluded.damage_dice, damage_type = excluded.damage_type, hands = excluded.hands, price_gp = excluded.price_gp, traits = excluded.traits, ruleset = excluded.ruleset, source_book = excluded.source_book, source_page = excluded.source_page, system_id = excluded.system_id, data = excluded.data, updated_at = now();

insert into public.catalog_items (id,name_pt,name_en,description_pt,item_category,level,price_gp,traits,ruleset,source_book,source_page,system_id,data) values
('dnd35.frostburn.gear.frostburn-crampons','Crampons','Crampons','Crampons consist of a set of metal spikes and hooks that lash on to boots and gauntlets to assist in climbing or walking across icy surfaces. While you wear crampons, you gain a +2 circumstance bonus on any Balance checks made to avoid slipping on an icy surface, and a +2 circumstance bonus on Climb checks. Crampons impose a –10 ft. penalty to speed when not walking on snow or ice.','gear',0,5,ARRAY[]::text[],'v35-frostburn','D&D 3.5 — Frostburn',78,'dnd35','{"id":"frostburn-crampons","name":"Crampons","cost":"5 gp","weight":"1 lb.","description":"Crampons consist of a set of metal spikes and hooks that lash on to boots and gauntlets to assist in climbing or walking across icy surfaces. While you wear crampons, you gain a +2 circumstance bonus on any Balance checks made to avoid slipping on an icy surface, and a +2 circumstance bonus on Climb checks. Crampons impose a –10 ft. penalty to speed when not walking on snow or ice."}'::jsonb),
('dnd35.frostburn.gear.frostburn-fur-clothing','Fur clothing','Fur clothing','Fur clothing consists of thick layers of animal furs designed to be worn over a regular set of clothing or armor. Wearing fur clothing grants a +5 circumstance bonus on Fortitude saving throws against exposure to cold weather. Fur clothing can be worn over a cold weather outfit; in this case the circumstance bonuses granted by each item stack, granting a total +10 circumstance bonus on Fortitude saving throws against exposure to cold weather. Fur clothing is cumbersome to wear. Although the furs do not provide an appreciable armor bonus, they do increase your total armor check penalty for any armor worn by 2 points.','gear',0,8,ARRAY[]::text[],'v35-frostburn','D&D 3.5 — Frostburn',78,'dnd35','{"id":"frostburn-fur-clothing","name":"Fur clothing","cost":"8 gp","weight":"10 lb.","description":"Fur clothing consists of thick layers of animal furs designed to be worn over a regular set of clothing or armor. Wearing fur clothing grants a +5 circumstance bonus on Fortitude saving throws against exposure to cold weather. Fur clothing can be worn over a cold weather outfit; in this case the circumstance bonuses granted by each item stack, granting a total +10 circumstance bonus on Fortitude saving throws against exposure to cold weather. Fur clothing is cumbersome to wear. Although the furs do not provide an appreciable armor bonus, they do increase your total armor check penalty for any armor worn by 2 points."}'::jsonb),
('dnd35.frostburn.gear.frostburn-hut-portable','Hut, portable','Hut, portable','A portable hut consists of a wooden framework that can be quickly assembled into a hut-shaped frame that covers a 10-foot square. The frame’s base consists of several iron spikes that can be driven through holes in the frame to affix the hut frame to the ground; further stability is granted by several rope supports that extend out 15 feet from the hut’s edge. Once the frame is in place, you simply attach the leather and fur wrappings over the outside of the wall and lash them directly to the frame to finish building the hut. A portable hut provides excellent shelter in the wilderness; assembling or disassembling a portable hut only takes 15 minutes of work. A portable hut serves as an improvised shelter (see page 10).','gear',0,125,ARRAY[]::text[],'v35-frostburn','D&D 3.5 — Frostburn',78,'dnd35','{"id":"frostburn-hut-portable","name":"Hut, portable","cost":"125 gp","weight":"75 lb.","description":"A portable hut consists of a wooden framework that can be quickly assembled into a hut-shaped frame that covers a 10-foot square. The frame’s base consists of several iron spikes that can be driven through holes in the frame to affix the hut frame to the ground; further stability is granted by several rope supports that extend out 15 feet from the hut’s edge. Once the frame is in place, you simply attach the leather and fur wrappings over the outside of the wall and lash them directly to the frame to finish building the hut. A portable hut provides excellent shelter in the wilderness; assembling or disassembling a portable hut only takes 15 minutes of work. A portable hut serves as an improvised shelter (see page 10)."}'::jsonb),
('dnd35.frostburn.gear.frostburn-skates','Skates','Skates','Skates allow full movement across icy surfaces for anyone with at least 5 ranks of Balance, but cannot be used at all on any other terrain.','gear',0,10,ARRAY[]::text[],'v35-frostburn','D&D 3.5 — Frostburn',78,'dnd35','{"id":"frostburn-skates","name":"Skates","cost":"10 gp","weight":"3 lb.","description":"Skates allow full movement across icy surfaces for anyone with at least 5 ranks of Balance, but cannot be used at all on any other terrain."}'::jsonb),
('dnd35.frostburn.gear.frostburn-skis-and-poles','Skis and poles','Skis and poles','Skis allow full movement across snow and icy surfaces but cannot be used at all on any other terrain. Downhill speed can be as a run (×4) on slight grades or as a run (×5) on severe grades. It takes a full-round action to don or to remove skis.','gear',0,15,ARRAY[]::text[],'v35-frostburn','D&D 3.5 — Frostburn',78,'dnd35','{"id":"frostburn-skis-and-poles","name":"Skis and poles","cost":"15 gp","weight":"6 lb.","description":"Skis allow full movement across snow and icy surfaces but cannot be used at all on any other terrain. Downhill speed can be as a run (×4) on slight grades or as a run (×5) on severe grades. It takes a full-round action to don or to remove skis."}'::jsonb),
('dnd35.frostburn.gear.frostburn-snow-goggles','Snow goggles','Snow goggles','These wooden goggles have a thin horizontal slit in the middle. They grant a +2 circumstance bonus on saving throws to resist blinding effects, including snow blindness, extremely bright light, or spells that target vision indirectly (such as sunburst but not blindness). While wearing snow goggles, you incur a –4 circumstance penalty on Spot and Search checks.','gear',0,2,ARRAY[]::text[],'v35-frostburn','D&D 3.5 — Frostburn',78,'dnd35','{"id":"frostburn-snow-goggles","name":"Snow goggles","cost":"2 gp","weight":"—","description":"These wooden goggles have a thin horizontal slit in the middle. They grant a +2 circumstance bonus on saving throws to resist blinding effects, including snow blindness, extremely bright light, or spells that target vision indirectly (such as sunburst but not blindness). While wearing snow goggles, you incur a –4 circumstance penalty on Spot and Search checks."}'::jsonb),
('dnd35.frostburn.gear.frostburn-snowshoes','Snowshoes','Snowshoes','These allow the wearer to move across snow and ice with increased speed. Snow of any depth is considered a minor impediment (see page 12). Snowshoes take 1 minute to don and a full-round action to remove.','gear',0,15,ARRAY[]::text[],'v35-frostburn','D&D 3.5 — Frostburn',78,'dnd35','{"id":"frostburn-snowshoes","name":"Snowshoes","cost":"15 gp","weight":"8 lb.","description":"These allow the wearer to move across snow and ice with increased speed. Snow of any depth is considered a minor impediment (see page 12). Snowshoes take 1 minute to don and a full-round action to remove."}'::jsonb),
('dnd35.frostburn.gear.frostburn-winter-fullcloth','Winter fullcloth','Winter fullcloth','This is a heavily quilted undergarment that is worn underneath regular clothing to protect the wearer against cold. Winter fullcloth is considered part of the cold weather outfit described in the Player’s Handbook. If worn by itself, it grants a +1 circumstance bonus on Fortitude saving throws against exposure to cold weather.','gear',0,4,ARRAY[]::text[],'v35-frostburn','D&D 3.5 — Frostburn',78,'dnd35','{"id":"frostburn-winter-fullcloth","name":"Winter fullcloth","cost":"4 gp","weight":"2 lb.","description":"This is a heavily quilted undergarment that is worn underneath regular clothing to protect the wearer against cold. Winter fullcloth is considered part of the cold weather outfit described in the Player’s Handbook. If worn by itself, it grants a +1 circumstance bonus on Fortitude saving throws against exposure to cold weather."}'::jsonb),
('dnd35.frostburn.alchemical.frostburn-armor-insulation','Armor insulation (flask)','Armor insulation (flask)','This thick red syrupy mixture is applied with a brush to the inner surface of a suit of armor. When the mixture comes in contact with body heat and sweat, it puffs up to trap body heat, insulating the wearer against the effects of cold. For 24 hours after application, the wearer of a suit of armor treated with armor insulation gains a +5 circumstance bonus on Fortitude saving throws against exposure to cold weather.','alchemical',0,50,ARRAY[]::text[],'v35-frostburn','D&D 3.5 — Frostburn',78,'dnd35','{"id":"frostburn-armor-insulation","name":"Armor insulation (flask)","craftDc":25,"cost":"50 gp","weight":"2 lb.","description":"This thick red syrupy mixture is applied with a brush to the inner surface of a suit of armor. When the mixture comes in contact with body heat and sweat, it puffs up to trap body heat, insulating the wearer against the effects of cold. For 24 hours after application, the wearer of a suit of armor treated with armor insulation gains a +5 circumstance bonus on Fortitude saving throws against exposure to cold weather."}'::jsonb),
('dnd35.frostburn.alchemical.frostburn-freeze-powder','Freeze powder (vial)','Freeze powder (vial)','Freeze powder looks like salt but is much finer to touch. One vial of freeze powder sprinkled into any liquid is enough to instantly freeze solid 1 cubic foot of liquid. If introduced into a larger body of water or liquid, the powder freezes into a 1-foot diameter ball of ice. Sprinkled on a wet floor, a vial of freeze powder can coat a 10-foot-square area with ice. Freeze powder is dangerous to eat; anyone foolish enough to swallow a vial of freeze powder takes 2d6 points of cold damage as the powder freeze-burns his mouth and throat. A successful DC 15 Fortitude saving throw halves the damage.','alchemical',0,100,ARRAY[]::text[],'v35-frostburn','D&D 3.5 — Frostburn',78,'dnd35','{"id":"frostburn-freeze-powder","name":"Freeze powder (vial)","craftDc":25,"cost":"100 gp","weight":"1 lb.","description":"Freeze powder looks like salt but is much finer to touch. One vial of freeze powder sprinkled into any liquid is enough to instantly freeze solid 1 cubic foot of liquid. If introduced into a larger body of water or liquid, the powder freezes into a 1-foot diameter ball of ice. Sprinkled on a wet floor, a vial of freeze powder can coat a 10-foot-square area with ice. Freeze powder is dangerous to eat; anyone foolish enough to swallow a vial of freeze powder takes 2d6 points of cold damage as the powder freeze-burns his mouth and throat. A successful DC 15 Fortitude saving throw halves the damage."}'::jsonb),
('dnd35.frostburn.alchemical.frostburn-frostbite-salve','Frostbite salve (jar)','Frostbite salve (jar)','This pale yellow cream provides instant relief from frostbite damage. It does not cure frostburn damage (see page 17), but temporarily suppresses up to 2 points of ability score damage caused by frostbite. The salve’s effectiveness lasts for just one hour, after which point the ability score damage suppressed by the salve returns.','alchemical',0,50,ARRAY[]::text[],'v35-frostburn','D&D 3.5 — Frostburn',78,'dnd35','{"id":"frostburn-frostbite-salve","name":"Frostbite salve (jar)","craftDc":20,"cost":"50 gp","weight":"1 lb.","description":"This pale yellow cream provides instant relief from frostbite damage. It does not cure frostburn damage (see page 17), but temporarily suppresses up to 2 points of ability score damage caused by frostbite. The salve’s effectiveness lasts for just one hour, after which point the ability score damage suppressed by the salve returns."}'::jsonb),
('dnd35.frostburn.alchemical.frostburn-ice-chalk','Ice chalk','Ice chalk','Ice chalk comes in a variety of colors. These waxy sticks can be used to make temporary marks on any icy surface, similar to how chalk can be used to mark slate or stone.','alchemical',0,20,ARRAY[]::text[],'v35-frostburn','D&D 3.5 — Frostburn',78,'dnd35','{"id":"frostburn-ice-chalk","name":"Ice chalk","craftDc":15,"cost":"20 gp","weight":"—","description":"Ice chalk comes in a variety of colors. These waxy sticks can be used to make temporary marks on any icy surface, similar to how chalk can be used to mark slate or stone."}'::jsonb),
('dnd35.frostburn.alchemical.frostburn-melt-powder','Melt powder (vial)','Melt powder (vial)','Utilizing some of the same principles as freeze powder, melt powder causes ice it is sprinkled upon to instantly melt. One vial of melt powder is enough to melt 1 cubic foot of ice. Sprinkled on an icy surface of up to 10 square feet, a vial of melt powder makes a 1-inch-deep pool of water that quickly refreezes. Melt powder is bitter tasting, but only harmful to creatures with the cold subtype if it is eaten. Such creatures take 2d6 points of acid damage as the powder desiccates and dissolves their tissues; a successful DC 15 Fortitude save halves the damage.','alchemical',0,25,ARRAY[]::text[],'v35-frostburn','D&D 3.5 — Frostburn',78,'dnd35','{"id":"frostburn-melt-powder","name":"Melt powder (vial)","craftDc":20,"cost":"25 gp","weight":"1 lb.","description":"Utilizing some of the same principles as freeze powder, melt powder causes ice it is sprinkled upon to instantly melt. One vial of melt powder is enough to melt 1 cubic foot of ice. Sprinkled on an icy surface of up to 10 square feet, a vial of melt powder makes a 1-inch-deep pool of water that quickly refreezes. Melt powder is bitter tasting, but only harmful to creatures with the cold subtype if it is eaten. Such creatures take 2d6 points of acid damage as the powder desiccates and dissolves their tissues; a successful DC 15 Fortitude save halves the damage."}'::jsonb),
('dnd35.frostburn.alchemical.frostburn-polar-skin','Polar skin (flask)','Polar skin (flask)','This dull white cream provides limited protection against cold-based damage. Polar skin becomes ineffective once it has absorbed 5 points of cold damage. Regardless of whether it absorbs any damage, polar skin loses its effectiveness 1 hour after application. Polar skin does not stack with magical protection from cold. Magical effects such as resist energy supersede the protection provided by polar skin. Applying polar skin takes 1 minute.','alchemical',0,25,ARRAY[]::text[],'v35-frostburn','D&D 3.5 — Frostburn',78,'dnd35','{"id":"frostburn-polar-skin","name":"Polar skin (flask)","craftDc":25,"cost":"25 gp","weight":"1 lb.","description":"This dull white cream provides limited protection against cold-based damage. Polar skin becomes ineffective once it has absorbed 5 points of cold damage. Regardless of whether it absorbs any damage, polar skin loses its effectiveness 1 hour after application. Polar skin does not stack with magical protection from cold. Magical effects such as resist energy supersede the protection provided by polar skin. Applying polar skin takes 1 minute."}'::jsonb),
('dnd35.frostburn.alchemical.frostburn-razor-ice-powder','Razor ice powder (vial)','Razor ice powder (vial)','This granular white powder can be sprinkled over any icy surface; one vial is enough to coat one 5-foot square. The area coated immediately grows hundreds of tiny razor-sharp crystals of ice; these crystals function as if the area had been covered with razor ice (see page 16). Razor ice is difficult to see; a successful DC 20 Survival check reveals the danger, otherwise, a victim won’t realize the true nature of the painful ice until she treads upon it. A creature with the cold subtype can use a standard action to sprinkle a vial of razor ice powder on any single natural weapon it possesses; it grants a +1 enhancement bonus on slashing damage for that natural attack for one hour.','alchemical',0,50,ARRAY[]::text[],'v35-frostburn','D&D 3.5 — Frostburn',78,'dnd35','{"id":"frostburn-razor-ice-powder","name":"Razor ice powder (vial)","craftDc":25,"cost":"50 gp","weight":"1 lb.","description":"This granular white powder can be sprinkled over any icy surface; one vial is enough to coat one 5-foot square. The area coated immediately grows hundreds of tiny razor-sharp crystals of ice; these crystals function as if the area had been covered with razor ice (see page 16). Razor ice is difficult to see; a successful DC 20 Survival check reveals the danger, otherwise, a victim won’t realize the true nature of the painful ice until she treads upon it. A creature with the cold subtype can use a standard action to sprinkle a vial of razor ice powder on any single natural weapon it possesses; it grants a +1 enhancement bonus on slashing damage for that natural attack for one hour."}'::jsonb),
('dnd35.frostburn.alchemical.frostburn-whale-grease','Whale grease (flask)','Whale grease (flask)','Whale grease is a thick clear grease fashioned from a combination of melted whale blubber and various powdered minerals and waxy plants. This foul-smelling stuff must be applied directly to the skin (taking 1 minute to do so) to be effective; once applied, the grease insulates the user from hypothermia, providing complete protection from hypothermia effects for as long as it lasts. Whale grease loses its effectiveness 1 hour after application. It is not water soluble, but can be quickly removed with alcohol. While worn, the pungent odor the grease gives off allows creatures with the scent ability to detect you at double normal range.','alchemical',0,75,ARRAY[]::text[],'v35-frostburn','D&D 3.5 — Frostburn',78,'dnd35','{"id":"frostburn-whale-grease","name":"Whale grease (flask)","craftDc":25,"cost":"75 gp","weight":"2 lb.","description":"Whale grease is a thick clear grease fashioned from a combination of melted whale blubber and various powdered minerals and waxy plants. This foul-smelling stuff must be applied directly to the skin (taking 1 minute to do so) to be effective; once applied, the grease insulates the user from hypothermia, providing complete protection from hypothermia effects for as long as it lasts. Whale grease loses its effectiveness 1 hour after application. It is not water soluble, but can be quickly removed with alcohol. While worn, the pungent odor the grease gives off allows creatures with the scent ability to detect you at double normal range."}'::jsonb),
('dnd35.frostburn.magic-item.frostburn-crystal-tear-minor-artifact','Crystal Tear','Crystal Tear','Legends hold that when Iborighu smote down Hleid and cast her fractured body into the polar sea, she cried for the loss to the uldra race. As her body arced over the polar world to the sea, these tears fell to the ground and became frozen, and some of Hleid’s divine power and emotion became frozen along with them and became crystal tears. A crystal tear looks like a large tear made of ice with flashes of light sparkling in its depths. These are potent minor artifacts; their presence constantly exudes a strong emotional magical effect (as a 20th-level caster) in an emanation with a 15-foot radius. As a free action, the holder of the tear can choose to produce either crushing despair or good hope. Once an effect is chosen, it operates until the holder changes it. The tear continues to emanate the last emotion the holder chose if the holder puts down the tear. The holder can decide as a free action what creatures in the area are affected. Living creatures in the emanation can attempt a DC 16 Will save to avoid the emanation’s effects. Those who fail suffer whatever effect the tear is currently producing, for as long as they remain within the radius of the emanation and for 1 minute after leaving. Those who successfully save cannot be affected by the tear’s current emanation for 1 minute (but must save again if the holder changes the effect). The holder of the tear finds that his own emotions are completely “drowned out” by the presence of the tear; this effectively keeps the user from experiencing any emotions at all (incurring a –2 penalty on all Charismabased skill checks), but also has the fortunate side effect of rendering him completely immune to mind-affecting spells and abilities. Overlapping emanations from multiple crystal tears do not stack if they generate identical emotions. Crystal tears do not melt if brought to warmer climates or if exposed to heat or flame; they always retain a cool temperature regardless of their environs. Despite this, the owner of a crystal tear can cause the tear to melt into liquid by targeting it with a spell that is of at least 5th level and carries the fire descriptor. The spell cast is absorbed completely by the tear, which then melts immediately and evaporates in 2d4 rounds. If the melted tear is imbibed before it evaporates, it grants a +4 inherent bonus to one of the drinker’s ability scores. The exact score to which the bonus is applied is determined randomly, although it does not apply to a score that already possesses an inherent bonus. If all the drinker’s scores already possess an inherent bonus, the +4 inherent bonus applies to the score with the lowest bonus.','magic-item',0,null,ARRAY[]::text[],'v35-frostburn','D&D 3.5 — Frostburn',109,'dnd35','{"id":"frostburn-crystal-tear-minor-artifact","name":"Crystal Tear","category":"Minor Artifact","aura":"Strong enchantment","casterLevel":20,"weight":"4 lb","description":"Legends hold that when Iborighu smote down Hleid and cast her fractured body into the polar sea, she cried for the loss to the uldra race. As her body arced over the polar world to the sea, these tears fell to the ground and became frozen, and some of Hleid’s divine power and emotion became frozen along with them and became crystal tears. A crystal tear looks like a large tear made of ice with flashes of light sparkling in its depths. These are potent minor artifacts; their presence constantly exudes a strong emotional magical effect (as a 20th-level caster) in an emanation with a 15-foot radius. As a free action, the holder of the tear can choose to produce either crushing despair or good hope. Once an effect is chosen, it operates until the holder changes it. The tear continues to emanate the last emotion the holder chose if the holder puts down the tear. The holder can decide as a free action what creatures in the area are affected. Living creatures in the emanation can attempt a DC 16 Will save to avoid the emanation’s effects. Those who fail suffer whatever effect the tear is currently producing, for as long as they remain within the radius of the emanation and for 1 minute after leaving. Those who successfully save cannot be affected by the tear’s current emanation for 1 minute (but must save again if the holder changes the effect). The holder of the tear finds that his own emotions are completely “drowned out” by the presence of the tear; this effectively keeps the user from experiencing any emotions at all (incurring a –2 penalty on all Charismabased skill checks), but also has the fortunate side effect of rendering him completely immune to mind-affecting spells and abilities. Overlapping emanations from multiple crystal tears do not stack if they generate identical emotions. Crystal tears do not melt if brought to warmer climates or if exposed to heat or flame; they always retain a cool temperature regardless of their environs. Despite this, the owner of a crystal tear can cause the tear to melt into liquid by targeting it with a spell that is of at least 5th level and carries the fire descriptor. The spell cast is absorbed completely by the tear, which then melts immediately and evaporates in 2d4 rounds. If the melted tear is imbibed before it evaporates, it grants a +4 inherent bonus to one of the drinker’s ability scores. The exact score to which the bonus is applied is determined randomly, although it does not apply to a score that already possesses an inherent bonus. If all the drinker’s scores already possess an inherent bonus, the +4 inherent bonus applies to the score with the lowest bonus."}'::jsonb),
('dnd35.frostburn.magic-item.frostburn-frostfell-figurine-of-wondrous-power','Frostfell Figurine of Wondrous Power','Frostfell Figurine of Wondrous Power','Each of the several kinds of frostfell figurines of wondrous power appears to be a miniature statuette of a creature an inch or so high. When the figurine is tossed down and the correct command word spoken, it becomes a living creature of normal size. The creature obeys and serves its owner. The creature understands Common but does not speak. If a frostfell figurine of wondrous power is broken or destroyed in its statuette form, it is forever ruined. All magic is lost, its power departed. If slain in animal form, the figurine simply reverts to a statuette that can be used again at a later time. Frostfell figurines of wondrous power differ from the standard figurines of wondrous power in that they are always quite cold to the touch. A character who carries a frostfell figurine of wondrous power gains resistance to cold 10 as long as it is in figurine form.','magic-item',0,null,ARRAY[]::text[],'v35-frostburn','D&D 3.5 — Frostburn',109,'dnd35','{"id":"frostburn-frostfell-figurine-of-wondrous-power","name":"Frostfell Figurine of Wondrous Power","description":"Each of the several kinds of frostfell figurines of wondrous power appears to be a miniature statuette of a creature an inch or so high. When the figurine is tossed down and the correct command word spoken, it becomes a living creature of normal size. The creature obeys and serves its owner. The creature understands Common but does not speak. If a frostfell figurine of wondrous power is broken or destroyed in its statuette form, it is forever ruined. All magic is lost, its power departed. If slain in animal form, the figurine simply reverts to a statuette that can be used again at a later time. Frostfell figurines of wondrous power differ from the standard figurines of wondrous power in that they are always quite cold to the touch. A character who carries a frostfell figurine of wondrous power gains resistance to cold 10 as long as it is in figurine form."}'::jsonb),
('dnd35.frostburn.magic-item.frostburn-basalt-glyptodon','Basalt Glyptodon','Basalt Glyptodon','When animated, a basalt glyptodon acts in all ways like a normal glyptodon under the command of its possessor. Unlike a normal glyptodon, a basalt glyptodon has damage reduction 5/—. The item can be used once per week for up to 6 hours per use. When 6 hours have passed or when the command word is spoken, a basalt glyptodon once again becomes a tiny statuette.','magic-item',0,32000,ARRAY[]::text[],'v35-frostburn','D&D 3.5 — Frostburn',109,'dnd35','{"id":"frostburn-basalt-glyptodon","name":"Basalt Glyptodon","family":"Frostfell Figurine of Wondrous Power","aura":"Moderate transmutation","casterLevel":11,"requirements":"Craft Wondrous Item, animate objects, stoneskin","price":"32,000 gp","description":"When animated, a basalt glyptodon acts in all ways like a normal glyptodon under the command of its possessor. Unlike a normal glyptodon, a basalt glyptodon has damage reduction 5/—. The item can be used once per week for up to 6 hours per use. When 6 hours have passed or when the command word is spoken, a basalt glyptodon once again becomes a tiny statuette."}'::jsonb),
('dnd35.frostburn.magic-item.frostburn-coral-zeuglodon','Coral Zeuglodon','Coral Zeuglodon','A coral zeuglodon can only be animated in any body of water large enough to hold the actual creature; it must be thrown into the water and the command word spoken immediately for it to animate. If the command word is not spoken, the coral zeuglodon sinks to the bottom. A coral zeuglodon remains brightly colored when animated, and acts in all ways like a normal zeuglodon under the command of its possessor, except that it has a swim speed of 120 feet. The item can be used up to twice per week for up to 4 hours per use. When a coral zeuglodon returns to figurine form, it magically reappears in the hand of its owner, despite any physical distance between the two. If the owner is dead or on another plane, a coral zeuglodon instead sinks to the bottom of the sea when it returns to figurine form.','magic-item',0,42000,ARRAY[]::text[],'v35-frostburn','D&D 3.5 — Frostburn',109,'dnd35','{"id":"frostburn-coral-zeuglodon","name":"Coral Zeuglodon","family":"Frostfell Figurine of Wondrous Power","aura":"Moderate transmutation","casterLevel":11,"requirements":"Craft Wondrous Item, animate objects","price":"42,000 gp","description":"A coral zeuglodon can only be animated in any body of water large enough to hold the actual creature; it must be thrown into the water and the command word spoken immediately for it to animate. If the command word is not spoken, the coral zeuglodon sinks to the bottom. A coral zeuglodon remains brightly colored when animated, and acts in all ways like a normal zeuglodon under the command of its possessor, except that it has a swim speed of 120 feet. The item can be used up to twice per week for up to 4 hours per use. When a coral zeuglodon returns to figurine form, it magically reappears in the hand of its owner, despite any physical distance between the two. If the owner is dead or on another plane, a coral zeuglodon instead sinks to the bottom of the sea when it returns to figurine form."}'::jsonb),
('dnd35.frostburn.magic-item.frostburn-diamond-ice-toad','Diamond Ice Toad','Diamond Ice Toad','A diamond ice toad acts as a normal ice toad when animated, except that it remains transparent and crystalline in appearance. It remains under the command of its possessor, and gains the benefits of concealment (20% miss chance) due to its transparent nature. It can be activated up to two times per week for 1 hour per use.','magic-item',0,33000,ARRAY[]::text[],'v35-frostburn','D&D 3.5 — Frostburn',109,'dnd35','{"id":"frostburn-diamond-ice-toad","name":"Diamond Ice Toad","family":"Frostfell Figurine of Wondrous Power","aura":"Moderate transmutation","casterLevel":11,"requirements":"Craft Wondrous Item, animate objects, blur","price":"33,000 gp","description":"A diamond ice toad acts as a normal ice toad when animated, except that it remains transparent and crystalline in appearance. It remains under the command of its possessor, and gains the benefits of concealment (20% miss chance) due to its transparent nature. It can be activated up to two times per week for 1 hour per use."}'::jsonb),
('dnd35.frostburn.magic-item.frostburn-iron-megaloceros','Iron Megaloceros','Iron Megaloceros','When animated, an iron megaloceros acts in all ways like a normal megaloceros under the command of its possessor, except that it is a construct made of iron. It possesses damage reduction 5/adamantine, and has immunity to poison, sleep effects, paralysis, stunning, disease, death effects, necromancy effects, mind-affecting effects (charms, compulsions, phantasms, patterns, and morale effects), and any effect that requires a Fortitude save unless it also works on objects or is harmless. It is not subject to extra damage from critical hits, nonlethal damage, ability damage, ability drain, fatigue, exhaustion, or energy drain. It cannot heal damage, but can be repaired. An iron megaloceros has darkvision 60 ft. and low-light vision. It has no Constitution score, but it does have 10-sided Hit Dice and 30 bonus hit points, granting it 63 hit points total. It can be affected normally by rust attacks, such as that of a rust monster or a rusting grasp spell. It functions in all other ways like a standard megaloceros. The item can be used up to twice a week for up to 6 hours per use.','magic-item',0,27000,ARRAY[]::text[],'v35-frostburn','D&D 3.5 — Frostburn',109,'dnd35','{"id":"frostburn-iron-megaloceros","name":"Iron Megaloceros","family":"Frostfell Figurine of Wondrous Power","aura":"Moderate transmutation","casterLevel":11,"requirements":"Craft Wondrous Item, Craft Construct, animate objects","price":"27,000 gp","description":"When animated, an iron megaloceros acts in all ways like a normal megaloceros under the command of its possessor, except that it is a construct made of iron. It possesses damage reduction 5/adamantine, and has immunity to poison, sleep effects, paralysis, stunning, disease, death effects, necromancy effects, mind-affecting effects (charms, compulsions, phantasms, patterns, and morale effects), and any effect that requires a Fortitude save unless it also works on objects or is harmless. It is not subject to extra damage from critical hits, nonlethal damage, ability damage, ability drain, fatigue, exhaustion, or energy drain. It cannot heal damage, but can be repaired. An iron megaloceros has darkvision 60 ft. and low-light vision. It has no Constitution score, but it does have 10-sided Hit Dice and 30 bonus hit points, granting it 63 hit points total. It can be affected normally by rust attacks, such as that of a rust monster or a rusting grasp spell. It functions in all other ways like a standard megaloceros. The item can be used up to twice a week for up to 6 hours per use."}'::jsonb),
('dnd35.frostburn.magic-item.frostburn-malachite-smilodon','Malachite Smilodon','Malachite Smilodon','When animated, a malachite smilodon acts in all ways like a normal smilodon under the command of its possessor, except that its fangs are exceptionally sharp. They threaten a critical hit on a roll of 17–20, and do ×3 damage on a successful critical hit. The item may be used once per day for up to 2 hours. If slain in animal form, a malachite smilodon cannot be brought back from statuette form for one full week.','magic-item',0,36000,ARRAY[]::text[],'v35-frostburn','D&D 3.5 — Frostburn',109,'dnd35','{"id":"frostburn-malachite-smilodon","name":"Malachite Smilodon","family":"Frostfell Figurine of Wondrous Power","aura":"Moderate transmutation","casterLevel":11,"requirements":"Craft Wondrous Item, animate objects, keen edge","price":"36,000 gp","description":"When animated, a malachite smilodon acts in all ways like a normal smilodon under the command of its possessor, except that its fangs are exceptionally sharp. They threaten a critical hit on a roll of 17–20, and do ×3 damage on a successful critical hit. The item may be used once per day for up to 2 hours. If slain in animal form, a malachite smilodon cannot be brought back from statuette form for one full week."}'::jsonb),
('dnd35.frostburn.magic-item.frostburn-gloves-of-the-uldra-savant','Gloves of the Uldra Savant','Gloves of the Uldra Savant','Gloves of the uldra savant are made of a pale blue metal and are adorned with light blue runes. The plates that make up the gauntlets always seem to be caked with frost and ice. The wearer of gloves of the uldra savant can create a ray of frost at will as a standard action. Three times per day, the user may imbue any melee weapon held in her hand with the frost special ability as a standard action; this causes the weapon to do an additional 1d6 points of cold damage on a successful hit. The weapon retains this quality for 5 rounds.','magic-item',0,12700,ARRAY[]::text[],'v35-frostburn','D&D 3.5 — Frostburn',109,'dnd35','{"id":"frostburn-gloves-of-the-uldra-savant","name":"Gloves of the Uldra Savant","aura":"Faint evocation and transmutation","casterLevel":5,"requirements":"Craft Wondrous Item, frost weapon, ray of frost","price":"12,700 gp","weight":"2 lb","description":"Gloves of the uldra savant are made of a pale blue metal and are adorned with light blue runes. The plates that make up the gauntlets always seem to be caked with frost and ice. The wearer of gloves of the uldra savant can create a ray of frost at will as a standard action. Three times per day, the user may imbue any melee weapon held in her hand with the frost special ability as a standard action; this causes the weapon to do an additional 1d6 points of cold damage on a successful hit. The weapon retains this quality for 5 rounds."}'::jsonb),
('dnd35.frostburn.magic-item.frostburn-iceheart-minor','Iceheart, Minor','Iceheart, Minor','This fist-sized lump of magical ice has been infused with the storms and bitter cold of winter. On command, a minor iceheart can produce the following effects: • Ray of frost (at will) • Fog cloud (3/day) • Sleet storm (3/day)','magic-item',0,24000,ARRAY[]::text[],'v35-frostburn','D&D 3.5 — Frostburn',109,'dnd35','{"id":"frostburn-iceheart-minor","name":"Iceheart, Minor","aura":"Faint evocation","casterLevel":5,"requirements":"Craft Wondrous Item, fog cloud, ray of frost, sleet storm, creator must be an uldra or a winterhaunt of Iborighu","price":"24,000 gp","weight":"1 lb","description":"This fist-sized lump of magical ice has been infused with the storms and bitter cold of winter. On command, a minor iceheart can produce the following effects: • Ray of frost (at will) • Fog cloud (3/day) • Sleet storm (3/day)"}'::jsonb),
('dnd35.frostburn.magic-item.frostburn-iceheart-major','Iceheart, Major','Iceheart, Major','A major iceheart looks similar to a minor iceheart, except that it is constantly surrounded by a swirling vortex of snow and ice to a radius of 1 foot. Creatures holding a major iceheart take 1d4+1 points of cold damage per round as the powerful magic of the device leeches heat from the body. On command, a major iceheart can be used to produce the following effects: • Ray of frost (at will) • Cone of cold (3/day) • Fog cloud (3/day) • Ice storm (3/day) • Sleet storm (3/day) • Polar ray (1/day) • Fimbulwinter (1/day, see below) A major iceheart’s most awesome power is the ability to create a fimbulwinter once per day. A major iceheart casts this spell automatically each day at sunset, unless it has already been used that day to create a fimbulwinter. Thus, the mere presence of a major iceheart generates a 15-mile-radius zone of eternal winter; the majority of frostfell regions that appear in temperate or tropical climates are the result of the introduction of a major iceheart into the region.','magic-item',0,140000,ARRAY[]::text[],'v35-frostburn','D&D 3.5 — Frostburn',109,'dnd35','{"id":"frostburn-iceheart-major","name":"Iceheart, Major","aura":"Strong transmutation","casterLevel":15,"requirements":"Craft Wondrous Item, cone of cold, fimbulwinter, fog cloud, ice storm, polar ray, ray of frost, sleet storm, creator must be an uldra or a winterhaunt of Iborighu","price":"140,000 gp","weight":"1 lb","description":"A major iceheart looks similar to a minor iceheart, except that it is constantly surrounded by a swirling vortex of snow and ice to a radius of 1 foot. Creatures holding a major iceheart take 1d4+1 points of cold damage per round as the powerful magic of the device leeches heat from the body. On command, a major iceheart can be used to produce the following effects: • Ray of frost (at will) • Cone of cold (3/day) • Fog cloud (3/day) • Ice storm (3/day) • Sleet storm (3/day) • Polar ray (1/day) • Fimbulwinter (1/day, see below) A major iceheart’s most awesome power is the ability to create a fimbulwinter once per day. A major iceheart casts this spell automatically each day at sunset, unless it has already been used that day to create a fimbulwinter. Thus, the mere presence of a major iceheart generates a 15-mile-radius zone of eternal winter; the majority of frostfell regions that appear in temperate or tropical climates are the result of the introduction of a major iceheart into the region."}'::jsonb),
('dnd35.frostburn.magic-item.frostburn-icicle-rod','Icicle Rod','Icicle Rod','An icicle rod looks like nothing more than a 3-foot-long icicle. The rod remains cold to the touch at all times but never melts. While it is held, the wielder gains resistance to cold 10. It may be wielded in melee as a +1 frost short sword. Three times per day the wielder may fire a small icicle from the rod as a standard action. This icicle has a maximum range of 1,000 feet, and attacks made with it are resolved as ranged touch attacks that do 2d4 points of cold damage on a hit. Once it hits, the icicle quickly begins to spread frost and ice over the target, doing an additional 2d4 points of cold damage each round for a total of five additional rounds after the initial hit. An icicle rod can also produce these additional effects: • Entomb (1/day) • Maximized ice storm (1/day)','magic-item',0,120000,ARRAY[]::text[],'v35-frostburn','D&D 3.5 — Frostburn',109,'dnd35','{"id":"frostburn-icicle-rod","name":"Icicle Rod","aura":"Strong evocation (cold)","casterLevel":15,"requirements":"Craft Rod, Craft Magic Arms and Armor, Maximize Spell, entomb, ice storm, resist elements","price":"120,000 gp","description":"An icicle rod looks like nothing more than a 3-foot-long icicle. The rod remains cold to the touch at all times but never melts. While it is held, the wielder gains resistance to cold 10. It may be wielded in melee as a +1 frost short sword. Three times per day the wielder may fire a small icicle from the rod as a standard action. This icicle has a maximum range of 1,000 feet, and attacks made with it are resolved as ranged touch attacks that do 2d4 points of cold damage on a hit. Once it hits, the icicle quickly begins to spread frost and ice over the target, doing an additional 2d4 points of cold damage each round for a total of five additional rounds after the initial hit. An icicle rod can also produce these additional effects: • Entomb (1/day) • Maximized ice storm (1/day)"}'::jsonb),
('dnd35.frostburn.magic-item.frostburn-instant-igloo','Instant Igloo','Instant Igloo','An instant igloo looks like an unremarkable snowball, except that it does not melt in high temperatures. If hurled to the ground at any point within 20 feet, it transforms into a large igloo. The igloo is identical to that created by the spell Leomund’s tiny igloo, except that the igloo created has a 10-foot radius and can contain up to 2 Large, 8 Medium, 32 Small, or 128 Tiny or smaller creatures. The igloo lasts for 16 hours before transforming back into its snowball form, at which point it cannot be used again for another 8 hours.','magic-item',0,11000,ARRAY[]::text[],'v35-frostburn','D&D 3.5 — Frostburn',109,'dnd35','{"id":"frostburn-instant-igloo","name":"Instant Igloo","aura":"Faint evocation","casterLevel":7,"requirements":"Craft Wondrous Item, Widen Spell, Leomund’s tiny igloo","price":"11,000 gp","description":"An instant igloo looks like an unremarkable snowball, except that it does not melt in high temperatures. If hurled to the ground at any point within 20 feet, it transforms into a large igloo. The igloo is identical to that created by the spell Leomund’s tiny igloo, except that the igloo created has a 10-foot radius and can contain up to 2 Large, 8 Medium, 32 Small, or 128 Tiny or smaller creatures. The igloo lasts for 16 hours before transforming back into its snowball form, at which point it cannot be used again for another 8 hours."}'::jsonb),
('dnd35.frostburn.magic-item.frostburn-mantle-of-hidden-faith','Mantle of Hidden Faith','Mantle of Hidden Faith','This plain gray mantle shields your faith, alignment, and patron deity from magical detection as long as it is worn. It does not provide any bonuses to skill checks used to disguise or lie about your faith and beliefs.','magic-item',0,15000,ARRAY[]::text[],'v35-frostburn','D&D 3.5 — Frostburn',109,'dnd35','{"id":"frostburn-mantle-of-hidden-faith","name":"Mantle of Hidden Faith","aura":"Faint abjuration","casterLevel":3,"requirements":"Craft Wondrous Item, undetectable alignment","price":"15,000 gp","description":"This plain gray mantle shields your faith, alignment, and patron deity from magical detection as long as it is worn. It does not provide any bonuses to skill checks used to disguise or lie about your faith and beliefs."}'::jsonb),
('dnd35.frostburn.magic-item.frostburn-pick-of-iceparting','Pick of Iceparting','Pick of Iceparting','This +2 cold bane heavy pick can score critical hits against creatures of the cold subtype normally immune to critical hits. Once per day, a pick of iceparting can be swung at an icy surface (such as a glacial wall, the surface of a frozen lake, or an iceberg) as a standard action. Three tiny fractures radiate out from the point you struck toward any three points within 50 feet; these three points can be chosen by you but must be connected to the initial impact point by a solid sheet of ice. When the cracks reach their targets, they cause the ice located there to explode violently. Any creature within 5 feet of this explosion takes 3d6 points of piercing damage (Reflex DC 14 half).','magic-item',0,30000,ARRAY[]::text[],'v35-frostburn','D&D 3.5 — Frostburn',109,'dnd35','{"id":"frostburn-pick-of-iceparting","name":"Pick of Iceparting","aura":"Medium evocation","casterLevel":8,"requirements":"Craft Magic Arms and Armor, crack ice, summon monster I","price":"30,000 gp","cost":"14,600 gp + 1,168 XP","weight":"6 lb","description":"This +2 cold bane heavy pick can score critical hits against creatures of the cold subtype normally immune to critical hits. Once per day, a pick of iceparting can be swung at an icy surface (such as a glacial wall, the surface of a frozen lake, or an iceberg) as a standard action. Three tiny fractures radiate out from the point you struck toward any three points within 50 feet; these three points can be chosen by you but must be connected to the initial impact point by a solid sheet of ice. When the cracks reach their targets, they cause the ice located there to explode violently. Any creature within 5 feet of this explosion takes 3d6 points of piercing damage (Reflex DC 14 half)."}'::jsonb),
('dnd35.frostburn.magic-item.frostburn-ring-of-the-icy-soul','Ring of the Icy Soul','Ring of the Icy Soul','This ring seems to be made of ice, but never melts in even the hottest temperature. As long as this ring is worn, you gain the cold subtype. You gain immunity to cold, but have vulnerability to fire. You take half again as much (+50%) damage as normal from fire, regardless of whether a saving throw is allowed, or if the save is a success or a failure.','magic-item',0,100000,ARRAY[]::text[],'v35-frostburn','D&D 3.5 — Frostburn',109,'dnd35','{"id":"frostburn-ring-of-the-icy-soul","name":"Ring of the Icy Soul","aura":"Medium transmutation","casterLevel":9,"requirements":"Forge Ring, mantle of the icy soul","price":"100,000 gp","description":"This ring seems to be made of ice, but never melts in even the hottest temperature. As long as this ring is worn, you gain the cold subtype. You gain immunity to cold, but have vulnerability to fire. You take half again as much (+50%) damage as normal from fire, regardless of whether a saving throw is allowed, or if the save is a success or a failure."}'::jsonb),
('dnd35.frostburn.magic-item.frostburn-ring-of-floating','Ring of Floating','Ring of Floating','This clear crystal ring seems slightly cold when worn. As long as this ring is worn, you float upon any liquid or similar surface, and cannot swim below the surface. If you are underwater when you put this ring on, you rise toward the surface at a speed of 30 feet.','magic-item',0,2000,ARRAY[]::text[],'v35-frostburn','D&D 3.5 — Frostburn',109,'dnd35','{"id":"frostburn-ring-of-floating","name":"Ring of Floating","family":"Ring of the Icy Soul","aura":"Faint transmutation","casterLevel":1,"requirements":"Forge Ring, float","price":"2,000 gp","description":"This clear crystal ring seems slightly cold when worn. As long as this ring is worn, you float upon any liquid or similar surface, and cannot swim below the surface. If you are underwater when you put this ring on, you rise toward the surface at a speed of 30 feet."}'::jsonb),
('dnd35.frostburn.magic-item.frostburn-ring-of-the-white-wyrm','Ring of the White Wyrm','Ring of the White Wyrm','A ring of the white wyrm is fashioned from the tooth of a great wyrm white dragon. The ring can produce the following effects on command: • Icewalking (at will): As spider climb, but the surfaces the wearer climbs must be icy. • Freezing fog (2/day): As solid fog, but the effect also causes a rime of slippery ice to form on any surface the fog touches, creating the effect of a grease spell. The wearer of the ring is immune to the grease effect because of the icewalking power the ring imparts. • Wall of ice (1/day) In addition, the wearer gains the ability to speak and understand the Draconic language as long as the ring is worn, and the ring grants the wearer resistance to cold 10. The primary function of the ring, however, is to infuse the wearer with the energy and power of a dragon. Once per day, the wearer may call upon the ring to transform herself into a half-dragon. This is a full-round action that provokes attacks of opportunity, and the transformation lasts for 1 hour. While transformed, the wearer gains the following benefits: • +4 natural armor bonus to AC. • Bite and claw attacks as a half-dragon of the same size as the wearer. • Breath weapon usable once per transformation (30-ft. cone, 3d6 cold damage, Reflex DC 16 half). • Immunity to cold. • +8 Strength, +2 Constitution, +2 Intelligence, +2 Charisma. These bonuses are considered racial bonuses and stack with other racial bonuses the wearer may have. The ring’s transformation power also changes the wearer’s appearance into a draconic form. The wearer’s general shape and size does not change, although her equipment is altered in shape so it can still be utilized. Unlike polymorph, the user’s equipment does not merge with the new form; it remains in place and fully functional while the user is in half-dragon form. Dragons and half-dragons cannot benefit from the effects of the ring’s transformation powers, although they can utilize the ring’s other abilities. Rumors abound that other rings exist that are keyed to different dragons, granting different powers.','magic-item',0,64000,ARRAY[]::text[],'v35-frostburn','D&D 3.5 — Frostburn',109,'dnd35','{"id":"frostburn-ring-of-the-white-wyrm","name":"Ring of the White Wyrm","family":"Ring of the Icy Soul","aura":"Strong transmutation","casterLevel":13,"requirements":"Forge Ring, polymorph, protection from elements, wall of ice, solid fog, spider climb, creator must be a dragon or half-dragon","price":"64,000 gp","description":"A ring of the white wyrm is fashioned from the tooth of a great wyrm white dragon. The ring can produce the following effects on command: • Icewalking (at will): As spider climb, but the surfaces the wearer climbs must be icy. • Freezing fog (2/day): As solid fog, but the effect also causes a rime of slippery ice to form on any surface the fog touches, creating the effect of a grease spell. The wearer of the ring is immune to the grease effect because of the icewalking power the ring imparts. • Wall of ice (1/day) In addition, the wearer gains the ability to speak and understand the Draconic language as long as the ring is worn, and the ring grants the wearer resistance to cold 10. The primary function of the ring, however, is to infuse the wearer with the energy and power of a dragon. Once per day, the wearer may call upon the ring to transform herself into a half-dragon. This is a full-round action that provokes attacks of opportunity, and the transformation lasts for 1 hour. While transformed, the wearer gains the following benefits: • +4 natural armor bonus to AC. • Bite and claw attacks as a half-dragon of the same size as the wearer. • Breath weapon usable once per transformation (30-ft. cone, 3d6 cold damage, Reflex DC 16 half). • Immunity to cold. • +8 Strength, +2 Constitution, +2 Intelligence, +2 Charisma. These bonuses are considered racial bonuses and stack with other racial bonuses the wearer may have. The ring’s transformation power also changes the wearer’s appearance into a draconic form. The wearer’s general shape and size does not change, although her equipment is altered in shape so it can still be utilized. Unlike polymorph, the user’s equipment does not merge with the new form; it remains in place and fully functional while the user is in half-dragon form. Dragons and half-dragons cannot benefit from the effects of the ring’s transformation powers, although they can utilize the ring’s other abilities. Rumors abound that other rings exist that are keyed to different dragons, granting different powers."}'::jsonb),
('dnd35.frostburn.magic-item.frostburn-rod-of-piercing-cold','Rod of Piercing Cold','Rod of Piercing Cold','This short rod appears to be made entirely out of ice, and comes to a needle-sharp point at one end. It can be used as a +2 frost dagger in combat. Up to three times per day, the owner of a rod of piercing cold can enhance one spell cast with the Piercing Cold metamagic feat, with no alteration to the spell’s effective level. This rod is a metamagic rod; a caster may only use one metamagic rod on a spell at a time. Normal rods of piercing cold can be used with spells of 6th level or lower. Lesser rods of piercing cold can be used with spells of 3rd level or lower, while greater rods of piercing cold can be used with spells of 9th level or lower.','magic-item',0,null,ARRAY[]::text[],'v35-frostburn','D&D 3.5 — Frostburn',109,'dnd35','{"id":"frostburn-rod-of-piercing-cold","name":"Rod of Piercing Cold","aura":"Strong (no school)","casterLevel":17,"requirements":"Craft Rod, Piercing Cold","price":"21,430 gp (lesser), 29,300 gp (normal), 42,800 gp (greater)","cost":"10,500 gp + 840 XP (lesser), 14,500 gp + 1,160 XP (normal), 21,400 gp + 1,700 XP (greater)","description":"This short rod appears to be made entirely out of ice, and comes to a needle-sharp point at one end. It can be used as a +2 frost dagger in combat. Up to three times per day, the owner of a rod of piercing cold can enhance one spell cast with the Piercing Cold metamagic feat, with no alteration to the spell’s effective level. This rod is a metamagic rod; a caster may only use one metamagic rod on a spell at a time. Normal rods of piercing cold can be used with spells of 6th level or lower. Lesser rods of piercing cold can be used with spells of 3rd level or lower, while greater rods of piercing cold can be used with spells of 9th level or lower."}'::jsonb),
('dnd35.frostburn.magic-item.frostburn-simulacrum-elixir','Simulacrum Elixir','Simulacrum Elixir','This small vial of clear fluid contains a potent magical charge. When the contents are poured over a body part (which can be as small as a fingernail clipping or a single hair), the liquid quickly grows in volume and transforms into a simulacrum of the creature from which the body part came. The simulacrum functions as the spell of the same name, and remains under the absolute command of the person who created it. The simulacrum to be created cannot be a duplicate of a creature with more than 26 HD or levels, and its likeness to the original creature is crude at best. A vial of simulacrum elixir contains enough fluid to create one simulacrum.','magic-item',0,21000,ARRAY[]::text[],'v35-frostburn','D&D 3.5 — Frostburn',109,'dnd35','{"id":"frostburn-simulacrum-elixir","name":"Simulacrum Elixir","aura":"Strong illusion (shadow)","casterLevel":13,"requirements":"Craft Wondrous Item, simulacrum","price":"21,000 gp","description":"This small vial of clear fluid contains a potent magical charge. When the contents are poured over a body part (which can be as small as a fingernail clipping or a single hair), the liquid quickly grows in volume and transforms into a simulacrum of the creature from which the body part came. The simulacrum functions as the spell of the same name, and remains under the absolute command of the person who created it. The simulacrum to be created cannot be a duplicate of a creature with more than 26 HD or levels, and its likeness to the original creature is crude at best. A vial of simulacrum elixir contains enough fluid to create one simulacrum."}'::jsonb),
('dnd35.frostburn.magic-item.frostburn-skull-talisman','Skull Talisman','Skull Talisman','The craft of creating skull talismans was originally pioneered by the primitive races that live in the frostfell. Potions tend to freeze in the cruel temperatures of the frostfell, so the skull talisman was invented to provide a replacement. A skull talisman can be used only once. The size of the creature’s skull used in creation of the talisman determines the maximum level of spell that can be stored in it. A Small skull can store a spell of up to 3rd level. A Medium Skull can store a spell of up to 6th level. A Large skull can store a spell of up to 9th level. Only spells that target one or more creatures can be stored in a skull talisman. Physical Description: A skull talisman appears as the runecovered skull of a creature of at least Small size; usually talismans are made of animal skulls, but particularly savage tribes and cruel individuals enjoy making them from their slain enemies. A Small skull talisman has AC 7, 5 hit points, hardness 2, and a break DC of 20. A Medium skull talisman has AC 5, 10 hit points, hardness 5, and a break DC of 25. A Large skull talisman has AC 4, 25 hit points, hardness 10, and a break DC of 30. A skull talisman carried by a creature has the same effective AC as the creature carrying it. A creature that controls possession of a skull talisman can automatically break it with one hand by taking a standard action to do so; the AC and break DCs listed above are for those who try to strike or break an unattended skull talisman or a skull talisman held by another creature. Identifying Skull Talismans: A skull talisman is covered with mystical runes and magic symbols; the exact spell stored in a skull talisman can be determined with a successful Spellcraft check (DC 20 + spell level); a read magic spell identifies the stored spell automatically. Activation: A skull talisman produces its effect when it is purposefully destroyed by crushing it, either by smashing it with a weapon or crushing it in one hand. The stored spell affects the person who destroyed it. If you have a skull talisman in your uncontested possession, you can automatically destroy it by crushing it with your hand, foot, or body. This is a standard action that provokes attacks of opportunity. If you do not have a skull talisman in your possession, you can destroy it by dealing enough damage to it. In order to gain the effects of a spell stored in a skull talisman, the skull must be within 5 feet of you when it is broken; otherwise, the stored spell dissipates harmlessly. Skull talismans are like spells cast upon the one who destroys the talisman. The character destroying the skull talisman doesn’t get to make any decisions about the effect—the creator of the talisman has already done so. The destroyer is both the effective target and the caster of the effect (though the skull talisman indicates the caster level, the destroyer still controls the effect). Skull Talisman Descriptions: Because skull talismans are simply spells stored in a magically prepared skull, refer to the appropriate spell description for all pertinent details. The caster level for a standard skull talisman is the minimum caster level needed to cast the spell.','magic-item',0,null,ARRAY[]::text[],'v35-frostburn','D&D 3.5 — Frostburn',109,'dnd35','{"id":"frostburn-skull-talisman","name":"Skull Talisman","description":"The craft of creating skull talismans was originally pioneered by the primitive races that live in the frostfell. Potions tend to freeze in the cruel temperatures of the frostfell, so the skull talisman was invented to provide a replacement. A skull talisman can be used only once. The size of the creature’s skull used in creation of the talisman determines the maximum level of spell that can be stored in it. A Small skull can store a spell of up to 3rd level. A Medium Skull can store a spell of up to 6th level. A Large skull can store a spell of up to 9th level. Only spells that target one or more creatures can be stored in a skull talisman. Physical Description: A skull talisman appears as the runecovered skull of a creature of at least Small size; usually talismans are made of animal skulls, but particularly savage tribes and cruel individuals enjoy making them from their slain enemies. A Small skull talisman has AC 7, 5 hit points, hardness 2, and a break DC of 20. A Medium skull talisman has AC 5, 10 hit points, hardness 5, and a break DC of 25. A Large skull talisman has AC 4, 25 hit points, hardness 10, and a break DC of 30. A skull talisman carried by a creature has the same effective AC as the creature carrying it. A creature that controls possession of a skull talisman can automatically break it with one hand by taking a standard action to do so; the AC and break DCs listed above are for those who try to strike or break an unattended skull talisman or a skull talisman held by another creature. Identifying Skull Talismans: A skull talisman is covered with mystical runes and magic symbols; the exact spell stored in a skull talisman can be determined with a successful Spellcraft check (DC 20 + spell level); a read magic spell identifies the stored spell automatically. Activation: A skull talisman produces its effect when it is purposefully destroyed by crushing it, either by smashing it with a weapon or crushing it in one hand. The stored spell affects the person who destroyed it. If you have a skull talisman in your uncontested possession, you can automatically destroy it by crushing it with your hand, foot, or body. This is a standard action that provokes attacks of opportunity. If you do not have a skull talisman in your possession, you can destroy it by dealing enough damage to it. In order to gain the effects of a spell stored in a skull talisman, the skull must be within 5 feet of you when it is broken; otherwise, the stored spell dissipates harmlessly. Skull talismans are like spells cast upon the one who destroys the talisman. The character destroying the skull talisman doesn’t get to make any decisions about the effect—the creator of the talisman has already done so. The destroyer is both the effective target and the caster of the effect (though the skull talisman indicates the caster level, the destroyer still controls the effect). Skull Talisman Descriptions: Because skull talismans are simply spells stored in a magically prepared skull, refer to the appropriate spell description for all pertinent details. The caster level for a standard skull talisman is the minimum caster level needed to cast the spell."}'::jsonb),
('dnd35.frostburn.magic-item.frostburn-staff-of-the-iceberg','Staff of the Iceberg','Staff of the Iceberg','This staff looks like a jagged lance of solid ice topped with a tangled mass of ice crystals. It allows the use of the following spells: • Snow walk (1 charge) • Entomb (2 charges) • Ice ship (2 charges) • Ice castle (3 charges) • Iceberg (5 charges) The staff may be used as a weapon, functioning as a +2 icy burst quarterstaff (only one end of the staff bears this magic). It also allows its wielder to move across icy surfaces without fear of slipping or falling. These two abilities continue to function after all the charges are expended.','magic-item',0,138000,ARRAY[]::text[],'v35-frostburn','D&D 3.5 — Frostburn',109,'dnd35','{"id":"frostburn-staff-of-the-iceberg","name":"Staff of the Iceberg","aura":"Strong evocation (cold)","casterLevel":17,"requirements":"Craft Staff, Craft Magic Arms and Armor; entomb, ice castle, ice ship, iceberg, snow walk","price":"138,000 gp","description":"This staff looks like a jagged lance of solid ice topped with a tangled mass of ice crystals. It allows the use of the following spells: • Snow walk (1 charge) • Entomb (2 charges) • Ice ship (2 charges) • Ice castle (3 charges) • Iceberg (5 charges) The staff may be used as a weapon, functioning as a +2 icy burst quarterstaff (only one end of the staff bears this magic). It also allows its wielder to move across icy surfaces without fear of slipping or falling. These two abilities continue to function after all the charges are expended."}'::jsonb),
('dnd35.frostburn.magic-item.frostburn-staff-of-winter','Staff of Winter','Staff of Winter','This staff is made of bleached white wood; the end is a large crystalline snowflake. It allows the use of the following spells: • Boreal wind (1 charge) • Obscuring snow (1 charge) • Winter’s embrace (1 charge) • Whiteout (2 charges)','magic-item',0,58000,ARRAY[]::text[],'v35-frostburn','D&D 3.5 — Frostburn',109,'dnd35','{"id":"frostburn-staff-of-winter","name":"Staff of Winter","aura":"Strong conjuration","casterLevel":13,"requirements":"Craft Staff, boreal wind, obscuring snow, whiteout, winter’s embrace","price":"58,000 gp","description":"This staff is made of bleached white wood; the end is a large crystalline snowflake. It allows the use of the following spells: • Boreal wind (1 charge) • Obscuring snow (1 charge) • Winter’s embrace (1 charge) • Whiteout (2 charges)"}'::jsonb),
('dnd35.frostburn.magic-item.frostburn-vial-of-icy-sheets','Vial of Icy Sheets','Vial of Icy Sheets','The vial of icy sheets contains a clear fluid that creates a region of slippery ice when its contents are poured upon the ground (a standard action). The fluid spreads from the point of origin to a radius of 10 feet, coating the ground with a thin sheet of slippery ice. All creatures caught in this area must make a DC 11 Reflex save or slip and fall. Those that successfully save can move at half speed across the surface. Those that remain in the area must make a new saving throw each round to avoid falling and to be able to move. Alternatively, the vial’s contents can be poured upon an object. This encases the object with slippery ice, and if the object is carried or wielded, its wielder must make a DC 11 Reflex save to avoid dropping the item. A new saving throw must be made each round the item is grasped. Icy sheets last for 5 rounds before they evaporate away into nothingness. A vial of icy sheets automatically replenishes its supply of liquid once every day. If the contents of a vial of icy sheets are swallowed, the ice coats the mouth, throat, and stomach of the poor fool who drank it. This causes 6d6 points of cold damage (Fortitude DC 20 half).','magic-item',0,2000,ARRAY[]::text[],'v35-frostburn','D&D 3.5 — Frostburn',109,'dnd35','{"id":"frostburn-vial-of-icy-sheets","name":"Vial of Icy Sheets","aura":"Faint conjuration","casterLevel":1,"requirements":"Craft Wondrous Item, ice slick","price":"2,000 gp","weight":"1 lb","description":"The vial of icy sheets contains a clear fluid that creates a region of slippery ice when its contents are poured upon the ground (a standard action). The fluid spreads from the point of origin to a radius of 10 feet, coating the ground with a thin sheet of slippery ice. All creatures caught in this area must make a DC 11 Reflex save or slip and fall. Those that successfully save can move at half speed across the surface. Those that remain in the area must make a new saving throw each round to avoid falling and to be able to move. Alternatively, the vial’s contents can be poured upon an object. This encases the object with slippery ice, and if the object is carried or wielded, its wielder must make a DC 11 Reflex save to avoid dropping the item. A new saving throw must be made each round the item is grasped. Icy sheets last for 5 rounds before they evaporate away into nothingness. A vial of icy sheets automatically replenishes its supply of liquid once every day. If the contents of a vial of icy sheets are swallowed, the ice coats the mouth, throat, and stomach of the poor fool who drank it. This causes 6d6 points of cold damage (Fortitude DC 20 half)."}'::jsonb),
('dnd35.frostburn.material.frostburn-blue-ice','Blue Ice','Blue Ice','Found only in the depths of the most ancient glaciers, veins of blue ice are often sought out by glacier dwarves. It appears as dark blue, opaque ice that sparkles in light as if it were coated with a tiny film of gemstones; this is merely a thin layer of frost that forms over its surface when exposed to air. The material is cold and feels identical to regular ice upon casual observation, but blue ice only melts under intense and direct application of heat, similar to iron. Those who mine this material from the ancient glaciers often do so simply by melting away the surrounding ice; this is a dangerous procedure, though, since it can rapidly destabilize the surrounding ice. As a result, only the most gifted miners attempt to mine blue ice. Blue ice can be forged, shaped, and utilized as if it were iron. Blue ice is much lighter than iron, and when forged into a slashing weapon it keeps its edge much longer and is much sharper than an equally forged iron weapon. Slashing weapons made of blue ice have a +1 enhancement bonus on damage. Bludgeoning or piercing weapons can be made of blue ice, but they gain no bonuses to damage. All weapons made of blue ice weigh half as much as normal. Blue ice isn’t just useful to make slashing weapons, though; it can be used to build anything that is normally built of iron. Many dwarven fortresses in the frostfell make heavy use of blue ice for metal components such as nails, tools, door hinges, utensils, and pretty much anything else they can think of; blue ice goblets and mugs are especially popular for export to warmer climates since they keep their contents chilled. A room lined with sheets of blue ice remains at a constant temperature of about freezing, making for an effective way to create refrigerated chambers for food storage. Items made out of blue ice weigh half as much as normal. Blue ice armor is much lighter than normal armor, although it can be uncomfortable to wear for creatures not immune or resistant to cold. Only armor normally fashioned of metal can be made from blue ice. Most blue ice armors are one category lighter than normal for purposes of movement and other limitations, so that medium armor counts as light armor, and heavy armor counts as medium armor. Light armor remains light armor. Spell failure chances for arcane spells remains unchanged, with the exception of spells with the cold descriptor, which can be cast while wearing blue ice armor with no chance of spell failure. Maximum Dexterity bonus is increased by 1, and armor check penalties are lessened by 2. If the creature wearing the armor is not resistant or immune to cold, he takes a –1 penalty on Reflex saving throws and initiative checks from the general numbness caused by the armor. The Cold Endurance feat is enough to prevent this effect. Blue ice has 20 hit points per inch of thickness and hardness 10.','material',0,null,ARRAY[]::text[],'v35-frostburn','D&D 3.5 — Frostburn',80,'dnd35','{"id":"frostburn-blue-ice","name":"Blue Ice","description":"Found only in the depths of the most ancient glaciers, veins of blue ice are often sought out by glacier dwarves. It appears as dark blue, opaque ice that sparkles in light as if it were coated with a tiny film of gemstones; this is merely a thin layer of frost that forms over its surface when exposed to air. The material is cold and feels identical to regular ice upon casual observation, but blue ice only melts under intense and direct application of heat, similar to iron. Those who mine this material from the ancient glaciers often do so simply by melting away the surrounding ice; this is a dangerous procedure, though, since it can rapidly destabilize the surrounding ice. As a result, only the most gifted miners attempt to mine blue ice. Blue ice can be forged, shaped, and utilized as if it were iron. Blue ice is much lighter than iron, and when forged into a slashing weapon it keeps its edge much longer and is much sharper than an equally forged iron weapon. Slashing weapons made of blue ice have a +1 enhancement bonus on damage. Bludgeoning or piercing weapons can be made of blue ice, but they gain no bonuses to damage. All weapons made of blue ice weigh half as much as normal. Blue ice isn’t just useful to make slashing weapons, though; it can be used to build anything that is normally built of iron. Many dwarven fortresses in the frostfell make heavy use of blue ice for metal components such as nails, tools, door hinges, utensils, and pretty much anything else they can think of; blue ice goblets and mugs are especially popular for export to warmer climates since they keep their contents chilled. A room lined with sheets of blue ice remains at a constant temperature of about freezing, making for an effective way to create refrigerated chambers for food storage. Items made out of blue ice weigh half as much as normal. Blue ice armor is much lighter than normal armor, although it can be uncomfortable to wear for creatures not immune or resistant to cold. Only armor normally fashioned of metal can be made from blue ice. Most blue ice armors are one category lighter than normal for purposes of movement and other limitations, so that medium armor counts as light armor, and heavy armor counts as medium armor. Light armor remains light armor. Spell failure chances for arcane spells remains unchanged, with the exception of spells with the cold descriptor, which can be cast while wearing blue ice armor with no chance of spell failure. Maximum Dexterity bonus is increased by 1, and armor check penalties are lessened by 2. If the creature wearing the armor is not resistant or immune to cold, he takes a –1 penalty on Reflex saving throws and initiative checks from the general numbness caused by the armor. The Cold Endurance feat is enough to prevent this effect. Blue ice has 20 hit points per inch of thickness and hardness 10.","costModifiers":[{"item":"Light armor","modifier":"+750 gp"},{"item":"Medium armor","modifier":"+3,000 gp"},{"item":"Heavy armor","modifier":"+7,000 gp"},{"item":"Shield","modifier":"+750 gp"},{"item":"Slashing weapon","modifier":"+500 gp"},{"item":"Other items","modifier":"+400 gp/lb."}]}'::jsonb),
('dnd35.frostburn.material.frostburn-rimefire-ice','Rimefire Ice','Rimefire Ice','This form of ice is found only in icebergs inhabited by rimefire eidolons. These icebergs are approximately 95% normal ice, but the remaining 5% consists of veins of pale blue ice that glows softly, providing illumination equal to that of a torch. Rimefire ice is especially cold to the touch, and any creature that comes in contact with it takes 1 point of cold damage per round of contact. Any amount of resistance or immunity to cold or the Mark of Hleid feat provides complete protection from this cold damage. The most unusual aspect of rimefire ice is that it is approximately as flammable as wood; it does not melt when heat is applied to it. Burning rimefire ice does not deal fire damage, though, even if it is ignited by an open flame. Rather, burning rimefire ice deals cold damage on anything unfortunate enough to get too close. Rimefire ice could make an interesting material to forge weapons out of; rimefire ice has about the same amount of resilience and strength as wood. It cannot be used to make any appreciable armor, but it can be used to create any weapon that is normally made out of wood (or nearly completely of wood, as in the case of a spear or javelin). Rimefire ice weapons glow with blue light, providing illumination to a 20-foot radius. They also deal +1 point of cold damage on each successful hit. Since rimefire is workable as wood, it can be used to build any object that can normally be made of wood. Rimefire ice objects glow blue, provide illumination as a torch, and retain their ability to cause 1 point of cold damage per round of contact to anything touching it. Rimefire ice brought into warmer climates does not melt into water; it melts into thick white clouds of water vapor with great rapidity. Each minute a piece of rimefire ice is exposed to temperatures above 40° F, it takes 1d6 points of damage (this damage overcomes the ice’s hardness and is not halved, as is most energy damage applied to objects). For each additional 10 degrees hotter than this, the ice takes an additional 1d6 points of damage per round. Rimefire ice has 5 hit points per inch of thickness and hardness 3.','material',0,null,ARRAY[]::text[],'v35-frostburn','D&D 3.5 — Frostburn',80,'dnd35','{"id":"frostburn-rimefire-ice","name":"Rimefire Ice","description":"This form of ice is found only in icebergs inhabited by rimefire eidolons. These icebergs are approximately 95% normal ice, but the remaining 5% consists of veins of pale blue ice that glows softly, providing illumination equal to that of a torch. Rimefire ice is especially cold to the touch, and any creature that comes in contact with it takes 1 point of cold damage per round of contact. Any amount of resistance or immunity to cold or the Mark of Hleid feat provides complete protection from this cold damage. The most unusual aspect of rimefire ice is that it is approximately as flammable as wood; it does not melt when heat is applied to it. Burning rimefire ice does not deal fire damage, though, even if it is ignited by an open flame. Rather, burning rimefire ice deals cold damage on anything unfortunate enough to get too close. Rimefire ice could make an interesting material to forge weapons out of; rimefire ice has about the same amount of resilience and strength as wood. It cannot be used to make any appreciable armor, but it can be used to create any weapon that is normally made out of wood (or nearly completely of wood, as in the case of a spear or javelin). Rimefire ice weapons glow with blue light, providing illumination to a 20-foot radius. They also deal +1 point of cold damage on each successful hit. Since rimefire is workable as wood, it can be used to build any object that can normally be made of wood. Rimefire ice objects glow blue, provide illumination as a torch, and retain their ability to cause 1 point of cold damage per round of contact to anything touching it. Rimefire ice brought into warmer climates does not melt into water; it melts into thick white clouds of water vapor with great rapidity. Each minute a piece of rimefire ice is exposed to temperatures above 40° F, it takes 1d6 points of damage (this damage overcomes the ice’s hardness and is not halved, as is most energy damage applied to objects). For each additional 10 degrees hotter than this, the ice takes an additional 1d6 points of damage per round. Rimefire ice has 5 hit points per inch of thickness and hardness 3.","costModifiers":[{"item":"Weapon","modifier":"+750 gp"},{"item":"Other objects","modifier":"+500 gp/lb."}]}'::jsonb),
('dnd35.frostburn.material.frostburn-stygian-ice','Stygian Ice','Stygian Ice','This extraplanar ice comes from Stygia, the fifth layer of Hell. Infused with the soulless evil of that realm, along with the magical waters of the river Styx, stygian ice is black and constantly crawls with a thin layer of pale blue mist. Stygian ice is much colder than normal ice, and it melts slowly in nonfreezing environs. The coldness that this ice exudes is magical in nature, and freezes the mind much more rapidly than flesh. Stygian ice deals 1d6 points of cold damage per round of contact. Worse, if a creature takes damage from this supernatural cold, it must make a DC 12 Will saving throw or take 2 points of Wisdom damage as its memories are slowly frozen. If a creature’s Wisdom is reduced to 0, further contact causes Constitution damage. A creature whose Constitution is reduced to 0 by Stygian ice rises as a wraith in 2d4 rounds. Stygian ice is not much harder than normal ice, so it doesn’t make effective armor. Weapons made of Stygian ice are somewhat fragile, and each time they deal damage the wielder must make a DC 15 Reflex save to avoid dealing the same amount of damage on the weapon itself. Stygian ice weapons deal 1d6 points of additional cold damage on a hit; if the creature hit takes cold damage, it must make a DC 12 Will saving throw or take 2 points of Wisdom damage (or Constitution damage, if Wisdom is at 0). This damage applies to the wielder of the weapon as well; a character who wishes to wield a weapon made of Stygian ice is advised to seek out protection from cold damage. Stygian ice has 5 hit points per inch of thickness and hardness 3. Magical fire damage is not halved when applied to stygian ice. An object made of Stygian ice takes 1 point of damage per hour it exists in an environment above 40° F; this damage overcomes the ice’s hardness. As it melts, the ice gives off foul vapors that nauseate anyone within 5 feet who fails a DC 12 Fortitude saving throw.','material',0,null,ARRAY[]::text[],'v35-frostburn','D&D 3.5 — Frostburn',80,'dnd35','{"id":"frostburn-stygian-ice","name":"Stygian Ice","description":"This extraplanar ice comes from Stygia, the fifth layer of Hell. Infused with the soulless evil of that realm, along with the magical waters of the river Styx, stygian ice is black and constantly crawls with a thin layer of pale blue mist. Stygian ice is much colder than normal ice, and it melts slowly in nonfreezing environs. The coldness that this ice exudes is magical in nature, and freezes the mind much more rapidly than flesh. Stygian ice deals 1d6 points of cold damage per round of contact. Worse, if a creature takes damage from this supernatural cold, it must make a DC 12 Will saving throw or take 2 points of Wisdom damage as its memories are slowly frozen. If a creature’s Wisdom is reduced to 0, further contact causes Constitution damage. A creature whose Constitution is reduced to 0 by Stygian ice rises as a wraith in 2d4 rounds. Stygian ice is not much harder than normal ice, so it doesn’t make effective armor. Weapons made of Stygian ice are somewhat fragile, and each time they deal damage the wielder must make a DC 15 Reflex save to avoid dealing the same amount of damage on the weapon itself. Stygian ice weapons deal 1d6 points of additional cold damage on a hit; if the creature hit takes cold damage, it must make a DC 12 Will saving throw or take 2 points of Wisdom damage (or Constitution damage, if Wisdom is at 0). This damage applies to the wielder of the weapon as well; a character who wishes to wield a weapon made of Stygian ice is advised to seek out protection from cold damage. Stygian ice has 5 hit points per inch of thickness and hardness 3. Magical fire damage is not halved when applied to stygian ice. An object made of Stygian ice takes 1 point of damage per hour it exists in an environment above 40° F; this damage overcomes the ice’s hardness. As it melts, the ice gives off foul vapors that nauseate anyone within 5 feet who fails a DC 12 Fortitude saving throw.","costModifiers":[{"item":"Weapon","modifier":"+6,000 gp"},{"item":"Other objects","modifier":"+2,000 gp/lb."}]}'::jsonb),
('dnd35.frostburn.vehicle-augmentation.frostburn-coldfire-keel','Coldfire Keel','Coldfire Keel','This item, often forged on the Elemental Planes, enables any vehicle to move across coldfire as if it were on its normal terrain (water, land, or air). The vessel’s speed is unaffected, but rough terrain or conditions slow the vehicle just as it would a land vehicle.','vehicle-augmentation',0,200000,ARRAY[]::text[],'v35-frostburn','D&D 3.5 — Frostburn',81,'dnd35','{"id":"frostburn-coldfire-keel","name":"Coldfire Keel","aura":"Strong universal","casterLevel":17,"requirements":"Craft Wondrous Item, wish","price":"200,000 gp","weight":"1,000 lb","description":"This item, often forged on the Elemental Planes, enables any vehicle to move across coldfire as if it were on its normal terrain (water, land, or air). The vessel’s speed is unaffected, but rough terrain or conditions slow the vehicle just as it would a land vehicle."}'::jsonb),
('dnd35.frostburn.vehicle-augmentation.frostburn-coldfire-engine','Coldfire Engine','Coldfire Engine','This item, typically constructed on the Elemental Planes, propels any vehicle at a speed of 80 feet.','vehicle-augmentation',0,200000,ARRAY[]::text[],'v35-frostburn','D&D 3.5 — Frostburn',81,'dnd35','{"id":"frostburn-coldfire-engine","name":"Coldfire Engine","aura":"Strong universal","casterLevel":17,"requirements":"Craft Wondrous Item, animate objects, wish","price":"200,000 gp","weight":"1,000 lb","description":"This item, typically constructed on the Elemental Planes, propels any vehicle at a speed of 80 feet."}'::jsonb),
('dnd35.frostburn.vehicle-augmentation.frostburn-ice-keel','Ice Keel','Ice Keel','This item, often forged on the Elemental Planes, enables a water or land vehicle to move across ice as if it were on water or land, respectively. The vessel’s speed is unaffected, but rough terrain slows the vehicle just as it would an ice vehicle.','vehicle-augmentation',0,150000,ARRAY[]::text[],'v35-frostburn','D&D 3.5 — Frostburn',81,'dnd35','{"id":"frostburn-ice-keel","name":"Ice Keel","aura":"Strong transmutation","casterLevel":17,"requirements":"Craft Wondrous Item, thaw, wish","price":"150,000 gp","weight":"1,000 lb","description":"This item, often forged on the Elemental Planes, enables a water or land vehicle to move across ice as if it were on water or land, respectively. The vessel’s speed is unaffected, but rough terrain slows the vehicle just as it would an ice vehicle."}'::jsonb),
('dnd35.frostburn.vehicle-augmentation.frostburn-runners-of-speed','Runners of Speed','Runners of Speed','These runners increase the speed of vehicles that travel through snow or ice by 20 feet.','vehicle-augmentation',0,100000,ARRAY[]::text[],'v35-frostburn','D&D 3.5 — Frostburn',81,'dnd35','{"id":"frostburn-runners-of-speed","name":"Runners of Speed","aura":"Strong transmutation","casterLevel":17,"requirements":"Craft Wondrous Item, haste, wish","price":"100,000 gp","weight":"1,000 lb","description":"These runners increase the speed of vehicles that travel through snow or ice by 20 feet."}'::jsonb),
('dnd35.frostburn.vehicle.frostburn-sled','Sled','Sled','Large vehicle; Handle Animal +2; Spd drawn (clumsy); Overall hp 40 (hardness 5); Overall AC 4; Ram 3d6; Face 15 ft. by 5 ft.; Height 5 ft.; Crew 1; Weight 300 lb., Cargo 1 ton; Cost 20 gp. Drawn across ice or snow, the sled is an almost entirely exposed structure. Eight riding dogs can pull the sled over ice or packed snow at a speed of 40 feet, even if it’s fully loaded. Untracked snow slows the speed by one-half, and deep snow cuts it to one-quarter.','vehicle',0,20,ARRAY[]::text[],'v35-frostburn','D&D 3.5 — Frostburn',81,'dnd35','{"id":"frostburn-sled","name":"Sled","statLine":"Large vehicle; Handle Animal +2; Spd drawn (clumsy); Overall hp 40 (hardness 5); Overall AC 4; Ram 3d6; Face 15 ft. by 5 ft.; Height 5 ft.; Crew 1; Weight 300 lb., Cargo 1 ton; Cost 20 gp.","description":"Drawn across ice or snow, the sled is an almost entirely exposed structure. Eight riding dogs can pull the sled over ice or packed snow at a speed of 40 feet, even if it’s fully loaded. Untracked snow slows the speed by one-half, and deep snow cuts it to one-quarter."}'::jsonb),
('dnd35.frostburn.vehicle.frostburn-worg-warsled','Worg Warsled','Worg Warsled','Huge vehicle; Handle Animal +2; Spd drawn (poor); Overall hp 100 (hardness 7); Overall AC 3; Ram 6d6; Face 15 ft. by 10 ft.; Height 5 ft.; Crew 1 (plus 3 passengers); Weight 900 lb.; Cargo 700 lb.; Cost 400 gp. Goblins in snowy climes use their worg allies to pull massive sleds covered with makeshift armor and spikes. The driver and passengers aboard such a warsled gain cover behind a 2-inch barrier of steel and wood (hp 20, hardness 7). Two worgs abreast pull the sled at a speed of 35 feet.','vehicle',0,400,ARRAY[]::text[],'v35-frostburn','D&D 3.5 — Frostburn',81,'dnd35','{"id":"frostburn-worg-warsled","name":"Worg Warsled","statLine":"Huge vehicle; Handle Animal +2; Spd drawn (poor); Overall hp 100 (hardness 7); Overall AC 3; Ram 6d6; Face 15 ft. by 10 ft.; Height 5 ft.; Crew 1 (plus 3 passengers); Weight 900 lb.; Cargo 700 lb.; Cost 400 gp.","description":"Goblins in snowy climes use their worg allies to pull massive sleds covered with makeshift armor and spikes. The driver and passengers aboard such a warsled gain cover behind a 2-inch barrier of steel and wood (hp 20, hardness 7). Two worgs abreast pull the sled at a speed of 35 feet."}'::jsonb),
('dnd35.frostburn.vehicle.frostburn-ice-sled-wagon','Ice Sled-Wagon','Ice Sled-Wagon','Huge vehicle; Handle Animal –2; Spd drawn (poor); Overall hp 60 (hardness 5); Overall AC 3; Ram 4d6; Face 15 ft. by 10 ft.; Height 5 ft.; Crew 1; Weight 400 lb., Cargo 2 tons; Cost 35 gp. A wagon is open-topped, so the driver and any passengers gain no cover. The most common dray creatures for the wagon are two heavy horses, which are strong enough to pull a fully loaded wagon at a speed of 35 feet. However, in frostfell regions, wagons may also be drawn by a single woolly mammoth or four saber-toothed tigers at a speed of 40 feet. An ice sled-wagon can also be equipped with a heavy catapult (adding 2 tons to the wagon’s weight and eliminating the cargo capacity) or a light catapult (adding 1 ton to weight, leaving 1 ton of cargo space for ammunition).','vehicle',0,35,ARRAY[]::text[],'v35-frostburn','D&D 3.5 — Frostburn',81,'dnd35','{"id":"frostburn-ice-sled-wagon","name":"Ice Sled-Wagon","statLine":"Huge vehicle; Handle Animal –2; Spd drawn (poor); Overall hp 60 (hardness 5); Overall AC 3; Ram 4d6; Face 15 ft. by 10 ft.; Height 5 ft.; Crew 1; Weight 400 lb., Cargo 2 tons; Cost 35 gp.","description":"A wagon is open-topped, so the driver and any passengers gain no cover. The most common dray creatures for the wagon are two heavy horses, which are strong enough to pull a fully loaded wagon at a speed of 35 feet. However, in frostfell regions, wagons may also be drawn by a single woolly mammoth or four saber-toothed tigers at a speed of 40 feet. An ice sled-wagon can also be equipped with a heavy catapult (adding 2 tons to the wagon’s weight and eliminating the cargo capacity) or a light catapult (adding 1 ton to weight, leaving 1 ton of cargo space for ammunition)."}'::jsonb),
('dnd35.frostburn.vehicle.frostburn-sailing-ice-ship','Sailing Ice Ship','Sailing Ice Ship','Colossal vehicle; Profession (sailor) +4; Spd ice wind × 30 ft. (average), snow wind × 20 ft. (poor); Overall AC –3; Section hp 50 (hardness 5); Section AC 3; Rigging 80 hp (hardness 0), AC 1; Ram 12d6; Face 80 ft. by 20 ft.; Height 10 ft. (draft 10 ft.); Crew 20; Cargo 150 tons (Spd wind × 15 ft. if 75 tons or more); Cost 10,000 gp. A sailing ice ship has runners that allow it to travel across fields of snow as well as sheets of ice. The deck has enough room for two light catapults or ballistae. The ship can be converted from ice to water travel or vice versa with four hours of work by a full crew.','vehicle',0,10000,ARRAY[]::text[],'v35-frostburn','D&D 3.5 — Frostburn',81,'dnd35','{"id":"frostburn-sailing-ice-ship","name":"Sailing Ice Ship","statLine":"Colossal vehicle; Profession (sailor) +4; Spd ice wind × 30 ft. (average), snow wind × 20 ft. (poor); Overall AC –3; Section hp 50 (hardness 5); Section AC 3; Rigging 80 hp (hardness 0), AC 1; Ram 12d6; Face 80 ft. by 20 ft.; Height 10 ft. (draft 10 ft.); Crew 20; Cargo 150 tons (Spd wind × 15 ft. if 75 tons or more); Cost 10,000 gp.","description":"A sailing ice ship has runners that allow it to travel across fields of snow as well as sheets of ice. The deck has enough room for two light catapults or ballistae. The ship can be converted from ice to water travel or vice versa with four hours of work by a full crew."}'::jsonb),
('dnd35.frostburn.vehicle.frostburn-sailing-ice-warship','Sailing Ice Warship','Sailing Ice Warship','Colossal vehicle; Profession (pilot) +2; Spd ice wind × 15 ft. (average), snow wind × 20 ft. (poor); Overall AC –3; Section hp 100 (hardness 5); Section AC 3; Rigging 80 hp (hardness 0), AC 1; Ram 15d6; Face 100 ft. by 20 ft.; Height 20 ft. (draft 15 ft.); SA Ramming prow; Crew 260 (80 rowers, 160 marines); Cargo 5 tons; Cost 25,000 gp. Used by the military forces of snow kingdoms or by glacial barbarian raiders, a sailing ice warship can bring devastation and death to vast expanses of ice and snow. An ice warship can accommodate two heavy catapults or four light catapults or ballistae. The ship can be converted from ice to water travel or vice versa with four hours of work by a full crew.','vehicle',0,25000,ARRAY[]::text[],'v35-frostburn','D&D 3.5 — Frostburn',81,'dnd35','{"id":"frostburn-sailing-ice-warship","name":"Sailing Ice Warship","statLine":"Colossal vehicle; Profession (pilot) +2; Spd ice wind × 15 ft. (average), snow wind × 20 ft. (poor); Overall AC –3; Section hp 100 (hardness 5); Section AC 3; Rigging 80 hp (hardness 0), AC 1; Ram 15d6; Face 100 ft. by 20 ft.; Height 20 ft. (draft 15 ft.); SA Ramming prow; Crew 260 (80 rowers, 160 marines); Cargo 5 tons; Cost 25,000 gp.","description":"Used by the military forces of snow kingdoms or by glacial barbarian raiders, a sailing ice warship can bring devastation and death to vast expanses of ice and snow. An ice warship can accommodate two heavy catapults or four light catapults or ballistae. The ship can be converted from ice to water travel or vice versa with four hours of work by a full crew."}'::jsonb),
('dnd35.frostburn.vehicle.frostburn-iceberg','Iceberg','Iceberg','Colossal vehicle; Profession (sailor) –20; Spd 5 ft. (nautical clumsy); Overall hp 900 (hardness 8); Overall AC –6; Section hp 50 (hardness 8); Section AC 3; Ram 20d6+1d6 cold; Space 100 ft.; Height 200 ft.; Cargo 1,000 tons; Cost —. An iceberg is a massive chuck of freshwater ice that has broken free of a glacier and fallen into the sea. These towering behemoths reach as high as 200 feet or more in height above the waterline (with usually another 800 feet or more hidden below the surface). An iceberg moves with the current and is impossible to control without some sort of sail, engine, or other force. For the specific terrain features of an iceberg, see Iceberg Terrain, page 25.','vehicle',0,null,ARRAY[]::text[],'v35-frostburn','D&D 3.5 — Frostburn',81,'dnd35','{"id":"frostburn-iceberg","name":"Iceberg","statLine":"Colossal vehicle; Profession (sailor) –20; Spd 5 ft. (nautical clumsy); Overall hp 900 (hardness 8); Overall AC –6; Section hp 50 (hardness 8); Section AC 3; Ram 20d6+1d6 cold; Space 100 ft.; Height 200 ft.; Cargo 1,000 tons; Cost —.","description":"An iceberg is a massive chuck of freshwater ice that has broken free of a glacier and fallen into the sea. These towering behemoths reach as high as 200 feet or more in height above the waterline (with usually another 800 feet or more hidden below the surface). An iceberg moves with the current and is impossible to control without some sort of sail, engine, or other force. For the specific terrain features of an iceberg, see Iceberg Terrain, page 25."}'::jsonb),
('dnd35.frostburn.vehicle.frostburn-skyberg','Skyberg','Skyberg','Colossal vehicle; Profession (pilot) –20; Spd fly wind × 20 ft. (clumsy); Overall hp 900 (hardness 8); Overall AC –6; Section hp 50 (hardness 8); Section AC 3; Ram 20d6+1d6 cold; Space 100 ft.; Height 200 ft.; Cargo 1,000 tons; Cost —. A skyberg resembles an iceberg in every way, except that it drifts along on wind currents rather than water currents. Skybergs reach 1,000 or more feet in height. For the specific terrain features of a skyberg, see Skyberg Terrain, page 26.','vehicle',0,null,ARRAY[]::text[],'v35-frostburn','D&D 3.5 — Frostburn',81,'dnd35','{"id":"frostburn-skyberg","name":"Skyberg","statLine":"Colossal vehicle; Profession (pilot) –20; Spd fly wind × 20 ft. (clumsy); Overall hp 900 (hardness 8); Overall AC –6; Section hp 50 (hardness 8); Section AC 3; Ram 20d6+1d6 cold; Space 100 ft.; Height 200 ft.; Cargo 1,000 tons; Cost —.","description":"A skyberg resembles an iceberg in every way, except that it drifts along on wind currents rather than water currents. Skybergs reach 1,000 or more feet in height. For the specific terrain features of a skyberg, see Skyberg Terrain, page 26."}'::jsonb),
('dnd35.frostburn.vehicle.frostburn-coldfire-ship','Coldfire Ship','Coldfire Ship','Colossal vehicle; Profession (sailor) +4; Spd ice 80 ft. (good); Overall AC –3; Section hp 50 (hardness 5); Section AC 3; Ram 12d6; Space 80 ft.; Height 20 ft.; Crew 10; Cargo 200 tons; Cost 500,000 gp. This magic ship has an ice keel and a coldfire engine, enabling it to move through ice at a speed of 80 feet. Planar sails stored belowdecks allow the ship to travel to the Elemental Planes or other frigid plane or layer where ice dominates the landscape (for more information on planar sails, see Chapter 3: Vehicles in the Arms and Equipment Guide). The ship has two ballistae mounted on rotating platforms, each of which can fire one 5d6 lightning bolt per round.','vehicle',0,500000,ARRAY[]::text[],'v35-frostburn','D&D 3.5 — Frostburn',81,'dnd35','{"id":"frostburn-coldfire-ship","name":"Coldfire Ship","statLine":"Colossal vehicle; Profession (sailor) +4; Spd ice 80 ft. (good); Overall AC –3; Section hp 50 (hardness 5); Section AC 3; Ram 12d6; Space 80 ft.; Height 20 ft.; Crew 10; Cargo 200 tons; Cost 500,000 gp.","description":"This magic ship has an ice keel and a coldfire engine, enabling it to move through ice at a speed of 80 feet. Planar sails stored belowdecks allow the ship to travel to the Elemental Planes or other frigid plane or layer where ice dominates the landscape (for more information on planar sails, see Chapter 3: Vehicles in the Arms and Equipment Guide). The ship has two ballistae mounted on rotating platforms, each of which can fire one 5d6 lightning bolt per round."}'::jsonb)
on conflict (id) do update set name_pt = excluded.name_pt, name_en = excluded.name_en, description_pt = excluded.description_pt, item_category = excluded.item_category, level = excluded.level, price_gp = excluded.price_gp, traits = excluded.traits, ruleset = excluded.ruleset, source_book = excluded.source_book, source_page = excluded.source_page, system_id = excluded.system_id, data = excluded.data, updated_at = now();

insert into public.catalog_spells (id,name_pt,name_en,description_pt,rank,is_cantrip,is_focus,traditions,cast_actions,range,targets,duration,defense,traits,ruleset,source_book,source_page,system_id,data) values
('dnd35.frostburn.spell.frostburn-algid-enhancement','Algid Enhancement','Algid Enhancement','You energize cold creatures with a surge of coldfire. Creatures with the cold subtype affected by this spell gain a +1 deflection bonus to AC, +1d8 temporary hit points, a +1 enhancement bonus on attack rolls, and a +2 bonus on saving throws against fire effects. Each of these enhancements increases by +1 for every three caster levels. So a 12th-level caster grants a +5 deflection bonus to AC, an extra 1d8+4 temporary hit points, a +5 enhancement bonus on attack rolls, and a +6 resistance bonus on saving throws against fire effects. This spell has no effect on creatures not of the cold subtype.
 Coldfire Component: One ounce of coldfire.',6,false,false,ARRAY['cleric']::text[],'1 round','Close (25 ft. + 5 ft./2 levels)','One cold creature/level','24 hours','None',ARRAY['Transmutation','Cold']::text[],'v35-frostburn','D&D 3.5 — Frostburn',88,'dnd35','{"id":"frostburn-algid-enhancement","name":"Algid Enhancement","school":"Transmutation","subschool":null,"descriptors":["Cold"],"schoolLine":"Transmutation [Cold]","levels":{"cleric":6},"levelLine":"Cleric 6","components":"V, S, Coldfire","castingTime":"1 round","range":"Close (25 ft. + 5 ft./2 levels)","duration":"24 hours","savingThrow":"None","spellResistance":"No","targetLabel":"Target","target":"One cold creature/level","description":"You energize cold creatures with a surge of coldfire. Creatures with the cold subtype affected by this spell gain a +1 deflection bonus to AC, +1d8 temporary hit points, a +1 enhancement bonus on attack rolls, and a +2 bonus on saving throws against fire effects. Each of these enhancements increases by +1 for every three caster levels. So a 12th-level caster grants a +5 deflection bonus to AC, an extra 1d8+4 temporary hit points, a +5 enhancement bonus on attack rolls, and a +6 resistance bonus on saving throws against fire effects. This spell has no effect on creatures not of the cold subtype.\n Coldfire Component: One ounce of coldfire."}'::jsonb),
('dnd35.frostburn.spell.frostburn-animate-snow','Animate Snow','Animate Snow','You imbue a mass of fallen snow with mobility and a semblance of life. The snow to be animated may be natural or magically created. Snow animated by this spell is treated as an animated object. You can animate four Large animated objects, two Huge animated objects, or one Gargantuan animated object. For details, see the Animated Object entry, page 13 of the Monster Manual. The animated snow can assume any basic shape you wish, and it attacks as directed by your vocal commands. Animated snow objects possess the Blind and Trample special attacks as detailed in the Monster Manual entry for animated objects. In addition, they have the cold subtype, and do an additional 1d6 points of cold damage on a successful hit. Animated snow objects take 1d6 points of damage each round if they exist in a place with temperatures above freezing.
 Material Component: Meltwater from a glacier.',6,false,false,ARRAY['druid']::text[],'1 standard action','Medium (100 ft. + 10 ft./level)','Up to a 20-ft. cube of snow','1 round/level','None',ARRAY['Transmutation','Cold']::text[],'v35-frostburn','D&D 3.5 — Frostburn',88,'dnd35','{"id":"frostburn-animate-snow","name":"Animate Snow","school":"Transmutation","subschool":null,"descriptors":["Cold"],"schoolLine":"Transmutation [Cold]","levels":{"druid":6},"levelLine":"Druid 6","components":"V, S, M","castingTime":"1 standard action","range":"Medium (100 ft. + 10 ft./level)","duration":"1 round/level","savingThrow":"None","spellResistance":"No","targetLabel":"Area","target":"Up to a 20-ft. cube of snow","description":"You imbue a mass of fallen snow with mobility and a semblance of life. The snow to be animated may be natural or magically created. Snow animated by this spell is treated as an animated object. You can animate four Large animated objects, two Huge animated objects, or one Gargantuan animated object. For details, see the Animated Object entry, page 13 of the Monster Manual. The animated snow can assume any basic shape you wish, and it attacks as directed by your vocal commands. Animated snow objects possess the Blind and Trample special attacks as detailed in the Monster Manual entry for animated objects. In addition, they have the cold subtype, and do an additional 1d6 points of cold damage on a successful hit. Animated snow objects take 1d6 points of damage each round if they exist in a place with temperatures above freezing.\n Material Component: Meltwater from a glacier."}'::jsonb),
('dnd35.frostburn.spell.frostburn-anticold-sphere','Anticold Sphere','Anticold Sphere','You bring into being a mobile, spherical energy field that protects against cold. All creatures within the area of the spell are granted immunity to cold. In addition, the sphere prevents the entrance of any creature with the cold subtype. The effect hedges out such creatures in the area when it is cast. This spell may be used only defensively, not aggressively. Forcing an abjuration barrier against creatures that the spell keeps at bay collapses the barrier (see Abjuration, page 172 of the Player’s Handbook).',5,false,false,ARRAY['sorcerer/wizard']::text[],'1 standard action','10 ft.','10-ft.-radius emanation, centered on you','10 min./level (D)','None',ARRAY['Abjuration']::text[],'v35-frostburn','D&D 3.5 — Frostburn',88,'dnd35','{"id":"frostburn-anticold-sphere","name":"Anticold Sphere","school":"Abjuration","subschool":null,"descriptors":[],"schoolLine":"Abjuration","levels":{"sorcerer/wizard":5},"levelLine":"Sorcerer/wizard 5","components":"V, S","castingTime":"1 standard action","range":"10 ft.","duration":"10 min./level (D)","savingThrow":"None","spellResistance":"Yes","targetLabel":"Area","target":"10-ft.-radius emanation, centered on you","description":"You bring into being a mobile, spherical energy field that protects against cold. All creatures within the area of the spell are granted immunity to cold. In addition, the sphere prevents the entrance of any creature with the cold subtype. The effect hedges out such creatures in the area when it is cast. This spell may be used only defensively, not aggressively. Forcing an abjuration barrier against creatures that the spell keeps at bay collapses the barrier (see Abjuration, page 172 of the Player’s Handbook)."}'::jsonb),
('dnd35.frostburn.spell.frostburn-arctic-haze','Arctic Haze','Arctic Haze','A bank of fog composed entirely of tiny, razor-sharp ice shards billows out from the targeted point. The fog obscures all sight, including darkvision, beyond 5 feet. A creature 5 feet away has concealment (20% miss chance). Creatures farther away have total concealment (50% miss chance, and the attacker can’t use sight to locate the target). In addition, the sharp ice particles tear the skin of those moving through the area, causing 4 points of damage per round, half of which is cold damage. A strong wind (21+ mph) disperses the fog in 4 rounds; a severe wind (31+ mph) disperses the fog in 1 round. Dispersing the fog in this manner, however, causes damage to those within its area as the icy shards whip past. A strong wind causes 4 points of damage per round (half cold); a severe wind causes 8 points of damage (half cold).',3,false,false,ARRAY['druid','sorcerer/wizard']::text[],'1 standard action','Medium (100 ft. + 10 ft./level)','Fog spreads in a 30-ft. radius, 20 ft. high','10 min./level','Fortitude half',ARRAY['Conjuration','Cold']::text[],'v35-frostburn','D&D 3.5 — Frostburn',88,'dnd35','{"id":"frostburn-arctic-haze","name":"Arctic Haze","school":"Conjuration","subschool":"Creation","descriptors":["Cold"],"schoolLine":"Conjuration (Creation) [Cold]","levels":{"druid":3,"sorcerer/wizard":3},"levelLine":"Druid 3, sorcerer/wizard 3","components":"V, S","castingTime":"1 standard action","range":"Medium (100 ft. + 10 ft./level)","duration":"10 min./level","savingThrow":"Fortitude half","spellResistance":"No","targetLabel":"Effect","target":"Fog spreads in a 30-ft. radius, 20 ft. high","description":"A bank of fog composed entirely of tiny, razor-sharp ice shards billows out from the targeted point. The fog obscures all sight, including darkvision, beyond 5 feet. A creature 5 feet away has concealment (20% miss chance). Creatures farther away have total concealment (50% miss chance, and the attacker can’t use sight to locate the target). In addition, the sharp ice particles tear the skin of those moving through the area, causing 4 points of damage per round, half of which is cold damage. A strong wind (21+ mph) disperses the fog in 4 rounds; a severe wind (31+ mph) disperses the fog in 1 round. Dispersing the fog in this manner, however, causes damage to those within its area as the icy shards whip past. A strong wind causes 4 points of damage per round (half cold); a severe wind causes 8 points of damage (half cold)."}'::jsonb),
('dnd35.frostburn.spell.frostburn-aura-of-cold-greater','Aura of Cold, Greater','Aura of Cold, Greater','This spell functions exactly like lesser aura of cold, except it deals 2d6 points of cold damage to all creatures within 10 feet.',7,false,false,ARRAY['cleric','druid']::text[],null,'10 ft.','10-ft.-radius spherical emanation, centered on you',null,null,ARRAY['Transmutation','Cold']::text[],'v35-frostburn','D&D 3.5 — Frostburn',88,'dnd35','{"id":"frostburn-aura-of-cold-greater","name":"Aura of Cold, Greater","school":"Transmutation","subschool":null,"descriptors":["Cold"],"schoolLine":"Transmutation [Cold]","levels":{"cleric":7,"druid":7},"levelLine":"Cleric 7, druid 7","range":"10 ft.","targetLabel":"Area","target":"10-ft.-radius spherical emanation, centered on you","description":"This spell functions exactly like lesser aura of cold, except it deals 2d6 points of cold damage to all creatures within 10 feet."}'::jsonb),
('dnd35.frostburn.spell.frostburn-aura-of-cold-lesser','Aura of Cold, Lesser','Aura of Cold, Lesser','You are covered in a thin layer of white frost and frigid cold emanates from your body, dealing 1d6 points of cold damage at the start of your round to each creature within 5 feet.',3,false,false,ARRAY['cleric','druid','paladin','ranger']::text[],'1 standard action','5 ft.','5-ft.-radius spherical emanation, centered on you','1 round/level (D)','None',ARRAY['Transmutation','Cold']::text[],'v35-frostburn','D&D 3.5 — Frostburn',88,'dnd35','{"id":"frostburn-aura-of-cold-lesser","name":"Aura of Cold, Lesser","school":"Transmutation","subschool":null,"descriptors":["Cold"],"schoolLine":"Transmutation [Cold]","levels":{"cleric":3,"druid":3,"paladin":4,"ranger":4},"levelLine":"Cleric 3, druid 3, paladin 4, ranger 4","components":"V, S, DF","castingTime":"1 standard action","range":"5 ft.","duration":"1 round/level (D)","savingThrow":"None","spellResistance":"Yes","targetLabel":"Area","target":"5-ft.-radius spherical emanation, centered on you","description":"You are covered in a thin layer of white frost and frigid cold emanates from your body, dealing 1d6 points of cold damage at the start of your round to each creature within 5 feet."}'::jsonb),
('dnd35.frostburn.spell.frostburn-binding-snow','Binding Snow','Binding Snow','This spell must be cast on a snow field. That snow field instantly freezes, impeding movement through the area. A creature caught within the area can move only at half its normal speed. By making a DC 20 Strength check or a DC 25 Escape Artist check, the creature can move at its normal speed for that round. A creature that succeeds on a Reflex save is not impeded.',3,false,false,ARRAY['cleric','druid','paladin','ranger']::text[],'1 standard action','Medium (100 ft. + 10 ft./level)','One 10-ft. square/level','1 hour/level (D)','Reflex negates',ARRAY['Transmutation','Cold']::text[],'v35-frostburn','D&D 3.5 — Frostburn',88,'dnd35','{"id":"frostburn-binding-snow","name":"Binding Snow","school":"Transmutation","subschool":null,"descriptors":["Cold"],"schoolLine":"Transmutation [Cold]","levels":{"cleric":3,"druid":3,"paladin":3,"ranger":3},"levelLine":"Cleric 3, druid 3, paladin 3, ranger 3","components":"V, S, DF, Frostfell","castingTime":"1 standard action","range":"Medium (100 ft. + 10 ft./level)","duration":"1 hour/level (D)","savingThrow":"Reflex negates","spellResistance":"Yes","targetLabel":"Area","target":"One 10-ft. square/level","description":"This spell must be cast on a snow field. That snow field instantly freezes, impeding movement through the area. A creature caught within the area can move only at half its normal speed. By making a DC 20 Strength check or a DC 25 Escape Artist check, the creature can move at its normal speed for that round. A creature that succeeds on a Reflex save is not impeded."}'::jsonb),
('dnd35.frostburn.spell.frostburn-blizzard','Blizzard','Blizzard','Immediately upon completion of this spell, the temperature drops to below freezing and a powerful blizzard erupts in the area. Visibility is reduced to zero, making Spot, Search, and Listen checks and all ranged attacks impossible. Unprotected flames are automatically extinguished and protected flames have a 75% chance of being doused. Creatures unprotected from the cold must make a Fortitude save or take 1d6 points of nonlethal cold damage. One foot of new snow falls each round. Movement within the area is impeded, depending on the creature’s size and depth of snow (for movement in a snow field, see page 12).',5,false,false,ARRAY['druid','winter']::text[],'1 round','Long (400 ft. + 40 ft./level)','100 ft.-radius/level spread','1 round/level','Fortitude partial',ARRAY['Transmutation','Cold']::text[],'v35-frostburn','D&D 3.5 — Frostburn',88,'dnd35','{"id":"frostburn-blizzard","name":"Blizzard","school":"Transmutation","subschool":null,"descriptors":["Cold"],"schoolLine":"Transmutation [Cold]","levels":{"druid":5,"winter":5},"levelLine":"Druid 5, Winter 5","components":"V, S","castingTime":"1 round","range":"Long (400 ft. + 40 ft./level)","duration":"1 round/level","savingThrow":"Fortitude partial","spellResistance":"No","targetLabel":"Area","target":"100 ft.-radius/level spread","description":"Immediately upon completion of this spell, the temperature drops to below freezing and a powerful blizzard erupts in the area. Visibility is reduced to zero, making Spot, Search, and Listen checks and all ranged attacks impossible. Unprotected flames are automatically extinguished and protected flames have a 75% chance of being doused. Creatures unprotected from the cold must make a Fortitude save or take 1d6 points of nonlethal cold damage. One foot of new snow falls each round. Movement within the area is impeded, depending on the creature’s size and depth of snow (for movement in a snow field, see page 12)."}'::jsonb),
('dnd35.frostburn.spell.frostburn-blood-snow','Blood Snow','Blood Snow','You must cast this spell on a snow field. You corrupt an area of fallen snow, imbuing it with negative energy. Each round, a creature in contact with blood snow must succeed on a Fortitude save or take 1d2 points of Constitution drain. In addition, anyone failing a saving throw is nauseated for the duration of the spell.',2,false,false,ARRAY['cleric','druid','sorcerer/wizard']::text[],'1 standard action','Medium (100 ft. + 10 ft./level)','20-ft. square of snow/level','1 round/level','Fortitude negates',ARRAY['Necromancy','Cold']::text[],'v35-frostburn','D&D 3.5 — Frostburn',88,'dnd35','{"id":"frostburn-blood-snow","name":"Blood Snow","school":"Necromancy","subschool":null,"descriptors":["Cold"],"schoolLine":"Necromancy [Cold]","levels":{"cleric":2,"druid":2,"sorcerer/wizard":3},"levelLine":"Cleric 2, druid 2, sorcerer/ wizard 3","components":"V, S","castingTime":"1 standard action","range":"Medium (100 ft. + 10 ft./level)","duration":"1 round/level","savingThrow":"Fortitude negates","spellResistance":"Yes","targetLabel":"Area","target":"20-ft. square of snow/level","description":"You must cast this spell on a snow field. You corrupt an area of fallen snow, imbuing it with negative energy. Each round, a creature in contact with blood snow must succeed on a Fortitude save or take 1d2 points of Constitution drain. In addition, anyone failing a saving throw is nauseated for the duration of the spell."}'::jsonb),
('dnd35.frostburn.spell.frostburn-bone-chill','Bone Chill','Bone Chill','A ray of burning cold erupts from your fingertips. Corporeal undead struck by the ray are covered in a layer of ice, rendering the subject immobile as if held. Each round on its turn, the subject may attempt a new saving throw to break free of the ice. (This is a full-round action that does not provoke attacks of opportunity.)
 Material Component: A small piece of bone and a 1-inch cube of ice.',2,false,false,ARRAY['sorcerer/wizard']::text[],'1 standard action','Close (25 ft. + 5 ft./2 levels)','Ray','1 round/level','Fortitude negates',ARRAY['Necromancy']::text[],'v35-frostburn','D&D 3.5 — Frostburn',88,'dnd35','{"id":"frostburn-bone-chill","name":"Bone Chill","school":"Necromancy","subschool":null,"descriptors":[],"schoolLine":"Necromancy","levels":{"sorcerer/wizard":2},"levelLine":"Sorcerer/wizard 2","components":"V, S, M","castingTime":"1 standard action","range":"Close (25 ft. + 5 ft./2 levels)","duration":"1 round/level","savingThrow":"Fortitude negates","spellResistance":"No","targetLabel":"Effect","target":"Ray","description":"A ray of burning cold erupts from your fingertips. Corporeal undead struck by the ray are covered in a layer of ice, rendering the subject immobile as if held. Each round on its turn, the subject may attempt a new saving throw to break free of the ice. (This is a full-round action that does not provoke attacks of opportunity.)\n Material Component: A small piece of bone and a 1-inch cube of ice."}'::jsonb),
('dnd35.frostburn.spell.frostburn-boreal-wind','Boreal Wind','Boreal Wind','You create a strong blast of arctic air that originates from your fingertips and moves in the direction you are facing. As a stronger form of gust of wind, this boreal wind automatically extinguishes candles, torches, and similar protected or unprotected flames, including lanterns. Large fires (such as bonfires, a blacksmith’s coals, or even a house fire) have a 50% chance to be extinguished by the boreal wind. Forest or grassland fires are too large to be extinguished by this spell. All creatures caught in the area take 1d4 points of cold damage per caster level (maximum 15d4). A successful Fortitude saving throw negates the gust’s effects. Those that fail the save are pushed away from the caster a distance of 3 feet per caster level. Creatures that remain in the area past the first round must make an additional saving throw each round. A boreal wind can do anything a sudden blast of wind would be expected to do. It can create a stinging spray of sand or dust, overturn tents and blow down small huts, scuttle a small boat, and blow gases or vapors to the edge of the range. The wind can change direction if you actively direct it (a move action for you); otherwise, it merely blows in the same direction.',4,false,false,ARRAY['bard','cleric','druid','sorcerer/wizard']::text[],'1 standard action','Long (400 ft. + 40 ft./level)','Gust of wind (20 ft. wide, 20 ft. high) emanating out from you to the extreme of the range','1 round + 1 round/2 levels','Fortitude negates',ARRAY['Evocation','Cold']::text[],'v35-frostburn','D&D 3.5 — Frostburn',88,'dnd35','{"id":"frostburn-boreal-wind","name":"Boreal Wind","school":"Evocation","subschool":null,"descriptors":["Cold"],"schoolLine":"Evocation [Cold]","levels":{"bard":5,"cleric":5,"druid":4,"sorcerer/wizard":5},"levelLine":"Bard 5, cleric 5, druid 4, sorcerer/ wizard 5","components":"V, S, DF","castingTime":"1 standard action","range":"Long (400 ft. + 40 ft./level)","duration":"1 round + 1 round/2 levels","savingThrow":"Fortitude negates","spellResistance":"Yes","targetLabel":"Effect","target":"Gust of wind (20 ft. wide, 20 ft. high) emanating out from you to the extreme of the range","description":"You create a strong blast of arctic air that originates from your fingertips and moves in the direction you are facing. As a stronger form of gust of wind, this boreal wind automatically extinguishes candles, torches, and similar protected or unprotected flames, including lanterns. Large fires (such as bonfires, a blacksmith’s coals, or even a house fire) have a 50% chance to be extinguished by the boreal wind. Forest or grassland fires are too large to be extinguished by this spell. All creatures caught in the area take 1d4 points of cold damage per caster level (maximum 15d4). A successful Fortitude saving throw negates the gust’s effects. Those that fail the save are pushed away from the caster a distance of 3 feet per caster level. Creatures that remain in the area past the first round must make an additional saving throw each round. A boreal wind can do anything a sudden blast of wind would be expected to do. It can create a stinging spray of sand or dust, overturn tents and blow down small huts, scuttle a small boat, and blow gases or vapors to the edge of the range. The wind can change direction if you actively direct it (a move action for you); otherwise, it merely blows in the same direction."}'::jsonb),
('dnd35.frostburn.spell.frostburn-brumal-stiffening','Brumal Stiffening','Brumal Stiffening','The targeted weapon becomes brittle, reducing its hardness by 5 for the duration of the spell, thereby increasing Brumal stiffening the effectiveness of sunder attempts against the weapon. In addition, rolling a 1 on an attack with the targeted weapon causes it to take damage equivalent to the amount it would have dealt on a successful hit.',2,false,false,ARRAY['cleric','druid','sorcerer/wizard']::text[],'1 standard action','Close (25 ft. + 5 ft./2 levels)','One weapon','1 round/level','Reflex negates',ARRAY['Transmutation','Cold']::text[],'v35-frostburn','D&D 3.5 — Frostburn',88,'dnd35','{"id":"frostburn-brumal-stiffening","name":"Brumal Stiffening","school":"Transmutation","subschool":null,"descriptors":["Cold"],"schoolLine":"Transmutation [Cold]","levels":{"cleric":2,"druid":2,"sorcerer/wizard":2},"levelLine":"Cleric 2, druid 2, sorcerer/ wizard 2","components":"V, S","castingTime":"1 standard action","range":"Close (25 ft. + 5 ft./2 levels)","duration":"1 round/level","savingThrow":"Reflex negates","spellResistance":"Yes","targetLabel":"Target","target":"One weapon","description":"The targeted weapon becomes brittle, reducing its hardness by 5 for the duration of the spell, thereby increasing Brumal stiffening the effectiveness of sunder attempts against the weapon. In addition, rolling a 1 on an attack with the targeted weapon causes it to take damage equivalent to the amount it would have dealt on a successful hit."}'::jsonb),
('dnd35.frostburn.spell.frostburn-call-avalanche','Call Avalanche','Call Avalanche','This spell may only be cast outside. Immediately upon completion of the spell, an avalanche of ice and snow falls out of the sky, dealing 8d6 points of crushing damage and potentially burying Large or smaller creatures within the area. Creatures making their Reflex saving throws take half damage and are not buried. Those that fail their saves are buried and take an additional 1d6 points of nonlethal damage per minute while still buried. If such a creature falls unconscious while buried, it must make a DC 15 Constitution check. If that check fails, it takes 1d6 points of lethal damage each minute thereafter until freed or dead. The ice and snow remains until melted by natural or unnatural means. A rapid melting of the ice and snow could cause a flash flood (see Freezing and Thawing, page 10). A 9th-level caster buries Large or smaller creatures. At 12th level, the maximum size of a creature increases to Huge. At 15th, Gargantuan creatures are also buried, and at 18th level, a creature of up to Colossal size is buried by the snow.',5,false,false,ARRAY['druid']::text[],'1 round','Long (400 ft. + 40 ft./level)','10 ft.-radius/level spread','Instantaneous','Reflex half; see text',ARRAY['Evocation','Cold']::text[],'v35-frostburn','D&D 3.5 — Frostburn',88,'dnd35','{"id":"frostburn-call-avalanche","name":"Call Avalanche","school":"Evocation","subschool":null,"descriptors":["Cold"],"schoolLine":"Evocation [Cold]","levels":{"druid":5},"levelLine":"Druid 5","components":"V, S","castingTime":"1 round","range":"Long (400 ft. + 40 ft./level)","duration":"Instantaneous","savingThrow":"Reflex half; see text","spellResistance":"No","targetLabel":"Area","target":"10 ft.-radius/level spread","description":"This spell may only be cast outside. Immediately upon completion of the spell, an avalanche of ice and snow falls out of the sky, dealing 8d6 points of crushing damage and potentially burying Large or smaller creatures within the area. Creatures making their Reflex saving throws take half damage and are not buried. Those that fail their saves are buried and take an additional 1d6 points of nonlethal damage per minute while still buried. If such a creature falls unconscious while buried, it must make a DC 15 Constitution check. If that check fails, it takes 1d6 points of lethal damage each minute thereafter until freed or dead. The ice and snow remains until melted by natural or unnatural means. A rapid melting of the ice and snow could cause a flash flood (see Freezing and Thawing, page 10). A 9th-level caster buries Large or smaller creatures. At 12th level, the maximum size of a creature increases to Huge. At 15th, Gargantuan creatures are also buried, and at 18th level, a creature of up to Colossal size is buried by the snow."}'::jsonb),
('dnd35.frostburn.spell.frostburn-column-of-ice','Column of Ice','Column of Ice','A column of ice rises from the ground, lifting any object or creature (including you) standing in the area into the air. Creatures making a Reflex saving throw can choose to avoid the column. Moving or fighting atop the ice column requires a DC 10 Balance check. Those who fail fall prone and must immediately succeed on a DC 12 Reflex saving throw or slip off the column, taking commensurate falling damage. Creatures atop the column as it rises may be smashed against the ceiling or other overhead obstructions, which deals 4d6 points of damage. Magical Ice Column: 10 feet thick; hardness 16; hp 160; break DC 90; Climb DC 30. Arcane Material Component: A 2-inch rod of ice.',3,false,false,ARRAY['druid','sorcerer/wizard']::text[],'1 standard action','Close (25 ft. + 5 ft./2 levels)','One column of ice, 10-ft. radius and 5 ft./level in height','Permanent','Reflex negates',ARRAY['Conjuration','Cold']::text[],'v35-frostburn','D&D 3.5 — Frostburn',88,'dnd35','{"id":"frostburn-column-of-ice","name":"Column of Ice","school":"Conjuration","subschool":"Creation","descriptors":["Cold"],"schoolLine":"Conjuration (Creation) [Cold]","levels":{"druid":3,"sorcerer/wizard":4},"levelLine":"Druid 3, sorcerer/wizard 4","components":"V, S, M","castingTime":"1 standard action","range":"Close (25 ft. + 5 ft./2 levels)","duration":"Permanent","savingThrow":"Reflex negates","spellResistance":"No","targetLabel":"Effect","target":"One column of ice, 10-ft. radius and 5 ft./level in height","description":"A column of ice rises from the ground, lifting any object or creature (including you) standing in the area into the air. Creatures making a Reflex saving throw can choose to avoid the column. Moving or fighting atop the ice column requires a DC 10 Balance check. Those who fail fall prone and must immediately succeed on a DC 12 Reflex saving throw or slip off the column, taking commensurate falling damage. Creatures atop the column as it rises may be smashed against the ceiling or other overhead obstructions, which deals 4d6 points of damage. Magical Ice Column: 10 feet thick; hardness 16; hp 160; break DC 90; Climb DC 30. Arcane Material Component: A 2-inch rod of ice."}'::jsonb),
('dnd35.frostburn.spell.frostburn-cometstrike','Cometstrike','Cometstrike','This spell may only be cast in an outdoor area; it fails if cast indoors or underground. When you cast this spell, you cause three frozen comets to strike down upon any three different creatures or objects in range. You must make a ranged touch attack to hit each target. Each target struck takes 3d6 points of bludgeoning damage and 1d4 points of cold damage per level (maximum 10d4), and is stunned for one round. A successful Reflex save negates the bludgeoning damage and the stunning effects, but not the cold damage. Each round the spell persists, another three frozen comets rain down upon the original three targets; as a standard action you can select new targets for one, two, or all three comets.',9,false,false,ARRAY['druid']::text[],'1 standard action','Medium (100 ft. + 10 ft./level)','Three different creatures or objects','3 rounds','Reflex partial',ARRAY['Conjuration','Cold']::text[],'v35-frostburn','D&D 3.5 — Frostburn',88,'dnd35','{"id":"frostburn-cometstrike","name":"Cometstrike","school":"Conjuration","subschool":"Creation","descriptors":["Cold"],"schoolLine":"Conjuration (Creation) [Cold]","levels":{"druid":9},"levelLine":"Druid 9","components":"V, DF","castingTime":"1 standard action","range":"Medium (100 ft. + 10 ft./level)","duration":"3 rounds","savingThrow":"Reflex partial","spellResistance":"No","targetLabel":"Target","target":"Three different creatures or objects","description":"This spell may only be cast in an outdoor area; it fails if cast indoors or underground. When you cast this spell, you cause three frozen comets to strike down upon any three different creatures or objects in range. You must make a ranged touch attack to hit each target. Each target struck takes 3d6 points of bludgeoning damage and 1d4 points of cold damage per level (maximum 10d4), and is stunned for one round. A successful Reflex save negates the bludgeoning damage and the stunning effects, but not the cold damage. Each round the spell persists, another three frozen comets rain down upon the original three targets; as a standard action you can select new targets for one, two, or all three comets."}'::jsonb),
('dnd35.frostburn.spell.frostburn-conjure-ice-beast-i','Conjure Ice Beast I','Conjure Ice Beast I','This spell creates a creature constructed from magical ice. It appears where you designate and acts immediately, on your turn. It attacks your opponents to the best of its ability. If you can communicate with the creature, you can direct it not to attack, to attack particular enemies, or to perform other actions. The spell conjures one of the creatures from the 1st-level list of either the summon monster table or the summon nature’s ally table (pages 287–288 of the Player’s Handbook). The conjured creature cannot have the fire subtype. You choose which kind of creature to conjure, and you can change that choice each time you cast the spell. The conjured creature is a construct made of magical ice, gaining the ice beast template (see page 138). In all other ways, conjure ice beast I functions like summon monster I.',1,false,false,ARRAY['cleric','druid','ranger']::text[],'1 round','Close (25 ft. + 5 ft./2 levels)','One conjured ice creature','1 round/level (D)','None',ARRAY['Conjuration','Cold']::text[],'v35-frostburn','D&D 3.5 — Frostburn',88,'dnd35','{"id":"frostburn-conjure-ice-beast-i","name":"Conjure Ice Beast I","school":"Conjuration","subschool":"Creation","descriptors":["Cold"],"schoolLine":"Conjuration (Creation) [Cold]","levels":{"cleric":1,"druid":1,"ranger":1},"levelLine":"Cleric 1, druid 1, ranger 1","components":"V, S, DF","castingTime":"1 round","range":"Close (25 ft. + 5 ft./2 levels)","duration":"1 round/level (D)","savingThrow":"None","spellResistance":"No","targetLabel":"Effect","target":"One conjured ice creature","description":"This spell creates a creature constructed from magical ice. It appears where you designate and acts immediately, on your turn. It attacks your opponents to the best of its ability. If you can communicate with the creature, you can direct it not to attack, to attack particular enemies, or to perform other actions. The spell conjures one of the creatures from the 1st-level list of either the summon monster table or the summon nature’s ally table (pages 287–288 of the Player’s Handbook). The conjured creature cannot have the fire subtype. You choose which kind of creature to conjure, and you can change that choice each time you cast the spell. The conjured creature is a construct made of magical ice, gaining the ice beast template (see page 138). In all other ways, conjure ice beast I functions like summon monster I."}'::jsonb),
('dnd35.frostburn.spell.frostburn-conjure-ice-beast-ii','Conjure Ice Beast II','Conjure Ice Beast II','This spell functions like conjure ice beast I, except that you can conjure one creature from the 2nd-level list or two creatures of the same kind from the 1st-level list.',2,false,false,ARRAY['cleric','druid','ranger']::text[],null,null,'One or more conjured ice creatures, no two of which can be more than 30 ft. apart',null,null,ARRAY['Conjuration','Cold']::text[],'v35-frostburn','D&D 3.5 — Frostburn',88,'dnd35','{"id":"frostburn-conjure-ice-beast-ii","name":"Conjure Ice Beast II","school":"Conjuration","subschool":"Creation","descriptors":["Cold"],"schoolLine":"Conjuration (Creation) [Cold]","levels":{"cleric":2,"druid":2,"ranger":2},"levelLine":"Cleric 2, druid 2, ranger 2","targetLabel":"Effect","target":"One or more conjured ice creatures, no two of which can be more than 30 ft. apart","description":"This spell functions like conjure ice beast I, except that you can conjure one creature from the 2nd-level list or two creatures of the same kind from the 1st-level list."}'::jsonb),
('dnd35.frostburn.spell.frostburn-conjure-ice-beast-iii','Conjure Ice Beast III','Conjure Ice Beast III','This spell functions like conjure ice beast I, except that you can conjure one creature from the 3rd-level list, two creatures of the same kind from the 2nd-level list, or four creatures of the same kind from the 1st-level list.',3,false,false,ARRAY['cleric','druid','ranger']::text[],null,null,'One or more conjured ice creatures, no two of which can be more than 30 ft. apart',null,null,ARRAY['Conjuration','Cold']::text[],'v35-frostburn','D&D 3.5 — Frostburn',88,'dnd35','{"id":"frostburn-conjure-ice-beast-iii","name":"Conjure Ice Beast III","school":"Conjuration","subschool":"Creation","descriptors":["Cold"],"schoolLine":"Conjuration (Creation) [Cold]","levels":{"cleric":3,"druid":3,"ranger":3},"levelLine":"Cleric 3, druid 3, ranger 3","targetLabel":"Effect","target":"One or more conjured ice creatures, no two of which can be more than 30 ft. apart","description":"This spell functions like conjure ice beast I, except that you can conjure one creature from the 3rd-level list, two creatures of the same kind from the 2nd-level list, or four creatures of the same kind from the 1st-level list."}'::jsonb),
('dnd35.frostburn.spell.frostburn-conjure-ice-beast-iv','Conjure Ice Beast IV','Conjure Ice Beast IV','This spell functions like conjure ice beast I, except that you can conjure one creature from the 4th-level list, two creatures of the same kind from the 3rd-level list, or four creatures of the same kind from a lower-level list.',4,false,false,ARRAY['cleric','druid','ranger']::text[],null,null,'One or more conjured ice creatures, no two of which can be more than 30 ft. apart',null,null,ARRAY['Conjuration','Cold']::text[],'v35-frostburn','D&D 3.5 — Frostburn',88,'dnd35','{"id":"frostburn-conjure-ice-beast-iv","name":"Conjure Ice Beast IV","school":"Conjuration","subschool":"Creation","descriptors":["Cold"],"schoolLine":"Conjuration (Creation) [Cold]","levels":{"cleric":4,"druid":4,"ranger":4},"levelLine":"Cleric 4, druid 4, ranger 4","targetLabel":"Effect","target":"One or more conjured ice creatures, no two of which can be more than 30 ft. apart","description":"This spell functions like conjure ice beast I, except that you can conjure one creature from the 4th-level list, two creatures of the same kind from the 3rd-level list, or four creatures of the same kind from a lower-level list."}'::jsonb),
('dnd35.frostburn.spell.frostburn-conjure-ice-beast-v','Conjure Ice Beast V','Conjure Ice Beast V','This spell functions like conjure ice beast I, except that you can conjure one creature from the 5th-level list, two creatures of the same kind from the 4th-level list, or four creatures of the same kind from a lower-level list.',5,false,false,ARRAY['cleric','druid']::text[],null,null,'One or more conjured ice creatures, no two of which can be more than 30 ft. apart',null,null,ARRAY['Conjuration','Cold']::text[],'v35-frostburn','D&D 3.5 — Frostburn',88,'dnd35','{"id":"frostburn-conjure-ice-beast-v","name":"Conjure Ice Beast V","school":"Conjuration","subschool":"Creation","descriptors":["Cold"],"schoolLine":"Conjuration (Creation) [Cold]","levels":{"cleric":5,"druid":5},"levelLine":"Cleric 5, druid 5","targetLabel":"Effect","target":"One or more conjured ice creatures, no two of which can be more than 30 ft. apart","description":"This spell functions like conjure ice beast I, except that you can conjure one creature from the 5th-level list, two creatures of the same kind from the 4th-level list, or four creatures of the same kind from a lower-level list."}'::jsonb),
('dnd35.frostburn.spell.frostburn-conjure-ice-beast-vi','Conjure Ice Beast VI','Conjure Ice Beast VI','This spell functions like conjure ice beast I, except that you can conjure one creature from the 6th-level list, two creatures of the same kind from the 5th-level list, or four creatures of the same kind from a lower-level list.',6,false,false,ARRAY['cleric','druid']::text[],null,null,'One or more conjured ice creatures, no two of which can be more than 30 ft. apart',null,null,ARRAY['Conjuration','Cold']::text[],'v35-frostburn','D&D 3.5 — Frostburn',88,'dnd35','{"id":"frostburn-conjure-ice-beast-vi","name":"Conjure Ice Beast VI","school":"Conjuration","subschool":"Creation","descriptors":["Cold"],"schoolLine":"Conjuration (Creation) [Cold]","levels":{"cleric":6,"druid":6},"levelLine":"Cleric 6, druid 6","targetLabel":"Effect","target":"One or more conjured ice creatures, no two of which can be more than 30 ft. apart","description":"This spell functions like conjure ice beast I, except that you can conjure one creature from the 6th-level list, two creatures of the same kind from the 5th-level list, or four creatures of the same kind from a lower-level list."}'::jsonb),
('dnd35.frostburn.spell.frostburn-conjure-ice-beast-vii','Conjure Ice Beast VII','Conjure Ice Beast VII','This spell functions like conjure ice beast I, except that you can conjure one creature from the 7th-level list, two creatures of the same kind from the 6th-level list, or four creatures of the same kind from a lower-level list.',7,false,false,ARRAY['cleric','druid']::text[],null,null,'One or more conjured ice creatures, no two of which can be more than 30 ft. apart',null,null,ARRAY['Conjuration','Cold']::text[],'v35-frostburn','D&D 3.5 — Frostburn',88,'dnd35','{"id":"frostburn-conjure-ice-beast-vii","name":"Conjure Ice Beast VII","school":"Conjuration","subschool":"Creation","descriptors":["Cold"],"schoolLine":"Conjuration (Creation) [Cold]","levels":{"cleric":7,"druid":7},"levelLine":"Cleric 7, druid 7","targetLabel":"Effect","target":"One or more conjured ice creatures, no two of which can be more than 30 ft. apart","description":"This spell functions like conjure ice beast I, except that you can conjure one creature from the 7th-level list, two creatures of the same kind from the 6th-level list, or four creatures of the same kind from a lower-level list."}'::jsonb),
('dnd35.frostburn.spell.frostburn-conjure-ice-beast-viii','Conjure Ice Beast VIII','Conjure Ice Beast VIII','This spell functions like conjure ice beast I, except that you can conjure one creature from the 8th-level list, two creatures of the same kind from the 7th-level list, or four creatures of the same kind from a lower-level list.',8,false,false,ARRAY['cleric','druid']::text[],null,null,'One or more conjured ice creatures, no two of which can be more than 30 ft. apart',null,null,ARRAY['Conjuration','Cold']::text[],'v35-frostburn','D&D 3.5 — Frostburn',88,'dnd35','{"id":"frostburn-conjure-ice-beast-viii","name":"Conjure Ice Beast VIII","school":"Conjuration","subschool":"Creation","descriptors":["Cold"],"schoolLine":"Conjuration (Creation) [Cold]","levels":{"cleric":8,"druid":8},"levelLine":"Cleric 8, druid 8","targetLabel":"Effect","target":"One or more conjured ice creatures, no two of which can be more than 30 ft. apart","description":"This spell functions like conjure ice beast I, except that you can conjure one creature from the 8th-level list, two creatures of the same kind from the 7th-level list, or four creatures of the same kind from a lower-level list."}'::jsonb),
('dnd35.frostburn.spell.frostburn-conjure-ice-beast-ix','Conjure Ice Beast IX','Conjure Ice Beast IX','This spell functions like conjure ice beast I, except that you can conjure one creature from the 9th-level list, two creatures of the same kind from the 8th-level list, or four creatures of the same kind from a lower-level list.',9,false,false,ARRAY['cleric','druid']::text[],null,null,'One or more conjured ice creatures, no two of which can be more than 30 ft. apart',null,null,ARRAY['Conjuration','Cold']::text[],'v35-frostburn','D&D 3.5 — Frostburn',88,'dnd35','{"id":"frostburn-conjure-ice-beast-ix","name":"Conjure Ice Beast IX","school":"Conjuration","subschool":"Creation","descriptors":["Cold"],"schoolLine":"Conjuration (Creation) [Cold]","levels":{"cleric":9,"druid":9},"levelLine":"Cleric 9, druid 9","targetLabel":"Effect","target":"One or more conjured ice creatures, no two of which can be more than 30 ft. apart","description":"This spell functions like conjure ice beast I, except that you can conjure one creature from the 9th-level list, two creatures of the same kind from the 8th-level list, or four creatures of the same kind from a lower-level list."}'::jsonb),
('dnd35.frostburn.spell.frostburn-conjure-ice-object','Conjure Ice Object','Conjure Ice Object','You conjure into being a block of transparent ice in the shape of any object you have seen at least once before, up to the weight limit (to a maximum of 50 pounds at 10th level). Any object with moving parts does not function (for example, a crossbow). You must succeed on an appropriate Craft check to make a complex item.',2,false,false,ARRAY['cleric','druid']::text[],'1 standard action','Personal','One object of up to 5 lb./level','1 min./level','None (harmless)',ARRAY['Conjuration','Cold']::text[],'v35-frostburn','D&D 3.5 — Frostburn',88,'dnd35','{"id":"frostburn-conjure-ice-object","name":"Conjure Ice Object","school":"Conjuration","subschool":"Creation","descriptors":["Cold"],"schoolLine":"Conjuration (Creation) [Cold]","levels":{"cleric":2,"druid":2},"levelLine":"Cleric 2, druid 2","components":"V, S, DF","castingTime":"1 standard action","range":"Personal","duration":"1 min./level","savingThrow":"None (harmless)","spellResistance":"No","targetLabel":"Effect","target":"One object of up to 5 lb./level","description":"You conjure into being a block of transparent ice in the shape of any object you have seen at least once before, up to the weight limit (to a maximum of 50 pounds at 10th level). Any object with moving parts does not function (for example, a crossbow). You must succeed on an appropriate Craft check to make a complex item."}'::jsonb),
('dnd35.frostburn.spell.frostburn-control-snow-and-ice','Control Snow and Ice','Control Snow and Ice','Depending on the version you choose, the control snow and ice spell raises or lowers ice or snow. Lower Snow and Ice: This causes snow and ice to sink away to a minimum depth of 1 inch. The depth can be lowered by up to 2 feet per caster level. The snow and ice is lowered within a squarish depression whose sides are up to 10 feet long per caster level. In extremely large and deep snow and ice fields, such as a glacier, the spell creates a crevasse that sweeps creatures downward (without dealing damage), rendering them unable to leave by normal movement for the duration of the spell. They can climb out of a crevasse, as normal with a DC 18 Climb check. When cast on ice elementals and other ice-based creatures, this spell acts as a slow spell. The spell has no effect on other creatures. Raise Snow and Ice: This causes snow and ice to rise in height, just as the lower snow and ice version causes it to lower. Creatures and objects on top of the snow or ice are raised along with the top level of snow. For either version, the character may reduce one horizontal dimension by half and double the other horizontal dimension.',3,false,false,ARRAY['cleric']::text[],'1 standard action','Long (400 ft. + 40 ft./level)','Ice and snow in a volume of 10 ft./level by 10 ft./level by 2 ft./level (S)','10 min./level (D)','None',ARRAY['Transmutation']::text[],'v35-frostburn','D&D 3.5 — Frostburn',88,'dnd35','{"id":"frostburn-control-snow-and-ice","name":"Control Snow and Ice","school":"Transmutation","subschool":null,"descriptors":[],"schoolLine":"Transmutation","levels":{"cleric":3},"levelLine":"Cleric 3","components":"V, S, DF","castingTime":"1 standard action","range":"Long (400 ft. + 40 ft./level)","duration":"10 min./level (D)","savingThrow":"None","spellResistance":"No","targetLabel":"Area","target":"Ice and snow in a volume of 10 ft./level by 10 ft./level by 2 ft./level (S)","description":"Depending on the version you choose, the control snow and ice spell raises or lowers ice or snow. Lower Snow and Ice: This causes snow and ice to sink away to a minimum depth of 1 inch. The depth can be lowered by up to 2 feet per caster level. The snow and ice is lowered within a squarish depression whose sides are up to 10 feet long per caster level. In extremely large and deep snow and ice fields, such as a glacier, the spell creates a crevasse that sweeps creatures downward (without dealing damage), rendering them unable to leave by normal movement for the duration of the spell. They can climb out of a crevasse, as normal with a DC 18 Climb check. When cast on ice elementals and other ice-based creatures, this spell acts as a slow spell. The spell has no effect on other creatures. Raise Snow and Ice: This causes snow and ice to rise in height, just as the lower snow and ice version causes it to lower. Creatures and objects on top of the snow or ice are raised along with the top level of snow. For either version, the character may reduce one horizontal dimension by half and double the other horizontal dimension."}'::jsonb),
('dnd35.frostburn.spell.frostburn-control-temperature','Control Temperature','Control Temperature','You imbue an area with cold or fire energy, reducing or raising the temperature by one temperature band per five caster levels. Effects of the new temperature on creatures and the environment are incurred immediately (see Cold Dangers, page 8 of this book, and Heat Dangers, page 303 of the Dungeon Master’s Guide). Arcane Material Component: A drop of mercury.',3,false,false,ARRAY['druid','sorcerer/wizard']::text[],'1 round','20 ft./level','20 cu. ft./level emanation, centered on you','1 hour/level','None',ARRAY['Transmutation','Cold','Fire']::text[],'v35-frostburn','D&D 3.5 — Frostburn',88,'dnd35','{"id":"frostburn-control-temperature","name":"Control Temperature","school":"Transmutation","subschool":null,"descriptors":["Cold","Fire"],"schoolLine":"Transmutation [Cold, Fire]","levels":{"druid":3,"sorcerer/wizard":3},"levelLine":"Druid 3, sorcerer/wizard 3","components":"V, S, M/DF","castingTime":"1 round","range":"20 ft./level","duration":"1 hour/level","savingThrow":"None","spellResistance":"No","targetLabel":"Area","target":"20 cu. ft./level emanation, centered on you","description":"You imbue an area with cold or fire energy, reducing or raising the temperature by one temperature band per five caster levels. Effects of the new temperature on creatures and the environment are incurred immediately (see Cold Dangers, page 8 of this book, and Heat Dangers, page 303 of the Dungeon Master’s Guide). Arcane Material Component: A drop of mercury."}'::jsonb),
('dnd35.frostburn.spell.frostburn-crack-ice','Crack Ice','Crack Ice','You create a sudden explosive burst that shatters ice bridges, breaks up river ice, opens frozen ponds, or damages an icy creature. The ice broken covers a 10-foot radius per caster level, and a 1-foot depth per level. Ice thicker than the spell’s depth is cracked and weakened, but not broken all the way through. Weakened ice is treated as one category thinner than it really is (see Table 1–2, page 11). Creatures dropped from a bridge, through lake or river ice, or off a glacier or iceberg take normal falling and cold water damage. Creatures on a glacier will have a crevasse open under them equal to the depth of the spell. Targeted against an ice creature of any weight (such as an ice golem, winterspawn, or entombed), crack ice deals 1d6 points of damage per caster level (maximum 10d6), with a Fortitude save for half damage.
 Material Component: A hammer carved from salt crystal (50 gp).',3,false,false,ARRAY['sorcerer/wizard']::text[],'1 standard action','Close (25 ft. + 5 ft./2 levels)','10-ft.-radius/level spread; or one ice creature','Instantaneous','Fortitude half (see text)',ARRAY['Evocation','Force']::text[],'v35-frostburn','D&D 3.5 — Frostburn',88,'dnd35','{"id":"frostburn-crack-ice","name":"Crack Ice","school":"Evocation","subschool":null,"descriptors":["Force"],"schoolLine":"Evocation [Force]","levels":{"sorcerer/wizard":3},"levelLine":"Sorcerer/wizard 3","components":"V, S, M","castingTime":"1 standard action","range":"Close (25 ft. + 5 ft./2 levels)","duration":"Instantaneous","savingThrow":"Fortitude half (see text)","spellResistance":"Yes (creature only)","targetLabel":"Area or Target","target":"10-ft.-radius/level spread; or one ice creature","description":"You create a sudden explosive burst that shatters ice bridges, breaks up river ice, opens frozen ponds, or damages an icy creature. The ice broken covers a 10-foot radius per caster level, and a 1-foot depth per level. Ice thicker than the spell’s depth is cracked and weakened, but not broken all the way through. Weakened ice is treated as one category thinner than it really is (see Table 1–2, page 11). Creatures dropped from a bridge, through lake or river ice, or off a glacier or iceberg take normal falling and cold water damage. Creatures on a glacier will have a crevasse open under them equal to the depth of the spell. Targeted against an ice creature of any weight (such as an ice golem, winterspawn, or entombed), crack ice deals 1d6 points of damage per caster level (maximum 10d6), with a Fortitude save for half damage.\n Material Component: A hammer carved from salt crystal (50 gp)."}'::jsonb),
('dnd35.frostburn.spell.frostburn-crunchy-snow','Crunchy Snow','Crunchy Snow','An area of fallen snow designated by you becomes hard and crumbly, generating a loud crunch when stepped upon. Creatures take a –20 penalty on Move Silently checks when traveling through crunchy snow.',1,false,false,ARRAY['druid','ranger']::text[],'1 standard action','Medium (100 ft. + 10 ft./level)','One 20-ft.-by-20-ft. square of snow/level','1 hour/level','None',ARRAY['Transmutation','Cold']::text[],'v35-frostburn','D&D 3.5 — Frostburn',88,'dnd35','{"id":"frostburn-crunchy-snow","name":"Crunchy Snow","school":"Transmutation","subschool":null,"descriptors":["Cold"],"schoolLine":"Transmutation [Cold]","levels":{"druid":1,"ranger":1},"levelLine":"Druid 1, ranger 1","components":"V, S, Frostfell","castingTime":"1 standard action","range":"Medium (100 ft. + 10 ft./level)","duration":"1 hour/level","savingThrow":"None","spellResistance":"No","targetLabel":"Area","target":"One 20-ft.-by-20-ft. square of snow/level","description":"An area of fallen snow designated by you becomes hard and crumbly, generating a loud crunch when stepped upon. Creatures take a –20 penalty on Move Silently checks when traveling through crunchy snow."}'::jsonb),
('dnd35.frostburn.spell.frostburn-death-hail','Death Hail','Death Hail','You call into being an intense storm of death hail in the area you designate. Creatures in the area must succeed on a Fortitude save or take 1d2 points of Strength and Constitution damage.',6,false,false,ARRAY['druid','winter']::text[],'1 round','Medium (100 ft. + 10 ft./level)','Cylinder (40-ft radius, 20 ft. high)','1 round/level','Fortitude half',ARRAY['Conjuration','Cold','Death']::text[],'v35-frostburn','D&D 3.5 — Frostburn',88,'dnd35','{"id":"frostburn-death-hail","name":"Death Hail","school":"Conjuration","subschool":"Creation","descriptors":["Cold","Death"],"schoolLine":"Conjuration (Creation) [Cold, Death]","levels":{"druid":6,"winter":6},"levelLine":"Druid 6, Winter 6","components":"V, S, DF","castingTime":"1 round","range":"Medium (100 ft. + 10 ft./level)","duration":"1 round/level","savingThrow":"Fortitude half","spellResistance":"No","targetLabel":"Area","target":"Cylinder (40-ft radius, 20 ft. high)","description":"You call into being an intense storm of death hail in the area you designate. Creatures in the area must succeed on a Fortitude save or take 1d2 points of Strength and Constitution damage."}'::jsonb),
('dnd35.frostburn.spell.frostburn-defile-snow-and-ice','Defile Snow and Ice','Defile Snow and Ice','You imbue an area of ice or fallen snow with negative energy, granting all undead within the area a +4 profane bonus against turning attempts. In addition, all cold creatures gain spell resistance 15 against fire effects.',3,false,false,ARRAY['cleric']::text[],'1 standard action','Medium (100 ft. + 10 ft./ level)','10 ft./level radius spread','1 min./level','None',ARRAY['Evocation','Cold','Evil']::text[],'v35-frostburn','D&D 3.5 — Frostburn',88,'dnd35','{"id":"frostburn-defile-snow-and-ice","name":"Defile Snow and Ice","school":"Evocation","subschool":null,"descriptors":["Cold","Evil"],"schoolLine":"Evocation [Cold, Evil]","levels":{"cleric":3},"levelLine":"Cleric 3","components":"V, S","castingTime":"1 standard action","range":"Medium (100 ft. + 10 ft./ level)","duration":"1 min./level","savingThrow":"None","spellResistance":"Yes","targetLabel":"Area","target":"10 ft./level radius spread","description":"You imbue an area of ice or fallen snow with negative energy, granting all undead within the area a +4 profane bonus against turning attempts. In addition, all cold creatures gain spell resistance 15 against fire effects."}'::jsonb),
('dnd35.frostburn.spell.frostburn-detect-fire','Detect Fire','Detect Fire','This spell functions like detect evil (see page 218 of the Player’s Handbook), except that it detects heat energy from normal fire, fire spells, fire magic items, clerics of fire deities, and all living beings other than those with the cold subtype. You are vulnerable to an overwhelming heat aura if you have the cold subtype. Living beings without the fire subtype are detected with a heat aura strength of faint only, regardless of level or Hit Dice.',1,false,false,ARRAY['cleric']::text[],null,null,null,null,null,ARRAY['Divination','Cold']::text[],'v35-frostburn','D&D 3.5 — Frostburn',88,'dnd35','{"id":"frostburn-detect-fire","name":"Detect Fire","school":"Divination","subschool":null,"descriptors":["Cold"],"schoolLine":"Divination [Cold]","levels":{"cleric":1},"levelLine":"Cleric 1","description":"This spell functions like detect evil (see page 218 of the Player’s Handbook), except that it detects heat energy from normal fire, fire spells, fire magic items, clerics of fire deities, and all living beings other than those with the cold subtype. You are vulnerable to an overwhelming heat aura if you have the cold subtype. Living beings without the fire subtype are detected with a heat aura strength of faint only, regardless of level or Hit Dice."}'::jsonb),
('dnd35.frostburn.spell.frostburn-dispel-cold','Dispel Cold','Dispel Cold','This spell functions like dispel evil (see page 222 of the Player’s Handbook), except that you are surrounded by constant, blue-white cold energy, and the spell affects cold creatures and spells rather than evil ones.',5,false,false,ARRAY['cleric']::text[],null,null,null,null,null,ARRAY['Abjuration','Fire']::text[],'v35-frostburn','D&D 3.5 — Frostburn',88,'dnd35','{"id":"frostburn-dispel-cold","name":"Dispel Cold","school":"Abjuration","subschool":null,"descriptors":["Fire"],"schoolLine":"Abjuration [Fire]","levels":{"cleric":5},"levelLine":"Cleric 5","description":"This spell functions like dispel evil (see page 222 of the Player’s Handbook), except that you are surrounded by constant, blue-white cold energy, and the spell affects cold creatures and spells rather than evil ones."}'::jsonb),
('dnd35.frostburn.spell.frostburn-dispel-fire','Dispel Fire','Dispel Fire','This spell functions like dispel evil (see page 222 of the Player’s Handbook), except that you are surrounded by constant red, orange, and yellow flames, and the spell affects fire creatures and spells rather than evil ones.',5,false,false,ARRAY['cleric']::text[],null,null,null,null,null,ARRAY['Abjuration','Cold']::text[],'v35-frostburn','D&D 3.5 — Frostburn',88,'dnd35','{"id":"frostburn-dispel-fire","name":"Dispel Fire","school":"Abjuration","subschool":null,"descriptors":["Cold"],"schoolLine":"Abjuration [Cold]","levels":{"cleric":5},"levelLine":"Cleric 5","description":"This spell functions like dispel evil (see page 222 of the Player’s Handbook), except that you are surrounded by constant red, orange, and yellow flames, and the spell affects fire creatures and spells rather than evil ones."}'::jsonb),
('dnd35.frostburn.spell.frostburn-ease-of-breath','Ease of Breath','Ease of Breath','You grant the target the ability to survive in thin air, conferring a +20 inherent bonus on Fortitude saves to resist altitude sickness as well as saving throws to resist becoming fatigued due to altitude or thin air.',1,false,false,ARRAY['cleric','druid','ranger']::text[],'1 standard action','Touch','Creature touched','1 hour/level','None',ARRAY['Necromancy','Cold']::text[],'v35-frostburn','D&D 3.5 — Frostburn',88,'dnd35','{"id":"frostburn-ease-of-breath","name":"Ease of Breath","school":"Necromancy","subschool":null,"descriptors":["Cold"],"schoolLine":"Necromancy [Cold]","levels":{"cleric":1,"druid":1,"ranger":1},"levelLine":"Cleric 1, druid 1, ranger 1","components":"V, S, DF","castingTime":"1 standard action","range":"Touch","duration":"1 hour/level","savingThrow":"None","spellResistance":"No","targetLabel":"Target","target":"Creature touched","description":"You grant the target the ability to survive in thin air, conferring a +20 inherent bonus on Fortitude saves to resist altitude sickness as well as saving throws to resist becoming fatigued due to altitude or thin air."}'::jsonb),
('dnd35.frostburn.spell.frostburn-entomb','Entomb','Entomb','An entomb spell traps living creatures in a block of ice, suffocating them. The spell entraps the targets with a thick layer of ice from head to toe. Those that make a successful Fortitude saving throw can shake off the ice immediately, though they still take 6d6 points of cold damage. If the creature fails its saving throw, it is held within the ice and immediately begins to suffocate per the drowning rules (see page 304 of the Dungeon Master’s Guide). In addition, the creature takes 2d12 points of cold damage and 1 point of Constitution damage per round from contact with the ice. Other than attempting to escape, creatures entombed can perform actions that only require mental or verbal activity. Escaping from the ice block requires a DC 20 Strength check or the application of 20 points of fire damage.
 Material Component: A clear gemstone with a minimum value of 500 gp.',6,false,false,ARRAY['druid','sorcerer/wizard']::text[],'1 standard action','Medium (100 ft. + 10 ft./level)','One creature/level, no two of which can be more than 30 ft. apart','Instantaneous and 1 round/ level; see text','Fortitude negates',ARRAY['Evocation','Cold']::text[],'v35-frostburn','D&D 3.5 — Frostburn',88,'dnd35','{"id":"frostburn-entomb","name":"Entomb","school":"Evocation","subschool":null,"descriptors":["Cold"],"schoolLine":"Evocation [Cold]","levels":{"druid":6,"sorcerer/wizard":6},"levelLine":"Druid 6, sorcerer/wizard 6","components":"V, S, M","castingTime":"1 standard action","range":"Medium (100 ft. + 10 ft./level)","duration":"Instantaneous and 1 round/ level; see text","savingThrow":"Fortitude negates","spellResistance":"Yes","targetLabel":"Area","target":"One creature/level, no two of which can be more than 30 ft. apart","description":"An entomb spell traps living creatures in a block of ice, suffocating them. The spell entraps the targets with a thick layer of ice from head to toe. Those that make a successful Fortitude saving throw can shake off the ice immediately, though they still take 6d6 points of cold damage. If the creature fails its saving throw, it is held within the ice and immediately begins to suffocate per the drowning rules (see page 304 of the Dungeon Master’s Guide). In addition, the creature takes 2d12 points of cold damage and 1 point of Constitution damage per round from contact with the ice. Other than attempting to escape, creatures entombed can perform actions that only require mental or verbal activity. Escaping from the ice block requires a DC 20 Strength check or the application of 20 points of fire damage.\n Material Component: A clear gemstone with a minimum value of 500 gp."}'::jsonb),
('dnd35.frostburn.spell.frostburn-evergreen','Evergreen','Evergreen','You imbue a 10-foot-radius area of plant life with magical heat, instantly healing 1d8 points of damage +1 point per caster level (maximum +10), and granting immunity to cold for the duration of the spell. Evergreen affects natural plants as well as creatures with the plant subtype.',2,false,false,ARRAY['druid']::text[],'1 standard action','Medium (100 ft. + 10 ft./level)','10-ft. radius','1 hour/level and instantaneous; see text','None',ARRAY['Transmutation','Fire']::text[],'v35-frostburn','D&D 3.5 — Frostburn',88,'dnd35','{"id":"frostburn-evergreen","name":"Evergreen","school":"Transmutation","subschool":null,"descriptors":["Fire"],"schoolLine":"Transmutation [Fire]","levels":{"druid":2},"levelLine":"Druid 2","components":"V, S, DF","castingTime":"1 standard action","range":"Medium (100 ft. + 10 ft./level)","duration":"1 hour/level and instantaneous; see text","savingThrow":"None","spellResistance":"No","targetLabel":"Area","target":"10-ft. radius","description":"You imbue a 10-foot-radius area of plant life with magical heat, instantly healing 1d8 points of damage +1 point per caster level (maximum +10), and granting immunity to cold for the duration of the spell. Evergreen affects natural plants as well as creatures with the plant subtype."}'::jsonb),
('dnd35.frostburn.spell.frostburn-fimbulwinter','Fimbulwinter','Fimbulwinter','You change the weather to a state of permanent winter, or strengthen winter conditions already present. It takes 10 minutes to cast the spell and an additional 10 minutes for the effects to manifest themselves. The current, natural weather conditions are determined by the DM. You then choose what wintry conditions you want to manifest; the strength of the winter depends on the existing climate and season of the area. Season Possible Weather Spring Frequent snowfall, nightly frost Summer Light snow, hailstorms, cold rain, cloudy Autumn Frequent snowfall, frost Winter Frigid cold, blizzard, and constant snowfall Daily wind and snowfall during a fimbulwinter are determined using the table below. Add +8 to the roll when cast during winter, +4 in spring or autumn, –2 in summer, +2 for a cold climate, –2 for temperate climate, and –6 for hot climate. Roll separately for wind and snow. The snow and wind shown are the maximum possible for the day; at your option, there can be less wind or snow. Fimbulwinter d20 Roll Amount of Snowfall Amount of Wind 0 or less 1d12 inches of snowfall melt Weak (0–10 mph) 1–5 No new snow Weak (0–10 mph) 6–10 1d4–1 inches snow Moderate (11+ mph) 11–15 1d8 inches snow or 1 inch hail Moderate (11+ mph) 16–20 1d12 inches snow Strong (21+ mph) 21–25 2d12+4 inches snow Strong (21+ mph) 26+ 1d6+1 feet of snow Very strong (31+ mph) You control the general tendencies of the weather, such as the direction and intensity of the wind. When you select a certain weather condition to occur, the weather assumes that condition 10 minutes later (changing gradually, not abruptly). The weather continues as you left it for the duration, or until you use a standard action to designate a new kind of weather (which fully manifests itself 10 minutes later). XP Cost: 100 XP.',8,false,false,ARRAY['cleric','druid','sorcerer/wizard','winter']::text[],'10 minutes (see text)','1 mile/level','1 mile/level radius, centered on you','4d12 weeks','None',ARRAY['Transmutation','Cold']::text[],'v35-frostburn','D&D 3.5 — Frostburn',88,'dnd35','{"id":"frostburn-fimbulwinter","name":"Fimbulwinter","school":"Transmutation","subschool":null,"descriptors":["Cold"],"schoolLine":"Transmutation [Cold]","levels":{"cleric":9,"druid":8,"sorcerer/wizard":8,"winter":9},"levelLine":"Cleric 9, druid 8, sorcerer/ wizard 8, Winter 9","components":"V, S, XP","castingTime":"10 minutes (see text)","range":"1 mile/level","duration":"4d12 weeks","savingThrow":"None","spellResistance":"No","targetLabel":"Area","target":"1 mile/level radius, centered on you","description":"You change the weather to a state of permanent winter, or strengthen winter conditions already present. It takes 10 minutes to cast the spell and an additional 10 minutes for the effects to manifest themselves. The current, natural weather conditions are determined by the DM. You then choose what wintry conditions you want to manifest; the strength of the winter depends on the existing climate and season of the area. Season Possible Weather Spring Frequent snowfall, nightly frost Summer Light snow, hailstorms, cold rain, cloudy Autumn Frequent snowfall, frost Winter Frigid cold, blizzard, and constant snowfall Daily wind and snowfall during a fimbulwinter are determined using the table below. Add +8 to the roll when cast during winter, +4 in spring or autumn, –2 in summer, +2 for a cold climate, –2 for temperate climate, and –6 for hot climate. Roll separately for wind and snow. The snow and wind shown are the maximum possible for the day; at your option, there can be less wind or snow. Fimbulwinter d20 Roll Amount of Snowfall Amount of Wind 0 or less 1d12 inches of snowfall melt Weak (0–10 mph) 1–5 No new snow Weak (0–10 mph) 6–10 1d4–1 inches snow Moderate (11+ mph) 11–15 1d8 inches snow or 1 inch hail Moderate (11+ mph) 16–20 1d12 inches snow Strong (21+ mph) 21–25 2d12+4 inches snow Strong (21+ mph) 26+ 1d6+1 feet of snow Very strong (31+ mph) You control the general tendencies of the weather, such as the direction and intensity of the wind. When you select a certain weather condition to occur, the weather assumes that condition 10 minutes later (changing gradually, not abruptly). The weather continues as you left it for the duration, or until you use a standard action to designate a new kind of weather (which fully manifests itself 10 minutes later). XP Cost: 100 XP."}'::jsonb),
('dnd35.frostburn.spell.frostburn-flash-freeze','Flash-Freeze','Flash-Freeze','All earth, stone, and water in the spell’s area is drained of heat. Earth, mud, and stone become everfrost and water freezes. You affect a 10-foot-square area to a depth of 1 foot. Magical, enchanted, dressed, or worked stone cannot be affected. Earth, stone, or water creatures are not affected. This spell can be used to create small icebergs in large bodies of water. These icebergs float, but are extremely slippery and unstable, requiring a DC 15 Balance check per round to stay on the iceberg. Icebergs may be propelled through the water by the current, paddling, or other means.',2,false,false,ARRAY['druid']::text[],'1 standard action','Close (25 ft. + 5 ft./2 levels)','10-ft. square/level','Instantaneous','None',ARRAY['Transmutation','Earth','Cold']::text[],'v35-frostburn','D&D 3.5 — Frostburn',88,'dnd35','{"id":"frostburn-flash-freeze","name":"Flash-Freeze","school":"Transmutation","subschool":null,"descriptors":["Earth","Cold"],"schoolLine":"Transmutation [Earth, Cold]","levels":{"druid":2},"levelLine":"Druid 2","components":"V, S, DF","castingTime":"1 standard action","range":"Close (25 ft. + 5 ft./2 levels)","duration":"Instantaneous","savingThrow":"None","spellResistance":"No","targetLabel":"Area","target":"10-ft. square/level","description":"All earth, stone, and water in the spell’s area is drained of heat. Earth, mud, and stone become everfrost and water freezes. You affect a 10-foot-square area to a depth of 1 foot. Magical, enchanted, dressed, or worked stone cannot be affected. Earth, stone, or water creatures are not affected. This spell can be used to create small icebergs in large bodies of water. These icebergs float, but are extremely slippery and unstable, requiring a DC 15 Balance check per round to stay on the iceberg. Icebergs may be propelled through the water by the current, paddling, or other means."}'::jsonb),
('dnd35.frostburn.spell.frostburn-flesh-to-ice','Flesh to Ice','Flesh to Ice','The subject, along with all its carried gear, turns into a mindless, inert ice sculpture. If the sculpture resulting from this spell is broken, melted, or damaged, the subject (if ever returned to its original state) has similar damage or deformities. The creature is not dead, but it does not seem to be alive either when viewed with spells such as deathwatch. Only creatures made of flesh are affected by this spell.
 Material Component: Water and a drop of blood.',5,false,false,ARRAY['sorcerer/wizard']::text[],'1 standard action','Medium (100 ft. + 10 ft./level)','One creature','Instantaneous','Fortitude negates',ARRAY['Transmutation']::text[],'v35-frostburn','D&D 3.5 — Frostburn',88,'dnd35','{"id":"frostburn-flesh-to-ice","name":"Flesh to Ice","school":"Transmutation","subschool":null,"descriptors":[],"schoolLine":"Transmutation","levels":{"sorcerer/wizard":5},"levelLine":"Sorcerer/wizard 5","components":"V, S, M","castingTime":"1 standard action","range":"Medium (100 ft. + 10 ft./level)","duration":"Instantaneous","savingThrow":"Fortitude negates","spellResistance":"Yes","targetLabel":"Target","target":"One creature","description":"The subject, along with all its carried gear, turns into a mindless, inert ice sculpture. If the sculpture resulting from this spell is broken, melted, or damaged, the subject (if ever returned to its original state) has similar damage or deformities. The creature is not dead, but it does not seem to be alive either when viewed with spells such as deathwatch. Only creatures made of flesh are affected by this spell.\n Material Component: Water and a drop of blood."}'::jsonb),
('dnd35.frostburn.spell.frostburn-float','Float','Float','The target gains buoyancy and can float on water for the duration of the spell. It cannot swim below the surface of the water. Creatures that must breathe water can still do so, but cannot swim under the surface. If the target is underwater at the time this spell is cast, it rises toward the surface at a speed of 30 feet.
 Material Component: An ice cube dropped into water.',1,false,false,ARRAY['sorcerer/wizard']::text[],'1 standard action','Long (400 ft. + 40 ft./level)','One Large or smaller creature or object','1 min./level','Fortitude negates',ARRAY['Transmutation']::text[],'v35-frostburn','D&D 3.5 — Frostburn',88,'dnd35','{"id":"frostburn-float","name":"Float","school":"Transmutation","subschool":null,"descriptors":[],"schoolLine":"Transmutation","levels":{"sorcerer/wizard":1},"levelLine":"Sorcerer/wizard 1","components":"V, S, M","castingTime":"1 standard action","range":"Long (400 ft. + 40 ft./level)","duration":"1 min./level","savingThrow":"Fortitude negates","spellResistance":"Yes","targetLabel":"Target","target":"One Large or smaller creature or object","description":"The target gains buoyancy and can float on water for the duration of the spell. It cannot swim below the surface of the water. Creatures that must breathe water can still do so, but cannot swim under the surface. If the target is underwater at the time this spell is cast, it rises toward the surface at a speed of 30 feet.\n Material Component: An ice cube dropped into water."}'::jsonb),
('dnd35.frostburn.spell.frostburn-fortify-cold-creatures','Fortify Cold Creatures','Fortify Cold Creatures','Creatures with the cold subtype gain a +1 sacred bonus on all attack rolls and on saving throws against fire effects.',1,false,false,ARRAY['cleric']::text[],'1 standard action','Close (25 ft. + 5 ft./2 levels)','One creature/level, no two of which can be more than 30 ft. apart','1 round/level','None',ARRAY['Transmutation','Cold']::text[],'v35-frostburn','D&D 3.5 — Frostburn',88,'dnd35','{"id":"frostburn-fortify-cold-creatures","name":"Fortify Cold Creatures","school":"Transmutation","subschool":null,"descriptors":["Cold"],"schoolLine":"Transmutation [Cold]","levels":{"cleric":1},"levelLine":"Cleric 1","components":"V, S, DF","castingTime":"1 standard action","range":"Close (25 ft. + 5 ft./2 levels)","duration":"1 round/level","savingThrow":"None","spellResistance":"No","targetLabel":"Area","target":"One creature/level, no two of which can be more than 30 ft. apart","description":"Creatures with the cold subtype gain a +1 sacred bonus on all attack rolls and on saving throws against fire effects."}'::jsonb),
('dnd35.frostburn.spell.frostburn-freeze-armor','Freeze Armor','Freeze Armor','Freeze armor locks suits of metal armor and equipment into a layer of ice and extreme cold, immobilizing and damaging the armor’s wearers. Unattended, nonmagical metal gets no saving throw. Enchanted metal is allowed a saving throw against the spell. An item in a creature’s possession uses the creature’s saving throw (unless its own is higher). A creature wearing metal armor that fails its save is frozen in place. The spell locks the armor’s joints and seams in inches of solid ice. The frozen creature takes the damage listed below. In addition, it suffers a –6 penalty on attack rolls, a –8 penalty to effective Dexterity, and can’t move. A frozen character who attempts to cast a spell must make a Concentration check (DC 15 + level of spell being cast) or lose the spell. A creature wearing metal armor that makes its save takes half the damage listed below. A creature not wearing metal armor that fails its save takes the damage listed below if its armor is affected or if it is holding, touching, wearing, or carrying metal weighing one-fifth of its weight. The creature takes minimum damage (1, 2, 3, or 4 points; see the table) each round if it is not wearing metal armor or the metal that it is carrying weighs less than one-fifth of the creature’s weight. A creature not wearing or carrying metal less than one-fifth of its weight that makes its save is entirely unaffected by freeze armor. Freeze Armor Damage Round Temperature Cold Damage 1 Cold 1d6 points 2 Icy 2d6 points 3–5 Freezing 3d6 points 6+ Lethal 4d6 points Any heat intense enough to damage the creature negates cold damage from the spell (and vice versa) on a point-for-point basis. For example, if the damage from a freeze armor spell indicates 5 points of cold damage and the creature plunges through a wall of fire in the same round and takes 8 points of fire damage, it winds up taking no cold damage and only 3 points of fire damage.',4,false,false,ARRAY['cleric','druid']::text[],'1 standard action','Close (25 ft. + 5 ft./2 levels)','Metal equipment of one creature/level','1 round/level','Fortitude partial; see text',ARRAY['Transmutation','Cold']::text[],'v35-frostburn','D&D 3.5 — Frostburn',88,'dnd35','{"id":"frostburn-freeze-armor","name":"Freeze Armor","school":"Transmutation","subschool":null,"descriptors":["Cold"],"schoolLine":"Transmutation [Cold]","levels":{"cleric":4,"druid":4},"levelLine":"Cleric 4, druid 4","components":"V, S","castingTime":"1 standard action","range":"Close (25 ft. + 5 ft./2 levels)","duration":"1 round/level","savingThrow":"Fortitude partial; see text","spellResistance":"Yes","targetLabel":"Target","target":"Metal equipment of one creature/level","description":"Freeze armor locks suits of metal armor and equipment into a layer of ice and extreme cold, immobilizing and damaging the armor’s wearers. Unattended, nonmagical metal gets no saving throw. Enchanted metal is allowed a saving throw against the spell. An item in a creature’s possession uses the creature’s saving throw (unless its own is higher). A creature wearing metal armor that fails its save is frozen in place. The spell locks the armor’s joints and seams in inches of solid ice. The frozen creature takes the damage listed below. In addition, it suffers a –6 penalty on attack rolls, a –8 penalty to effective Dexterity, and can’t move. A frozen character who attempts to cast a spell must make a Concentration check (DC 15 + level of spell being cast) or lose the spell. A creature wearing metal armor that makes its save takes half the damage listed below. A creature not wearing metal armor that fails its save takes the damage listed below if its armor is affected or if it is holding, touching, wearing, or carrying metal weighing one-fifth of its weight. The creature takes minimum damage (1, 2, 3, or 4 points; see the table) each round if it is not wearing metal armor or the metal that it is carrying weighs less than one-fifth of the creature’s weight. A creature not wearing or carrying metal less than one-fifth of its weight that makes its save is entirely unaffected by freeze armor. Freeze Armor Damage Round Temperature Cold Damage 1 Cold 1d6 points 2 Icy 2d6 points 3–5 Freezing 3d6 points 6+ Lethal 4d6 points Any heat intense enough to damage the creature negates cold damage from the spell (and vice versa) on a point-for-point basis. For example, if the damage from a freeze armor spell indicates 5 points of cold damage and the creature plunges through a wall of fire in the same round and takes 8 points of fire damage, it winds up taking no cold damage and only 3 points of fire damage."}'::jsonb),
('dnd35.frostburn.spell.frostburn-freezing-glance','Freezing Glance','Freezing Glance','Your eyes become wintry tombs that destroy the spark of life in those who you meet your stare. Each round you may target a single living creature. It must make a Will saving throw or be frozen in place. Frozen creatures cannot move, attack, cast spells, or defend themselves; they are considered immobile, losing shield and Dexterity bonuses to Armor Class and taking a further –4 penalty to Armor Class. Frozen creatures are entitled to an additional saving throw if attacked, but this provides no immunity to the gaze. A creature that has been immobilizing with a freezing glance, then restored to motion after an attack, can still be the target of the same freezing glance in a later round. Though the gaze attack ends rather quickly, frozen creatures remain immobile for 1 minute per level. In some cases, this can cause serious damage through exposure to the elements.',6,false,false,ARRAY['sorcerer/wizard']::text[],'1 standard action','Close (25 ft. + 5 ft./2 levels)','One living creature','1 round/level; see text','Will negates',ARRAY['Enchantment','Cold']::text[],'v35-frostburn','D&D 3.5 — Frostburn',88,'dnd35','{"id":"frostburn-freezing-glance","name":"Freezing Glance","school":"Enchantment","subschool":null,"descriptors":["Cold"],"schoolLine":"Enchantment [Cold]","levels":{"sorcerer/wizard":6},"levelLine":"Sorcerer/wizard 6","components":"V, S","castingTime":"1 standard action","range":"Close (25 ft. + 5 ft./2 levels)","duration":"1 round/level; see text","savingThrow":"Will negates","spellResistance":"Yes","targetLabel":"Target","target":"One living creature","description":"Your eyes become wintry tombs that destroy the spark of life in those who you meet your stare. Each round you may target a single living creature. It must make a Will saving throw or be frozen in place. Frozen creatures cannot move, attack, cast spells, or defend themselves; they are considered immobile, losing shield and Dexterity bonuses to Armor Class and taking a further –4 penalty to Armor Class. Frozen creatures are entitled to an additional saving throw if attacked, but this provides no immunity to the gaze. A creature that has been immobilizing with a freezing glance, then restored to motion after an attack, can still be the target of the same freezing glance in a later round. Though the gaze attack ends rather quickly, frozen creatures remain immobile for 1 minute per level. In some cases, this can cause serious damage through exposure to the elements."}'::jsonb),
('dnd35.frostburn.spell.frostburn-frost-weapon','Frost Weapon','Frost Weapon','You imbue a weapon with icy cold, granting it a power similar to the frost special ability. A frost weapon deals an extra 1d6 points of cold damage on a successful hit. If cast on a bow, crossbow, or sling, the spell bestows the cold energy upon the weapon’s ammunition. This ability stacks with the frost special ability, but not with itself.
 Material Component: A drop of water.',2,false,false,ARRAY['cleric','druid','sorcerer/wizard']::text[],'1 standard action','Touch','Weapon touched','1 round/level','Will negates (harmless, object)',ARRAY['Transmutation']::text[],'v35-frostburn','D&D 3.5 — Frostburn',88,'dnd35','{"id":"frostburn-frost-weapon","name":"Frost Weapon","school":"Transmutation","subschool":null,"descriptors":[],"schoolLine":"Transmutation","levels":{"cleric":2,"druid":2,"sorcerer/wizard":2},"levelLine":"Cleric 2, druid 2, sorcerer/ wizard 2","components":"V, S, M","castingTime":"1 standard action","range":"Touch","duration":"1 round/level","savingThrow":"Will negates (harmless, object)","spellResistance":"No","targetLabel":"Area","target":"Weapon touched","description":"You imbue a weapon with icy cold, granting it a power similar to the frost special ability. A frost weapon deals an extra 1d6 points of cold damage on a successful hit. If cast on a bow, crossbow, or sling, the spell bestows the cold energy upon the weapon’s ammunition. This ability stacks with the frost special ability, but not with itself.\n Material Component: A drop of water."}'::jsonb),
('dnd35.frostburn.spell.frostburn-frostbite','Frostbite','Frostbite','You chill the air and create a layer of frost on the skin of target creatures. The targets are entitled to a Fortitude save; those who fail take 6d6 points of cold damage and 2d6 points of Dexterity damage. Creatures dropping to 0 Dexterity are frozen in a layer of ice, shivering and unable to attack, move, or defend.',5,false,false,ARRAY['cleric']::text[],'1 standard action','Close (25 ft. + 5 ft./2 levels)','One creature/2 levels, no two of which can be more than 30 ft. apart','Instantaneous','Fortitude half',ARRAY['Conjuration','Cold']::text[],'v35-frostburn','D&D 3.5 — Frostburn',88,'dnd35','{"id":"frostburn-frostbite","name":"Frostbite","school":"Conjuration","subschool":"Creation","descriptors":["Cold"],"schoolLine":"Conjuration (Creation) [Cold]","levels":{"cleric":5},"levelLine":"Cleric 5","components":"V, S, DF","castingTime":"1 standard action","range":"Close (25 ft. + 5 ft./2 levels)","duration":"Instantaneous","savingThrow":"Fortitude half","spellResistance":"Yes","targetLabel":"Target","target":"One creature/2 levels, no two of which can be more than 30 ft. apart","description":"You chill the air and create a layer of frost on the skin of target creatures. The targets are entitled to a Fortitude save; those who fail take 6d6 points of cold damage and 2d6 points of Dexterity damage. Creatures dropping to 0 Dexterity are frozen in a layer of ice, shivering and unable to attack, move, or defend."}'::jsonb),
('dnd35.frostburn.spell.frostburn-frostburn','Frostburn','Frostburn','This spell functions like lesser frostburn, except that it deals 3d12 points of frostburn damage +1 point per caster level (maximum +20).',4,false,false,ARRAY['cleric']::text[],null,null,null,null,null,ARRAY['Necromancy','Cold']::text[],'v35-frostburn','D&D 3.5 — Frostburn',88,'dnd35','{"id":"frostburn-frostburn","name":"Frostburn","school":"Necromancy","subschool":null,"descriptors":["Cold"],"schoolLine":"Necromancy [Cold]","levels":{"cleric":4},"levelLine":"Cleric 4","description":"This spell functions like lesser frostburn, except that it deals 3d12 points of frostburn damage +1 point per caster level (maximum +20)."}'::jsonb),
('dnd35.frostburn.spell.frostburn-frostburn-lesser','Frostburn, Lesser','Frostburn, Lesser','When laying your hand upon a creature, you channel cold energy that deals 1d12 points of frostburn damage +1 point per caster level (maximum +5). When cast upon a cold subtype creature, this spell heals a like amount of damage, rather than harming it.',2,false,false,ARRAY['cleric']::text[],'1 standard action','Touch','Creature touched','Instantaneous','Fortitude half',ARRAY['Necromancy','Cold']::text[],'v35-frostburn','D&D 3.5 — Frostburn',88,'dnd35','{"id":"frostburn-frostburn-lesser","name":"Frostburn, Lesser","school":"Necromancy","subschool":null,"descriptors":["Cold"],"schoolLine":"Necromancy [Cold]","levels":{"cleric":2},"levelLine":"Cleric 2","components":"V, S, DF","castingTime":"1 standard action","range":"Touch","duration":"Instantaneous","savingThrow":"Fortitude half","spellResistance":"Yes","targetLabel":"Target","target":"Creature touched","description":"When laying your hand upon a creature, you channel cold energy that deals 1d12 points of frostburn damage +1 point per caster level (maximum +5). When cast upon a cold subtype creature, this spell heals a like amount of damage, rather than harming it."}'::jsonb),
('dnd35.frostburn.spell.frostburn-frostburn-mass','Frostburn, Mass','Frostburn, Mass','Cold energy spreads out in all directions from the point of origin, dealing 3d12 points of frostburn damage +1 point per caster level (maximum +20) to nearby enemies. Like other frostburn spells, mass frostburn cures cold subtype creatures in its area rather than damaging them.',6,false,false,ARRAY['cleric']::text[],'1 standard action','Close (25 ft. + 5 ft./2 levels)','One creature/level, no two of which can be more than 30 ft. apart','Instantaneous','Fortitude half',ARRAY['Necromancy','Cold']::text[],'v35-frostburn','D&D 3.5 — Frostburn',88,'dnd35','{"id":"frostburn-frostburn-mass","name":"Frostburn, Mass","school":"Necromancy","subschool":null,"descriptors":["Cold"],"schoolLine":"Necromancy [Cold]","levels":{"cleric":6},"levelLine":"Cleric 6","components":"V, S, DF","castingTime":"1 standard action","range":"Close (25 ft. + 5 ft./2 levels)","duration":"Instantaneous","savingThrow":"Fortitude half","spellResistance":"Yes","targetLabel":"Target","target":"One creature/level, no two of which can be more than 30 ft. apart","description":"Cold energy spreads out in all directions from the point of origin, dealing 3d12 points of frostburn damage +1 point per caster level (maximum +20) to nearby enemies. Like other frostburn spells, mass frostburn cures cold subtype creatures in its area rather than damaging them."}'::jsonb),
('dnd35.frostburn.spell.frostburn-frostfell','Frostfell','Frostfell','The area you designate becomes a frigid and icy environment, immediately dropping the temperature by 3 temperature bands. For example, if the temperature is moderate, it drops to extreme cold (see page 9). If the new temperature is below the cold band, all water is turned to ice and all earth and stone becomes everfrost to a depth of 10 feet per caster level. Air within the area freezes, resulting in a heavy snowstorm lasting for the duration of the spell. Snow accumulates only if the ground temperature is below the moderate band. Living creatures caught within the area when the spell is cast instantly turn to ice (as per the flesh to ice spell). If a creature successfully saves, frostfell deals 1d6 points of frostburn damage per caster level (maximum 20d6). Creatures entering the area after the spell has been cast do not take this damage; however, all creatures in the area are subject to the normal effects of cold, snow, and ice for the duration of the spell. Objects in the area, including those held by creatures, are instantly covered in a thin layer of frost, making them slippery. When a creature uses a frosted item (a weapon, lockpicks, a potion, and so on), it must succeed on a DC 10 Dexterity check or it drops the item before it can be used. Cold spells cast within the area gain a +1 caster level. Multiple frostfells may be cast in the same area to increase the effects (dropping the temperature by an additional 3 bands). The temperature band cannot be dropped below unearthly cold, no matter how many times frostfell has been cast. Arcane Material Component: A pinch of dust and a few drops of water.',8,false,false,ARRAY['druid','sorcerer/wizard']::text[],'1 round','Medium (100 ft. + 10 ft./level)','20-ft. cube/level','1 hour/level','Fortitude partial; see text',ARRAY['Transmutation','Cold']::text[],'v35-frostburn','D&D 3.5 — Frostburn',88,'dnd35','{"id":"frostburn-frostfell","name":"Frostfell","school":"Transmutation","subschool":null,"descriptors":["Cold"],"schoolLine":"Transmutation [Cold]","levels":{"druid":8,"sorcerer/wizard":9},"levelLine":"Druid 8, sorcerer/wizard 9","components":"V, S, M/DF","castingTime":"1 round","range":"Medium (100 ft. + 10 ft./level)","duration":"1 hour/level","savingThrow":"Fortitude partial; see text","spellResistance":"See text","targetLabel":"Area","target":"20-ft. cube/level","description":"The area you designate becomes a frigid and icy environment, immediately dropping the temperature by 3 temperature bands. For example, if the temperature is moderate, it drops to extreme cold (see page 9). If the new temperature is below the cold band, all water is turned to ice and all earth and stone becomes everfrost to a depth of 10 feet per caster level. Air within the area freezes, resulting in a heavy snowstorm lasting for the duration of the spell. Snow accumulates only if the ground temperature is below the moderate band. Living creatures caught within the area when the spell is cast instantly turn to ice (as per the flesh to ice spell). If a creature successfully saves, frostfell deals 1d6 points of frostburn damage per caster level (maximum 20d6). Creatures entering the area after the spell has been cast do not take this damage; however, all creatures in the area are subject to the normal effects of cold, snow, and ice for the duration of the spell. Objects in the area, including those held by creatures, are instantly covered in a thin layer of frost, making them slippery. When a creature uses a frosted item (a weapon, lockpicks, a potion, and so on), it must succeed on a DC 10 Dexterity check or it drops the item before it can be used. Cold spells cast within the area gain a +1 caster level. Multiple frostfells may be cast in the same area to increase the effects (dropping the temperature by an additional 3 bands). The temperature band cannot be dropped below unearthly cold, no matter how many times frostfell has been cast. Arcane Material Component: A pinch of dust and a few drops of water."}'::jsonb),
('dnd35.frostburn.spell.frostburn-frostfell-slide','Frostfell Slide','Frostfell Slide','You gain the ability to instantly teleport from one area of slush, snow, or ice to any other area of slush, snow, or ice up to the distance indicated on the table below. Transport distance is based upon the substance touched at the point of departure, not at the point of arrival. You may wait to travel in this manner up to the duration of the spell, holding the charge, but immediately upon arriving at the destination point, the spell ends. Type of Area Transport Distance Slush 1,000 feet Snow 2,000 feet Ice 3,000 feet',4,false,false,ARRAY['druid','ranger']::text[],'1 standard action','Personal','You','1 hour/level or until expended; see text',null,ARRAY['Conjuration','Cold']::text[],'v35-frostburn','D&D 3.5 — Frostburn',88,'dnd35','{"id":"frostburn-frostfell-slide","name":"Frostfell Slide","school":"Conjuration","subschool":"Teleportation","descriptors":["Cold"],"schoolLine":"Conjuration (Teleportation) [Cold]","levels":{"druid":4,"ranger":4},"levelLine":"Druid 4, ranger 4","components":"V, S, DF, Frostfell","castingTime":"1 standard action","range":"Personal","duration":"1 hour/level or until expended; see text","targetLabel":"Target","target":"You","description":"You gain the ability to instantly teleport from one area of slush, snow, or ice to any other area of slush, snow, or ice up to the distance indicated on the table below. Transport distance is based upon the substance touched at the point of departure, not at the point of arrival. You may wait to travel in this manner up to the duration of the spell, holding the charge, but immediately upon arriving at the destination point, the spell ends. Type of Area Transport Distance Slush 1,000 feet Snow 2,000 feet Ice 3,000 feet"}'::jsonb),
('dnd35.frostburn.spell.frostburn-gelid-blood','Gelid Blood','Gelid Blood','Cold energy surges through the target’s body, congealing the blood in the creature’s extremities. This effect causes a –4 penalty on attacks, Armor Class, and all Strengthand Dexterity-related checks, and anyone casting a spell with a somatic component has a 50% chance of spell failure for the duration of the spell. If the target makes its Fortitude save, the creature only takes a –2 penalty on attacks, Armor Class, and all Strengthand Dexterity-related checks and has only a 25% chance of spell failure for spells with a somatic component.
 Material Component: A pinch of flour.',5,false,false,ARRAY['sorcerer/wizard']::text[],'1 standard action','Close (25 ft. + 5 ft./2 levels)','One creature','1 round/level','Fortitude partial',ARRAY['Necromancy','Cold']::text[],'v35-frostburn','D&D 3.5 — Frostburn',88,'dnd35','{"id":"frostburn-gelid-blood","name":"Gelid Blood","school":"Necromancy","subschool":null,"descriptors":["Cold"],"schoolLine":"Necromancy [Cold]","levels":{"sorcerer/wizard":5},"levelLine":"Sorcerer/wizard 5","components":"V, S, M","castingTime":"1 standard action","range":"Close (25 ft. + 5 ft./2 levels)","duration":"1 round/level","savingThrow":"Fortitude partial","spellResistance":"Yes","targetLabel":"Target","target":"One creature","description":"Cold energy surges through the target’s body, congealing the blood in the creature’s extremities. This effect causes a –4 penalty on attacks, Armor Class, and all Strengthand Dexterity-related checks, and anyone casting a spell with a somatic component has a 50% chance of spell failure for the duration of the spell. If the target makes its Fortitude save, the creature only takes a –2 penalty on attacks, Armor Class, and all Strengthand Dexterity-related checks and has only a 25% chance of spell failure for spells with a somatic component.\n Material Component: A pinch of flour."}'::jsonb),
('dnd35.frostburn.spell.frostburn-glacial-globe-of-invulnerability','Glacial Globe of Invulnerability','Glacial Globe of Invulnerability','A frosty sphere of cold energy surrounds you and excludes all spells and spell-like abilities with the fire descriptor of 3rd level or lower. This spell functions like globe of invulnerability, except that it affects only fire spells. In addition, the frosty opaqueness of the globe grants concealment (20% miss chance) to those within the area against attacks from outside. Likewise, targets outside the globe gain concealment against attacks from those within the spell’s area. Arcane Material Component: A tiny sphere of ice that shatters at the expiration of the spell.',3,false,false,ARRAY['cleric','sorcerer/wizard']::text[],'1 standard action','10 ft.','10-ft.-radius spherical emanation, centered on you','1 round/level (D)','None',ARRAY['Abjuration','Cold']::text[],'v35-frostburn','D&D 3.5 — Frostburn',88,'dnd35','{"id":"frostburn-glacial-globe-of-invulnerability","name":"Glacial Globe of Invulnerability","school":"Abjuration","subschool":null,"descriptors":["Cold"],"schoolLine":"Abjuration [Cold]","levels":{"cleric":4,"sorcerer/wizard":3},"levelLine":"Cleric 4, sorcerer/wizard 3","components":"V, S, M/DF","castingTime":"1 standard action","range":"10 ft.","duration":"1 round/level (D)","savingThrow":"None","spellResistance":"No","targetLabel":"Area","target":"10-ft.-radius spherical emanation, centered on you","description":"A frosty sphere of cold energy surrounds you and excludes all spells and spell-like abilities with the fire descriptor of 3rd level or lower. This spell functions like globe of invulnerability, except that it affects only fire spells. In addition, the frosty opaqueness of the globe grants concealment (20% miss chance) to those within the area against attacks from outside. Likewise, targets outside the globe gain concealment against attacks from those within the spell’s area. Arcane Material Component: A tiny sphere of ice that shatters at the expiration of the spell."}'::jsonb),
('dnd35.frostburn.spell.frostburn-glacial-ward-greater','Glacial Ward, Greater','Glacial Ward, Greater','A 10-foot-radius globe of swirling coldfire surrounds you, granting you and anyone inside the globe spell resistance 25 against all fire spells and spell-like effects. In addition, any creature using a fire-based supernatural ability on a target inside the globe (such as a breath weapon) must also make a caster level check to affect the target. The globe does not offer protection against natural heat and fire, including immersion in lava.
 Material Component: A pinch of sulfur.
 Coldfire Component: One ounce of coldfire.',7,false,false,ARRAY['sorcerer/wizard']::text[],'1 standard action','10 ft.','10-ft.-radius spherical emanation, centered on you','1 round/level (D)','None',ARRAY['Abjuration','Cold']::text[],'v35-frostburn','D&D 3.5 — Frostburn',88,'dnd35','{"id":"frostburn-glacial-ward-greater","name":"Glacial Ward, Greater","school":"Abjuration","subschool":null,"descriptors":["Cold"],"schoolLine":"Abjuration [Cold]","levels":{"sorcerer/wizard":7},"levelLine":"Sorcerer/wizard 7","components":"V, S, M, Coldfire","castingTime":"1 standard action","range":"10 ft.","duration":"1 round/level (D)","savingThrow":"None","spellResistance":"No","targetLabel":"Area","target":"10-ft.-radius spherical emanation, centered on you","description":"A 10-foot-radius globe of swirling coldfire surrounds you, granting you and anyone inside the globe spell resistance 25 against all fire spells and spell-like effects. In addition, any creature using a fire-based supernatural ability on a target inside the globe (such as a breath weapon) must also make a caster level check to affect the target. The globe does not offer protection against natural heat and fire, including immersion in lava.\n Material Component: A pinch of sulfur.\n Coldfire Component: One ounce of coldfire."}'::jsonb),
('dnd35.frostburn.spell.frostburn-glacial-ward','Glacial Ward','Glacial Ward','A faint, shimmering reddish energy encases the subject’s body, granting spell resistance 18 against fire spells and spell-like abilities. In addition, any creature using a fire-based supernatural ability on the subject (such as a breath weapon) must succeed on a DC 18 level check (1d20 + level or HD) to affect a creature warded by this spell.
 Material Component: A pinch of sulfur.',4,false,false,ARRAY['sorcerer/wizard']::text[],'1 standard action','Touch','Creature touched','1 min./level (D)','None',ARRAY['Abjuration','Cold']::text[],'v35-frostburn','D&D 3.5 — Frostburn',88,'dnd35','{"id":"frostburn-glacial-ward","name":"Glacial Ward","school":"Abjuration","subschool":null,"descriptors":["Cold"],"schoolLine":"Abjuration [Cold]","levels":{"sorcerer/wizard":4},"levelLine":"Sorcerer/wizard 4","components":"V, S, M","castingTime":"1 standard action","range":"Touch","duration":"1 min./level (D)","savingThrow":"None","spellResistance":"No","targetLabel":"Target","target":"Creature touched","description":"A faint, shimmering reddish energy encases the subject’s body, granting spell resistance 18 against fire spells and spell-like abilities. In addition, any creature using a fire-based supernatural ability on the subject (such as a breath weapon) must succeed on a DC 18 level check (1d20 + level or HD) to affect a creature warded by this spell.\n Material Component: A pinch of sulfur."}'::jsonb),
('dnd35.frostburn.spell.frostburn-glacier','Glacier','Glacier','When you cast this spell, you bring into existence 20-foot cubes of animated glacial ice (one per two caster levels, to a maximum of ten glaciers at 20th level), which need not appear adjacent to one another, but must be placed on a horizontal surface. Glaciers placed in the air or on nonhorizontal surfaces do not appear, but are deducted from the number of glaciers the caster may conjure. The glaciers remain stationary unless commanded, attacking any creatures within 5 feet with a +15 slam attack that deals 2d8+4 points of damage, plus 3d6 points of cold damage. As a standard action, you may command any number of glaciers to move at a speed of 10 feet. You cannot command any glacier to move more than 100 feet away from you, and if you move more than 100 feet from any glacier, that glacier remains stationary, attacking any creatures in its area (but it can be commanded again if you move with in 100 feet). A glacier has 20 hit points per caster level and a hardness of 0. Creatures can hit the glacier automatically. Fire, including a fireball spell and red dragon breath, can melt a glacier, and it deals full damage to the ice (instead of the normal half damage taken by objects). Suddenly melting a glacier creates a great cloud of steamy fog that lasts for 10 minutes.',8,false,false,ARRAY['druid']::text[],'1 round','Close (25 ft. + 5 ft./2 levels); see text','One 20-ft. cube/2 levels','1 round/level','None',ARRAY['Conjuration','Cold']::text[],'v35-frostburn','D&D 3.5 — Frostburn',88,'dnd35','{"id":"frostburn-glacier","name":"Glacier","school":"Conjuration","subschool":"Creation","descriptors":["Cold"],"schoolLine":"Conjuration (Creation) [Cold]","levels":{"druid":8},"levelLine":"Druid 8","components":"V, S, DF","castingTime":"1 round","range":"Close (25 ft. + 5 ft./2 levels); see text","duration":"1 round/level","savingThrow":"None","spellResistance":"No","targetLabel":"Effect","target":"One 20-ft. cube/2 levels","description":"When you cast this spell, you bring into existence 20-foot cubes of animated glacial ice (one per two caster levels, to a maximum of ten glaciers at 20th level), which need not appear adjacent to one another, but must be placed on a horizontal surface. Glaciers placed in the air or on nonhorizontal surfaces do not appear, but are deducted from the number of glaciers the caster may conjure. The glaciers remain stationary unless commanded, attacking any creatures within 5 feet with a +15 slam attack that deals 2d8+4 points of damage, plus 3d6 points of cold damage. As a standard action, you may command any number of glaciers to move at a speed of 10 feet. You cannot command any glacier to move more than 100 feet away from you, and if you move more than 100 feet from any glacier, that glacier remains stationary, attacking any creatures in its area (but it can be commanded again if you move with in 100 feet). A glacier has 20 hit points per caster level and a hardness of 0. Creatures can hit the glacier automatically. Fire, including a fireball spell and red dragon breath, can melt a glacier, and it deals full damage to the ice (instead of the normal half damage taken by objects). Suddenly melting a glacier creates a great cloud of steamy fog that lasts for 10 minutes."}'::jsonb),
('dnd35.frostburn.spell.frostburn-glaze-lock','Glaze Lock','Glaze Lock','You jam a locking mechanism with ice, raising its Open Lock DC by 10 and the lock’s hardness by 5. Fire attacks against the lock deal double damage. In cold or lower temperature bands, this spell lasts 1 hour per level.',1,false,false,ARRAY['sorcerer/wizard']::text[],'1 standard action','Touch','Lock touched','10 min./level; see text','None',ARRAY['Conjuration','Cold']::text[],'v35-frostburn','D&D 3.5 — Frostburn',88,'dnd35','{"id":"frostburn-glaze-lock","name":"Glaze Lock","school":"Conjuration","subschool":"Creation","descriptors":["Cold"],"schoolLine":"Conjuration (Creation) [Cold]","levels":{"sorcerer/wizard":1},"levelLine":"Sorcerer/wizard 1","components":"V, S","castingTime":"1 standard action","range":"Touch","duration":"10 min./level; see text","savingThrow":"None","spellResistance":"No","targetLabel":"Target","target":"Lock touched","description":"You jam a locking mechanism with ice, raising its Open Lock DC by 10 and the lock’s hardness by 5. Fire attacks against the lock deal double damage. In cold or lower temperature bands, this spell lasts 1 hour per level."}'::jsonb),
('dnd35.frostburn.spell.frostburn-heartfreeze','Heartfreeze','Heartfreeze','You encase the heart of the target creature in a block of ice. The target becomes immediately exhausted and dies in 1d3+2 rounds. The subject is entitled to a Fortitude saving throw to survive the attack. If the target succeeds on the save, it instead takes 5d8 points of cold damage and is not exhausted. (The target might die from damage even if it succeeds on the saving throw.) A character attempting to save the victim of a heartfreeze spell must use a healing spell or effect on the victim as well as succeed on a DC 26 caster level check, otherwise the victim will succumb to the heartfreeze and die. A creature immune to critical hits and sneak attacks is unaffected by heartfreeze.
 Material Component: A strip of dried humanoid sinew.',6,false,false,ARRAY['sorcerer/wizard']::text[],'1 standard action','Close (25 ft. + 5 ft./2 levels)','One creature','Instantaneous','Fortitude partial',ARRAY['Necromancy','Cold']::text[],'v35-frostburn','D&D 3.5 — Frostburn',88,'dnd35','{"id":"frostburn-heartfreeze","name":"Heartfreeze","school":"Necromancy","subschool":null,"descriptors":["Cold"],"schoolLine":"Necromancy [Cold]","levels":{"sorcerer/wizard":6},"levelLine":"Sorcerer/wizard 6","components":"V, S, M","castingTime":"1 standard action","range":"Close (25 ft. + 5 ft./2 levels)","duration":"Instantaneous","savingThrow":"Fortitude partial","spellResistance":"Yes","targetLabel":"Target","target":"One creature","description":"You encase the heart of the target creature in a block of ice. The target becomes immediately exhausted and dies in 1d3+2 rounds. The subject is entitled to a Fortitude saving throw to survive the attack. If the target succeeds on the save, it instead takes 5d8 points of cold damage and is not exhausted. (The target might die from damage even if it succeeds on the saving throw.) A character attempting to save the victim of a heartfreeze spell must use a healing spell or effect on the victim as well as succeed on a DC 26 caster level check, otherwise the victim will succumb to the heartfreeze and die. A creature immune to critical hits and sneak attacks is unaffected by heartfreeze.\n Material Component: A strip of dried humanoid sinew."}'::jsonb),
('dnd35.frostburn.spell.frostburn-heat-leech','Heat Leech','Heat Leech','You plant a tiny sphere of intense cold in the body of a living creature. On each round on your turn (including the round during which you cast the spell), the target must succeed on a Fortitude saving throw or take 1d8 points of cold damage.
 Material Component: A leech and a pinch of snow.',2,false,false,ARRAY['sorcerer/wizard']::text[],'1 standard action','Close (25 ft. + 5 ft./2 levels)','One creature','1 round/level','Fortitude negates; see text',ARRAY['Necromancy','Cold']::text[],'v35-frostburn','D&D 3.5 — Frostburn',88,'dnd35','{"id":"frostburn-heat-leech","name":"Heat Leech","school":"Necromancy","subschool":null,"descriptors":["Cold"],"schoolLine":"Necromancy [Cold]","levels":{"sorcerer/wizard":2},"levelLine":"Sorcerer/wizard 2","components":"V, S, M","castingTime":"1 standard action","range":"Close (25 ft. + 5 ft./2 levels)","duration":"1 round/level","savingThrow":"Fortitude negates; see text","spellResistance":"Yes","targetLabel":"Target","target":"One creature","description":"You plant a tiny sphere of intense cold in the body of a living creature. On each round on your turn (including the round during which you cast the spell), the target must succeed on a Fortitude saving throw or take 1d8 points of cold damage.\n Material Component: A leech and a pinch of snow."}'::jsonb),
('dnd35.frostburn.spell.frostburn-hibernal-healing','Hibernal Healing','Hibernal Healing','You absorb slush, snow, and ice, channeling the cold energy stored within to cure 10 points of damage per caster level, to a maximum of 150 points at 15th level. The spell melts all slush, snow, and ice within 10 feet of the caster.',4,false,false,ARRAY['cleric','druid']::text[],'1 round','Personal','You','Instantaneous','Fortitude half (harmless)',ARRAY['Transmutation','Cold']::text[],'v35-frostburn','D&D 3.5 — Frostburn',88,'dnd35','{"id":"frostburn-hibernal-healing","name":"Hibernal Healing","school":"Transmutation","subschool":null,"descriptors":["Cold"],"schoolLine":"Transmutation [Cold]","levels":{"cleric":5,"druid":4},"levelLine":"Cleric 5, druid 4","components":"V, S, Frostfell","castingTime":"1 round","range":"Personal","duration":"Instantaneous","savingThrow":"Fortitude half (harmless)","spellResistance":"Yes (harmless)","targetLabel":"Target","target":"You","description":"You absorb slush, snow, and ice, channeling the cold energy stored within to cure 10 points of damage per caster level, to a maximum of 150 points at 15th level. The spell melts all slush, snow, and ice within 10 feet of the caster."}'::jsonb),
('dnd35.frostburn.spell.frostburn-hibernate','Hibernate','Hibernate','You put a creature into a state of suspended animation, slowing its life functions to almost imperceptible levels and allowing a creature to survive for weeks without food or water. This suspension of life functions automatically stabilizes a dying creature, and it can save starving or dehydrated creatures from death. Creatures affected by a hibernate spell have a slower metabolism, healing wounds at a rate of just 1 hit point per level per week. If the target is unwilling, it is entitled a Will saving throw. A successful saving throw negates the effect of the spell; a failure allows the target an additional saving throw whenever it takes damage, when it is splashed with water or other liquids, or when 24 hours pass, whichever comes first.',5,false,false,ARRAY['cleric','druid']::text[],'1 standard action','Touch','One living creature','1 week/level (D)','Will negates',ARRAY['Necromancy']::text[],'v35-frostburn','D&D 3.5 — Frostburn',88,'dnd35','{"id":"frostburn-hibernate","name":"Hibernate","school":"Necromancy","subschool":null,"descriptors":[],"schoolLine":"Necromancy","levels":{"cleric":5,"druid":5},"levelLine":"Cleric 5, druid 5","components":"V, S, DF","castingTime":"1 standard action","range":"Touch","duration":"1 week/level (D)","savingThrow":"Will negates","spellResistance":"Yes","targetLabel":"Target","target":"One living creature","description":"You put a creature into a state of suspended animation, slowing its life functions to almost imperceptible levels and allowing a creature to survive for weeks without food or water. This suspension of life functions automatically stabilizes a dying creature, and it can save starving or dehydrated creatures from death. Creatures affected by a hibernate spell have a slower metabolism, healing wounds at a rate of just 1 hit point per level per week. If the target is unwilling, it is entitled a Will saving throw. A successful saving throw negates the effect of the spell; a failure allows the target an additional saving throw whenever it takes damage, when it is splashed with water or other liquids, or when 24 hours pass, whichever comes first."}'::jsonb),
('dnd35.frostburn.spell.frostburn-ice-assassin','Ice Assassin','Ice Assassin','The ice assassin spell is in many ways an improved version of simulacrum. Developed by powerful frost mages who have more than their fair share of enemies to fight, an ice assassin is an effective way to destroy an enemy without putting yourself at risk. An ice assassin spell creates a living, breathing creature that is a near-perfect duplicate of an existing creature. The duplicate is formed entirely out of ice, but once the spell is in effect, it appears as an exact duplicate to all but its source, who always sees the ice assassin as an animated ice statue of himself. The ice assassin possesses all the skills, abilities, and memories possessed by the original, but its personality is warped and twisted by an all-consuming need to slay the original. It also constantly uses locate creature on its duplicate at a caster level equal to your own. If its quarry is outside the range of this effect, the ice assassin must rely on its own cleverness or advice from you to track the original. The ice assassin has the cold subtype. Creatures familiar with the original might detect the ruse with a successful Spot check. You must make a Disguise check (gaining a +10 circumstance bonus from the power of the spell) when you cast the spell to determine how good the likeness is. The ice assassin is under your absolute command. You possess a telepathic link to the ice assassin, and when you concentrate, you receive a clear image of the area surrounding the ice assassin as if you were scrying it. Further, you can have any spell you cast on yourself affect the ice assassin as well; this includes spells with a target of “You” only. These benefits persist as long as you and the ice assassin remain within a mile of each other. If the ice assassin travels beyond this range, it continues to function and seek out its nemesis, but you have no direct control over it. An ice assassin has no ability to become more powerful; it cannot increase its level or abilities. Damage caused to the ice assassin can be repaired only via a complex process requiring 1 day, 100 gp per hit point, and a fully equipped laboratory. If the ice assassin is reduced to 0 hit points by any damage except for fire damage, it explodes into a burst of icy shrapnel in a 20-foot radius that causes 1d6 points of cold damage for every two caster levels you possess; a successful Reflex saving throw halves the damage. An ice assassin slain by fire damage simply melts into a pool of water.
 Material Component: This spell is cast over the ice statue of the creature to be duplicated. Some portion of the creature to be duplicated (hair, nail, and so on) must be placed inside the ice statue as it is constructed. In addition, the spell requires powdered diamond worth 20,000 gp. XP Cost: 5,000.',9,false,false,ARRAY['sorcerer/wizard']::text[],'8 hours','Touch','One duplicate creature','Instantaneous','None; see text',ARRAY['Illusion']::text[],'v35-frostburn','D&D 3.5 — Frostburn',88,'dnd35','{"id":"frostburn-ice-assassin","name":"Ice Assassin","school":"Illusion","subschool":"Shadow","descriptors":[],"schoolLine":"Illusion (Shadow)","levels":{"sorcerer/wizard":9},"levelLine":"Sorcerer/wizard 9","components":"V, S, M, XP","castingTime":"8 hours","range":"Touch","duration":"Instantaneous","savingThrow":"None; see text","spellResistance":"No","targetLabel":"Effect","target":"One duplicate creature","description":"The ice assassin spell is in many ways an improved version of simulacrum. Developed by powerful frost mages who have more than their fair share of enemies to fight, an ice assassin is an effective way to destroy an enemy without putting yourself at risk. An ice assassin spell creates a living, breathing creature that is a near-perfect duplicate of an existing creature. The duplicate is formed entirely out of ice, but once the spell is in effect, it appears as an exact duplicate to all but its source, who always sees the ice assassin as an animated ice statue of himself. The ice assassin possesses all the skills, abilities, and memories possessed by the original, but its personality is warped and twisted by an all-consuming need to slay the original. It also constantly uses locate creature on its duplicate at a caster level equal to your own. If its quarry is outside the range of this effect, the ice assassin must rely on its own cleverness or advice from you to track the original. The ice assassin has the cold subtype. Creatures familiar with the original might detect the ruse with a successful Spot check. You must make a Disguise check (gaining a +10 circumstance bonus from the power of the spell) when you cast the spell to determine how good the likeness is. The ice assassin is under your absolute command. You possess a telepathic link to the ice assassin, and when you concentrate, you receive a clear image of the area surrounding the ice assassin as if you were scrying it. Further, you can have any spell you cast on yourself affect the ice assassin as well; this includes spells with a target of “You” only. These benefits persist as long as you and the ice assassin remain within a mile of each other. If the ice assassin travels beyond this range, it continues to function and seek out its nemesis, but you have no direct control over it. An ice assassin has no ability to become more powerful; it cannot increase its level or abilities. Damage caused to the ice assassin can be repaired only via a complex process requiring 1 day, 100 gp per hit point, and a fully equipped laboratory. If the ice assassin is reduced to 0 hit points by any damage except for fire damage, it explodes into a burst of icy shrapnel in a 20-foot radius that causes 1d6 points of cold damage for every two caster levels you possess; a successful Reflex saving throw halves the damage. An ice assassin slain by fire damage simply melts into a pool of water.\n Material Component: This spell is cast over the ice statue of the creature to be duplicated. Some portion of the creature to be duplicated (hair, nail, and so on) must be placed inside the ice statue as it is constructed. In addition, the spell requires powdered diamond worth 20,000 gp. XP Cost: 5,000."}'::jsonb),
('dnd35.frostburn.spell.frostburn-ice-castle','Ice Castle','Ice Castle','You create a huge castle of ice and snow, fully formed with walls, towers, gates, and battlements and magical wards. The castle includes a single main gate and a sally port, a drawbridge, a 30-foot diameter central tower made of blue ice (see page 80), and one additional tower per 6 levels of the caster. The size of the castle is determined by the location of the towers, which enclose an open courtyard. The maximum perimeter of the structure is 20 feet per caster level. In addition, you can place any or all of the following three magical effects in the castle. 1. Icicle spells in two areas (typically in the gatehouse and in the central tower). Saving Throw: See text. Spell Resistance: No. 2. Ice slick spells triggered an intruder steps on the tower stairs. Saving Throw: See text. Spell Resistance: No. 3. Obscuring snow in any corridors or rooms, obscuring all sight, including darkvision, beyond 5 feet. A creature within 5 feet has concealment (attacks have a 20% miss chance). Creatures father away have total concealment (50% miss chance, and the attacker cannot use sight to locate the target). Saving Throw: None. Spell Resistance: No. The castle can be created around living creatures, and in this case it rises up from the earth and snow around them. It cannot be “dropped” onto creatures as an offensive spell. The caster may choose to be lifted onto the roof of the central tower by centering the spell on himself. If the castle is summoned on relatively level ground, a moat of icy water 20 feet wide surrounds the castle. If summoned on sharply sloping ground, an icy crevasse 20 feet wide and 50 feet deep surrounds the castle. The castle melts slowly whenever the temperature rises above freezing; an ice castle takes 1d6 points of damage each round in a place with temperatures above freezing. When struck by fire spells, the castle is damaged normally. The castle has 200 hit points per 5-foot section and a hardness of 0. The central tower is made of blue ice which has 300 hit points per 5-foot section and a hardness of 10 Creatures can hit the castle automatically. Fire, including a fireball spell and red dragon breath, can melt the ice castle, and it deals full damage to the structure (instead of the normal half damage taken by objects). Suddenly melting an ice castle creates a great cloud of steamy fog that lasts for 10 minutes. Arcane Focus: A piece of blue ice carved to resemble the desired castle worth 2,000 gp.',7,false,false,ARRAY['sorcerer/wizard']::text[],'10 minutes','Medium (100 ft. + 10 ft./level)','Fortress of ice and snow','24 hours','No',ARRAY['Conjuration','Cold']::text[],'v35-frostburn','D&D 3.5 — Frostburn',88,'dnd35','{"id":"frostburn-ice-castle","name":"Ice Castle","school":"Conjuration","subschool":"Creation","descriptors":["Cold"],"schoolLine":"Conjuration (Creation) [Cold]","levels":{"sorcerer/wizard":7},"levelLine":"Sorcerer/wizard 7","components":"V, S, F","castingTime":"10 minutes","range":"Medium (100 ft. + 10 ft./level)","duration":"24 hours","savingThrow":"No","spellResistance":"No","targetLabel":"Effect","target":"Fortress of ice and snow","description":"You create a huge castle of ice and snow, fully formed with walls, towers, gates, and battlements and magical wards. The castle includes a single main gate and a sally port, a drawbridge, a 30-foot diameter central tower made of blue ice (see page 80), and one additional tower per 6 levels of the caster. The size of the castle is determined by the location of the towers, which enclose an open courtyard. The maximum perimeter of the structure is 20 feet per caster level. In addition, you can place any or all of the following three magical effects in the castle. 1. Icicle spells in two areas (typically in the gatehouse and in the central tower). Saving Throw: See text. Spell Resistance: No. 2. Ice slick spells triggered an intruder steps on the tower stairs. Saving Throw: See text. Spell Resistance: No. 3. Obscuring snow in any corridors or rooms, obscuring all sight, including darkvision, beyond 5 feet. A creature within 5 feet has concealment (attacks have a 20% miss chance). Creatures father away have total concealment (50% miss chance, and the attacker cannot use sight to locate the target). Saving Throw: None. Spell Resistance: No. The castle can be created around living creatures, and in this case it rises up from the earth and snow around them. It cannot be “dropped” onto creatures as an offensive spell. The caster may choose to be lifted onto the roof of the central tower by centering the spell on himself. If the castle is summoned on relatively level ground, a moat of icy water 20 feet wide surrounds the castle. If summoned on sharply sloping ground, an icy crevasse 20 feet wide and 50 feet deep surrounds the castle. The castle melts slowly whenever the temperature rises above freezing; an ice castle takes 1d6 points of damage each round in a place with temperatures above freezing. When struck by fire spells, the castle is damaged normally. The castle has 200 hit points per 5-foot section and a hardness of 0. The central tower is made of blue ice which has 300 hit points per 5-foot section and a hardness of 10 Creatures can hit the castle automatically. Fire, including a fireball spell and red dragon breath, can melt the ice castle, and it deals full damage to the structure (instead of the normal half damage taken by objects). Suddenly melting an ice castle creates a great cloud of steamy fog that lasts for 10 minutes. Arcane Focus: A piece of blue ice carved to resemble the desired castle worth 2,000 gp."}'::jsonb),
('dnd35.frostburn.spell.frostburn-ice-darts','Ice Darts','Ice Darts','A sharp, transparent icicle shoots from your fingertip. You may fire one dart, plus one additional dart for every two levels beyond 3rd (to a maximum of five darts at 11th level). Each dart requires a ranged touch attack to hit and deals 2d4 points of damage, half of which is cold damage.',2,false,false,ARRAY['bard','sorcerer/wizard']::text[],'1 standard action','Close (25 ft. + 5 ft./2 levels)','One or more ice darts','Instantaneous','None',ARRAY['Conjuration','Cold']::text[],'v35-frostburn','D&D 3.5 — Frostburn',88,'dnd35','{"id":"frostburn-ice-darts","name":"Ice Darts","school":"Conjuration","subschool":"Creation","descriptors":["Cold"],"schoolLine":"Conjuration (Creation) [Cold]","levels":{"bard":2,"sorcerer/wizard":2},"levelLine":"Bard 2, sorcerer/wizard 2","components":"V, S","castingTime":"1 standard action","range":"Close (25 ft. + 5 ft./2 levels)","duration":"Instantaneous","savingThrow":"None","spellResistance":"No","targetLabel":"Effect","target":"One or more ice darts","description":"A sharp, transparent icicle shoots from your fingertip. You may fire one dart, plus one additional dart for every two levels beyond 3rd (to a maximum of five darts at 11th level). Each dart requires a ranged touch attack to hit and deals 2d4 points of damage, half of which is cold damage."}'::jsonb),
('dnd35.frostburn.spell.frostburn-ice-rift','Ice Rift','Ice Rift','When you cast ice rift, an intense but highly localized tremor rips through the ice. The shock knocks creatures down, collapses structures, opens cracks in the ice, and more. The effect lasts for 1 round, during which time creatures on the ice can’t move or attack. A spellcaster on the ice must make a Concentration check (DC 20 + spell level) or lose any spell he or she tries to cast. The ice rift affects all terrain, vegetation, structures, and creatures in the area. The specific effect of an ice rift spell depends on the nature of the terrain where it is cast. Ice or Snow Cave, Cavern, or Tunnel: The spell collapses the roof, dealing 8d6 points of bludgeoning damage to any creature caught under the cave-in (Reflex DC 15 half) and burying that creature in snow. An ice rift cast on the roof of a very large ice or snow cavern could also endanger those outside the actual area but below the falling debris. Edge of a Glacier: Ice rift causes a glacier’s edge to crumble, creating a landslide that travels horizontally as far as it fell vertically. An ice rift cast at the top of a 100-foot glacier would sweep debris 100 feet outward from the base of the glacier. Any creature in the path takes 8d6 points of bludgeoning damage (Reflex DC 15 half) and is pinned beneath rubble (see below). Open Glacier: Each creature standing in the area must make a DC 15 Reflex save or fall down. Fissures open in the ice, and every creature on the ice has a 25% chance to fall into one (Reflex DC 20 to avoid a fissure). At the end of the spell, all fissures grind shut, killing any creatures still trapped within. Frozen Water: Fissures open in the ice, and every creature on the ice has a 25% chance to fall into the freezing water (Reflex DC 20 to avoid a fissure). Characters who fall into a fissure are immediately subject to hypothermia and take 2d6 points of cold damage from the frigid water. At the end of the spell, all rents in the ice grind shut, sealing any creatures in the icy water beneath (for additional rules on characters in cold water, see Hypothermia, page 10). Arcane Material Component: A bit of earth and a pinch of snow.',6,false,false,ARRAY['cleric','druid','sorcerer/wizard']::text[],'1 standard action','Long (400 ft. + 40 ft./level)','40-ft.-radius spread (S)','1 round','See text',ARRAY['Evocation','Cold']::text[],'v35-frostburn','D&D 3.5 — Frostburn',88,'dnd35','{"id":"frostburn-ice-rift","name":"Ice Rift","school":"Evocation","subschool":null,"descriptors":["Cold"],"schoolLine":"Evocation [Cold]","levels":{"cleric":6,"druid":6,"sorcerer/wizard":6},"levelLine":"Cleric 6, druid 6, sorcerer/ wizard 6","components":"V, S, M/DF","castingTime":"1 standard action","range":"Long (400 ft. + 40 ft./level)","duration":"1 round","savingThrow":"See text","spellResistance":"No","targetLabel":"Area","target":"40-ft.-radius spread (S)","description":"When you cast ice rift, an intense but highly localized tremor rips through the ice. The shock knocks creatures down, collapses structures, opens cracks in the ice, and more. The effect lasts for 1 round, during which time creatures on the ice can’t move or attack. A spellcaster on the ice must make a Concentration check (DC 20 + spell level) or lose any spell he or she tries to cast. The ice rift affects all terrain, vegetation, structures, and creatures in the area. The specific effect of an ice rift spell depends on the nature of the terrain where it is cast. Ice or Snow Cave, Cavern, or Tunnel: The spell collapses the roof, dealing 8d6 points of bludgeoning damage to any creature caught under the cave-in (Reflex DC 15 half) and burying that creature in snow. An ice rift cast on the roof of a very large ice or snow cavern could also endanger those outside the actual area but below the falling debris. Edge of a Glacier: Ice rift causes a glacier’s edge to crumble, creating a landslide that travels horizontally as far as it fell vertically. An ice rift cast at the top of a 100-foot glacier would sweep debris 100 feet outward from the base of the glacier. Any creature in the path takes 8d6 points of bludgeoning damage (Reflex DC 15 half) and is pinned beneath rubble (see below). Open Glacier: Each creature standing in the area must make a DC 15 Reflex save or fall down. Fissures open in the ice, and every creature on the ice has a 25% chance to fall into one (Reflex DC 20 to avoid a fissure). At the end of the spell, all fissures grind shut, killing any creatures still trapped within. Frozen Water: Fissures open in the ice, and every creature on the ice has a 25% chance to fall into the freezing water (Reflex DC 20 to avoid a fissure). Characters who fall into a fissure are immediately subject to hypothermia and take 2d6 points of cold damage from the frigid water. At the end of the spell, all rents in the ice grind shut, sealing any creatures in the icy water beneath (for additional rules on characters in cold water, see Hypothermia, page 10). Arcane Material Component: A bit of earth and a pinch of snow."}'::jsonb),
('dnd35.frostburn.spell.frostburn-ice-shape','Ice Shape','Ice Shape','You can form an existing piece of ice into any shape that suits your purpose. For example, you can make an ice weapon, a special trapdoor, or a crude idol. Ice shape also permits you to reshape an ice door to make an exit where one didn’t exist or to seal a door shut. While it’s possible to make crude coffers, doors, and so forth with ice shape, fine detail isn’t possible. There is a 30% chance that any shape including moving parts simply doesn’t work. Arcane Material Component: Slush, which must be spread into roughly the desired shape of the ice object and then touched to the ice while the verbal component is uttered.',3,false,false,ARRAY['cleric','druid','sorcerer/wizard']::text[],'1 standard action','Touch','Ice touched, up to 10 cu. ft. + 1 cu. ft./level','Instantaneous','None',ARRAY['Transmutation','Cold']::text[],'v35-frostburn','D&D 3.5 — Frostburn',88,'dnd35','{"id":"frostburn-ice-shape","name":"Ice Shape","school":"Transmutation","subschool":null,"descriptors":["Cold"],"schoolLine":"Transmutation [Cold]","levels":{"cleric":3,"druid":3,"sorcerer/wizard":5},"levelLine":"Cleric 3, druid 3, sorcerer/ wizard 5","components":"V, S, M/DF","castingTime":"1 standard action","range":"Touch","duration":"Instantaneous","savingThrow":"None","spellResistance":"No","targetLabel":"Area","target":"Ice touched, up to 10 cu. ft. + 1 cu. ft./level","description":"You can form an existing piece of ice into any shape that suits your purpose. For example, you can make an ice weapon, a special trapdoor, or a crude idol. Ice shape also permits you to reshape an ice door to make an exit where one didn’t exist or to seal a door shut. While it’s possible to make crude coffers, doors, and so forth with ice shape, fine detail isn’t possible. There is a 30% chance that any shape including moving parts simply doesn’t work. Arcane Material Component: Slush, which must be spread into roughly the desired shape of the ice object and then touched to the ice while the verbal component is uttered."}'::jsonb),
('dnd35.frostburn.spell.frostburn-ice-shield','Ice Shield','Ice Shield','The warded creature gains resistance to blows, cuts, stabs, and slashes. The subject gains damage reduction 15/—. The spell prevents a total of 10 points of damage per caster level (maximum 150 points). While protected by the spell, the creature also has vulnerability to fire and takes half again as much (+50%) damage as normal from the effect, regardless of whether a saving throw is allowed, or if the save is a success or failure. The duration increases to 10 minutes per level when in a frostfell environment.
 Material Component: A pinch of sleet.
 Coldfire Component: Five ounces of coldfire.',4,false,false,ARRAY['druid','sorcerer/wizard']::text[],'1 standard action','Touch','Creature touched','1 min./level','Will negates (harmless)',ARRAY['Abjuration']::text[],'v35-frostburn','D&D 3.5 — Frostburn',88,'dnd35','{"id":"frostburn-ice-shield","name":"Ice Shield","school":"Abjuration","subschool":null,"descriptors":[],"schoolLine":"Abjuration","levels":{"druid":5,"sorcerer/wizard":4},"levelLine":"Druid 5, sorcerer/wizard 4","components":"V, S, M, Coldfire","castingTime":"1 standard action","range":"Touch","duration":"1 min./level","savingThrow":"Will negates (harmless)","spellResistance":"Yes (harmless)","targetLabel":"Target","target":"Creature touched","description":"The warded creature gains resistance to blows, cuts, stabs, and slashes. The subject gains damage reduction 15/—. The spell prevents a total of 10 points of damage per caster level (maximum 150 points). While protected by the spell, the creature also has vulnerability to fire and takes half again as much (+50%) damage as normal from the effect, regardless of whether a saving throw is allowed, or if the save is a success or failure. The duration increases to 10 minutes per level when in a frostfell environment.\n Material Component: A pinch of sleet.\n Coldfire Component: Five ounces of coldfire."}'::jsonb),
('dnd35.frostburn.spell.frostburn-ice-ship','Ice Ship','Ice Ship','You create a ship made of ice. The vessel can take one of two forms, depending on your needs at the time. The form is chosen when the spell is cast and cannot be changed. Ice Runner: This tiny, narrow ship appears with a set of stone runners that carry the ship at speeds of up to 80 mph over any level ice, such as a lake, river, or ocean pack ice. It can carry one Medium creature per caster level, and it cannot move against the prevailing winds (though it can move at right angles to the wind). Large creatures cannot fit on an ice runner. This form has 40 hit points and a hardness of 3. Ice Galleon: This sailing vessel can move against the wind at a steady pace of 5 mph, or with the wind at 10 mph. It carries three Medium creatures per caster level, or one Large creature per level. This form has 60 hit points and a hardness of 5. If the ship is created in an area of temperature above freezing, it immediately begins to melt, taking 1d12 points of damage per hour. Both forms begin to melt or crack slowly during the last hour of the spell regardless of temperature, and disappear into puddles or splinters of ice at the end of the spell’s duration.
 Material Component: A small glass model of a ship worth at least 200 gp.',4,false,false,ARRAY['sorcerer/wizard']::text[],'1 standard action','Close (25 ft. +5 ft./2 levels)','Creates ship of ice','1 hour/level (D)',null,ARRAY['Conjuration','Creation']::text[],'v35-frostburn','D&D 3.5 — Frostburn',88,'dnd35','{"id":"frostburn-ice-ship","name":"Ice Ship","school":"Conjuration","subschool":null,"descriptors":["Creation"],"schoolLine":"Conjuration [Creation]","levels":{"sorcerer/wizard":4},"levelLine":"Sorcerer/wizard 4","components":"V, S, M","castingTime":"1 standard action","range":"Close (25 ft. +5 ft./2 levels)","duration":"1 hour/level (D)","targetLabel":"Effect","target":"Creates ship of ice","description":"You create a ship made of ice. The vessel can take one of two forms, depending on your needs at the time. The form is chosen when the spell is cast and cannot be changed. Ice Runner: This tiny, narrow ship appears with a set of stone runners that carry the ship at speeds of up to 80 mph over any level ice, such as a lake, river, or ocean pack ice. It can carry one Medium creature per caster level, and it cannot move against the prevailing winds (though it can move at right angles to the wind). Large creatures cannot fit on an ice runner. This form has 40 hit points and a hardness of 3. Ice Galleon: This sailing vessel can move against the wind at a steady pace of 5 mph, or with the wind at 10 mph. It carries three Medium creatures per caster level, or one Large creature per level. This form has 60 hit points and a hardness of 5. If the ship is created in an area of temperature above freezing, it immediately begins to melt, taking 1d12 points of damage per hour. Both forms begin to melt or crack slowly during the last hour of the spell regardless of temperature, and disappear into puddles or splinters of ice at the end of the spell’s duration.\n Material Component: A small glass model of a ship worth at least 200 gp."}'::jsonb),
('dnd35.frostburn.spell.frostburn-ice-skate','Ice Skate','Ice Skate','You allow a creature to skate across any icy surface, either level or inclined, increasing its base land speed by 60 feet. (This adjustment is treated as an enhancement bonus.) No Balance checks are required for this movement (even during combat on ice) unless the recipient attempts exceptional maneuvers, such as jumping a crevasse or gliding up a frozen waterfall, or takes damage—even then, the recipient gains a +4 enhancement bonus on its Balance check.',1,false,false,ARRAY['druid','ranger']::text[],'1 standard action','Touch','Creature touched','10 min./level (D)','Fortitude negates (harmless)',ARRAY['Transmutation']::text[],'v35-frostburn','D&D 3.5 — Frostburn',88,'dnd35','{"id":"frostburn-ice-skate","name":"Ice Skate","school":"Transmutation","subschool":null,"descriptors":[],"schoolLine":"Transmutation","levels":{"druid":1,"ranger":1},"levelLine":"Druid 1, ranger 1","components":"V, S, DF","castingTime":"1 standard action","range":"Touch","duration":"10 min./level (D)","savingThrow":"Fortitude negates (harmless)","spellResistance":"Yes (harmless)","targetLabel":"Target","target":"Creature touched","description":"You allow a creature to skate across any icy surface, either level or inclined, increasing its base land speed by 60 feet. (This adjustment is treated as an enhancement bonus.) No Balance checks are required for this movement (even during combat on ice) unless the recipient attempts exceptional maneuvers, such as jumping a crevasse or gliding up a frozen waterfall, or takes damage—even then, the recipient gains a +4 enhancement bonus on its Balance check."}'::jsonb),
('dnd35.frostburn.spell.frostburn-ice-slick','Ice Slick','Ice Slick','An ice slick spell covers a solid surface with a layer of slippery ice. Any creature entering the area or caught in it when the spell is cast must make a successful Balance check or slip, skid, and fall. Those that succeed on the skill check can move at half speed across the surface, or can skate or glide normally. However, those that remain in the area must each make a new skill check every round to avoid falling and be able to move. The DM should adjust skill checks by circumstance. For example, a creature charging down a hill that is suddenly iced has little chance to avoid the effect, but its ability to exit the affected area is almost assured (whether it wants to or not).',1,false,false,ARRAY['cleric']::text[],'1 standard action','Close (25 ft. + 5 ft./2 levels)','One 20-ft. square','1 round/level (D)','See text',ARRAY['Conjuration','Cold']::text[],'v35-frostburn','D&D 3.5 — Frostburn',88,'dnd35','{"id":"frostburn-ice-slick","name":"Ice Slick","school":"Conjuration","subschool":"Creation","descriptors":["Cold"],"schoolLine":"Conjuration (Creation) [Cold]","levels":{"cleric":1},"levelLine":"Cleric 1","components":"V, S, DF","castingTime":"1 standard action","range":"Close (25 ft. + 5 ft./2 levels)","duration":"1 round/level (D)","savingThrow":"See text","spellResistance":"No","targetLabel":"Area","target":"One 20-ft. square","description":"An ice slick spell covers a solid surface with a layer of slippery ice. Any creature entering the area or caught in it when the spell is cast must make a successful Balance check or slip, skid, and fall. Those that succeed on the skill check can move at half speed across the surface, or can skate or glide normally. However, those that remain in the area must each make a new skill check every round to avoid falling and be able to move. The DM should adjust skill checks by circumstance. For example, a creature charging down a hill that is suddenly iced has little chance to avoid the effect, but its ability to exit the affected area is almost assured (whether it wants to or not)."}'::jsonb),
('dnd35.frostburn.spell.frostburn-ice-to-flesh','Ice to Flesh','Ice to Flesh','This spell restores a frozen creature to its normal state, restoring life and goods. The creature must make a DC 15 Fortitude save to survive the process. Any frozen creature, regardless of size, can be restored. The spell also can convert a mass of ice into a fleshy substance. Such flesh is inert and lacking a vital life force unless a life force or magical energy is available. (For example, an ordinary ice sculpture would become a corpse.) You can affect an object that fits within a cylinder from 1 foot to 3 feet in diameter and up to 10 feet long or a cylinder of up to those dimensions in a larger mass of ice.
 Material Component: A cube of ice and a drop of blood.',5,false,false,ARRAY['sorcerer/wizard']::text[],'1 standard action','Medium (100 ft. + 10 ft./level)','One frozen creature or a cylinder of ice from 1 ft. to 3 ft. in diameter and up to 10 ft. long','Instantaneous','Fortitude negates (object); see text',ARRAY['Transmutation']::text[],'v35-frostburn','D&D 3.5 — Frostburn',88,'dnd35','{"id":"frostburn-ice-to-flesh","name":"Ice to Flesh","school":"Transmutation","subschool":null,"descriptors":[],"schoolLine":"Transmutation","levels":{"sorcerer/wizard":5},"levelLine":"Sorcerer/wizard 5","components":"V, S, M","castingTime":"1 standard action","range":"Medium (100 ft. + 10 ft./level)","duration":"Instantaneous","savingThrow":"Fortitude negates (object); see text","spellResistance":"Yes","targetLabel":"Target","target":"One frozen creature or a cylinder of ice from 1 ft. to 3 ft. in diameter and up to 10 ft. long","description":"This spell restores a frozen creature to its normal state, restoring life and goods. The creature must make a DC 15 Fortitude save to survive the process. Any frozen creature, regardless of size, can be restored. The spell also can convert a mass of ice into a fleshy substance. Such flesh is inert and lacking a vital life force unless a life force or magical energy is available. (For example, an ordinary ice sculpture would become a corpse.) You can affect an object that fits within a cylinder from 1 foot to 3 feet in diameter and up to 10 feet long or a cylinder of up to those dimensions in a larger mass of ice.\n Material Component: A cube of ice and a drop of blood."}'::jsonb),
('dnd35.frostburn.spell.frostburn-ice-web','Ice Web','Ice Web','Ice web creates a many-layered mass of strong, frigid strands of pure coldfire. These masses must be anchored to two or more solid and diametrically opposed points—floor and ceiling, opposite walls, or the like—or else the ice web collapses upon itself and disappears. Creatures caught within the ice web become entangled in the strands. Attacking a creature in an ice web won’t cause you to become entangled. Any creature moving into or through the spell’s area takes 1d6 points of frostburn damage per round. In addition, anyone in the effect’s area when the spell is cast must make a Reflex save. If this save succeeds, the creature is entangled, but not prevented from moving, though moving is more difficult than normal (see below). If the save fails, the creature is entangled and can’t move from its space, but can break loose by spending 1 round and making a DC 20 Strength check or a DC 25 Escape Artist check. Once loose (either by making the initial Reflex save or a later Strength check or Escape Artist check), a creature remains entangled, but may move through the ice web very slowly. Each round devoted to moving allows the creature to make a new Strength check or Escape Artist check. The creature moves 5 feet for each full 5 points by which the check result exceeds 10. If you have at least 5 feet of ice web between you and an opponent, it provides cover. If you have at least 20 feet of ice web between you, it provides total cover. The strands of an ice web are immune to damage from cold. Any fire—a torch, burning oil, a flaming sword, and so forth—can melt 5 square feet of coldfire strands in 1 round. Ice web can be made permanent with a permanency spell. A permanent ice web that is damaged (but not destroyed) regrows in 10 minutes. Creatures with the cold subtype may pass unimpeded and unharmed through an ice web.
 Coldfire Component: Two ounces of coldfire.',4,false,false,ARRAY['sorcerer/wizard']::text[],'1 standard action','Medium (100 ft. + 10 ft./level)','Webs of coldfire in a 20-ft.- radius spread','10 min./level (D)','Reflex negates; see text',ARRAY['Conjuration','Cold']::text[],'v35-frostburn','D&D 3.5 — Frostburn',88,'dnd35','{"id":"frostburn-ice-web","name":"Ice Web","school":"Conjuration","subschool":"Creation","descriptors":["Cold"],"schoolLine":"Conjuration (Creation) [Cold]","levels":{"sorcerer/wizard":4},"levelLine":"Sorcerer/wizard 4","components":"V, S, Coldfire","castingTime":"1 standard action","range":"Medium (100 ft. + 10 ft./level)","duration":"10 min./level (D)","savingThrow":"Reflex negates; see text","spellResistance":"No","targetLabel":"Effect","target":"Webs of coldfire in a 20-ft.- radius spread","description":"Ice web creates a many-layered mass of strong, frigid strands of pure coldfire. These masses must be anchored to two or more solid and diametrically opposed points—floor and ceiling, opposite walls, or the like—or else the ice web collapses upon itself and disappears. Creatures caught within the ice web become entangled in the strands. Attacking a creature in an ice web won’t cause you to become entangled. Any creature moving into or through the spell’s area takes 1d6 points of frostburn damage per round. In addition, anyone in the effect’s area when the spell is cast must make a Reflex save. If this save succeeds, the creature is entangled, but not prevented from moving, though moving is more difficult than normal (see below). If the save fails, the creature is entangled and can’t move from its space, but can break loose by spending 1 round and making a DC 20 Strength check or a DC 25 Escape Artist check. Once loose (either by making the initial Reflex save or a later Strength check or Escape Artist check), a creature remains entangled, but may move through the ice web very slowly. Each round devoted to moving allows the creature to make a new Strength check or Escape Artist check. The creature moves 5 feet for each full 5 points by which the check result exceeds 10. If you have at least 5 feet of ice web between you and an opponent, it provides cover. If you have at least 20 feet of ice web between you, it provides total cover. The strands of an ice web are immune to damage from cold. Any fire—a torch, burning oil, a flaming sword, and so forth—can melt 5 square feet of coldfire strands in 1 round. Ice web can be made permanent with a permanency spell. A permanent ice web that is damaged (but not destroyed) regrows in 10 minutes. Creatures with the cold subtype may pass unimpeded and unharmed through an ice web.\n Coldfire Component: Two ounces of coldfire."}'::jsonb),
('dnd35.frostburn.spell.frostburn-iceberg','Iceberg','Iceberg','Iceberg is a brutal and direct spell. When cast, the spell creates a single large block of ice that drops from the sky onto a spot you select. The iceberg then shatters if it encounters a solid surface. Elephant-sized blocks of ice scatter in all directions, affecting nearby creatures based on how far they are from the center of the area. Within 20 Feet of the Center Point: Any creature or object directly beneath the iceberg takes 20d6 points of crushing damage (no save) and is buried in snow (see page 90). Between 20 Feet and 40 Feet of the Center Point: Creatures and objects in the middle section of the area also take 20d6 points of crushing damage, but are entitled to a Reflex save for half damage. They are buried in snow (see page 90). Between 40 Feet and 60 Feet of the Center Point: Creatures in the outer-most section may be struck by flying debris for 10d6 points of damage. They are entitled to a Reflex save for half damage, and are not buried regardless of whether the saving throw is successful or not.',9,false,false,ARRAY['sorcerer/wizard']::text[],'1 standard action','Long (400 ft. + 40 ft./level)','60-foot radius','Instantaneous','None or Reflex half; see text',ARRAY['Evocation','Cold']::text[],'v35-frostburn','D&D 3.5 — Frostburn',88,'dnd35','{"id":"frostburn-iceberg","name":"Iceberg","school":"Evocation","subschool":null,"descriptors":["Cold"],"schoolLine":"Evocation [Cold]","levels":{"sorcerer/wizard":9},"levelLine":"Sorcerer/wizard 9","components":"V, S","castingTime":"1 standard action","range":"Long (400 ft. + 40 ft./level)","duration":"Instantaneous","savingThrow":"None or Reflex half; see text","spellResistance":"Yes","targetLabel":"Area","target":"60-foot radius","description":"Iceberg is a brutal and direct spell. When cast, the spell creates a single large block of ice that drops from the sky onto a spot you select. The iceberg then shatters if it encounters a solid surface. Elephant-sized blocks of ice scatter in all directions, affecting nearby creatures based on how far they are from the center of the area. Within 20 Feet of the Center Point: Any creature or object directly beneath the iceberg takes 20d6 points of crushing damage (no save) and is buried in snow (see page 90). Between 20 Feet and 40 Feet of the Center Point: Creatures and objects in the middle section of the area also take 20d6 points of crushing damage, but are entitled to a Reflex save for half damage. They are buried in snow (see page 90). Between 40 Feet and 60 Feet of the Center Point: Creatures in the outer-most section may be struck by flying debris for 10d6 points of damage. They are entitled to a Reflex save for half damage, and are not buried regardless of whether the saving throw is successful or not."}'::jsonb),
('dnd35.frostburn.spell.frostburn-icicle','Icicle','Icicle','You create icicles on a ceiling, doorway, or similar overhang. The icicles fall when a creature walks beneath them, dealing 4d6 points of piercing damage. Anyone directly under the area takes this damage with no saving throw. Others within 5 feet of the icicles take half damage, or none if they succeed on a Reflex saving throw. The caster and any characters you choose can walk under the icicles or through the doorway without triggering the ice attack. Likewise, you can remove the icicles whenever desired. Others can remove them with a successful dispel magic or 10 points of fire damage. However, an unsuccessful attempt to dispel or melt the icicles automatically triggers the attack.',2,false,false,ARRAY['sorcerer/wizard']::text[],'1 standard action','Close (25 ft. + 5 ft./2 levels)','One 10-ft. square section of ceiling or doorframe','Until discharged (D)','See text',ARRAY['Abjuration','Cold']::text[],'v35-frostburn','D&D 3.5 — Frostburn',88,'dnd35','{"id":"frostburn-icicle","name":"Icicle","school":"Abjuration","subschool":null,"descriptors":["Cold"],"schoolLine":"Abjuration [Cold]","levels":{"sorcerer/wizard":2},"levelLine":"Sorcerer/wizard 2","components":"V, S","castingTime":"1 standard action","range":"Close (25 ft. + 5 ft./2 levels)","duration":"Until discharged (D)","savingThrow":"See text","spellResistance":"Yes","targetLabel":"Area","target":"One 10-ft. square section of ceiling or doorframe","description":"You create icicles on a ceiling, doorway, or similar overhang. The icicles fall when a creature walks beneath them, dealing 4d6 points of piercing damage. Anyone directly under the area takes this damage with no saving throw. Others within 5 feet of the icicles take half damage, or none if they succeed on a Reflex saving throw. The caster and any characters you choose can walk under the icicles or through the doorway without triggering the ice attack. Likewise, you can remove the icicles whenever desired. Others can remove them with a successful dispel magic or 10 points of fire damage. However, an unsuccessful attempt to dispel or melt the icicles automatically triggers the attack."}'::jsonb),
('dnd35.frostburn.spell.frostburn-ivory-flesh','Ivory Flesh','Ivory Flesh','The subject’s flesh and all his equipment turn white, granting him a +5 circumstance bonus on Hide checks in heavy snow or ice areas. In any nonwhite-hued area (including ebony ice), ivory flesh instead incurs a –5 penalty on Hide checks.',1,false,false,ARRAY['bard','druid','ranger']::text[],'1 standard action','Touch','Creature touched','1 hour/level','Will negates (harmless)',ARRAY['Transmutation']::text[],'v35-frostburn','D&D 3.5 — Frostburn',88,'dnd35','{"id":"frostburn-ivory-flesh","name":"Ivory Flesh","school":"Transmutation","subschool":null,"descriptors":[],"schoolLine":"Transmutation","levels":{"bard":1,"druid":1,"ranger":1},"levelLine":"Bard 1, druid 1, ranger 1","components":"V, S","castingTime":"1 standard action","range":"Touch","duration":"1 hour/level","savingThrow":"Will negates (harmless)","spellResistance":"Yes (harmless)","targetLabel":"Target","target":"Creature touched","description":"The subject’s flesh and all his equipment turn white, granting him a +5 circumstance bonus on Hide checks in heavy snow or ice areas. In any nonwhite-hued area (including ebony ice), ivory flesh instead incurs a –5 penalty on Hide checks."}'::jsonb),
('dnd35.frostburn.spell.frostburn-leomunds-tiny-igloo','Leomund’s Tiny Igloo','Leomund’s Tiny Igloo','You create a small domed snow house with a single entrance passage. Up to one Large or three Medium or twelve Small creatures can fit into the igloo with you; they can freely pass into and out of the hut without harming it. The temperature inside the igloo is magically warm, at exactly 50° F, and the walls do not melt. The igloo has two features that help arctic survival: a sleeping platform and a lamp. The snow sleeping platform takes advantage of the warm air trapped below the low roof, generated by body heat and a stone lamp. The magical smokeless lamp provides heat for comfort and for cooking. The igloo also provides protection against the elements, such as wind, snow, and hail. The igloo withstands any wind of less than hurricane force, but a hurricane (75+ mph wind speed) or greater force destroys it. The loose-packed snow of the igloo has a hardness of 0, and 3 hp per inch of thickness.
 Material Component: A small dollop of seal fat or caribou fat.',2,false,false,ARRAY['sorcerer/wizard']::text[],'1 standard action','5 ft.','5-ft.-radius sphere, with 1-in.- thick wall/level centered on your location','2 hours/level (D)','None',ARRAY['Evocation','Cold']::text[],'v35-frostburn','D&D 3.5 — Frostburn',88,'dnd35','{"id":"frostburn-leomunds-tiny-igloo","name":"Leomund’s Tiny Igloo","school":"Evocation","subschool":null,"descriptors":["Cold"],"schoolLine":"Evocation [Cold]","levels":{"sorcerer/wizard":2},"levelLine":"Sorcerer/wizard 2","components":"V, S, M","castingTime":"1 standard action","range":"5 ft.","duration":"2 hours/level (D)","savingThrow":"None","spellResistance":"No","targetLabel":"Effect","target":"5-ft.-radius sphere, with 1-in.- thick wall/level centered on your location","description":"You create a small domed snow house with a single entrance passage. Up to one Large or three Medium or twelve Small creatures can fit into the igloo with you; they can freely pass into and out of the hut without harming it. The temperature inside the igloo is magically warm, at exactly 50° F, and the walls do not melt. The igloo has two features that help arctic survival: a sleeping platform and a lamp. The snow sleeping platform takes advantage of the warm air trapped below the low roof, generated by body heat and a stone lamp. The magical smokeless lamp provides heat for comfort and for cooking. The igloo also provides protection against the elements, such as wind, snow, and hail. The igloo withstands any wind of less than hurricane force, but a hurricane (75+ mph wind speed) or greater force destroys it. The loose-packed snow of the igloo has a hardness of 0, and 3 hp per inch of thickness.\n Material Component: A small dollop of seal fat or caribou fat."}'::jsonb),
('dnd35.frostburn.spell.frostburn-mantle-of-the-icy-soul','Mantle of the Icy Soul','Mantle of the Icy Soul','Mantle of the icy soul permanently adds the cold subtype to the targeted creature. The skin, hair, and scales of the creature subtly change color to take on an icy blue tint, and its breath does not frost in cold temperatures. The recipient of a mantle of the icy soul gains immunity to cold, but has vulnerability to fire, which means that it takes half again as much damage (+50%) as normal from fire regardless of whether a saving throw is allowed, or if it is a success or a failure. There is no change to the creature’s Challenge Rating or effective character level. The effects of this spell can be removed by a limited wish or wish.
 Material Component: A handful of ice or snow that must be pressed to the target’s body. XP Cost: 2,000.',5,false,false,ARRAY['cleric','druid']::text[],'1 standard action','Touch','Creature touched','Instantaneous','Will negates (harmless)',ARRAY['Transmutation']::text[],'v35-frostburn','D&D 3.5 — Frostburn',88,'dnd35','{"id":"frostburn-mantle-of-the-icy-soul","name":"Mantle of the Icy Soul","school":"Transmutation","subschool":null,"descriptors":[],"schoolLine":"Transmutation","levels":{"cleric":6,"druid":5},"levelLine":"Cleric 6, druid 5","components":"V, S, M, XP","castingTime":"1 standard action","range":"Touch","duration":"Instantaneous","savingThrow":"Will negates (harmless)","spellResistance":"Yes (harmless)","targetLabel":"Area","target":"Creature touched","description":"Mantle of the icy soul permanently adds the cold subtype to the targeted creature. The skin, hair, and scales of the creature subtly change color to take on an icy blue tint, and its breath does not frost in cold temperatures. The recipient of a mantle of the icy soul gains immunity to cold, but has vulnerability to fire, which means that it takes half again as much damage (+50%) as normal from fire regardless of whether a saving throw is allowed, or if it is a success or a failure. There is no change to the creature’s Challenge Rating or effective character level. The effects of this spell can be removed by a limited wish or wish.\n Material Component: A handful of ice or snow that must be pressed to the target’s body. XP Cost: 2,000."}'::jsonb),
('dnd35.frostburn.spell.frostburn-meld-into-ice','Meld into Ice','Meld into Ice','Meld into ice enables you to meld your body and possessions into a single block of ice. The ice must be large enough to accommodate your body in all three dimensions. When the casting is complete, you and not more than 100 pounds of nonliving gear merge with the ice. If either condition is violated, the spell fails and is wasted. While in the ice, you remain in contact, however tenuous, with the face of the ice through which you melded. You remain aware of the passage of time and can cast spells on yourself while hiding in the ice. Nothing that goes on outside the ice can be seen, but you can still hear what happens around you. Minor physical damage to the ice does not harm you, but its partial destruction (to the extent that you no longer fit within it) expels you and deals you 5d6 points of damage. The ice’s complete destruction (by damage or thawing) expels you and slays you instantly unless you make a DC 18 Fortitude save. Any time before the duration expires, you can step out of the ice through the surface that you entered. If the spell’s duration expires or the effect is dispelled before you voluntarily exit the stone, you are violently expelled and take 5d6 points of damage. The following spells harm you if cast upon the ice that you are occupying: Ice to flesh expels you and deals you 5d6 points of damage. Ice shape deals you 3d6 points of damage but does not expel you. Thaw expels you and then slays you instantly unless you make a DC 18 Fortitude save, in which case you are merely expelled. Finally, pass through ice expels you without damage.',3,false,false,ARRAY['cleric','druid']::text[],'1 standard action','Personal','You','10 min./level',null,ARRAY['Transmutation']::text[],'v35-frostburn','D&D 3.5 — Frostburn',88,'dnd35','{"id":"frostburn-meld-into-ice","name":"Meld into Ice","school":"Transmutation","subschool":null,"descriptors":[],"schoolLine":"Transmutation","levels":{"cleric":3,"druid":3},"levelLine":"Cleric 3, druid 3","components":"V, S, DF","castingTime":"1 standard action","range":"Personal","duration":"10 min./level","targetLabel":"Target","target":"You","description":"Meld into ice enables you to meld your body and possessions into a single block of ice. The ice must be large enough to accommodate your body in all three dimensions. When the casting is complete, you and not more than 100 pounds of nonliving gear merge with the ice. If either condition is violated, the spell fails and is wasted. While in the ice, you remain in contact, however tenuous, with the face of the ice through which you melded. You remain aware of the passage of time and can cast spells on yourself while hiding in the ice. Nothing that goes on outside the ice can be seen, but you can still hear what happens around you. Minor physical damage to the ice does not harm you, but its partial destruction (to the extent that you no longer fit within it) expels you and deals you 5d6 points of damage. The ice’s complete destruction (by damage or thawing) expels you and slays you instantly unless you make a DC 18 Fortitude save. Any time before the duration expires, you can step out of the ice through the surface that you entered. If the spell’s duration expires or the effect is dispelled before you voluntarily exit the stone, you are violently expelled and take 5d6 points of damage. The following spells harm you if cast upon the ice that you are occupying: Ice to flesh expels you and deals you 5d6 points of damage. Ice shape deals you 3d6 points of damage but does not expel you. Thaw expels you and then slays you instantly unless you make a DC 18 Fortitude save, in which case you are merely expelled. Finally, pass through ice expels you without damage."}'::jsonb),
('dnd35.frostburn.spell.frostburn-mindfrost','Mindfrost','Mindfrost','This spell freezes the mental pathways of living creatures, dealing 5d6 points of cold damage and 1d4 points of Intelligence damage.
 Material Component: A small stone covered in frost.',4,false,false,ARRAY['sorcerer/wizard']::text[],'1 standard action','Close (25 ft. + 5 ft./2 levels)','One creature','Instantaneous','Fortitude half',ARRAY['Necromancy','Cold']::text[],'v35-frostburn','D&D 3.5 — Frostburn',88,'dnd35','{"id":"frostburn-mindfrost","name":"Mindfrost","school":"Necromancy","subschool":null,"descriptors":["Cold"],"schoolLine":"Necromancy [Cold]","levels":{"sorcerer/wizard":4},"levelLine":"Sorcerer/wizard 4","components":"V, S, M","castingTime":"1 standard action","range":"Close (25 ft. + 5 ft./2 levels)","duration":"Instantaneous","savingThrow":"Fortitude half","spellResistance":"Yes","targetLabel":"Target","target":"One creature","description":"This spell freezes the mental pathways of living creatures, dealing 5d6 points of cold damage and 1d4 points of Intelligence damage.\n Material Component: A small stone covered in frost."}'::jsonb),
('dnd35.frostburn.spell.frostburn-move-snow-and-ice','Move Snow and Ice','Move Snow and Ice','This spell moves snow and ice. The area to be affected determines the casting time. For every 150-foot square (up to 10 feet deep), casting takes 10 minutes. The maximum area, 750 feet by 750 feet, takes 4 hours and 10 minutes to move. This spell does not violently break the surface of snow or ice. Instead, it creates wavelike crests and troughs, with glacierlike fluidity until the desired result is achieved. Trees, structures, rock formations, and such are mostly unaffected except for changes in elevation and relative topography. The spell cannot be used for tunnel-ing and is generally too slow to trap or bury creatures. Its primary use is for digging or adjusting terrain contours before a battle. This spell has no effect on ice creatures.
 Material Component: A mixture of snow and ice in a small bag, and an iron blade.',6,false,false,ARRAY['druid','sorcerer/wizard']::text[],'See text','Long (400 ft. + 40 ft./level)','Snow or ice in an area up to 750 ft. square and up to 10 ft. deep (S)','Instantaneous','None',ARRAY['Transmutation','Cold','Ice']::text[],'v35-frostburn','D&D 3.5 — Frostburn',88,'dnd35','{"id":"frostburn-move-snow-and-ice","name":"Move Snow and Ice","school":"Transmutation","subschool":null,"descriptors":["Cold","Ice"],"schoolLine":"Transmutation [Cold, Ice]","levels":{"druid":6,"sorcerer/wizard":6},"levelLine":"Druid 6, sorcerer/wizard 6","components":"V, S, M","castingTime":"See text","range":"Long (400 ft. + 40 ft./level)","duration":"Instantaneous","savingThrow":"None","spellResistance":"No","targetLabel":"Area","target":"Snow or ice in an area up to 750 ft. square and up to 10 ft. deep (S)","description":"This spell moves snow and ice. The area to be affected determines the casting time. For every 150-foot square (up to 10 feet deep), casting takes 10 minutes. The maximum area, 750 feet by 750 feet, takes 4 hours and 10 minutes to move. This spell does not violently break the surface of snow or ice. Instead, it creates wavelike crests and troughs, with glacierlike fluidity until the desired result is achieved. Trees, structures, rock formations, and such are mostly unaffected except for changes in elevation and relative topography. The spell cannot be used for tunnel-ing and is generally too slow to trap or bury creatures. Its primary use is for digging or adjusting terrain contours before a battle. This spell has no effect on ice creatures.\n Material Component: A mixture of snow and ice in a small bag, and an iron blade."}'::jsonb),
('dnd35.frostburn.spell.frostburn-numbing-sphere','Numbing Sphere','Numbing Sphere','A sphere of intense cold energy rolls in whichever direction you point and damages those it strikes. It moves 30 feet per round. As part of this movement, it can ascend or jump up to 30 feet to strike a target. If it enters a space with a creature, it stops moving for the round and deals 1d6 points of cold damage as well as 1d4 points of Dexterity damage to that creature, though a successful Reflex save negates both the cold damage and Dexterity damage. A numbing sphere rolls over barriers less than 4 feet tall, such as furniture and low walls. It instantly freezes water it encounters in 5-foot-cube sections, creating chunks of ice in large bodies of water. The sphere moves as long as you actively direct it (a move action for you); otherwise, it merely remains at rest. The sphere can be destroyed by attacks directed against it. It has 10 hit points and damage reduction 5/–. The surface of the sphere has a spongy, yielding consistency and so does not cause damage except by extreme cold. It cannot push aside unwilling creatures or batter down large obstacles. A numbing sphere winks out if it exceeds the spell’s range. Arcane Material Component: A bit of sponge and a drop of water.',2,false,false,ARRAY['druid','sorcerer/wizard']::text[],'1 standard action','Medium (100 ft. + 10 ft./level)','5-ft.-diameter sphere','1 round/level','Reflex negates',ARRAY['Evocation','Cold']::text[],'v35-frostburn','D&D 3.5 — Frostburn',88,'dnd35','{"id":"frostburn-numbing-sphere","name":"Numbing Sphere","school":"Evocation","subschool":null,"descriptors":["Cold"],"schoolLine":"Evocation [Cold]","levels":{"druid":2,"sorcerer/wizard":2},"levelLine":"Druid 2, sorcerer/wizard 2","components":"V, S, M/DF","castingTime":"1 standard action","range":"Medium (100 ft. + 10 ft./level)","duration":"1 round/level","savingThrow":"Reflex negates","spellResistance":"Yes","targetLabel":"Effect","target":"5-ft.-diameter sphere","description":"A sphere of intense cold energy rolls in whichever direction you point and damages those it strikes. It moves 30 feet per round. As part of this movement, it can ascend or jump up to 30 feet to strike a target. If it enters a space with a creature, it stops moving for the round and deals 1d6 points of cold damage as well as 1d4 points of Dexterity damage to that creature, though a successful Reflex save negates both the cold damage and Dexterity damage. A numbing sphere rolls over barriers less than 4 feet tall, such as furniture and low walls. It instantly freezes water it encounters in 5-foot-cube sections, creating chunks of ice in large bodies of water. The sphere moves as long as you actively direct it (a move action for you); otherwise, it merely remains at rest. The sphere can be destroyed by attacks directed against it. It has 10 hit points and damage reduction 5/–. The surface of the sphere has a spongy, yielding consistency and so does not cause damage except by extreme cold. It cannot push aside unwilling creatures or batter down large obstacles. A numbing sphere winks out if it exceeds the spell’s range. Arcane Material Component: A bit of sponge and a drop of water."}'::jsonb),
('dnd35.frostburn.spell.frostburn-obedient-avalanche','Obedient Avalanche','Obedient Avalanche','Obedient Avalanche Half impact and full cold damage (Reflex negates) If save fails, +13 bull rush away from center Light snow 1d8 / 2 caster levels plus 1d6 cold / 2 caster levels If save fails, creature is buried. + Heavy snow One square equals 5 feet You summon an avalanche of snow out of a rift in midair, burying your foes and sending them to a frosty death. The obedient avalanche affects creatures differently, depending on where they are in relation to the avalanche. Within 20 Feet of the Center Point: Creatures take 1d8 points of damage per two caster levels (maximum 10d8) and an additional 1d6 points of cold damage per two caster levels. Creatures who fail their saves are also buried (as described in Avalanches, page 90 of the Dungeon Master’s Guide). All squares within 20 feet of the center point are covered in heavy snow (see page 94 of the Dungeon Master’s Guide), which persists as long as ordinary snow would. Between 20 Feet and 40 Feet of the Center Point: Creatures take half as much damage from the impact of the avalanche as the creatures nearer the center point took (Reflex save negates). Creatures who fail their saves must also resist the force of the snow moving past them as if they were being bull rushed. The snow has a +13 bonus (+5 for effective Strength of 20 and +8 for effectively being Huge) on the bull rush check, and it pushes characters away from the center point of the spell. All squares in the 20-foot to 40-foot ring are covered in light snow, which persists as long as ordinary snow would. Terrain and Structures: The avalanche uproots small trees and other vegetation automatically, and it leaves a trail of light rubble (as described on page 91 of the Dungeon Master’s Guide) even after the snow melts. Structures struck by an obedient avalanche take 1d610 points of damage. The obedient avalanche extinguishes all flames, whether normal or magical, it touches.',9,false,false,ARRAY['cold']::text[],'1 standard action','Medium (100 ft. + 10 ft./level)','20-ft.-radius av a lanche of snow, centered anywhere within range; see text','Instantaneous','Reflex half; see text',ARRAY['Conjuration','Cold']::text[],'v35-frostburn','D&D 3.5 — Frostburn',88,'dnd35','{"id":"frostburn-obedient-avalanche","name":"Obedient Avalanche","school":"Conjuration","subschool":"Creation","descriptors":["Cold"],"schoolLine":"Conjuration (Creation) [Cold]","levels":{"cold":9},"levelLine":"Cold 9","components":"V, S","castingTime":"1 standard action","range":"Medium (100 ft. + 10 ft./level)","duration":"Instantaneous","savingThrow":"Reflex half; see text","spellResistance":"No","targetLabel":"Effect","target":"20-ft.-radius av a lanche of snow, centered anywhere within range; see text","description":"Obedient Avalanche Half impact and full cold damage (Reflex negates) If save fails, +13 bull rush away from center Light snow 1d8 / 2 caster levels plus 1d6 cold / 2 caster levels If save fails, creature is buried. + Heavy snow One square equals 5 feet You summon an avalanche of snow out of a rift in midair, burying your foes and sending them to a frosty death. The obedient avalanche affects creatures differently, depending on where they are in relation to the avalanche. Within 20 Feet of the Center Point: Creatures take 1d8 points of damage per two caster levels (maximum 10d8) and an additional 1d6 points of cold damage per two caster levels. Creatures who fail their saves are also buried (as described in Avalanches, page 90 of the Dungeon Master’s Guide). All squares within 20 feet of the center point are covered in heavy snow (see page 94 of the Dungeon Master’s Guide), which persists as long as ordinary snow would. Between 20 Feet and 40 Feet of the Center Point: Creatures take half as much damage from the impact of the avalanche as the creatures nearer the center point took (Reflex save negates). Creatures who fail their saves must also resist the force of the snow moving past them as if they were being bull rushed. The snow has a +13 bonus (+5 for effective Strength of 20 and +8 for effectively being Huge) on the bull rush check, and it pushes characters away from the center point of the spell. All squares in the 20-foot to 40-foot ring are covered in light snow, which persists as long as ordinary snow would. Terrain and Structures: The avalanche uproots small trees and other vegetation automatically, and it leaves a trail of light rubble (as described on page 91 of the Dungeon Master’s Guide) even after the snow melts. Structures struck by an obedient avalanche take 1d610 points of damage. The obedient avalanche extinguishes all flames, whether normal or magical, it touches."}'::jsonb),
('dnd35.frostburn.spell.frostburn-obscuring-snow','Obscuring Snow','Obscuring Snow','A swirling snow vapor arises around you, and follows you from that point on. The snow obscures all sight, including darkvision, beyond 5 feet. A creature 5 feet away has concealment (attacks have a 20% miss chance). Creatures farther away have total concealment (50% miss chance, and the attacker cannot use sight to locate the target). A strong wind (21+ mph) disperses the snow in 4 rounds. A very strong wind (31+ mph) disperses the snow in 1 round. A fireball, flame strike, or similar spell burns away the snow in the explosive or fiery spell’s area. A wall of fire burns away the snow in the area into which it deals damage. This spell does not function underwater. Creatures with snowsight are immune to the effects of this spell.',2,false,false,ARRAY['cleric','druid','sorcerer/wizard']::text[],'1 standard action','30 ft.','Cloud spreads in 30-ft.-radius from you, 30 ft. high','1 hour/level','None',ARRAY['Conjuration','Air','Cold']::text[],'v35-frostburn','D&D 3.5 — Frostburn',88,'dnd35','{"id":"frostburn-obscuring-snow","name":"Obscuring Snow","school":"Conjuration","subschool":"Creation","descriptors":["Air","Cold"],"schoolLine":"Conjuration (Creation) [Air, Cold]","levels":{"cleric":2,"druid":2,"sorcerer/wizard":2},"levelLine":"Cleric 2, druid 2, sorcerer/ wizard 2","components":"V, S","castingTime":"1 standard action","range":"30 ft.","duration":"1 hour/level","savingThrow":"None","spellResistance":"No","targetLabel":"Effect","target":"Cloud spreads in 30-ft.-radius from you, 30 ft. high","description":"A swirling snow vapor arises around you, and follows you from that point on. The snow obscures all sight, including darkvision, beyond 5 feet. A creature 5 feet away has concealment (attacks have a 20% miss chance). Creatures farther away have total concealment (50% miss chance, and the attacker cannot use sight to locate the target). A strong wind (21+ mph) disperses the snow in 4 rounds. A very strong wind (31+ mph) disperses the snow in 1 round. A fireball, flame strike, or similar spell burns away the snow in the explosive or fiery spell’s area. A wall of fire burns away the snow in the area into which it deals damage. This spell does not function underwater. Creatures with snowsight are immune to the effects of this spell."}'::jsonb),
('dnd35.frostburn.spell.frostburn-pass-through-ice','Pass through Ice','Pass through Ice','The transmuted creature is able to pass through ice or snow as easily as water, but not through stone or frozen mud. The creature moves at a speed of 15 feet and can rise or sink into ice at a rate of 5 feet per round. When a pass through ice spell ends, the affected creature is ejected out to the nearest ice surface. If someone dispels pass through ice or you dismiss it while a creature is still in the ice, the creatures may be trapped in the ice unless they can reach the nearest surface within a single round of movement. Creatures trapped act as if caught in an entomb spell.',5,false,false,ARRAY['cleric','druid']::text[],'1 standard action','Touch','Creature touched','1 round/level (D)','Yes (harmless)',ARRAY['Transmutation']::text[],'v35-frostburn','D&D 3.5 — Frostburn',88,'dnd35','{"id":"frostburn-pass-through-ice","name":"Pass through Ice","school":"Transmutation","subschool":null,"descriptors":[],"schoolLine":"Transmutation","levels":{"cleric":5,"druid":5},"levelLine":"Cleric 5, druid 5","components":"V, S, DF","castingTime":"1 standard action","range":"Touch","duration":"1 round/level (D)","savingThrow":"Yes (harmless)","spellResistance":"Yes (harmless)","targetLabel":"Target","target":"Creature touched","description":"The transmuted creature is able to pass through ice or snow as easily as water, but not through stone or frozen mud. The creature moves at a speed of 15 feet and can rise or sink into ice at a rate of 5 feet per round. When a pass through ice spell ends, the affected creature is ejected out to the nearest ice surface. If someone dispels pass through ice or you dismiss it while a creature is still in the ice, the creatures may be trapped in the ice unless they can reach the nearest surface within a single round of movement. Creatures trapped act as if caught in an entomb spell."}'::jsonb),
('dnd35.frostburn.spell.frostburn-raise-ice-forest','Raise Ice Forest','Raise Ice Forest','Immediately after casting this spell, ice trees erupt from frostfell regions within the spell’s area. The ice trees resemble any type of tree designated by the caster (deciduous, evergreen, oak, or others). Trees have 5-foot-diameter trunks and rise to a height of 15 feet. Three trees appear in each Snow wave 20-foot-square frostfell region in the area. Ice Tree: 5 feet thick; hardness 8; hp 80; break DC 45; Climb DC 20.',7,false,false,ARRAY['druid']::text[],'1 round','Long (400 ft. + 40 ft./level)','20-ft. square of snow/level','Permanent','None',ARRAY['Conjuration','Cold']::text[],'v35-frostburn','D&D 3.5 — Frostburn',88,'dnd35','{"id":"frostburn-raise-ice-forest","name":"Raise Ice Forest","school":"Conjuration","subschool":"Creation","descriptors":["Cold"],"schoolLine":"Conjuration (Creation) [Cold]","levels":{"druid":7},"levelLine":"Druid 7","components":"V, S, DF, Frostfell","castingTime":"1 round","range":"Long (400 ft. + 40 ft./level)","duration":"Permanent","savingThrow":"None","spellResistance":"No","targetLabel":"Area","target":"20-ft. square of snow/level","description":"Immediately after casting this spell, ice trees erupt from frostfell regions within the spell’s area. The ice trees resemble any type of tree designated by the caster (deciduous, evergreen, oak, or others). Trees have 5-foot-diameter trunks and rise to a height of 15 feet. Three trees appear in each Snow wave 20-foot-square frostfell region in the area. Ice Tree: 5 feet thick; hardness 8; hp 80; break DC 45; Climb DC 20."}'::jsonb),
('dnd35.frostburn.spell.frostburn-shivering-touch','Shivering Touch','Shivering Touch','On a successful melee touch attack, you instantly suck the heat from the target’s body, rendering it numb. The target takes 3d6 points of Dexterity damage. Creatures with the cold subtype are immune to the effects of shivering touch.',3,false,false,ARRAY['cleric','sorcerer/wizard']::text[],'1 standard action','Touch','Creature touched','1 round/level','None',ARRAY['Necromancy','Cold']::text[],'v35-frostburn','D&D 3.5 — Frostburn',88,'dnd35','{"id":"frostburn-shivering-touch","name":"Shivering Touch","school":"Necromancy","subschool":null,"descriptors":["Cold"],"schoolLine":"Necromancy [Cold]","levels":{"cleric":3,"sorcerer/wizard":3},"levelLine":"Cleric 3, sorcerer/wizard 3","components":"V, S","castingTime":"1 standard action","range":"Touch","duration":"1 round/level","savingThrow":"None","spellResistance":"Yes","targetLabel":"Target","target":"Creature touched","description":"On a successful melee touch attack, you instantly suck the heat from the target’s body, rendering it numb. The target takes 3d6 points of Dexterity damage. Creatures with the cold subtype are immune to the effects of shivering touch."}'::jsonb),
('dnd35.frostburn.spell.frostburn-shivering-touch-lesser','Shivering Touch, Lesser','Shivering Touch, Lesser','Your successful melee touch attack delivers a bitter chill to the target, causing it to shiver uncontrollably for the duration of the spell. Shivering characters take 1d6 points of Dexterity damage. Creatures with the cold subtype are immune to the effects of lesser shivering touch.',1,false,false,ARRAY['cleric','sorcerer/wizard']::text[],'1 standard action','Touch','Creature touched','1 round/level','None',ARRAY['Necromancy','Cold']::text[],'v35-frostburn','D&D 3.5 — Frostburn',88,'dnd35','{"id":"frostburn-shivering-touch-lesser","name":"Shivering Touch, Lesser","school":"Necromancy","subschool":null,"descriptors":["Cold"],"schoolLine":"Necromancy [Cold]","levels":{"cleric":1,"sorcerer/wizard":1},"levelLine":"Cleric 1, sorcerer/wizard 1","components":"V, S","castingTime":"1 standard action","range":"Touch","duration":"1 round/level","savingThrow":"None","spellResistance":"Yes","targetLabel":"Target","target":"Creature touched","description":"Your successful melee touch attack delivers a bitter chill to the target, causing it to shiver uncontrollably for the duration of the spell. Shivering characters take 1d6 points of Dexterity damage. Creatures with the cold subtype are immune to the effects of lesser shivering touch."}'::jsonb),
('dnd35.frostburn.spell.frostburn-snow-walk','Snow Walk','Snow Walk','The subjects can walk on top of snow rather than through it, avoiding the usual movement penalties and leaving neither footprints nor scent. Tracking the subject is impossible by nonmagical means, and the gliding along the surface of the snow adds 10 feet to the target creature’s land speed. (This adjustment is treated as an enhancement bonus.)',2,false,false,ARRAY['druid','ranger','winter']::text[],'1 standard action','Touch','One creature/level touched','10 min./level','Will negates (harmless)',ARRAY['Transmutation']::text[],'v35-frostburn','D&D 3.5 — Frostburn',88,'dnd35','{"id":"frostburn-snow-walk","name":"Snow Walk","school":"Transmutation","subschool":null,"descriptors":[],"schoolLine":"Transmutation","levels":{"druid":2,"ranger":2,"winter":2},"levelLine":"Druid 2, ranger 2, Winter 2","components":"V, S, DF","castingTime":"1 standard action","range":"Touch","duration":"10 min./level","savingThrow":"Will negates (harmless)","spellResistance":"Yes (harmless)","targetLabel":"Targets","target":"One creature/level touched","description":"The subjects can walk on top of snow rather than through it, avoiding the usual movement penalties and leaving neither footprints nor scent. Tracking the subject is impossible by nonmagical means, and the gliding along the surface of the snow adds 10 feet to the target creature’s land speed. (This adjustment is treated as an enhancement bonus.)"}'::jsonb),
('dnd35.frostburn.spell.frostburn-snow-wave','Snow Wave','Snow Wave','You create a wave of snow that knocks creatures in its path prone and deals 4d6 points of crushing damage plus 1d6 points of cold damage to targets caught in the cone. Any creature making a Fortitude saving throw takes only half the cold damage from a snow wave; however, it still takes the full crushing damage. In addition, anyone in the area must make a Reflex save or be knocked prone.',6,false,false,ARRAY['druid']::text[],'1 round','30 ft.','Cone-shaped burst','Instantaneous','Fortitude half and Reflex negates; see text',ARRAY['Conjuration','Cold']::text[],'v35-frostburn','D&D 3.5 — Frostburn',88,'dnd35','{"id":"frostburn-snow-wave","name":"Snow Wave","school":"Conjuration","subschool":null,"descriptors":["Cold"],"schoolLine":"Conjuration [Cold]","levels":{"druid":6},"levelLine":"Druid 6","components":"V, S","castingTime":"1 round","range":"30 ft.","duration":"Instantaneous","savingThrow":"Fortitude half and Reflex negates; see text","spellResistance":"No","targetLabel":"Area","target":"Cone-shaped burst","description":"You create a wave of snow that knocks creatures in its path prone and deals 4d6 points of crushing damage plus 1d6 points of cold damage to targets caught in the cone. Any creature making a Fortitude saving throw takes only half the cold damage from a snow wave; however, it still takes the full crushing damage. In addition, anyone in the area must make a Reflex save or be knocked prone."}'::jsonb),
('dnd35.frostburn.spell.frostburn-snowdrift','Snowdrift','Snowdrift','You can form existing snow into any shape that suits your purpose. For example, you can make a snowbank for concealment, sculpt a snow statue or idol, open a tunnel in deep snow, or simply cover a set of tracks. Snowdrift also permits you to raise snowy barriers around a door or house to prevent vision in or out, or to clog a chimney with snow. Snow cannot be made into weapons with this spell, and snowdrift does not affect solid ice in any form. Arcane Material Component: A pinch of white flour.',1,false,false,ARRAY['druid','sorcerer/wizard']::text[],'1 standard action','Touch','Snow touched, up to 10 cu. ft. +1 cu. ft./level','Instantaneous','None',ARRAY['Transmutation']::text[],'v35-frostburn','D&D 3.5 — Frostburn',88,'dnd35','{"id":"frostburn-snowdrift","name":"Snowdrift","school":"Transmutation","subschool":null,"descriptors":[],"schoolLine":"Transmutation","levels":{"druid":1,"sorcerer/wizard":1},"levelLine":"Druid 1, sorcerer/ wizard 1","components":"V, S, M/DF","castingTime":"1 standard action","range":"Touch","duration":"Instantaneous","savingThrow":"None","spellResistance":"No","targetLabel":"Target","target":"Snow touched, up to 10 cu. ft. +1 cu. ft./level","description":"You can form existing snow into any shape that suits your purpose. For example, you can make a snowbank for concealment, sculpt a snow statue or idol, open a tunnel in deep snow, or simply cover a set of tracks. Snowdrift also permits you to raise snowy barriers around a door or house to prevent vision in or out, or to clog a chimney with snow. Snow cannot be made into weapons with this spell, and snowdrift does not affect solid ice in any form. Arcane Material Component: A pinch of white flour."}'::jsonb),
('dnd35.frostburn.spell.frostburn-snowsight','Snowsight','Snowsight','The subject gains the ability to see to the normal limits of its vision even in whiteout conditions, and ignores all penalties due to snow glare and snow blindness. Snowsight is no better than normal vision. During daylight, this usually means the subject can see to the horizon; at night, vision is restricted to ambient light or darkvision as appropriate for the subject creature. Snowsight does not grant creatures the ability to see in darkness.',1,false,false,ARRAY['druid','ranger','winter']::text[],'1 standard action','Touch','Creature touched','1 hour/level','None',ARRAY['Transmutation']::text[],'v35-frostburn','D&D 3.5 — Frostburn',88,'dnd35','{"id":"frostburn-snowsight","name":"Snowsight","school":"Transmutation","subschool":null,"descriptors":[],"schoolLine":"Transmutation","levels":{"druid":1,"ranger":1,"winter":1},"levelLine":"Druid 1, ranger 1, Winter 1","components":"V, S, DF","castingTime":"1 standard action","range":"Touch","duration":"1 hour/level","savingThrow":"None","spellResistance":"Yes (harmless)","targetLabel":"Target","target":"Creature touched","description":"The subject gains the ability to see to the normal limits of its vision even in whiteout conditions, and ignores all penalties due to snow glare and snow blindness. Snowsight is no better than normal vision. During daylight, this usually means the subject can see to the horizon; at night, vision is restricted to ambient light or darkvision as appropriate for the subject creature. Snowsight does not grant creatures the ability to see in darkness."}'::jsonb),
('dnd35.frostburn.spell.frostburn-snowsong','Snowsong','Snowsong','Snowsong fills the area with a soft snowfall that melts and evaporates on contact with anything solid. When you cast the spell, you must designate all creatures in the area as either allies or enemies. While the snow falls, allies in the area hear a soft, lilting song that bolsters their spirits and confidence. At the same time, as the snow strikes their bodies, it melts and washes away scars, wounds, and filth. Allies under the effect of the snow gain a +4 morale bonus to Charisma and attack rolls, and a +4 insight bonus to Armor Class. In addition, the snow imparts fast healing 1 and resistance to cold 15 to all affected allies. All melee attacks made by allies in the snowsong deal an additional 1d6 points of cold damage. Enemies in the area of a snowsong have a much different experience. To them, the snow is bitterly cold and leaves scabs and angry welts when it lands their skin. They perceive the music as a discordant jangle of crashes, scrapes, and howls. As long as they remain in the area, they suffer a 20% chance of spell failure (for both divine and arcane spells) when casting any spells with a verbal component. Enemies can resist the effects of a snowsong with a successful Will saving throw. These benefits remain in place as long as the spell persists and as long as the target remains in the spell’s area. If a creature leaves the spell’s area, all effects end for that creature until it returns to the snowsong’s area.',6,false,false,ARRAY['bard']::text[],'1 standard action','30 ft.','30-ft. radius centered on you','10 min./level','Will negates',ARRAY['Enchantment','Mind-Affecting']::text[],'v35-frostburn','D&D 3.5 — Frostburn',88,'dnd35','{"id":"frostburn-snowsong","name":"Snowsong","school":"Enchantment","subschool":"Compulsion","descriptors":["Mind-Affecting"],"schoolLine":"Enchantment (Compulsion) [Mind-Affecting]","levels":{"bard":6},"levelLine":"Bard 6","components":"V","castingTime":"1 standard action","range":"30 ft.","duration":"10 min./level","savingThrow":"Will negates","spellResistance":"Yes","targetLabel":"Area","target":"30-ft. radius centered on you","description":"Snowsong fills the area with a soft snowfall that melts and evaporates on contact with anything solid. When you cast the spell, you must designate all creatures in the area as either allies or enemies. While the snow falls, allies in the area hear a soft, lilting song that bolsters their spirits and confidence. At the same time, as the snow strikes their bodies, it melts and washes away scars, wounds, and filth. Allies under the effect of the snow gain a +4 morale bonus to Charisma and attack rolls, and a +4 insight bonus to Armor Class. In addition, the snow imparts fast healing 1 and resistance to cold 15 to all affected allies. All melee attacks made by allies in the snowsong deal an additional 1d6 points of cold damage. Enemies in the area of a snowsong have a much different experience. To them, the snow is bitterly cold and leaves scabs and angry welts when it lands their skin. They perceive the music as a discordant jangle of crashes, scrapes, and howls. As long as they remain in the area, they suffer a 20% chance of spell failure (for both divine and arcane spells) when casting any spells with a verbal component. Enemies can resist the effects of a snowsong with a successful Will saving throw. These benefits remain in place as long as the spell persists and as long as the target remains in the spell’s area. If a creature leaves the spell’s area, all effects end for that creature until it returns to the snowsong’s area."}'::jsonb),
('dnd35.frostburn.spell.frostburn-summon-giants','Summon Giants','Summon Giants','You summon one or more giants that attack your enemies. They appear where you designate and act immediately, on your turn. The giants attack your opponents to the best of their ability. If you speak Giant, you can direct the giants not to attack, to attack particular enemies, or to perform other actions. Summoned giants act normally on the last round of the spell and disappear at the end of their turn. Choose a giant kind from the table below. Type Number Align Hill giants, fiendish 3 CE Stone giants, celestial 2 N or fiendish Frost giant, fiendish 1 CE Fire giant, fiendish 1 LE Focus: A lock of hair from a giant of the desired kind.',8,false,false,ARRAY['cleric','winter']::text[],'1 full round','Close (25 ft. + 5 ft./2 levels)','One or more summoned creatures','1 round/level (D)','None',ARRAY['Conjuration']::text[],'v35-frostburn','D&D 3.5 — Frostburn',88,'dnd35','{"id":"frostburn-summon-giants","name":"Summon Giants","school":"Conjuration","subschool":"Summoning","descriptors":[],"schoolLine":"Conjuration (Summoning)","levels":{"cleric":8,"winter":8},"levelLine":"Cleric 8, Winter 8","components":"V, S, F/DF","castingTime":"1 full round","range":"Close (25 ft. + 5 ft./2 levels)","duration":"1 round/level (D)","savingThrow":"None","spellResistance":"No","targetLabel":"Effect","target":"One or more summoned creatures","description":"You summon one or more giants that attack your enemies. They appear where you designate and act immediately, on your turn. The giants attack your opponents to the best of their ability. If you speak Giant, you can direct the giants not to attack, to attack particular enemies, or to perform other actions. Summoned giants act normally on the last round of the spell and disappear at the end of their turn. Choose a giant kind from the table below. Type Number Align Hill giants, fiendish 3 CE Stone giants, celestial 2 N or fiendish Frost giant, fiendish 1 CE Fire giant, fiendish 1 LE Focus: A lock of hair from a giant of the desired kind."}'::jsonb),
('dnd35.frostburn.spell.frostburn-suppress-flame','Suppress Flame','Suppress Flame','You imbue an area with a combination of cold and negative energies that suppresses flame. Illumination emitted by fire (torches, continual flame, and so on) is reduced by half. For example, a hooded lantern within the area of a suppress flame spell clearly illuminates a 15-foot radius (instead of a 30-foot radius) and provides shadowy illumination in a 30-foot radius (instead of a 60-foot radius). In addition, all damage caused by fire, including all fire spells and spell-like effects, is reduced to 1 point per die. So, a fireball cast by a 10th-level wizard would deal 10 points of fire damage to those who fail their Reflex save or 5 points of fire damage to those who make their Reflex save, rather than 10d6 points of fire damage or half that amount, respectively, outside the confines of a suppress flame spell. A caster can make a caster level check (DC 10 + the suppress flame’s caster level) to cause normal amounts of damage from fire spells. A new caster level check must be made for each spell cast.
 Coldfire Component: Ten ounces of coldfire.',6,false,false,ARRAY['sorcerer/wizard']::text[],'1 round','Medium (100 ft. + 10 ft./level)','10-ft. cube/level (S)','1 hour/level','None',ARRAY['Transmutation','Cold']::text[],'v35-frostburn','D&D 3.5 — Frostburn',88,'dnd35','{"id":"frostburn-suppress-flame","name":"Suppress Flame","school":"Transmutation","subschool":null,"descriptors":["Cold"],"schoolLine":"Transmutation [Cold]","levels":{"sorcerer/wizard":6},"levelLine":"Sorcerer/wizard 6","components":"V, S, Coldfire","castingTime":"1 round","range":"Medium (100 ft. + 10 ft./level)","duration":"1 hour/level","savingThrow":"None","spellResistance":"No","targetLabel":"Area","target":"10-ft. cube/level (S)","description":"You imbue an area with a combination of cold and negative energies that suppresses flame. Illumination emitted by fire (torches, continual flame, and so on) is reduced by half. For example, a hooded lantern within the area of a suppress flame spell clearly illuminates a 15-foot radius (instead of a 30-foot radius) and provides shadowy illumination in a 30-foot radius (instead of a 60-foot radius). In addition, all damage caused by fire, including all fire spells and spell-like effects, is reduced to 1 point per die. So, a fireball cast by a 10th-level wizard would deal 10 points of fire damage to those who fail their Reflex save or 5 points of fire damage to those who make their Reflex save, rather than 10d6 points of fire damage or half that amount, respectively, outside the confines of a suppress flame spell. A caster can make a caster level check (DC 10 + the suppress flame’s caster level) to cause normal amounts of damage from fire spells. A new caster level check must be made for each spell cast.\n Coldfire Component: Ten ounces of coldfire."}'::jsonb),
('dnd35.frostburn.spell.frostburn-thaw','Thaw','Thaw','All everfrost, slush, snow, mud, and ice in the spell’s area are filled with heat. Ice and snow become slush, slush becomes everfrost, and everfrost becomes bog (see page 88 of the Dungeon Master’s Guide, for information on bogs).',2,false,false,ARRAY['druid']::text[],'1 standard action','Close (25 ft. + 5 ft./2 levels)','10-ft. cube/level','Instantaneous','None',ARRAY['Transmutation','Earth','Fire']::text[],'v35-frostburn','D&D 3.5 — Frostburn',88,'dnd35','{"id":"frostburn-thaw","name":"Thaw","school":"Transmutation","subschool":null,"descriptors":["Earth","Fire"],"schoolLine":"Transmutation [Earth, Fire]","levels":{"druid":2},"levelLine":"Druid 2","components":"V, S, DF","castingTime":"1 standard action","range":"Close (25 ft. + 5 ft./2 levels)","duration":"Instantaneous","savingThrow":"None","spellResistance":"No","targetLabel":"Area","target":"10-ft. cube/level","description":"All everfrost, slush, snow, mud, and ice in the spell’s area are filled with heat. Ice and snow become slush, slush becomes everfrost, and everfrost becomes bog (see page 88 of the Dungeon Master’s Guide, for information on bogs)."}'::jsonb),
('dnd35.frostburn.spell.frostburn-thin-air','Thin Air','Thin Air','This spell thins the oxygen in the area, causing creatures caught therein to suffer the effects of extreme altitude sickness. Subjects failing their saves take 1 point of damage to all ability scores because of altitude sickness (see page 90 of the Dungeon Masters Guide). Characters acclimated to high altitude receive a +4 competence bonus on their saving throws. Creatures that do not breathe are immune to the effects of the spell.',2,false,false,ARRAY['cleric','druid','sorcerer/wizard']::text[],'1 standard action','Medium (100 ft. + 10 ft./level)','30-ft.-radius emanation','1 min./level','Fortitude negates',ARRAY['Necromancy','Cold']::text[],'v35-frostburn','D&D 3.5 — Frostburn',88,'dnd35','{"id":"frostburn-thin-air","name":"Thin Air","school":"Necromancy","subschool":null,"descriptors":["Cold"],"schoolLine":"Necromancy [Cold]","levels":{"cleric":2,"druid":2,"sorcerer/wizard":3},"levelLine":"Cleric 2, druid 2, sorcerer/ wizard 3","components":"V, S","castingTime":"1 standard action","range":"Medium (100 ft. + 10 ft./level)","duration":"1 min./level","savingThrow":"Fortitude negates","spellResistance":"No","targetLabel":"Area","target":"30-ft.-radius emanation","description":"This spell thins the oxygen in the area, causing creatures caught therein to suffer the effects of extreme altitude sickness. Subjects failing their saves take 1 point of damage to all ability scores because of altitude sickness (see page 90 of the Dungeon Masters Guide). Characters acclimated to high altitude receive a +4 competence bonus on their saving throws. Creatures that do not breathe are immune to the effects of the spell."}'::jsonb),
('dnd35.frostburn.spell.frostburn-wall-of-coldfire','Wall of Coldfire','Wall of Coldfire','An immobile, opaque curtain of frosty coldfire springs into existence. One side of the wall, selected by you, sends forth waves of cold, dealing 2d4 points of cold damage to creatures within 10 feet and 1d4 points of cold damage to those past 10 feet but within 20 feet. The wall deals this damage when it appears and on your turn each round to all creatures in the area. In addition, the wall deals 2d6 points of frostburn damage +1 point of frostburn damage per caster level (maximum +20) to any creature passing through it. If you evoke the wall so that it appears where creatures are, each creature takes damage as if passing through the wall. The opaqueness of the coldfire grants concealment (20% miss chance) against attacks made from the opposite side of the wall. If any 5-foot length of wall takes 20 points of fire damage or more in 1 round, that length goes out. (Do not divide fire damage by 4, as for normal objects.) Wall of coldfire can be made permanent with a permanency spell. A permanent wall of coldfire that is extinguished by fire damage becomes inactive for 10 minutes, then reforms at normal strength.
 Coldfire Component: Three ounces of coldfire.',4,false,false,ARRAY['druid','sorcerer/wizard']::text[],'1 standard action','Medium (100 ft. + 10 ft./level)','Opaque sheet of coldfire up to 20 ft. long/level or a ring of coldfire with a radius of up to 5 ft. per two levels; either form 20 ft. high','Concentration + 1 round/ level','None',ARRAY['Evocation','Cold']::text[],'v35-frostburn','D&D 3.5 — Frostburn',88,'dnd35','{"id":"frostburn-wall-of-coldfire","name":"Wall of Coldfire","school":"Evocation","subschool":null,"descriptors":["Cold"],"schoolLine":"Evocation [Cold]","levels":{"druid":5,"sorcerer/wizard":4},"levelLine":"Druid 5, sorcerer/wizard 4","components":"V, S, Coldfire","castingTime":"1 standard action","range":"Medium (100 ft. + 10 ft./level)","duration":"Concentration + 1 round/ level","savingThrow":"None","spellResistance":"Yes","targetLabel":"Effect","target":"Opaque sheet of coldfire up to 20 ft. long/level or a ring of coldfire with a radius of up to 5 ft. per two levels; either form 20 ft. high","description":"An immobile, opaque curtain of frosty coldfire springs into existence. One side of the wall, selected by you, sends forth waves of cold, dealing 2d4 points of cold damage to creatures within 10 feet and 1d4 points of cold damage to those past 10 feet but within 20 feet. The wall deals this damage when it appears and on your turn each round to all creatures in the area. In addition, the wall deals 2d6 points of frostburn damage +1 point of frostburn damage per caster level (maximum +20) to any creature passing through it. If you evoke the wall so that it appears where creatures are, each creature takes damage as if passing through the wall. The opaqueness of the coldfire grants concealment (20% miss chance) against attacks made from the opposite side of the wall. If any 5-foot length of wall takes 20 points of fire damage or more in 1 round, that length goes out. (Do not divide fire damage by 4, as for normal objects.) Wall of coldfire can be made permanent with a permanency spell. A permanent wall of coldfire that is extinguished by fire damage becomes inactive for 10 minutes, then reforms at normal strength.\n Coldfire Component: Three ounces of coldfire."}'::jsonb),
('dnd35.frostburn.spell.frostburn-waves-of-cold','Waves of Cold','Waves of Cold','Waves of frigid energy render all creatures with the fire subtype in the spell’s area shaken for the duration of the spell. Any creature with the cold subtype caught in the area of this spell loses its immunity to cold for the duration of the spell. Whether or not a creature makes its saving throw, it becomes immune to further castings of this spell for 24 hours.
 Coldfire Component: Two ounces of coldfire.',6,false,false,ARRAY['sorcerer/wizard']::text[],'1 standard action','60 ft.','Cone-shaped burst','1 round/level','Will negates',ARRAY['Necromancy','Cold']::text[],'v35-frostburn','D&D 3.5 — Frostburn',88,'dnd35','{"id":"frostburn-waves-of-cold","name":"Waves of Cold","school":"Necromancy","subschool":null,"descriptors":["Cold"],"schoolLine":"Necromancy [Cold]","levels":{"sorcerer/wizard":6},"levelLine":"Sorcerer/wizard 6","components":"V, S, Coldfire","castingTime":"1 standard action","range":"60 ft.","duration":"1 round/level","savingThrow":"Will negates","spellResistance":"Yes","targetLabel":"Area","target":"Cone-shaped burst","description":"Waves of frigid energy render all creatures with the fire subtype in the spell’s area shaken for the duration of the spell. Any creature with the cold subtype caught in the area of this spell loses its immunity to cold for the duration of the spell. Whether or not a creature makes its saving throw, it becomes immune to further castings of this spell for 24 hours.\n Coldfire Component: Two ounces of coldfire."}'::jsonb),
('dnd35.frostburn.spell.frostburn-whiteout','Whiteout','Whiteout','A swirling snow and a strong wind arise around you or a creature you designate, and follows you or the creature from that point on. Characters in whiteout conditions take a –2 penalty to AC, lose any Dexterity bonus to AC, move at half speed, and take a –4 penalty on Dexterity-based skill checks, as well as Search, Spot, and any other checks that rely on vision. The character also gains total concealment (50% miss chance). These effects end when the character leaves the area of whiteout. Whiteout conditions stack with wind and snowfall. Visibility is 5 feet. In addition, any creature trying to move within the effects of this spell must make a Survival check (DC 10 + caster level) every move action or wander lost inside the whiteout. A creature that fails can’t leave the area, but can move around within it. Groups of creatures roped or otherwise physically held together can use the lead creature’s Survival check and stay together. A new check can be made once per minute.',7,false,false,ARRAY['druid']::text[],'1 standard action','Long (400 ft. + 40 ft./level)','Cloud centered on target spreads 120 ft. and is 20 ft. high','1 hour/level','None (see text)',ARRAY['Conjuration','Cold']::text[],'v35-frostburn','D&D 3.5 — Frostburn',88,'dnd35','{"id":"frostburn-whiteout","name":"Whiteout","school":"Conjuration","subschool":"Creation","descriptors":["Cold"],"schoolLine":"Conjuration (Creation) [Cold]","levels":{"druid":7},"levelLine":"Druid 7","components":"V, S","castingTime":"1 standard action","range":"Long (400 ft. + 40 ft./level)","duration":"1 hour/level","savingThrow":"None (see text)","spellResistance":"No","targetLabel":"Effect","target":"Cloud centered on target spreads 120 ft. and is 20 ft. high","description":"A swirling snow and a strong wind arise around you or a creature you designate, and follows you or the creature from that point on. Characters in whiteout conditions take a –2 penalty to AC, lose any Dexterity bonus to AC, move at half speed, and take a –4 penalty on Dexterity-based skill checks, as well as Search, Spot, and any other checks that rely on vision. The character also gains total concealment (50% miss chance). These effects end when the character leaves the area of whiteout. Whiteout conditions stack with wind and snowfall. Visibility is 5 feet. In addition, any creature trying to move within the effects of this spell must make a Survival check (DC 10 + caster level) every move action or wander lost inside the whiteout. A creature that fails can’t leave the area, but can move around within it. Groups of creatures roped or otherwise physically held together can use the lead creature’s Survival check and stay together. A new check can be made once per minute."}'::jsonb),
('dnd35.frostburn.spell.frostburn-winters-embrace','Winter’s Embrace','Winter’s Embrace','Winter’s embrace covers the victim with sheets of ice and lumps of snow. If the subject succeeds on its Fortitude save, the ice and snow instantly slough from its body, causing a mere 1d4 points of cold damage and ending the effect. If the subject fails its saving throw, the ice and snow cling tenaciously to its body and cause 1d8 points of cold damage each round. On the subject’s action each round, it can attempt a new Fortitude saving throw to avoid taking damage that round. If a creature takes damage twice from a single casting of winter’s embrace, it becomes fatigued. The fourth time a creature takes damage from the same spell, it becomes exhausted.',3,false,false,ARRAY['cleric','druid','winter']::text[],'1 standard action','Close (25 ft. + 5 ft./2 levels)','One creature','1 round/level','Fortitude negates',ARRAY['Evocation','Cold']::text[],'v35-frostburn','D&D 3.5 — Frostburn',88,'dnd35','{"id":"frostburn-winters-embrace","name":"Winter’s Embrace","school":"Evocation","subschool":null,"descriptors":["Cold"],"schoolLine":"Evocation [Cold]","levels":{"cleric":4,"druid":3,"winter":3},"levelLine":"Cleric 4, druid 3, Winter 3","components":"V, S","castingTime":"1 standard action","range":"Close (25 ft. + 5 ft./2 levels)","duration":"1 round/level","savingThrow":"Fortitude negates","spellResistance":"Yes","targetLabel":"Area","target":"One creature","description":"Winter’s embrace covers the victim with sheets of ice and lumps of snow. If the subject succeeds on its Fortitude save, the ice and snow instantly slough from its body, causing a mere 1d4 points of cold damage and ending the effect. If the subject fails its saving throw, the ice and snow cling tenaciously to its body and cause 1d8 points of cold damage each round. On the subject’s action each round, it can attempt a new Fortitude saving throw to avoid taking damage that round. If a creature takes damage twice from a single casting of winter’s embrace, it becomes fatigued. The fourth time a creature takes damage from the same spell, it becomes exhausted."}'::jsonb),
('dnd35.frostburn.spell.frostburn-zone-of-glacial-cold','Zone of Glacial Cold','Zone of Glacial Cold','You create a zone of icy cold within the spell’s area, dealing 1d6 points of cold damage per round. Arcane Material Component: A snowball.',2,false,false,ARRAY['druid','ranger','sorcerer/wizard']::text[],'1 standard action','Medium (100 ft. + 10 ft./level)','20-ft. radius','1 round/level','Fortitude half',ARRAY['Conjuration','Cold']::text[],'v35-frostburn','D&D 3.5 — Frostburn',88,'dnd35','{"id":"frostburn-zone-of-glacial-cold","name":"Zone of Glacial Cold","school":"Conjuration","subschool":null,"descriptors":["Cold"],"schoolLine":"Conjuration [Cold]","levels":{"druid":2,"ranger":2,"sorcerer/wizard":2},"levelLine":"Druid 2, ranger 2, sorcerer/ wizard 2","components":"V, S, M","castingTime":"1 standard action","range":"Medium (100 ft. + 10 ft./level)","duration":"1 round/level","savingThrow":"Fortitude half","spellResistance":"No","targetLabel":"Effect","target":"20-ft. radius","description":"You create a zone of icy cold within the spell’s area, dealing 1d6 points of cold damage per round. Arcane Material Component: A snowball."}'::jsonb),
('dnd35.frostburn.power.frostburn-energy-emanation','Energy Emanation','Energy Emanation','You expel concentrated energy from your body, dealing 1d6 points of energy damage to all creatures within the area every round. Creatures in the area must make a new Fortitude save each round. The energy is the type you choose: cold, electricity, fire, or sonic. Once chosen, you emanate the same energy type for the power’s duration. Cold: This energy type deals +1 point of damage per die. Electricity: This energy type provides a +2 bonus to the save DC and a +2 bonus on manifester level checks for the purpose of overcoming power resistance. Fire: This energy type deals +1 point of damage per die. Sonic: This energy type deals –1 point of damage per die and ignores an object’s hardness. This power’s subtype is the same as the type of energy you manifest. Augment: For every 3 additional power points you spend, this power’s damage increases by one die (d6). For each extra die of damage, this power’s save DC increases by 1.',2,false,false,ARRAY['psion/wilder','psychicwarrior']::text[],'1 standard action','5 ft.','5-ft.-radius emanation, centered on you','1 round/level','Fortitude half',ARRAY['power','Psychokinesis']::text[],'v35-frostburn','D&D 3.5 — Frostburn',108,'dnd35','{"id":"frostburn-energy-emanation","name":"Energy Emanation","discipline":"Psychokinesis","schoolLine":"Psychokinesis [see text]","levels":{"psion/wilder":2,"psychicwarrior":2},"levelLine":"Psion/wilder 2, psychic warrior 2","display":"Visual","manifestingTime":"1 standard action","range":"5 ft.","targetLabel":"Target","target":"5-ft.-radius emanation, centered on you","duration":"1 round/level","savingThrow":"Fortitude half","powerResistance":"Yes","powerPoints":3,"description":"You expel concentrated energy from your body, dealing 1d6 points of energy damage to all creatures within the area every round. Creatures in the area must make a new Fortitude save each round. The energy is the type you choose: cold, electricity, fire, or sonic. Once chosen, you emanate the same energy type for the power’s duration. Cold: This energy type deals +1 point of damage per die. Electricity: This energy type provides a +2 bonus to the save DC and a +2 bonus on manifester level checks for the purpose of overcoming power resistance. Fire: This energy type deals +1 point of damage per die. Sonic: This energy type deals –1 point of damage per die and ignores an object’s hardness. This power’s subtype is the same as the type of energy you manifest. Augment: For every 3 additional power points you spend, this power’s damage increases by one die (d6). For each extra die of damage, this power’s save DC increases by 1."}'::jsonb),
('dnd35.frostburn.power.frostburn-energy-flash','Energy Flash','Energy Flash','On a successful touch attack, you deal 7d6 points of damage to the creature touched, doing either cold, electricity, fire, or sonic damage. In addition to the energy damage, on a failed Fortitude save (the same save that determines full or half damage), a target is dazed for 1 round. Cold: This energy type deals +1 point of damage per die. Electricity: This energy type provides a +2 bonus to the save DC and a +2 bonus on manifester level checks for the purpose of overcoming power resistance. Fire: This energy type deals +1 point of damage per die. Sonic: This energy type deals –1 point of damage per die and ignores an object’s hardness. This power’s subtype is the same as the type of energy you manifest. Augment: For every additional power point you spend, this power’s damage increases by one die (d6). For each extra two dice of damage, this power’s save DC increases by 1.',4,false,false,ARRAY['psion/wilder']::text[],'1 standard action','Touch','Touched creature, or up to 1 cu. ft. of water/level','Instantaneous','Fortitude half',ARRAY['power','Psychokinesis']::text[],'v35-frostburn','D&D 3.5 — Frostburn',108,'dnd35','{"id":"frostburn-energy-flash","name":"Energy Flash","discipline":"Psychokinesis","schoolLine":"Psychokinesis [see text]","levels":{"psion/wilder":4},"levelLine":"Psion/wilder 4","display":"Visual","manifestingTime":"1 standard action","range":"Touch","targetLabel":"Target","target":"Touched creature, or up to 1 cu. ft. of water/level","duration":"Instantaneous","savingThrow":"Fortitude half","powerResistance":"Yes","powerPoints":7,"description":"On a successful touch attack, you deal 7d6 points of damage to the creature touched, doing either cold, electricity, fire, or sonic damage. In addition to the energy damage, on a failed Fortitude save (the same save that determines full or half damage), a target is dazed for 1 round. Cold: This energy type deals +1 point of damage per die. Electricity: This energy type provides a +2 bonus to the save DC and a +2 bonus on manifester level checks for the purpose of overcoming power resistance. Fire: This energy type deals +1 point of damage per die. Sonic: This energy type deals –1 point of damage per die and ignores an object’s hardness. This power’s subtype is the same as the type of energy you manifest. Augment: For every additional power point you spend, this power’s damage increases by one die (d6). For each extra two dice of damage, this power’s save DC increases by 1."}'::jsonb),
('dnd35.frostburn.power.frostburn-energy-nullification-field','Energy Nullification Field','Energy Nullification Field','An invisible field of energy surrounds you. This power functions like null psionics field, but applies only to powers with the energy descriptor you choose when you first manifest this power: cold, electricity, fire, or sonic.',5,false,false,ARRAY['kineticist']::text[],'1 standard action','10 ft.','10-ft.-radius emanation, centered on you','10 min./level (D)','None',ARRAY['power','Psychokinesis']::text[],'v35-frostburn','D&D 3.5 — Frostburn',108,'dnd35','{"id":"frostburn-energy-nullification-field","name":"Energy Nullification Field","discipline":"Psychokinesis","schoolLine":"Psychokinesis [see text]","levels":{"kineticist":5},"levelLine":"Kineticist 5","display":"Visual and auditory","manifestingTime":"1 standard action","range":"10 ft.","targetLabel":"Area","target":"10-ft.-radius emanation, centered on you","duration":"10 min./level (D)","savingThrow":"None","powerResistance":"See text","powerPoints":9,"description":"An invisible field of energy surrounds you. This power functions like null psionics field, but applies only to powers with the energy descriptor you choose when you first manifest this power: cold, electricity, fire, or sonic."}'::jsonb),
('dnd35.frostburn.power.frostburn-mind-over-energy','Mind over Energy','Mind over Energy','You mentally reinforce your living tissue with pure psionic will, gaining immunity to the energy type you choose for the duration of the power: cold, electricity, fire, or sonic.',6,false,false,ARRAY['psion/wilder','psychicwarrior']::text[],'1 standard action','Personal','You','1 round/level','None',ARRAY['power','Psychometabolism']::text[],'v35-frostburn','D&D 3.5 — Frostburn',108,'dnd35','{"id":"frostburn-mind-over-energy","name":"Mind over Energy","discipline":"Psychometabolism","schoolLine":"Psychometabolism","levels":{"psion/wilder":6,"psychicwarrior":6},"levelLine":"Psion/wilder 6, psychic warrior 6","display":"Visual","manifestingTime":"1 standard action","range":"Personal","targetLabel":"Target","target":"You","duration":"1 round/level","savingThrow":"None","powerResistance":"No","powerPoints":11,"description":"You mentally reinforce your living tissue with pure psionic will, gaining immunity to the energy type you choose for the duration of the power: cold, electricity, fire, or sonic."}'::jsonb),
('dnd35.frostburn.power.frostburn-slow-breathing','Slow Breathing','Slow Breathing','You reduce the need for oxygen in your body, increasing your ability to become acclimated to the thin air of high altitude. You gain a +4 competence bonus on saving throws against altitude sickness (see page 90 of the Dungeon Master’s Guide). Augmentation: For every additional power point you spend, the competence bonus increases by 2.',1,false,false,ARRAY['psion/wilder','psychicwarrior']::text[],'1 standard action','Personal','You','1 hour/level','None (harmless)',ARRAY['power','Psychometabolism']::text[],'v35-frostburn','D&D 3.5 — Frostburn',108,'dnd35','{"id":"frostburn-slow-breathing","name":"Slow Breathing","discipline":"Psychometabolism","schoolLine":"Psychometabolism","levels":{"psion/wilder":1,"psychicwarrior":1},"levelLine":"Psion/wilder 1, psychic warrior 1","display":"Visual","manifestingTime":"1 standard action","range":"Personal","targetLabel":"Target","target":"You","duration":"1 hour/level","savingThrow":"None (harmless)","powerResistance":"No (harmless)","powerPoints":1,"description":"You reduce the need for oxygen in your body, increasing your ability to become acclimated to the thin air of high altitude. You gain a +4 competence bonus on saving throws against altitude sickness (see page 90 of the Dungeon Master’s Guide). Augmentation: For every additional power point you spend, the competence bonus increases by 2."}'::jsonb)
on conflict (id) do update set name_pt = excluded.name_pt, name_en = excluded.name_en, description_pt = excluded.description_pt, rank = excluded.rank, is_cantrip = excluded.is_cantrip, is_focus = excluded.is_focus, traditions = excluded.traditions, cast_actions = excluded.cast_actions, range = excluded.range, targets = excluded.targets, duration = excluded.duration, defense = excluded.defense, traits = excluded.traits, ruleset = excluded.ruleset, source_book = excluded.source_book, source_page = excluded.source_page, system_id = excluded.system_id, data = excluded.data, updated_at = now();

insert into public.catalog_items (id,name_pt,name_en,description_pt,item_category,level,price_gp,traits,ruleset,source_book,source_page,system_id,data) values
('dnd35.frostburn.domain.frostburn-cold','Cold','Cold','You can turn or destroy fire creatures as a good cleric turns undead. You can also rebuke or command cold creatures as an evil cleric rebukes undead.','domain',0,null,ARRAY[]::text[],'v35-frostburn','D&D 3.5 — Frostburn',84,'dnd35','{"id":"frostburn-cold","name":"Cold","sourceBook":"Frostburn","sourcePages":"84-85","deities":["Auril","Iborighu","Levistus","Telchur","Thrym","Ulutiu"],"grantedPower":"You can turn or destroy fire creatures as a good cleric turns undead. You can also rebuke or command cold creatures as an evil cleric rebukes undead.","spells":[{"level":1,"name":"Chill Touch","summary":"One touch/level deals 1d6 damage and possibly 1 Str damage.","frostburnSpell":false},{"level":2,"name":"Chill Metal","summary":"Cold metal damages those who touch it.","frostburnSpell":false},{"level":3,"name":"Sleet Storm","summary":"Hampers vision and movement.","frostburnSpell":false},{"level":4,"name":"Ice Storm","summary":"Hail deals 5d6 damage in cylinder 40 ft. across.","frostburnSpell":false},{"level":5,"name":"Wall of Ice","summary":"Ice plane creates wall with 15 hp +1/level, or hemisphere can trap creatures inside.","frostburnSpell":false},{"level":6,"name":"Cone of Cold","summary":"1d6/level cold damage.","frostburnSpell":false},{"level":7,"name":"Control Weather","summary":"Changes weather in local area.","frostburnSpell":false},{"level":8,"name":"Polar Ray","summary":"Ranged touch attack deals 1d6/level cold damage.","frostburnSpell":false},{"level":9,"name":"Obedient Avalanche","summary":"Snowy avalanche crushes and buries your foes.","frostburnSpell":true}]}'::jsonb),
('dnd35.frostburn.domain.frostburn-winter','Winter','Winter','During the winter season, you gain a +2 sacred bonus on all Wisdom-based skill checks.','domain',0,null,ARRAY[]::text[],'v35-frostburn','D&D 3.5 — Frostburn',84,'dnd35','{"id":"frostburn-winter","name":"Winter","sourceBook":"Frostburn","sourcePages":"85","deities":["Aengrist","Auril","Hleid","Telchur"],"grantedPower":"During the winter season, you gain a +2 sacred bonus on all Wisdom-based skill checks.","spells":[{"level":1,"name":"Snowsight","summary":"Normal vision in winter weather conditions.","frostburnSpell":true},{"level":2,"name":"Snow Walk","summary":"Increase your speed and walk effortlessly on top of snow without leaving tracks or scent.","frostburnSpell":true},{"level":3,"name":"Winter’s Embrace","summary":"Subject takes 1d8 damage/round; can cause fatigue.","frostburnSpell":true},{"level":4,"name":"Ice Storm","summary":"Hail deals 5d6 damage in cylinder 40 ft. across.","frostburnSpell":false},{"level":5,"name":"Blizzard","summary":"Temperature drops and powerful blizzard reduces visibility to zero.","frostburnSpell":true},{"level":6,"name":"Death Hail","summary":"Summons a storm of death hail.","frostburnSpell":true},{"level":7,"name":"Control Weather","summary":"Changes weather in local area.","frostburnSpell":false},{"level":8,"name":"Summon Giants (Frost Giants Only)","summary":"Summons outsider giants to fight for you.","frostburnSpell":true},{"level":9,"name":"Fimbulwinter","summary":"Creates winter weather for miles around you that lasts for months.","frostburnSpell":true,"flags":["X"]}]}'::jsonb)
on conflict (id) do update set name_pt = excluded.name_pt, name_en = excluded.name_en, description_pt = excluded.description_pt, item_category = excluded.item_category, level = excluded.level, price_gp = excluded.price_gp, traits = excluded.traits, ruleset = excluded.ruleset, source_book = excluded.source_book, source_page = excluded.source_page, system_id = excluded.system_id, data = excluded.data, updated_at = now();

